export type { SheetsCell, SheetsCellKind } from './cell-model/sheets-cell';

import type { SheetsConfig } from '../context/sheets-context';

/**
 * Execute a GraphQL mutation against the auth endpoint.
 * Falls back to the data endpoint if authEndpoint is not configured.
 */
export async function executeAuthMutation<TResult = unknown>(
	config: SheetsConfig,
	query: string,
	variables?: Record<string, unknown>,
): Promise<TResult> {
	const url = config.authEndpoint || config.endpoint;
	if (!url) {
		throw new Error('No auth endpoint configured.');
	}

	const headers: Record<string, string> = {
		'Content-Type': 'application/json',
		Accept: 'application/graphql-response+json',
	};

	let response: Response;
	try {
		response = await fetch(url, {
			method: 'POST',
			headers,
			body: JSON.stringify({
				query,
				...(variables !== undefined && { variables }),
			}),
		});
	} catch (error) {
		throw new Error(
			`Network error: ${error instanceof Error ? error.message : 'Failed to connect to auth endpoint'}`,
		);
	}

	if (!response.ok) {
		const { status, statusText } = response;
		try {
			const body = await response.json();
			if (body.errors?.length) {
				const firstError = body.errors[0];
				const err = new Error(firstError.message || `Auth request failed: ${status}`);
				(err as any).code = firstError.extensions?.code;
				(err as any).errors = body.errors;
				throw err;
			}
		} catch (e) {
			if (e instanceof Error && (e as any).errors) throw e;
		}
		throw new Error(`Auth request failed: ${status} ${statusText}`);
	}

	const result = await response.json();

	if (result.errors?.length) {
		const firstError = result.errors[0];
		const err = new Error(firstError.message || 'Auth mutation failed');
		(err as any).code = firstError.extensions?.code;
		(err as any).errors = result.errors;
		throw err;
	}

	return result.data as TResult;
}

import { useState } from 'react';

import { useSheetsContext } from '../context/sheets-context';
import { useSheetsStore } from '../store/sheets-store';
import { useSheetsLogin } from './hooks/use-login';
import { useSheetsRegister } from './hooks/use-register';
import { useSheetsForgotPassword } from './hooks/use-forgot-password';
import { useSheetsResetPassword } from './hooks/use-reset-password';
import { SheetsLoginForm } from './ui/login-form';
import { SheetsRegisterForm } from './ui/register-form';
import { SheetsForgotPasswordForm } from './ui/forgot-password-form';
import { SheetsResetPasswordForm } from './ui/reset-password-form';
import { AuthScreenHeader, type AuthBrandingProps } from './ui/auth-screen-header';
import { AuthScreenLayout } from './ui/auth-screen-layout';

type AuthMode = 'login' | 'register' | 'forgot' | 'reset';

const AUTH_CONTENT: Record<AuthMode, { title: string; description: string }> = {
	login: {
		title: 'Welcome back',
		description: 'Sign in to your account',
	},
	register: {
		title: 'Create an account',
		description: 'Get started with your free account',
	},
	forgot: {
		title: 'Reset your password',
		description: "We'll send you a password reset link",
	},
	reset: {
		title: 'Set a new password',
		description: 'Enter your new password below',
	},
} as const;

export interface SheetsAuthGateProps extends AuthBrandingProps {
	children: React.ReactNode;
	loginComponent?: React.ComponentType;
	resetToken?: string;
	roleId?: string;
}

export function SheetsAuthGate({
	children,
	loginComponent: CustomLoginComponent,
	resetToken,
	roleId,
	logo,
	appName,
	showLogo,
}: SheetsAuthGateProps) {
	const { config } = useSheetsContext();
	const isAuthenticated = useSheetsStore((s) => s.isAuthenticated);

	// Embedded mode: auth gate is transparent, always renders children
	if (config.auth.mode === 'embedded') {
		return <>{children}</>;
	}

	// Standalone mode: check auth state
	if (isAuthenticated) {
		return <>{children}</>;
	}

	// Not authenticated in standalone mode — show login UI
	if (CustomLoginComponent) {
		return <CustomLoginComponent />;
	}

	return (
		<StandaloneAuthUI
			resetToken={resetToken}
			roleId={roleId}
			logo={logo}
			appName={appName}
			showLogo={showLogo}
		/>
	);
}

interface StandaloneAuthUIProps extends AuthBrandingProps {
	resetToken?: string;
	roleId?: string;
}

function StandaloneAuthUI({ resetToken, roleId, logo, appName, showLogo }: StandaloneAuthUIProps) {
	const initialMode: AuthMode = resetToken ? 'reset' : 'login';
	const [mode, setMode] = useState<AuthMode>(initialMode);

	const loginMutation = useSheetsLogin();
	const registerMutation = useSheetsRegister();
	const forgotPasswordMutation = useSheetsForgotPassword();
	const resetPasswordMutation = useSheetsResetPassword();

	const { title, description } = AUTH_CONTENT[mode];

	return (
		<AuthScreenLayout fill='parent' logo={logo} appName={appName} showLogo={showLogo}>
			<AuthScreenHeader
				title={title}
				description={description}
				logo={logo}
				appName={appName}
				showLogo={showLogo}
			/>

			<div>
				{mode === 'login' && (
					<SheetsLoginForm
						onLogin={(credentials) => loginMutation.mutateAsync(credentials).then(() => {})}
						onShowForgot={() => setMode('forgot')}
						onShowRegister={() => setMode('register')}
					/>
				)}
				{mode === 'register' && (
					<SheetsRegisterForm
						onRegister={(data) => registerMutation.mutateAsync(data)}
						onShowLogin={() => setMode('login')}
					/>
				)}
				{mode === 'forgot' && (
					<SheetsForgotPasswordForm
						onForgotPassword={(data) => forgotPasswordMutation.mutateAsync(data)}
						onShowLogin={() => setMode('login')}
					/>
				)}
				{mode === 'reset' && (
					<SheetsResetPasswordForm
						resetToken={resetToken || ''}
						roleId={roleId}
						onResetPassword={(input) => resetPasswordMutation.mutateAsync(input)}
						onShowLogin={() => setMode('login')}
					/>
				)}
			</div>
		</AuthScreenLayout>
	);
}

// ============================================================================
// Auth Result Types
// ============================================================================

export interface AuthResultRecord {
	id: string;
	userId: string;
	accessToken: string;
	accessTokenExpiresAt: string;
	isVerified?: boolean | null;
	totpEnabled?: boolean | null;
}

// ============================================================================
// Generic Helper
// ============================================================================

export type MutationVariables<TInput> = { input: TInput };

// ============================================================================
// SignIn Mutation
// ============================================================================

export interface SignInInput {
	email: string;
	password: string;
	rememberMe?: boolean;
}

export type SignInMutationVariables = MutationVariables<SignInInput>;

export interface SignInMutationResult {
	signIn?: {
		result?: AuthResultRecord | null;
		clientMutationId?: string | null;
	} | null;
}

// ============================================================================
// SignUp Mutation
// ============================================================================

export interface SignUpInput {
	email: string;
	password: string;
}

export type SignUpMutationVariables = MutationVariables<SignUpInput>;

export interface SignUpMutationResult {
	signUp?: {
		clientMutationId?: string | null;
	} | null;
}

// ============================================================================
// Forgot Password Mutation
// ============================================================================

export interface ForgotPasswordInput {
	email: string;
}

export type ForgotPasswordMutationVariables = MutationVariables<ForgotPasswordInput>;

export interface ForgotPasswordMutationResult {
	forgotPassword?: {
		clientMutationId?: string | null;
	} | null;
}

// ============================================================================
// Reset Password Mutation
// ============================================================================

export interface ResetPasswordInput {
	newPassword: string;
	resetToken: string;
	roleId?: string;
}

export type ResetPasswordMutationVariables = MutationVariables<ResetPasswordInput>;

export interface ResetPasswordMutationResult {
	resetPassword?: {
		result?: boolean | null;
		clientMutationId?: string | null;
	} | null;
}

// ============================================================================
// Token Helper
// ============================================================================

export function toAuthToken(record: AuthResultRecord | null | undefined): { accessToken: string; expiresAt: string } | null {
	if (!record?.accessToken || !record?.accessTokenExpiresAt) {
		return null;
	}
	return {
		accessToken: record.accessToken,
		expiresAt: record.accessTokenExpiresAt,
	};
}

export { useSheetsLogin } from './use-login';
export { useSheetsRegister } from './use-register';
export { useSheetsForgotPassword } from './use-forgot-password';
export { useSheetsResetPassword } from './use-reset-password';

import { useMutation } from '@tanstack/react-query';

import { useSheetsContext } from '../../context/sheets-context';
import { executeAuthMutation } from '../auth-execute';
import type { ForgotPasswordMutationResult, ForgotPasswordMutationVariables } from '../auth-types';

const FORGOT_PASSWORD_MUTATION = /* GraphQL */ `
	mutation ForgotPassword($input: ForgotPasswordInput!) {
		forgotPassword(input: $input) {
			clientMutationId
		}
	}
`;

export function useSheetsForgotPassword() {
	const { config } = useSheetsContext();

	return useMutation({
		mutationKey: ['sheets', 'auth', 'forgotPassword'],
		mutationFn: async ({ email }: { email: string }) => {
			await executeAuthMutation<ForgotPasswordMutationResult>(
				config,
				FORGOT_PASSWORD_MUTATION,
				{
					input: { email },
				} satisfies ForgotPasswordMutationVariables,
			);
			return { email };
		},
	});
}

import { useMutation, useQueryClient } from '@tanstack/react-query';

import { createInvalidCredentialsError } from '../utils/auth-errors';
import type { LoginFormData } from '../utils/schemas';
import { useSheetsContext } from '../../context/sheets-context';
import { useSheetsStoreApi } from '../../store/sheets-store';
import { setStoredToken } from '../utils/token-store';
import { executeAuthMutation } from '../auth-execute';
import { toAuthToken, type SignInMutationResult, type SignInMutationVariables } from '../auth-types';

const SIGN_IN_MUTATION = /* GraphQL */ `
	mutation SignIn($input: SignInInput!) {
		signIn(input: $input) {
			result {
				id
				userId
				accessToken
				accessTokenExpiresAt
				isVerified
				totpEnabled
			}
			clientMutationId
		}
	}
`;

export function useSheetsLogin() {
	const queryClient = useQueryClient();
	const { config } = useSheetsContext();
	const storeApi = useSheetsStoreApi();

	return useMutation({
		mutationKey: ['sheets', 'auth', 'signIn'],
		mutationFn: async (credentials: LoginFormData) => {
			const result = await executeAuthMutation<SignInMutationResult>(
				config,
				SIGN_IN_MUTATION,
				{
					input: {
						email: credentials.email,
						password: credentials.password,
						rememberMe: credentials.rememberMe,
					},
				} satisfies SignInMutationVariables,
			);

			const signInResult = result.signIn?.result;
			if (!signInResult) {
				throw createInvalidCredentialsError();
			}

			const token = toAuthToken(signInResult);
			if (!token) {
				throw createInvalidCredentialsError();
			}

			return { token, email: credentials.email, identityKey: signInResult.userId };
		},
		onSuccess: ({ token, identityKey }) => {
			const databaseId = config.databaseId || 'default';
			setStoredToken(databaseId, token.accessToken, token.expiresAt, identityKey);
			storeApi.getState().setAuthenticated(token.accessToken, token.expiresAt, identityKey);
			queryClient.invalidateQueries({ queryKey: ['sheets'] });
		},
	});
}

import { useMutation, useQueryClient } from '@tanstack/react-query';

import type { RegisterFormData } from '../utils/schemas';
import { useSheetsContext } from '../../context/sheets-context';
import { useSheetsStoreApi } from '../../store/sheets-store';
import { executeAuthMutation } from '../auth-execute';
import { type SignUpMutationResult, type SignUpMutationVariables } from '../auth-types';

const SIGN_UP_MUTATION = /* GraphQL */ `
	mutation SignUp($input: SignUpInput!) {
		signUp(input: $input) {
			clientMutationId
		}
	}
`;

export function useSheetsRegister() {
	const queryClient = useQueryClient();
	const { config } = useSheetsContext();
	const storeApi = useSheetsStoreApi();

	return useMutation({
		mutationKey: ['sheets', 'auth', 'signUp'],
		mutationFn: async (formData: RegisterFormData) => {
			// sign_up never signs anyone in: the address is mailed a link that does
			await executeAuthMutation<SignUpMutationResult>(
				config,
				SIGN_UP_MUTATION,
				{
					input: {
						email: formData.email,
						password: formData.password,
					},
				} satisfies SignUpMutationVariables,
			);

			return { email: formData.email };
		},
		onSuccess: () => {
			queryClient.invalidateQueries({ queryKey: ['sheets'] });
		},
		onError: () => {
			storeApi.getState().setUnauthenticated();
		},
	});
}

import { useMutation, useQueryClient } from '@tanstack/react-query';

import { useSheetsContext } from '../../context/sheets-context';
import { executeAuthMutation } from '../auth-execute';
import type { ResetPasswordInput, ResetPasswordMutationResult, ResetPasswordMutationVariables } from '../auth-types';

const RESET_PASSWORD_MUTATION = /* GraphQL */ `
	mutation ResetPassword($input: ResetPasswordInput!) {
		resetPassword(input: $input) {
			result
			clientMutationId
		}
	}
`;

export function useSheetsResetPassword() {
	const queryClient = useQueryClient();
	const { config } = useSheetsContext();

	return useMutation({
		mutationKey: ['sheets', 'auth', 'resetPassword'],
		mutationFn: async (input: ResetPasswordInput) => {
			const result = await executeAuthMutation<ResetPasswordMutationResult>(
				config,
				RESET_PASSWORD_MUTATION,
				{
					input: {
						newPassword: input.newPassword,
						resetToken: input.resetToken,
						roleId: input.roleId,
					},
				} satisfies ResetPasswordMutationVariables,
			);

			if (!result.resetPassword?.result) {
				throw new Error('Failed to reset password. The link may have expired.');
			}

			return { success: true };
		},
		onSuccess: () => {
			queryClient.invalidateQueries({ queryKey: ['sheets'] });
		},
	});
}

