}

export function SheetsForgotPasswordForm({ onForgotPassword, onShowLogin }: SheetsForgotPasswordFormProps) {
	const [error, setError] = useState<string | null>(null);
	const [isSubmitting, setIsSubmitting] = useState(false);
	const [isSuccess, setIsSuccess] = useState(false);

	const form = useForm({
		defaultValues: {
			email: '',
		},
		onSubmit: async ({ value }) => {
			setError(null);
			setIsSubmitting(true);

			try {
				const validatedData = forgotPasswordSchema.parse(value);
				await onForgotPassword(validatedData);
				setIsSuccess(true);
			} catch (err) {
				setError(parseGraphQLError(err).message);
			} finally {
				setIsSubmitting(false);
			}
		},
		validators: {
			onChange: ({ value }) => {
				const result = forgotPasswordSchema.safeParse(value);
				if (!result.success) {
