			<div className='space-y-5 text-center'>
				<div className='flex justify-center'>
					<div className='bg-success/10 flex h-12 w-12 items-center justify-center rounded-full'>
						<CheckCircleIcon className='text-success h-6 w-6' />
					</div>
				</div>
				<div className='space-y-1.5'>
					<h3 className='text-lg font-semibold'>Password reset successful</h3>
					<p className='text-muted-foreground text-sm'>
						Your password has been reset successfully. You can now sign in with your new password.
					</p>
				</div>
				{onShowLogin && (
					<div className='pt-1'>
						<Button type='button' onClick={onShowLogin} className='w-full'>
							Sign in
						</Button>
					</div>
				)}
			</div>
		);
	}

	return (
		<div className='space-y-5'>
			<AuthScreenHeader title='Set a new password' description='Enter your new password below' />

			<form
				onSubmit={(e) => {
					e.preventDefault();
					e.stopPropagation();
					form.handleSubmit();
				}}
				className='space-y-4 px-8'
			>
				<AuthErrorAlert error={error} />
				<form.Field
					name='password'
					validators={{
						onChange: ({ value }) => {
							if (!value) return 'Password is required';
							if (value.length < 8) return 'Password must be at least 8 characters';
							if (!/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/.test(value)) {
								return 'Password must contain uppercase, lowercase, number, and special character';
							}
							return undefined;
						},
					}}
				>
					{(field) => (
						<div className='space-y-2'>
							<FormField
								field={field}
								label='New Password'
								placeholder='Enter your new password'
								type='password'
							/>
							<PasswordStrength password={field.state.value} />
						</div>
					)}
				</form.Field>

				<form.Field
					name='confirmPassword'
					validators={{
						onChange: ({ value }) => {
							if (!value) return 'Please confirm your password';
							const password = form.getFieldValue('password');
							if (value !== password) return 'Passwords do not match';
							return undefined;
						},
					}}
				>
					{(field) => (
						<FormField
							field={field}
							label='Confirm New Password'
							placeholder='Confirm your new password'
							type='password'
						/>
					)}
				</form.Field>

				<div className='pt-2'>
					<AuthLoadingButton
						type='submit'
						className='w-full'
						isLoading={isSubmitting}
						disabled={!form.state.canSubmit || isSubmitting}
						data-testid='auth-reset-submit'
					>
						Reset Password
					</AuthLoadingButton>
				</div>
			</form>

			{onShowLogin && (
				<div className='text-muted-foreground text-center text-sm'>
					Remember your password?{' '}
					<Button
						variant='link'
						className='text-primary hover:text-primary/80 h-auto p-0 font-medium'
						onClick={onShowLogin}
						type='button'
					>
						Sign in
					</Button>
				</div>
			)}
		</div>
	);
}

/**
 * Auth Error Handling
 *
 * Centralized error code mapping and parsing for auth forms.
 * Handles GraphQL errors, validation errors (Zod-like), and custom AuthErrors.
 *
 * Backend error codes handled:
 * - INCORRECT_PASSWORD: Wrong password
 * - PASSWORD_INSECURE: Password doesn't meet security requirements
 * - ACCOUNT_LOCKED_EXCEED_ATTEMPTS: Too many failed login attempts
 * - ACCOUNT_DISABLED: Account has been disabled
 * - ACCOUNT_EXISTS: Email already registered
 * - PASSWORD_LEN: Password length invalid (must be 8-63 characters)
 * - INVITE_NOT_FOUND: Invitation code not found
 * - INVITE_LIMIT: Invitation usage limit reached
 * - INVITE_EMAIL_NOT_FOUND: Email not associated with invitation
 */

// ============================================================================
// Error Code Constants
// ============================================================================

/**
 * Known backend error codes.
 * These codes are returned in GraphQL error extensions.
 */
export const ERROR_CODES = {
	// Auth errors - login
	INVALID_CREDENTIALS: 'INVALID_CREDENTIALS', // Generic - prevents user enumeration
	INCORRECT_PASSWORD: 'INCORRECT_PASSWORD',
	ACCOUNT_LOCKED_EXCEED_ATTEMPTS: 'ACCOUNT_LOCKED_EXCEED_ATTEMPTS',
	ACCOUNT_DISABLED: 'ACCOUNT_DISABLED',

	// Password validation errors
	PASSWORD_INSECURE: 'PASSWORD_INSECURE',
	PASSWORD_LEN: 'PASSWORD_LEN',

	// Registration errors
	ACCOUNT_EXISTS: 'ACCOUNT_EXISTS',

	// Invitation errors
	INVITE_NOT_FOUND: 'INVITE_NOT_FOUND',
	INVITE_LIMIT: 'INVITE_LIMIT',
	INVITE_EMAIL_NOT_FOUND: 'INVITE_EMAIL_NOT_FOUND',
} as const;

export type ErrorCode = (typeof ERROR_CODES)[keyof typeof ERROR_CODES];

// ============================================================================
// User-Friendly Error Messages
// ============================================================================

/**
 * User-friendly error messages for each error code.
 * These messages are shown to users in the UI.
 */
export const ERROR_MESSAGES: Record<ErrorCode, string> = {
	[ERROR_CODES.INVALID_CREDENTIALS]: 'Invalid email or password.',
	[ERROR_CODES.INCORRECT_PASSWORD]: 'The password you entered is incorrect. Please try again.',
	[ERROR_CODES.ACCOUNT_LOCKED_EXCEED_ATTEMPTS]:
		'Your account has been temporarily locked due to too many failed login attempts. Please try again later or reset your password.',
	[ERROR_CODES.ACCOUNT_DISABLED]:
		'Your account has been disabled. Please contact support for assistance.',
	[ERROR_CODES.PASSWORD_INSECURE]:
		'This password is not secure enough. Please choose a stronger password.',
	[ERROR_CODES.PASSWORD_LEN]: 'Password must be between 8 and 63 characters long.',
	[ERROR_CODES.ACCOUNT_EXISTS]:
		'An account with this email already exists. Please sign in or use a different email.',
	[ERROR_CODES.INVITE_NOT_FOUND]:
		'The invitation code is invalid or has expired. Please check the code or request a new invitation.',
	[ERROR_CODES.INVITE_LIMIT]:
		'This invitation has reached its usage limit. Please request a new invitation.',
	[ERROR_CODES.INVITE_EMAIL_NOT_FOUND]:
		'This email is not associated with the invitation. Please use the email address the invitation was sent to.',
};

/**
 * Generic fallback message when no specific error code is matched.
 */
export const DEFAULT_ERROR_MESSAGE = 'Something went wrong. Please try again.';

// ============================================================================
// AuthError Class
// ============================================================================

/**
 * Custom error class for authentication errors.
 * Provides typed error codes that map to user-friendly messages.
 *
 * @example
 * ```ts
 * // Throw with a known error code
 * throw new AuthError('INVALID_CREDENTIALS');
 *
 * // Throw with custom message override
 * throw new AuthError('ACCOUNT_DISABLED', 'Your account has been suspended.');
 *
 * // In catch block, get user-friendly message
 * catch (err) {
 *   if (err instanceof AuthError) {
 *     setError(err.userMessage);
 *   }
 * }
 * ```
 */
export class AuthError extends Error {
	public readonly code: ErrorCode;
	public readonly userMessage: string;

	constructor(code: ErrorCode, customMessage?: string) {
		const userMessage = customMessage ?? ERROR_MESSAGES[code];
		super(userMessage);
		this.name = 'AuthError';
		this.code = code;
		this.userMessage = userMessage;

		if (Error.captureStackTrace) {
			Error.captureStackTrace(this, AuthError);
		}
	}

	/**
	 * Check if an error is an AuthError with a specific code.
	 */
	static isCode(error: unknown, code: ErrorCode): error is AuthError {
		return error instanceof AuthError && error.code === code;
	}
}

/**
 * Create an AuthError for invalid credentials.
 * Use this when login fails due to null token response.
 * The generic message prevents user enumeration attacks.
 */
export function createInvalidCredentialsError(): AuthError {
	return new AuthError('INVALID_CREDENTIALS');
}

// ============================================================================
// Configuration
// ============================================================================

/**
 * Options for parseGraphQLError.
 */
export interface ParseGraphQLErrorOptions {
	/**
	 * Custom fallback message when no known error code is matched.
	 * Defaults to DEFAULT_ERROR_MESSAGE.
	 */
	defaultMessage?: string;

	/**
	 * Custom error code to message mapping to extend or override defaults.
	 * Merged with ERROR_MESSAGES (custom takes precedence).
	 */
	customMessages?: Record<string, string>;
}

// ============================================================================
// Error Parsing Utilities
// ============================================================================

/**
 * Shape of a GraphQL error with extensions.
 */
interface GraphQLErrorLike {
	message?: string;
	extensions?: {
		code?: string;
		[key: string]: unknown;
	};
}

/**
 * Check if a value looks like a GraphQL error object.
 */
function isGraphQLErrorLike(value: unknown): value is GraphQLErrorLike {
	if (!value || typeof value !== 'object') return false;
	return 'message' in value || 'extensions' in value;
}

/**
 * Shape of a validation error (Zod-like).
 * Detected by duck typing to avoid tight coupling to Zod.
 */
interface ValidationErrorLike {
	name: string;
	issues: Array<{ message: string; path?: (string | number)[] }>;
}

/**
 * Check if a value looks like a Zod validation error.
 * Uses duck typing (name + issues array) for portability.
 */
function isValidationError(value: unknown): value is ValidationErrorLike {
	if (!value || typeof value !== 'object') return false;
	const err = value as Record<string, unknown>;
	return (
		err.name === 'ZodError' &&
		Array.isArray(err.issues) &&
		err.issues.length > 0 &&
		typeof err.issues[0]?.message === 'string'
	);
}

/**
 * Extract error code from various error formats.
 *
 * Checks (in order):
 * 1. AuthError instance (has typed code)
 * 2. error.extensions.code (GraphQL error format)
 * 3. error.code (generic error format)
 * 4. Error code embedded in message (e.g., "Error (Code: ACCOUNT_EXISTS)")
 * 5. Direct code match in error message (e.g., "ACCOUNT_EXISTS")
 */
function extractErrorCode(error: unknown, knownCodes: string[]): string | null {
	// Handle AuthError instances
	if (error instanceof AuthError) {
		return error.code;
	}

	// Handle GraphQLRequestError (has .errors array with GraphQL error objects)
	if (error && typeof error === 'object' && 'errors' in error) {
		const gqlErrors = (error as { errors: Array<{ message?: string; extensions?: Record<string, unknown> }> })
			.errors;
		if (Array.isArray(gqlErrors) && gqlErrors.length > 0) {
			const firstError = gqlErrors[0];
			if (firstError.extensions?.code) return String(firstError.extensions.code);
			if (firstError.message) {
				const codeMatch = firstError.message.match(/\(\s*[Cc]ode:\s*([A-Z_]+)\s*\)/);
				if (codeMatch) return codeMatch[1];
				for (const code of knownCodes) {
					if (firstError.message.includes(code)) return code;
				}
			}
		}
	}

	// Handle GraphQL error with extensions
	if (isGraphQLErrorLike(error) && error.extensions?.code) {
		return String(error.extensions.code);
	}

	// Handle error object with code property
	if (error && typeof error === 'object' && 'code' in error) {
		const code = (error as { code: unknown }).code;
		if (typeof code === 'string') return code;
	}

	// Extract message for pattern matching
	let message: string | null = null;
	if (error instanceof Error) {
		message = error.message;
	} else if (isGraphQLErrorLike(error) && error.message) {
		message = error.message;
	} else if (typeof error === 'string') {
		message = error;
	}

	if (!message) return null;

	// Try to extract code from message pattern: "(Code: ERROR_CODE)"
	const codeMatch = message.match(/\(\s*[Cc]ode:\s*([A-Z_]+)\s*\)/);
	if (codeMatch) {
		return codeMatch[1];
	}

	// Check if any known error code appears in the message
	for (const code of knownCodes) {
		if (message.includes(code)) {
			return code;
		}
	}

	return null;
}

/**
 * Check if an error code is a known error code.
 */
export function isKnownErrorCode(code: string | null): code is ErrorCode {
	if (!code) return false;
	return Object.values(ERROR_CODES).includes(code as ErrorCode);
}

/**
 * Get the user-friendly message for an error code.
 */
export function getErrorMessage(code: ErrorCode): string {
	return ERROR_MESSAGES[code];
}

/**
 * Check if a message looks like technical/internal error (not user-friendly).
 */
function isTechnicalMessage(message: string): boolean {
	const lower = message.toLowerCase();
	return (
		lower.includes('graphql') ||
		lower.includes('fetch') ||
		lower.includes('network') ||
		lower.includes('econnrefused') ||
		lower.includes('undefined') ||
		lower.includes('null') ||
		lower.includes('timeout') ||
		lower.includes('connection') ||
		lower.includes('socket') ||
		lower.includes('enotfound') ||
		lower.includes('abort')
	);
}

// ============================================================================
// Main Parse Function
// ============================================================================

/**
 * Result of parsing a GraphQL error.
 */
export interface ParsedGraphQLError {
	/** The extracted error code, if any */
	code: string | null;
	/** User-friendly error message */
	message: string;
	/** Whether a known error code was found */
	isKnownError: boolean;
	/** Original error for debugging */
	originalError: unknown;
}

/**
 * Parse a GraphQL error and return a user-friendly message.
 *
 * This function:
 * 1. Extracts the error code from various error formats
 * 2. Maps known codes to user-friendly messages
 * 3. Falls back to generic message for unknown/technical errors
 *
 * @param error - The error to parse (can be Error, GraphQL error, string, etc.)
 * @param options - Optional configuration for custom messages
 * @returns ParsedGraphQLError with code, message, and metadata
 *
 * @example
 * ```ts
 * // Basic usage
 * const { message } = parseGraphQLError(error);
 * setError(message);
 *
 * // With custom default message
 * const { message } = parseGraphQLError(error, {
 *   defaultMessage: 'Unable to sign in. Please try again.'
 * });
 *
 * // With custom error code mappings
 * const { message } = parseGraphQLError(error, {
 *   customMessages: {
 *     'CUSTOM_ERROR': 'A custom error occurred.',
 *   }
 * });
 * ```
 */
export function parseGraphQLError(
	error: unknown,
	options: ParseGraphQLErrorOptions = {}
): ParsedGraphQLError {
	// Fast path for AuthError - already has user-friendly message
	if (error instanceof AuthError) {
		return {
			code: error.code,
			message: error.userMessage,
			isKnownError: true,
			originalError: error,
		};
	}

	// Handle validation errors (Zod-like) - detect by shape, not import
	// This keeps the module portable without tight coupling to Zod
	if (isValidationError(error)) {
		// Get the first error message (most relevant for form validation)
		const firstIssue = error.issues[0];
		const message = firstIssue?.message || 'Validation failed. Please check your input.';
		return {
			code: 'VALIDATION_ERROR',
			message,
			isKnownError: true,
			originalError: error,
		};
	}

	const { defaultMessage = DEFAULT_ERROR_MESSAGE, customMessages = {} } = options;

	// Merge custom messages with defaults (custom takes precedence)
	const allMessages: Record<string, string> = { ...ERROR_MESSAGES, ...customMessages };
	const allKnownCodes = Object.keys(allMessages);

	const code = extractErrorCode(error, allKnownCodes);
	const isKnown = code !== null && code in allMessages;

	let message: string;
	if (isKnown && code) {
		message = allMessages[code];
	} else {
		// Use error message if available and not technical
		if (error instanceof Error && error.message && !isTechnicalMessage(error.message)) {
			message = error.message;
		} else if (
			error instanceof Error &&
			isTechnicalMessage(error.message) &&
			'errors' in error &&
			Array.isArray((error as { errors: unknown[] }).errors)
		) {
			// Extract user-friendly message from GraphQLRequestError's inner errors
			const innerMsg = (
				(error as { errors: Array<{ message?: string }> }).errors[0] as { message?: string } | undefined
			)?.message;
			message = innerMsg && !isTechnicalMessage(innerMsg) ? innerMsg : defaultMessage;
		} else {
			message = defaultMessage;
		}
	}

	return {
		code: isKnown ? code : null,
		message,
		isKnownError: isKnown,
		originalError: error,
	};
}

import { z } from 'zod';

/**
 * Password validation schema with strong requirements
 */
const passwordSchema = z
	.string()
	.min(8, 'Password must be at least 8 characters')
	.regex(
		/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/,
		'Password must contain uppercase, lowercase, number, and special character',
	);

/**
 * Email validation schema
 */
const emailSchema = z.string().email('Please enter a valid email address');

/**
 * Login form validation schema
 */
export const loginSchema = z.object({
	email: emailSchema,
	password: z.string().min(1, 'Password is required'),
	rememberMe: z.boolean().optional(),
});

/**
 * Registration form validation schema
 * Backend only receives email/password - confirmPassword is frontend-only validation
 * Password strength is validated by backend to avoid duplicate/conflicting rules
 */
export const registerSchema = z
	.object({
		email: emailSchema,
		password: z.string().min(1, 'Password is required'),
		confirmPassword: z.string().min(1, 'Please confirm your password'),
	})
	.refine((data) => data.password === data.confirmPassword, {
		message: 'Passwords do not match',
		path: ['confirmPassword'],
	});

/**
 * Forgot password form validation schema
 */
export const forgotPasswordSchema = z.object({
	email: emailSchema,
});

/**
 * Reset password form validation schema
 */
export const resetPasswordSchema = z
	.object({
		password: passwordSchema,
		confirmPassword: z.string(),
		token: z.string().min(1, 'Reset token is required'),
	})
	.refine((data) => data.password === data.confirmPassword, {
		message: 'Passwords do not match',
		path: ['confirmPassword'],
	});

/**
 * TypeScript types inferred from schemas
 */
export type LoginFormData = z.infer<typeof loginSchema>;
export type RegisterFormData = z.infer<typeof registerSchema>;
export type ForgotPasswordFormData = z.infer<typeof forgotPasswordSchema>;
export type ResetPasswordFormData = z.infer<typeof resetPasswordSchema>;

const KEY_PREFIX = 'sheets-auth-token';

function storageKey(databaseId: string): string {
	return `${KEY_PREFIX}:${databaseId}`;
}

function getStorage(): Storage | null {
	if (typeof window === 'undefined') return null;
	try {
		return window.localStorage;
	} catch {
		return null;
	}
}

export interface StoredToken {
	accessToken: string;
	expiresAt: string;
	identityKey?: string | null;
}

export function getStoredToken(databaseId: string): StoredToken | null {
	const storage = getStorage();
	if (!storage) return null;

	try {
		const raw = storage.getItem(storageKey(databaseId));
		if (!raw) return null;
		const parsed = JSON.parse(raw) as StoredToken;
		if (!parsed.accessToken || !parsed.expiresAt) return null;
		if (parsed.identityKey != null && typeof parsed.identityKey !== 'string') return null;
		return parsed;
	} catch {
		return null;
	}
}

export function setStoredToken(
	databaseId: string,
	accessToken: string,
	expiresAt: string,
	identityKey?: string | null,
): void {
	const storage = getStorage();
	if (!storage) return;

	try {
		const data: StoredToken = { accessToken, expiresAt, identityKey };
		storage.setItem(storageKey(databaseId), JSON.stringify(data));
	} catch {
		// Silently fail — localStorage might be full or unavailable
	}
}

export function clearStoredToken(databaseId: string): void {
	const storage = getStorage();
	if (!storage) return;

	try {
		storage.removeItem(storageKey(databaseId));
	} catch {
		// Silently fail
	}
}

/**
 * Custom validation functions for authentication forms
 */

/**
 * Calculate password strength score (0-5)
 */
export function getPasswordStrength(password: string): number {
	let score = 0;

	// Length check
	if (password.length >= 8) score++;

	// Character variety checks
	if (/[a-z]/.test(password)) score++;
	if (/[A-Z]/.test(password)) score++;
	if (/\d/.test(password)) score++;
	if (/[@$!%*?&]/.test(password)) score++;

	return score;
}

/**
 * Get password strength label
 */
export function getPasswordStrengthLabel(score: number): string {
	const labels = ['Very Weak', 'Weak', 'Fair', 'Good', 'Strong'];
	return labels[score - 1] || 'Very Weak';
}

/**
 * Get password strength color class
 */
export function getPasswordStrengthColor(score: number): string {
	const colors = ['bg-red-500', 'bg-orange-500', 'bg-yellow-500', 'bg-blue-500', 'bg-green-500'];
	return colors[score - 1] || 'bg-red-500';
}

/**
 * Validate email format (additional validation beyond zod)
 */
export function validateEmail(email: string): boolean {
	const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
	return emailRegex.test(email);
}

/**
 * Check if password meets minimum requirements
 */
export function isPasswordValid(password: string): boolean {
	return getPasswordStrength(password) >= 3;
}

/**
 * Async email availability check (placeholder - integrate with your API)
 */
export async function checkEmailAvailability(email: string): Promise<boolean> {
	// Placeholder implementation - replace with actual API call
	return new Promise((resolve) => {
		setTimeout(() => {
			// Simulate API call
			const unavailableEmails = ['admin@example.com', 'test@example.com'];
			resolve(!unavailableEmails.includes(email));
		}, 500);
	});
}

/**
 * Validate password confirmation
 */
export function validatePasswordConfirmation(password: string, confirmPassword: string): boolean {
	return password === confirmPassword && password.length > 0;
}

// The badge / category color system (DESIGN_SPEC §7) — the signature element.
//
// Category pills render as a tinted chip: a soft same-hue background paired with
// saturated same-hue text. The DEFAULT tone is `neutral`; color is OPT-IN. The
// consumer assigns a tone per value via a `Record<string, BadgeTone>` overrides
// map (exact value -> tone) or a `(value) => BadgeTone | undefined` resolver
// (e.g. CRM grids letting users color their own categories). There is NO
// automatic hashing — an unconfigured grid stays calm and on-brand, resolving
// every value to `neutral`.
//
// `neutral` is the only tone built from semantic tokens (so it themes for free);
// the 8-hue categorical palette below is intentional data-viz color and ships
// explicit `dark:` pairs — the one sanctioned exception to the tokens-not-palette
// law (§6).

export type BadgeTone = 'neutral' | 'blue' | 'green' | 'amber' | 'red' | 'purple' | 'pink' | 'teal';

export const BADGE_TONES: Record<BadgeTone, string> = {
	neutral: 'bg-muted text-muted-foreground',
	blue: 'bg-blue-50 text-blue-700 dark:bg-blue-500/15 dark:text-blue-300',
	green: 'bg-emerald-50 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-300',
	amber: 'bg-amber-50 text-amber-700 dark:bg-amber-500/15 dark:text-amber-300',
	red: 'bg-rose-50 text-rose-700 dark:bg-rose-500/15 dark:text-rose-300',
	purple: 'bg-violet-50 text-violet-700 dark:bg-violet-500/15 dark:text-violet-300',
	pink: 'bg-pink-50 text-pink-700 dark:bg-pink-500/15 dark:text-pink-300',
	teal: 'bg-teal-50 text-teal-700 dark:bg-teal-500/15 dark:text-teal-300',
};

/**
 * Resolve a badge value to its tone. Resolution order (first hit wins):
 *   1. `overrides[value]` — exact value -> tone map.
 *   2. `resolver?.(value)` — programmatic resolver.
 *   3. `'neutral'` — the default; color is neutral-until-configured.
 *
 * No automatic hashing: an unmapped value is always `neutral`.
 */
export function resolveBadgeTone(
	value: string,
	overrides?: Record<string, BadgeTone>,
	resolver?: (v: string) => BadgeTone | undefined,
): BadgeTone {
	return overrides?.[value] ?? resolver?.(value) ?? 'neutral';
}

// Public component contract for a native DOM cell view. Pure types.

import type { CellType } from '../cell-types/types';
import type { SheetsCell } from './sheets-cell';

/** Smallest render-column descriptor a cell view needs now. Overridable. */
export interface CellColumnDescriptor {
	key: string;
	name: string;
	cellType: CellType;
}

/** Props every native cell view receives. Minimal and overridable. */
export interface CellProps {
	cell: SheetsCell;
	value: unknown;
	colKey: string;
	rowId: string;
	rowIndex: number;
	column: CellColumnDescriptor;
	isEditing: boolean;
