}

// Consumer-facing cell-component override slots. A thin sugar over the native
// `cell` field of a CellTypeDefinition: a `CellSlots` map (keyed by cell typeKey)
// compiles down to component-only CellTypeDefinitions that the registry resolves
// via `getCellComponent`. Pure logic — no React render, no glide.

import type { CellTypeDefinition } from '../cell-types/define-cell-type';
import type { CellProps } from './cell-props';
import type { EditorProps } from '../grid-dom/editors/editor-props';

/**
 * A single slot: either a bare cell component, or an object overriding the cell
 * view and/or the native editor for a typeKey. The object form lets a consumer
 * override JUST the editor (`{ editor: MyEditor }`) without touching the view.
 */
export type CellSlot =
	| React.ComponentType<CellProps>
	| { cell?: React.ComponentType<CellProps>; editor?: React.ComponentType<EditorProps> };

/** Consumer cell-component / editor overrides keyed by cell typeKey. */
export type CellSlots = Record<string, CellSlot>;

/**
 * Compile a {@link CellSlots} map into {@link CellTypeDefinition}s. The function
 * form yields `{ typeKey, cell }` (view-only); the object form yields
 * `{ typeKey, cell?, editorComponent? }`. Entries that resolve to neither a cell
 * nor an editor (e.g. `{ json: {} }`) are skipped. Returns `[]` for empty/undefined.
 */
export function compileSlots(slots: CellSlots | undefined): CellTypeDefinition[] {
	if (!slots) return [];
	const defs: CellTypeDefinition[] = [];
	for (const [typeKey, slot] of Object.entries(slots)) {
		if (typeof slot === 'function') {
			defs.push({ typeKey, cell: slot });
			continue;
		}
		const { cell, editor } = slot;
		if (!cell && !editor) continue;
		defs.push({ typeKey, cell, editorComponent: editor });
	}
	return defs;
}

// The SheetsCell DISPATCHER — the native analogue of v1's `createCellContent`
// (grid/cell-content-factory.ts). Given a (value, metadata) it selects the first
// family factory whose `canHandle(cellType, value)` is true and returns its
// neutral {@link SheetsCell} render payload. Geometry stays out-of-band: the
// optional `deriveGeometry` hook is threaded straight through to the geometry
// factory (v1's `createGeometryCell` mirror) so this module never imports the
// leaflet-backed geometry view.
//
// Precedence MIRRORS v1 CELL_FACTORIES exactly (image, uri, badges, dateTime,
// interval, geometry, relation, number, boolean, text) — `text` is the universal
// fallback and MUST stay last. Null handling mirrors `createEmptyCell`: pick the
// first factory that claims the cellType for a null value and let it emit its own
// empty cell.

import type { CellType } from '../cell-types/types';
import type { CellCreationMetadata } from '../grid/grid-cell-types';
import { badgesSheetsCellFactory } from './factories/badges';
import { booleanSheetsCellFactory } from './factories/boolean';
import { dateTimeSheetsCellFactory } from './factories/datetime';
import { geometrySheetsCellFactory } from './factories/geometry';
import { imageSheetsCellFactory } from './factories/image';
import { intervalSheetsCellFactory } from './factories/interval';
import { numberSheetsCellFactory } from './factories/number';
import { relationSheetsCellFactory } from './factories/relation';
import { textSheetsCellFactory } from './factories/text';
import type { SheetsCellFactory } from './factories/types';
import { uriSheetsCellFactory } from './factories/uri';
import type { SheetsCell } from './sheets-cell';

// Registry of all SheetsCell factories — SAME precedence as glide CELL_FACTORIES
// (more specific first; the text fallback MUST be last).
const SHEETS_CELL_FACTORIES: SheetsCellFactory[] = [
	imageSheetsCellFactory,
	uriSheetsCellFactory,
	badgesSheetsCellFactory,
	dateTimeSheetsCellFactory,
	intervalSheetsCellFactory,
	geometrySheetsCellFactory,
	relationSheetsCellFactory,
	numberSheetsCellFactory,
	booleanSheetsCellFactory,
	textSheetsCellFactory, // Fallback — must be last.
];

/**
 * Build the neutral {@link SheetsCell} for a (value, metadata). Mirrors v1
 * `createCellContent`: null/undefined → the first claiming factory's empty cell
 * (mirror of `createEmptyCell`); otherwise the first factory whose
 * `canHandle(cellType, value)` is true. `deriveGeometry` is threaded to the
 * geometry factory unchanged. The `text` factory's `canHandle` always returns
 * true, so a factory is always found and the explicit final fallback below is a
 * defensive belt-and-braces guard.
 */
/**
 * Stamp the resolved cellType onto the cell's `meta` so the cell SELF-DESCRIBES
 * its type (the host reads `SheetsCellResolution.typeKey`, but the cell carrying
 * `meta.cellType` keeps it self-contained for the editor adapters that already
 * read it — date/geometry). MERGE (not replace) so any factory-set meta key
 * (e.g. geometry's `geometryType`) survives. This does not change display or
 * copy text because projection ignores `meta`.
 */
function withTypeKey(cell: SheetsCell, cellType: string): SheetsCell {
	return { ...cell, meta: { ...cell.meta, cellType: cellType as CellType } };
}

export function createSheetsCell(
	value: unknown,
	metadata: CellCreationMetadata,
	deriveGeometry?: (value: unknown) => SheetsCell,
): SheetsCell {
	const { cellType } = metadata;

	if (value === null || value === undefined) {
		const emptyFactory = SHEETS_CELL_FACTORIES.find((f) => f.canHandle(cellType, null));
		if (emptyFactory) {
			return withTypeKey(emptyFactory.create(null, metadata, deriveGeometry), cellType);
		}
		return withTypeKey({ kind: 'text', data: '', displayData: '', readonly: false }, cellType);
	}

	const factory = SHEETS_CELL_FACTORIES.find((f) => f.canHandle(cellType, value));
	if (factory) {
		return withTypeKey(factory.create(value, metadata, deriveGeometry), cellType);
	}

	return withTypeKey(
		{
			kind: 'text',
			data: value,
			displayData: String(value),
			readonly: false,
		},
		cellType,
	);
}

// Badges SheetsCell factory — native analogue of v1 `ArrayCellFactory`.
//
// Owns the array/bubble family: every array-like cellType plus `tsvector`. The
// glide `BubbleCell` carries `data: string[]` and NO `displayData`, so the
// neutral payload mirrors that exactly — `data` is the string[] (copyText ===
// JSON.stringify(array)), `displayData` is '' (no display side in v1), and the
// kind is the neutral `badges`. ALL domain logic from v1 is ported verbatim
// (tags array/comma-string, tsvector lexeme preview, generic per-item
// stringify, null/undefined -> [], non-array fallback -> [String(value)]); the
// tsvector parser is copied in so this file never imports the glide factory
// (which is deleted at cutover).

import type { CellType } from '../../cell-types/types';
import { isArrayCellType } from '../../cell-types/cell-type-groups';
import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

// Minimal tsvector parser for previews — copied verbatim from v1
// cell-content-factory.ts (do NOT import it; it stays glide-only).
function parseTsvectorForPreview(tsvector: string): Array<{ lexeme: string; weights: Array<'A' | 'B' | 'C' | 'D'> }> {
	if (!tsvector || typeof tsvector !== 'string') return [];
	const results: Array<{ lexeme: string; weights: Array<'A' | 'B' | 'C' | 'D'> }> = [];
	try {
		const regex = /'([^']+)':([0-9A-D,]+)/g;
		let match: RegExpExecArray | null;
		while ((match = regex.exec(tsvector)) !== null) {
			const lexeme = match[1];
			const posStr = match[2];
			const weights = Array.from(
				new Set(
					posStr
						.split(',')
						.map((p) => p.match(/[A-D]$/)?.[0] as 'A' | 'B' | 'C' | 'D' | undefined)
						.filter((w): w is 'A' | 'B' | 'C' | 'D' => !!w),
				),
			).sort();
			results.push({ lexeme, weights });
		}
	} catch {
		// ignore parsing errors
	}
	return results;
}

// Compute the string[] the v1 BubbleCell put in `.data`, branch-for-branch.
function deriveBadges(value: unknown, metadata: CellCreationMetadata): string[] {
	if (value === null || value === undefined) {
		return [];
	}

	if (metadata.cellType === 'tags') {
		if (Array.isArray(value)) {
			return value.map((v) => (v == null ? '' : String(v))).filter((v) => v.length > 0);
		}
		if (typeof value === 'string') {
			return value
				.split(',')
				.map((v) => v.trim())
				.filter((v) => v.length > 0);
		}
	}

	if (metadata.cellType === 'tsvector' && typeof value === 'string') {
		const tokens = parseTsvectorForPreview(value);
		return tokens.map((t) => (t.weights.length ? `${t.lexeme} ${t.weights.join(',')}` : t.lexeme));
	}

	if (Array.isArray(value)) {
		return value.map((item) => {
			if (item === null || item === undefined) return '';
			if (typeof item === 'string') return item;
			if (typeof item === 'number') return String(item);
			if (typeof item === 'boolean') return String(item);
			if (item instanceof Date) return item.toISOString().split('T')[0];
			if (typeof item === 'object') return JSON.stringify(item);
			return String(item);
		});
	}

	return [String(value)];
}

export const badgesSheetsCellFactory: SheetsCellFactory = {
	canHandle(cellType: string, _value: unknown): boolean {
		return isArrayCellType(cellType) || cellType === 'tsvector';
	},

	create(value: unknown, metadata: CellCreationMetadata): SheetsCell {
		return {
			kind: 'badges',
			data: deriveBadges(value, metadata),
			displayData: '',
			readonly: false,
			meta: { cellType: metadata.cellType as CellType },
		};
	},
};

// Boolean SheetsCell factory — native analogue of v1's BooleanCellFactory
// (grid/cell-content-factory.ts). Claims BOOLEAN_TYPES (boolean, bit, toggle).
//
// The BooleanCell keeps the boolean in `data` for copying and leaves
// `displayData` empty because the view owns its visual representation.

import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import { BOOLEAN_TYPES } from '../../cell-types/cell-type-groups';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

function canHandle(cellType: string, _value: unknown): boolean {
	return BOOLEAN_TYPES.has(cellType);
}

function create(value: unknown, _metadata: CellCreationMetadata): SheetsCell {
	const boolValue = value === null || value === undefined ? false : typeof value === 'boolean' ? value : Boolean(value);
	return { kind: 'boolean', data: boolValue, displayData: '', readonly: false };
}

export const booleanSheetsCellFactory: SheetsCellFactory = { canHandle, create };

// SheetsCell factory for the datetime family — native analogue of v1's
// DateTimeCellFactory (cell-content-factory.ts). Claims the DATE_TIME_TYPES
// (date, datetime, time, timestamptz) and emits a neutral `text` cell carrying
// the value's string form. v1 renders the raw value as formatted text: non-null
// -> data/displayData = String(value); null/undefined -> both ''. This factory
// preserves that display and copy behavior.

import type { CellType } from '../../cell-types/types';
import { DATE_TIME_TYPES } from '../../cell-types/cell-type-groups';
import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

function canHandle(cellType: string, _value: unknown): boolean {
	return DATE_TIME_TYPES.has(cellType);
}

function create(value: unknown, metadata: CellCreationMetadata): SheetsCell {
	const meta = { cellType: metadata.cellType as CellType };

	if (value === null || value === undefined) {
		return { kind: 'text', data: '', displayData: '', readonly: false, meta };
	}

	const text = String(value);
	return { kind: 'text', data: text, displayData: text, readonly: false, meta };
}

export const dateTimeSheetsCellFactory: SheetsCellFactory = { canHandle, create };

// Geometry SheetsCell factory — native analogue of v1 `GeometryCellFactory`.
//
// Owns GEOMETRY_TYPES (geometry, geometry-point, geometry-collection). Geometry
// stays out-of-band: when the caller supplies a `deriveGeometry` builder (the
// native mirror of v1's `createGeometryCell`), this factory delegates to it so
// this module never imports the leaflet-backed geometry view. Without a builder,
// it falls back to a compact JSON preview as both the copy value and the display
// string — identical to v1's Text fallback.
//
// Copy and display text intentionally use the same compact JSON preview when no
// geometry-specific builder is available.

import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import { GEOMETRY_TYPES } from '../../cell-types/cell-type-groups';
import { compactJsonPreview } from '../../grid/sheets.formatters';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

function canHandle(cellType: string, _value: unknown): boolean {
	return GEOMETRY_TYPES.has(cellType);
}

function create(
	value: unknown,
	_metadata: CellCreationMetadata,
	deriveGeometry?: (value: unknown) => SheetsCell,
): SheetsCell {
	if (deriveGeometry) {
		return deriveGeometry(value ?? null);
	}

	const display = compactJsonPreview(value, 80);
	return {
		kind: 'geometry',
		data: display,
		displayData: display,
		readonly: false,
	};
}

export const geometrySheetsCellFactory: SheetsCellFactory = { canHandle, create };

// Native SheetsCell factory for the MEDIA family (image/file/video/audio/upload).
//
// Ports v1 `ImageCellFactory` (grid/cell-content-factory.ts). The glide cell put
// the resolved URL in BOTH `data` and `displayData` as a single-element array
// (`[url]`); empty/null/'' collapses to `['']`. The neutral SheetsCell keeps the
// SAME `data: [url]` array (so copyText === JSON.stringify([url]) like glide) and
// sets `displayData` to the STRING form of that array (JSON.stringify) so the
// `image` kind — projected via stringifyField, NOT the geometry/custom branch —
// yields the SAME displayText glide produced from its array `displayData`.
//
// URL extraction logic copied verbatim (NOT imported from cell-content-factory,
// which stays glide-only and is deleted at cutover).

import type { CellType } from '../../cell-types/types';
import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import { MEDIA_TYPES } from '../../cell-types/cell-type-groups';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

/** Resolve a media URL from a string or an object's url/src/href/path keys (v1 order). */
function resolveMediaUrl(value: unknown): string {
	if (typeof value === 'string') return value;
	if (typeof value === 'object' && value) {
		const obj = value as Record<string, unknown>;
		return (obj.url || obj.src || obj.href || obj.path || '') as string;
	}
	return '';
}

export const imageSheetsCellFactory: SheetsCellFactory = {
	canHandle(cellType: string): boolean {
		return MEDIA_TYPES.has(cellType);
	},

	create(value: unknown, metadata: CellCreationMetadata): SheetsCell {
		const url = value === null || value === undefined || value === '' ? '' : resolveMediaUrl(value);
		const data = [url];
		return {
			kind: 'image',
			data,
			displayData: JSON.stringify(data),
			readonly: false,
			meta: { cellType: metadata.cellType as CellType }
		};
	}
};

// Interval SheetsCell factory — native analogue of v1 `IntervalCellFactory`
// (grid/cell-content-factory.ts). Claims `cellType === 'interval'` and emits a
// neutral `text` SheetsCell whose displayData is the compact interval label and
// whose data is the raw string (or JSON of the object). The display/copy
// projection parity with the glide factory is the whole point of this phase.
//
// `formatIntervalForDisplay` (+ its `IntervalValue` shape) is interval-only domain
// logic copied VERBATIM from cell-content-factory.ts — it is intentionally NOT
// imported, because that module stays glide-only and is deleted at cutover.

import type { CellType } from '../../cell-types/types';
import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

// PostgreSQL interval value structure
interface IntervalValue {
	years?: number;
	months?: number;
	days?: number;
	hours?: number;
	minutes?: number;
	seconds?: number;
}

/**
 * Format a PostgreSQL interval value for compact cell display.
 * Shows only non-zero units in descending order of magnitude.
 * Examples: "1y 6mo", "2h 30m", "7d", "45s"
 */
function formatIntervalForDisplay(value: unknown): string {
	if (value === null || value === undefined) return '';

	let interval: IntervalValue;

	if (typeof value === 'string') {
		try {
			interval = JSON.parse(value);
		} catch {
			if (/\d+[yMwdhms]/.test(value)) {
				return value;
			}
			return value;
		}
	} else if (typeof value === 'object') {
		interval = value as IntervalValue;
	} else {
		return String(value);
	}

	const parts: string[] = [];

	if (interval.years && interval.years !== 0) {
		parts.push(`${interval.years}y`);
	}
	if (interval.months && interval.months !== 0) {
		parts.push(`${interval.months}mo`);
	}
	if (interval.days && interval.days !== 0) {
		parts.push(`${interval.days}d`);
	}
	if (interval.hours && interval.hours !== 0) {
		parts.push(`${interval.hours}h`);
	}
	if (interval.minutes && interval.minutes !== 0) {
		parts.push(`${interval.minutes}m`);
	}
	if (interval.seconds && interval.seconds !== 0) {
		const secs = interval.seconds;
		if (Number.isInteger(secs)) {
			parts.push(`${secs}s`);
		} else {
			parts.push(`${secs.toFixed(1)}s`);
		}
	}

	if (parts.length === 0) {
		return '0s';
	}

	return parts.join(' ');
}

function canHandle(cellType: string, _value: unknown): boolean {
	return cellType === 'interval';
}

function create(value: unknown, metadata: CellCreationMetadata): SheetsCell {
	if (value === null || value === undefined) {
		return {
			kind: 'text',
			data: '',
			displayData: '',
			readonly: false,
			meta: { cellType: metadata.cellType as CellType },
		};
	}

	const displayValue = formatIntervalForDisplay(value);
	const dataValue = typeof value === 'string' ? value : JSON.stringify(value);

	return {
		kind: 'text',
		data: dataValue,
		displayData: displayValue,
		readonly: false,
		meta: { cellType: metadata.cellType as CellType },
	};
}

export const intervalSheetsCellFactory: SheetsCellFactory = { canHandle, create };

// Number SheetsCell factory — native analogue of v1's NumberCellFactory
// (grid/cell-content-factory.ts). Claims NUMBER_TYPES (number, integer, smallint,
// decimal, currency, percentage, AND `rating` — `rating` lives in NUMBER_TYPES so
// the number family wins it before the text fallback; this is a deliberate v1
// quirk preserved for parity).
//
// Null, undefined, and invalid values become an empty cell. Valid values keep
// the numeric data and a string display value.

import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import { NUMBER_TYPES } from '../../cell-types/cell-type-groups';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

function canHandle(cellType: string, _value: unknown): boolean {
	return NUMBER_TYPES.has(cellType);
}

function create(value: unknown, _metadata: CellCreationMetadata): SheetsCell {
	if (value === null || value === undefined) {
		return { kind: 'number', data: undefined, displayData: '', readonly: false };
	}

	const numValue = typeof value === 'number' ? value : parseFloat(value as string);
	if (isNaN(numValue)) {
		return { kind: 'number', data: undefined, displayData: '', readonly: false };
	}

	return { kind: 'number', data: numValue, displayData: String(numValue), readonly: false };
}

export const numberSheetsCellFactory: SheetsCellFactory = { canHandle, create };

// Native SheetsCell factory for the `relation` family — the port of v1's glide
// `RelationCellFactory` (grid/cell-content-factory.ts). Owns BOTH single relations
// (belongsTo/hasOne — glide emitted a Text cell) and list relations
// (hasMany/manyToMany — glide emitted a Bubble cell); both collapse to the single
// neutral kind `relation`. All label-derivation + chip-overflow domain logic is
// copied verbatim from v1 (no import from cell-content-factory.ts — that module
// stays glide-only and is deleted at cutover).
//
// Single relations use their label for data and display. List relations keep
// their final chips in data while the relation view owns their visual display.

import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import { compactJsonPreview } from '../../grid/sheets.formatters';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

// ─── Domain constants (copied verbatim from v1 RelationCellFactory) ──────────
const DEFAULT_MAX_RELATION_CHIPS = 3;
const DEFAULT_RELATION_LABEL_MAX_LEN = 24;

const RELATION_ID_KEYS = new Set(['id', 'uuid', 'rowId', 'nodeId']);

function truncateLabel(s: string, max: number): string {
	if (s.length <= max) return s;
	if (max <= 1) return '…';
	return s.slice(0, Math.max(0, max - 1)) + '…';
}

// Copied verbatim from v1 `RelationCellFactory.deriveRelationLabel`, lifted from a
// private method to a pure function (metadata threaded as an explicit argument).
function deriveRelationLabel(relationValue: any, metadata: CellCreationMetadata, maxLength: number): string {
	if (relationValue == null) return '';

	// Suppress draft placeholder IDs from being displayed as relation labels
	if (typeof relationValue === 'string' && relationValue.startsWith('draft:')) return '';
	if (
		typeof relationValue === 'object' &&
		!Array.isArray(relationValue) &&
		typeof (relationValue as Record<string, unknown>).id === 'string' &&
		((relationValue as Record<string, unknown>).id as string).startsWith('draft:')
	)
		return '';

	const ensureString = (val: unknown): string => {
		if (val == null) return '';
		const str = String(val).trim();
		if (!str || str.toLowerCase() === 'null') return '';
		return str;
	};

	if (typeof relationValue === 'string' || typeof relationValue === 'number') {
		return truncateLabel(ensureString(relationValue), maxLength);
	}

	if (Array.isArray(relationValue)) {
		const labels = relationValue
			.map((item) => deriveRelationLabel(item, metadata, maxLength))
			.filter((label) => label.length > 0);
		return labels.join(', ');
	}

	if (typeof relationValue !== 'object') {
		return truncateLabel(ensureString(relationValue), maxLength);
	}

	const relInfo = metadata.relationInfo;
	const candidatesFromMeta: string[] = relInfo?.displayCandidates ?? [];
	const objectValue = relationValue as Record<string, unknown>;
	const keys = Object.keys(objectValue);

	// Try name-like display candidates first (exclude id/uuid — those are last resort)
	const meaningfulCandidates = candidatesFromMeta.filter((k) => !RELATION_ID_KEYS.has(k));

	const heuristicKeys = Array.from(
		new Set([
			...meaningfulCandidates,
			...keys.filter((key) => /(name|label|title|display|email)/i.test(key)),
			'displayName',
			'fullName',
			'name',
			'title',
			'label',
			'description',
			'username',
			'email',
			'code',
		]),
	);

	for (const candidate of heuristicKeys) {
		if (!candidate) continue;
		const candidateValue = ensureString(objectValue[candidate]);
		if (candidateValue) {
			return truncateLabel(candidateValue, maxLength);
		}
	}

	// Last resort: id/uuid
	for (const idKey of ['id', 'uuid']) {
		const idVal = ensureString(objectValue[idKey]);
		if (idVal) {
			return truncateLabel(idVal, maxLength);
		}
	}

	const firstPrimitive = keys
		.map((key) => objectValue[key])
		.find((val) => val != null && ['string', 'number', 'boolean'].includes(typeof val));
	if (firstPrimitive !== undefined) {
		return truncateLabel(ensureString(firstPrimitive), maxLength);
	}

	return truncateLabel(compactJsonPreview(objectValue, 80), maxLength);
}

function canHandle(cellType: string, _value: unknown): boolean {
	return cellType === 'relation';
}

function create(value: unknown, metadata: CellCreationMetadata, _deriveGeometry?: (value: unknown) => SheetsCell): SheetsCell {
	const relInfo = metadata.relationInfo;
	const relOptions = metadata.relationOptions;
	const chipLimit = relOptions?.relationChipLimit ?? DEFAULT_MAX_RELATION_CHIPS;
	const labelMax = relOptions?.relationLabelMaxLength ?? DEFAULT_RELATION_LABEL_MAX_LEN;

	const isListRelation = relInfo?.kind === 'hasMany' || relInfo?.kind === 'manyToMany';

	if (isListRelation) {
		const arr = Array.isArray(value) ? value : [];
		const labelsAll = arr
			.map((entry) => deriveRelationLabel(entry, metadata, labelMax))
			.filter((label) => label.length > 0);
		const labels = labelsAll.slice(0, chipLimit);
		const remaining = labelsAll.length - labels.length;
		const finalData = remaining > 0 ? [...labels, `+${remaining}`] : labels;
		// glide emitted a Bubble cell (no displayData) -> displayData projects to ''.
		return {
			kind: 'relation',
			data: finalData,
			displayData: '',
			readonly: false,
		};
	}

	const label = deriveRelationLabel(value, metadata, labelMax);
	// glide emitted a Text cell -> data = displayData = label.
	return {
		kind: 'relation',
		data: label,
		displayData: label,
		readonly: false,
	};
}

export const relationSheetsCellFactory: SheetsCellFactory = { canHandle, create };

// Default (fallback) SheetsCell factory — native analogue of v1's TextCellFactory
// (grid/cell-content-factory.ts). It is the LAST factory in dispatcher precedence:
// `canHandle` returns true for every cellType, so it only WINS the types no
// earlier family claimed (text, textarea, phone, citext, bpchar, json, jsonb,
// inet, uuid, color, origin, unknown).
//
// v1 emits a Text glide cell: null/undefined -> data/displayData ''; string ->
// data/displayData = value; anything else -> compactJsonPreview(value, 80) for
// both. `compactJsonPreview` is shared (sheets.formatters), so it is imported
// rather than copied.

import type { CellType } from '../../cell-types/types';
import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import { compactJsonPreview } from '../../grid/sheets.formatters';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

function canHandle(_cellType: string, _value: unknown): boolean {
	return true;
}

function create(value: unknown, metadata: CellCreationMetadata): SheetsCell {
	const meta = { cellType: metadata.cellType as CellType };

	if (value === null || value === undefined) {
		return { kind: 'text', data: '', displayData: '', readonly: false, meta };
	}

	if (typeof value === 'string') {
		return { kind: 'text', data: value, displayData: value, readonly: false, meta };
	}

	const display = compactJsonPreview(value, 80);
	return { kind: 'text', data: display, displayData: display, readonly: false, meta };
}

export const textSheetsCellFactory: SheetsCellFactory = { canHandle, create };

// SheetsCell factory contract — the native analogue of v1's cell-content-factory
// family. Each factory claims a set of `cellType`s (and/or value shapes) and emits
// the neutral {@link SheetsCell} render payload. Geometry stays out-of-band: the
// optional `deriveGeometry` hook lets a factory delegate to a geometry builder
// without this module importing leaflet peers (mirrors v1 createGeometryCell).

import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import type { SheetsCell } from '../sheets-cell';

export interface SheetsCellFactory {
	canHandle(cellType: string, value: unknown): boolean;
	create(value: unknown, metadata: CellCreationMetadata, deriveGeometry?: (value: unknown) => SheetsCell): SheetsCell;
}

// Native SheetsCell factory — URI family (url | email). Ports v1
// `UriCellFactory` (grid/cell-content-factory.ts) to the neutral SheetsCell
// render payload. All domain logic (email -> mailto, url passthrough, empty
// guard) is reproduced here verbatim so this file is glide-free at cutover.
//
// `data` holds the navigable URI while `displayData` keeps the user-facing
// string; the DOM view owns click behavior.

import type { CellType } from '../../cell-types/types';
import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

function canHandle(cellType: string, _value: unknown): boolean {
	return cellType === 'url' || cellType === 'email';
}

function create(value: unknown, metadata: CellCreationMetadata): SheetsCell {
	const cellType = metadata.cellType as CellType;

	if (value === null || value === undefined || value === '') {
		return { kind: 'uri', data: '', displayData: '', readonly: false, meta: { cellType } };
	}

	const stringValue = String(value);
	const isEmail = metadata.cellType === 'email';
	const data = isEmail ? `mailto:${stringValue}` : stringValue;

	return { kind: 'uri', data, displayData: stringValue, readonly: false, meta: { cellType } };
}

export const uriSheetsCellFactory: SheetsCellFactory = { canHandle, create };

// Bounded module-level LRU that RETAINS decoded images by URL so they stay warm in
// the browser's in-memory cache across unmount/remount. In a virtualized grid the
// body <img> is destroyed when its row scrolls off-screen; without a live reference
// the decoded bitmap is dropped and a remounted <img src> refetches/repaints (flicker,
// pop-in). Holding a decoded Image reference keeps the URL warm — a remounted <img>
// paints from memory instead of refetching, even for no-cache/short-lived URLs.

const CAP = 256;
const cache = new Map<string, HTMLImageElement>(); // Map preserves insertion order → LRU.

export function warmImage(url: string): void {
	if (!url || typeof Image === 'undefined') return; // SSR / empty-url guard.

	if (cache.has(url)) {
		// Mark most-recently-used: re-insert moves it to the end of the iteration order.
		const img = cache.get(url)!;
		cache.delete(url);
		cache.set(url, img);
		return;
	}

	const img = new Image();
	img.decoding = 'async';
	img.src = url;
	cache.set(url, img);

	while (cache.size > CAP) {
		// Evict the oldest (front of insertion order).
		const oldest = cache.keys().next().value;
		if (oldest === undefined) break;
		cache.delete(oldest);
	}
}

// Native cell model — the DOM render payload that replaces glide `GridCell`.
//
// Pure types: no @tanstack/* or virtual import. `SheetsCellKind` is the neutral
// render vocabulary consumed by the DOM cell host.

import type { CellType } from '../cell-types/types';

/**
 * Neutral render kinds. `loading` and `draft-action` originate from grid-internal
 * state, not the `CellType` system.
 */
export type SheetsCellKind =
	| 'text'
	| 'number'
	| 'boolean'
	| 'badges'
	| 'uri'
	| 'image'
	| 'geometry'
	| 'relation'
	| 'loading'
	| 'draft-action'
	| 'custom';

/** Per-cell visual hint, open-ish so later phases can enrich it. */
export interface SheetsCellStyleHint {
	draft?: boolean;
	faded?: boolean;
	/** This draft cell has a field-level validation error (draftMeta.errors[colKey]). */
	error?: boolean;
	[extra: string]: unknown;
}

/**
 * The factory output + render payload. A SINGLE interface with a `kind` field
 * (not a per-kind discriminated union): text/number/boolean share this payload
 * and do not diverge yet.
 *
 * TODO(phases 2+): enrich `meta` per kind (badges/uri/image/geometry/relation)
 * once their factories and views are ported.
 */
export interface SheetsCell {
	kind: SheetsCellKind;
	data: unknown;
	displayData: string;
	readonly: boolean;
	styleHint?: SheetsCellStyleHint;
	meta?: { cellType?: CellType; [extra: string]: unknown };
}

// Default DOM view for the `badges` SheetsCell family — the native analogue of
// v1's glide BubbleCell render. Dependency-light: plain JSX + Tailwind v4 + a
// local `cn`, with no shared primitive dependency. Reads the string[] off
// `props.cell.data` (the badges payload) and renders one tonal chip per item per
// DESIGN_SPEC §7; an empty array renders an empty cell.
//
// Chips default to the `neutral` tone — the palette is wired for opt-in color
// later (consumer-supplied tone map / resolver); an unconfigured grid stays calm.

import { BADGE_TONES, resolveBadgeTone } from '../badge-tones';
import { cn } from '../../utils/cn';
import type { CellProps } from '../cell-props';

export function BadgesCellView(props: CellProps) {
	const items = Array.isArray(props.cell.data) ? (props.cell.data as string[]) : [];

	return (
		<div
			role="gridcell"
			data-slot="badges-cell"
			className={cn(
				'flex h-full w-full items-center gap-1 overflow-hidden px-3',
				// Single row in the fixed-height cell (no vertical cramming): pills that run
				// past the right edge fade out, signalling more items beyond the cut (DESIGN_SPEC §7).
				// The mask only bites when content actually reaches the right edge, so a short list
				// (nothing near the edge) shows no fade.
				'[mask-image:linear-gradient(to_right,black,black_calc(100%_-_1.5rem),transparent)]',
			)}
		>
			{items.map((item, index) => (
				<span
					key={`${index}-${item}`}
					className={cn(
						'inline-flex shrink-0 items-center rounded-md px-2 py-0.5 text-xs font-medium',
						BADGE_TONES[resolveBadgeTone(item)],
					)}
				>
					{item}
				</span>
			))}
		</div>
	);
}

