// Default DOM view for the `relation` SheetsCell family. Dependency-light: plain
// JSX + Tailwind v4 + a local `cn`, with no shared primitive dependency. Reads the
// render payload off `props.cell` (produced by relationSheetsCellFactory):
//   - list relation  -> cell.data is string[] (chips, possibly a trailing "+N")
//   - single relation -> cell.data is a string label
// The factory already truncated labels and computed overflow; the view only paints.
//
// PARITY (canvas grid/draw-relation-badge.ts): for a list relation, paint a leading
// COUNT BADGE pill — the number of related items — before the chips, mirroring the
// canvas `drawRelationBadge`. Item count matches the canvas `getRelationCount`: the
// trailing "+N" overflow chip means count = (chips − 1) + N, otherwise chips.length.
// The single-relation (string) path stays plain text.

import React from 'react';

import { cn } from '../../utils/cn';
import type { CellProps } from '../cell-props';

// Mirrors canvas `getRelationCount` for the Bubble (list) branch: a trailing "+N"
// element is an overflow indicator, so the true count is (visible chips) + N.
function getListRelationCount(chips: unknown[]): number {
	const last = chips[chips.length - 1];
	if (typeof last === 'string' && last.startsWith('+')) {
		const overflow = parseInt(last.slice(1), 10);
		if (!isNaN(overflow)) return chips.length - 1 + overflow;
	}
	return chips.length;
}

export function RelationCellView(props: CellProps): React.JSX.Element {
	const { cell } = props;
	const isList = Array.isArray(cell.data);

	if (!isList) {
		return (
			<div
				data-slot="relation-cell"
				role="gridcell"
				className="flex h-full w-full items-center gap-1 overflow-hidden px-3 text-sm"
			>
				<span className="truncate text-foreground">{String(cell.data ?? '')}</span>
			</div>
		);
	}

	const chips = cell.data as unknown[];
	const count = getListRelationCount(chips);

	return (
		<div
			data-slot="relation-cell"
			role="gridcell"
			className="flex h-full w-full items-center gap-1 overflow-hidden px-3 text-sm"
		>
			{count > 0 ? (
				<span
					data-slot="relation-count-badge"
					className={cn(
						'inline-flex shrink-0 items-center rounded-sm border border-border bg-muted',
						'px-1 text-[10px] font-medium text-muted-foreground tabular-nums',
					)}
				>
					{count}
				</span>
			) : null}
			{chips.map((chip, index) => (
				<span
					key={index}
					className={cn(
						'inline-flex shrink-0 items-center rounded-md bg-muted px-1.5 py-0.5',
						'text-xs font-medium text-muted-foreground',
					)}
				>
					{String(chip)}
				</span>
			))}
		</div>
	);
}

// Default DOM view for the text family (the fallback). v1 renders the value as
// plain truncated text inside the canvas; the native analogue is a single
// truncated span. Dependency-light: plain JSX + Tailwind v4 + local `cn`, no
// shared primitive dependency. Reads the rendered string off the SheetsCell
// payload (`cell.displayData`) so it stays in lockstep with the factory.

import type { CellProps } from '../cell-props';
import { cn } from '../../utils/cn';

export function TextCellView(props: CellProps) {
	const text = props.cell.displayData;

	return (
		<div
			role="gridcell"
			data-slot="text-cell"
			title={text}
			className={cn('flex h-full w-full items-center truncate px-3 text-sm')}
		>
			<span className="truncate">{text}</span>
		</div>
	);
}

// Native DOM view for the URI family (url | email). Dependency-light: plain JSX
// + Tailwind v4 + local `cn`. Reads the render payload off `props.cell`
// (`data` -> href, `displayData` -> visible label). The view owns the click
// (v1's UriCellFactory dropped its onClickUri side-effect): the anchor opens in
// a new tab. Empty cells (`data === ''`) render inert text, not a dead link.

import type { CellProps } from '../cell-props';
import { cn } from '../../utils/cn';

export function UriCellView(props: CellProps) {
	const { cell } = props;
	const href = String(cell.data ?? '');
	const label = cell.displayData;
	const hasHref = href.length > 0;

	return (
		<div role="gridcell" data-slot="uri-cell" className="flex h-full w-full min-w-0 items-center px-3 text-sm">
			{hasHref ? (
				<a
					href={href}
					target="_blank"
					rel="noreferrer"
					title={label}
					className={cn('truncate text-info underline-offset-2 hover:underline', 'focus-visible:outline-hidden')}
				>
					{label}
				</a>
			) : (
				<span className="truncate text-muted-foreground">{label}</span>
			)}
		</div>
	);
}

import type { CellType } from './types';

import type { CellPlugin, CellRegistryEntry, CellRenderer } from './types';

class CellRegistryClass {
	private entries = new Map<CellType, CellRegistryEntry>();
	private plugins = new Map<string, CellPlugin>();

	// Register a cell renderer for a cell type
	register(entry: CellRegistryEntry): void {
		this.entries.set(entry.type, entry);
	}

	// Register multiple entries at once
	registerBatch(entries: CellRegistryEntry[]): void {
		entries.forEach((entry) => this.register(entry));
	}

	// Get cell renderer for a type
	get(type: CellType): CellRegistryEntry | undefined {
		return this.entries.get(type);
	}

	// Get all registered cell types
	getAll(): CellRegistryEntry[] {
		return Array.from(this.entries.values());
	}

	// Get cell component for a type
	getComponent(type: CellType): CellRenderer | undefined {
		const entry = this.entries.get(type);
		return entry?.component;
	}

	// Find cell entry by match function
	// NOTE: Cell type is determined ONLY from schema metadata, never from runtime values
	findByMatch(metadata: {
		gqlType: string;
		isArray: boolean;
		pgAlias?: string | null;
		pgType?: string | null;
		subtype?: string | null;
		fieldName?: string;
	}): CellRegistryEntry | undefined {
		// Iterate through all entries and find the first one with a matching match function
		for (const entry of this.entries.values()) {
			if (entry.match && entry.match(metadata)) {
				return entry;
			}
		}
		return undefined;
	}

	// Get cell component using match function first, then fallback to type
	// NOTE: Cell type is determined ONLY from schema metadata, never from runtime values
	getComponentWithMatch(
		type: CellType,
		metadata?: {
			gqlType: string;
			isArray: boolean;
			pgAlias?: string | null;
			pgType?: string | null;
			subtype?: string | null;
			fieldName?: string;
		},
	): CellRenderer | undefined {
		// First try to find by match function if metadata is provided
		if (metadata) {
			const matchedEntry = this.findByMatch(metadata);
			if (matchedEntry) {
				return matchedEntry.component;
			}
		}

		// Fallback to regular type-based lookup
		return this.getComponent(type);
	}

	// Get edit component for a type
	getEditComponent(type: CellType): CellRenderer | undefined {
		const entry = this.entries.get(type);
		return entry?.editComponent || entry?.component;
	}

	// Check if a type is registered
	has(type: CellType): boolean {
		return this.entries.has(type);
	}

	// Install a plugin
	installPlugin(plugin: CellPlugin): void {
		if (this.plugins.has(plugin.name)) {
			console.warn(`Plugin ${plugin.name} is already installed`);
			return;
		}

		// Install plugin cells
		plugin.cells.forEach((cell) => this.register(cell));

		// Run plugin install hook
		plugin.install?.();

		this.plugins.set(plugin.name, plugin);
	}

	// Uninstall a plugin
	uninstallPlugin(pluginName: string): void {
		const plugin = this.plugins.get(pluginName);
		if (!plugin) {
			console.warn(`Plugin ${pluginName} is not installed`);
			return;
		}

		// Remove plugin cells
		plugin.cells.forEach((cell) => this.entries.delete(cell.type));

		// Run plugin uninstall hook
		plugin.uninstall?.();

		this.plugins.delete(pluginName);
	}

	// Get installed plugins
	getInstalledPlugins(): CellPlugin[] {
		return Array.from(this.plugins.values());
	}

	// Clear all entries (useful for testing)
	clear(): void {
		this.entries.clear();
		this.plugins.clear();
	}

	// Get entries by category
	getByCategory(category: string): CellRegistryEntry[] {
		return Array.from(this.entries.values()).filter((entry) => entry.metadata?.category === category);
	}
}

