// Per-instance cell-type registry.
//
// This is a thin OVERRIDE LAYER over the built-in native rendering engine:
// consumer definitions (from `SheetsConfig.plugins` and `<Sheets cellTypes>`)
// win by `typeKey` and by `match()`, and anything they don't define falls back
// to the built-in `toSheetsCell`. The built-in engine is injected so this module
// stays free of a cell-types -> grid import cycle. The registry is created once
// per <SheetsProvider> (same lifetime as the store), so it is SSR- and
// multi-tenant-safe — no module singleton.
import type {
	CellTypeDefinition,
	CellTypeMatchInput,
	SheetsCellRenderContext,
} from './define-cell-type';
import type { SheetsCell } from '../cell-model/sheets-cell';
import type { CellProps } from '../cell-model/cell-props';
import type { EditorProps } from '../grid-dom/editors/editor-props';

/** The built-in engine the registry falls back to (injected to avoid a cycle). */
export interface CellTypeBuiltins {
	toSheetsCell: (value: unknown, ctx: SheetsCellRenderContext) => SheetsCell;
}

export interface CellTypeRegistry {
	/** Detection: consumer `match()` chain first (later defs win), else the built-in resolver. */
	resolveTypeKey(meta: CellTypeMatchInput, builtinFallback: () => string): string;
	/** Native display: consumer `def.toSheetsCell` for this typeKey, else the built-in renderer. */
	toSheetsCell(typeKey: string, value: unknown, ctx: SheetsCellRenderContext): SheetsCell;
	/** The registered definition for a typeKey, if any (consumer defs only). */
	get(typeKey: string): CellTypeDefinition<any> | undefined;
	/** The native cell COMPONENT override for a typeKey, if any (consumer `def.cell`). */
	getCellComponent(typeKey: string): React.ComponentType<CellProps> | undefined;
	/** The native EDITOR override for a typeKey, if any (consumer `def.editorComponent`). */
	getEditorComponent(typeKey: string): React.ComponentType<EditorProps> | undefined;
}

/**
 * Build a registry. `cellTypes` are consumer definitions in precedence order
 * (provider `plugins` first, then per-instance `cellTypes`); later entries win,
 * so an instance-level def overrides a provider-level one with the same typeKey.
 */
export function createCellTypeRegistry(cellTypes: CellTypeDefinition<any>[], builtins: CellTypeBuiltins): CellTypeRegistry {
	// Index by typeKey — last write wins (instance overrides provider).
	const byKey = new Map<string, CellTypeDefinition<any>>();
	for (const def of cellTypes) byKey.set(def.typeKey, def);

	// Match list in REVERSE precedence so later (instance) defs are tried first.
	const matchers = [...cellTypes].reverse().filter((d) => d.match);

	return {
		resolveTypeKey(meta, builtinFallback) {
			for (const def of matchers) {
				if (def.match!(meta)) return def.typeKey;
			}
			return builtinFallback();
		},
		toSheetsCell(typeKey, value, ctx) {
			const def = byKey.get(typeKey);
			return def?.toSheetsCell ? def.toSheetsCell(value, ctx) : builtins.toSheetsCell(value, ctx);
		},
		get(typeKey) {
			return byKey.get(typeKey);
		},
		getCellComponent(typeKey) {
			return byKey.get(typeKey)?.cell;
		},
		getEditorComponent(typeKey) {
			return byKey.get(typeKey)?.editorComponent;
		},
	};
}

import { CellRegistry } from './cell-registry';
import { NON_EDITABLE_TYPES, VIEWER_ONLY_TYPES } from './cell-type-groups';
import { mapToFrontendCellType } from './type-mapping';

export interface FieldMetadata {
	name: string;
	type?: {
		gqlType: string;
		pgType?: string | null;
		pgAlias?: string | null;
		isArray?: boolean;
		subtype?: string | null;
	};
}

export interface CellTypeResolution {
	cellType: string;
	canEdit: boolean;
	canActivate: boolean;
	activationBehavior: 'single-click' | 'double-click';
	isReadonly: boolean;
}

// Use double-click to activate overlay for all cell types
const SINGLE_CLICK_CELL_TYPES = new Set<string>();

const READONLY_CONDITIONS = new Map([
	['id', (fieldMeta?: FieldMetadata) => fieldMeta?.type?.gqlType === 'UUID'],
	['createdAt', () => true],
	['updatedAt', () => true],
]);

export function resolveCellType(fieldName: string, fieldMeta?: FieldMetadata): CellTypeResolution {
	// Check for readonly fields first
	const readonlyCheck = READONLY_CONDITIONS.get(fieldName);
	const isReadonly = readonlyCheck?.(fieldMeta) ?? false;

	let cellType: string = 'text'; // Default fallback

	if (fieldMeta?.type) {
		// First try CellRegistry matching (same as existing logic)
		// NOTE: Cell type is determined ONLY from schema metadata, never from runtime values
		const matchedEntry = CellRegistry.findByMatch({
			gqlType: fieldMeta.type.gqlType || '',
			isArray: !!fieldMeta.type.isArray,
			pgAlias: fieldMeta.type.pgAlias,
			pgType: fieldMeta.type.pgType,
			subtype: fieldMeta.type.subtype ?? null,
			fieldName,
		});

		if (matchedEntry) {
			cellType = matchedEntry.type;
		} else {
			// Fallback: Map GraphQL field metadata to frontend cell types
			cellType = mapToFrontendCellType({
				gqlType: fieldMeta.type.gqlType,
				isArray: !!fieldMeta.type.isArray,
				pgAlias: fieldMeta.type.pgAlias,
				pgType: fieldMeta.type.pgType,
				subtype: fieldMeta.type.subtype ?? null,
			});
		}
	}

	// Determine editing capabilities
	const canEdit = !isReadonly && !NON_EDITABLE_TYPES.has(cellType);
	const canActivate = canEdit || VIEWER_ONLY_TYPES.has(cellType);
	const activationBehavior = SINGLE_CLICK_CELL_TYPES.has(cellType) ? 'single-click' : 'double-click';

	return {
		cellType,
		canEdit,
		canActivate,
		activationBehavior,
		isReadonly,
	};
}

export function shouldShowCellActivation(fieldName: string, cellType: string): boolean {
	// Disable activation for specific readonly fields
	if (fieldName === 'createdAt' || fieldName === 'updatedAt') {
		return false;
	}

	if (VIEWER_ONLY_TYPES.has(cellType)) {
		return false;
	}

	return true;
}

// Helper for checking if a field is an image type (used by existing column logic)
export function isImageField(fieldMeta?: FieldMetadata, fieldName?: string): boolean {
	if (!fieldMeta || !fieldName) return false;

	// Check if this field is configured as an image type
	const isImageByType =
		fieldMeta.type?.gqlType === 'JSON' && // Image fields are often JSON
		(fieldName.toLowerCase().includes('image') ||
			fieldName.toLowerCase().includes('picture') ||
			fieldName.toLowerCase().includes('photo') ||
			fieldName.toLowerCase().includes('avatar'));

	// Also check using CellRegistry matching
	const matchedEntry = CellRegistry.findByMatch({
		gqlType: fieldMeta.type?.gqlType || '',
		isArray: !!fieldMeta.type?.isArray,
		pgAlias: fieldMeta.type?.pgAlias,
		pgType: fieldMeta.type?.pgType,
		subtype: fieldMeta.type?.subtype ?? null,
		fieldName,
	});

	return isImageByType || matchedEntry?.type === 'image';
}

// Public contract for defining and overriding cell types.
//
// A CellTypeDefinition unifies DETECTION (`match`) and native DISPLAY
// (`toSheetsCell` / `cell`) and native EDITING (`editorComponent`) in one object.
// Consumers register them per-instance via `<SheetsProvider config={{ plugins }}>`
// or `<Sheets cellTypes>`; a def whose `typeKey` matches a built-in overrides that
// built-in for this grid, and a def with a `match()` adds detection. Any concern
// left undefined falls back to the built-in behavior, so a def may override just
// the editor, just the display, or add a brand-new type end-to-end.

import type { CellCategory } from './types';
// Type-only imports (erased at runtime) — avoids a cell-types -> grid cycle.
import type { CellCreationMetadata } from '../grid/grid-cell-types';
import type { SheetsCell } from '../cell-model/sheets-cell';
import type { CellProps } from '../cell-model/cell-props';
import type { EditorProps } from '../grid-dom/editors/editor-props';

/** Schema-only inputs used to DETECT a cell type. Never the runtime value. */
export interface CellTypeMatchInput {
	gqlType: string;
	isArray: boolean;
	pgAlias?: string | null;
	pgType?: string | null;
	subtype?: string | null;
	fieldName?: string;
}

/** Context handed to `toSheetsCell` so a definition can build the neutral cell.
 * Geometry uses the built-in fallback, so no `createGeometry` callback is needed. */
export interface SheetsCellRenderContext {
	metadata: CellCreationMetadata;
}

export interface CellTypeDefinition<TValue = unknown> {
	/** Stable key. A def whose typeKey equals a built-in (e.g. 'relation') overrides it. */
	typeKey: string;
	category?: CellCategory;
	/** Toolbar / type-picker icon. */
	icon?: React.ComponentType<{ size?: number }>;
	defaultWidth?: number;
	supportsInlineEdit?: boolean;
	/** DETECTION (schema-only). Highest-priority match wins; omit for typeKey-only. */
	match?: (meta: CellTypeMatchInput) => boolean;
	/** Native DISPLAY. Build the neutral SheetsCell. Omit to keep the built-in renderer. */
	toSheetsCell?: (value: TValue, ctx: SheetsCellRenderContext) => SheetsCell;
	/** Native cell COMPONENT override (the slot target). Omit to keep the built-in view. */
	cell?: React.ComponentType<CellProps>;
	/** Native EDITOR override (DOM portal overlay). Omit to keep the built-in native editor. */
	editorComponent?: React.ComponentType<EditorProps>;
	/** Value -> display/copy/export string. */
	format?: (value: TValue) => string;
	defaultValue?: () => TValue;
}

/** Identity helper that pins the generic — `defineCellType<number>({ ... })`. */
export function defineCellType<T = unknown>(def: CellTypeDefinition<T>): CellTypeDefinition<T> {
	return def;
}

/** A named bundle of cell types, registered via `SheetsConfig.plugins`. */
export interface CellTypePlugin {
	name: string;
	cellTypes: CellTypeDefinition<any>[];
}

export type { CellCreationMetadata };

import { ENHANCED_TYPES, MEDIA_TYPES, STRUCTURED_DATA_TYPES } from './cell-type-groups';
import type { CellType, ColumnSchema } from './types';

/**
 * Maps GraphQL field metadata to frontend cell types
 * Uses priority: pgAlias > pgType > gqlType for type determination
 * This is completely backend-agnostic and focuses only on frontend rendering needs
 */
export function mapToFrontendCellType(metadata: {
	gqlType: string;
	isArray: boolean;
	pgAlias?: string | null;
	pgType?: string | null;
	subtype?: string | null;
	encoding?: { kind: string; geometrySubtype?: string | null } | null;
}): CellType {
	const { gqlType, isArray, pgAlias, pgType } = metadata;

	const encodedType = mapEncodingToCellType(metadata.encoding);
	if (encodedType) return encodedType;

	// Priority 1: Use pgAlias if available (most specific)
	// This must be checked FIRST, even for arrays, to preserve types like 'array' vs 'text-array'
	if (pgAlias) {
		const aliasType = mapAliasToCellType(pgAlias);
		if (aliasType !== 'unknown') return aliasType;
	}

	// Handle arrays after pgAlias check
	if (isArray) {
		const result = mapGraphQLTypeToCellType(gqlType, isArray, metadata.subtype, null);
		return result;
	}

	// Priority 2: Use pgType if available (backend-specific but still useful)
	if (pgType) {
		const pgTypeMapped = mapBackendTypeToCellType(pgType);
		if (pgTypeMapped !== 'unknown') return pgTypeMapped;
	}

	// Priority 3: Fall back to GraphQL type
	const fallbackResult = mapGraphQLTypeToCellType(gqlType, isArray, metadata.subtype, null);
	return fallbackResult;
}

function mapEncodingToCellType(
	encoding?: { kind: string; geometrySubtype?: string | null } | null,
): CellType | null {
	if (!encoding) return null;

	switch (encoding.kind) {
		case 'bigint': return 'integer';
		case 'datetime': return 'datetime';
		case 'date': return 'date';
		case 'time': return 'time';
		case 'interval': return 'interval';
		case 'uuid': return 'uuid';
		case 'inet': return 'inet';
		case 'point': return 'geometry-point';
		case 'geojson':
			return encoding.geometrySubtype === 'Point' ? 'geometry-point' : 'geometry';
		case 'vector': return 'number-array';
		case 'composite': return 'json';
		case 'ltree':
		case 'bytea':
			return 'text';
		default:
			return null;
	}
}

/**
 * Maps PostgreSQL aliases to frontend cell types
 */
function mapAliasToCellType(alias: string): CellType {
	const aliasMap: Record<string, CellType> = {
		// Media types
		image: 'image',
		file: 'file',
		video: 'video',
		audio: 'audio',
