		phone: 'phone',
		citext: 'citext',
		textarea: 'textarea',

		// Enhanced numeric types
		number: 'number',
		currency: 'currency',
		percentage: 'percentage',
		numeric: 'decimal',
		decimal: 'decimal',
		int: 'integer',
		integer: 'integer',
		smallint: 'smallint',

		// Boolean types
		boolean: 'boolean',
		toggle: 'toggle',

		// Date/time types
		date: 'date',
		datetime: 'datetime',
		time: 'time',
		timestamptz: 'timestamptz',
		interval: 'interval',

		// JSON types
		json: 'json',
		jsonb: 'jsonb',

		// Network types
		inet: 'inet',

		// Geometric types
		geometry: 'geometry',
		'geometry-point': 'geometry-point',
		'geometry-collection': 'geometry-collection',

		// Special types
		color: 'color',
		rating: 'rating',
		tags: 'tags',
		uuid: 'uuid',
		tsvector: 'tsvector',
		origin: 'origin',

		// Character types
		char: 'bpchar',
