/**
 * Keybinding primitives — COPIED from packages/command-palette/src/keybinding.ts
 * (kbd / matchKeyBinding / isMac / isEditableTarget) so @constructive-io/sheets stays
 * distributable WITHOUT a dependency on command-palette. Keep the two in sync by hand;
 * the logic is intentionally identical (strict modifier matching, Mac mod=meta).
 */

/** Modifier key abstraction. 'mod' = Cmd on Mac, Ctrl on Windows/Linux. */
export type KeyModifier = 'mod' | 'shift' | 'alt';

/** Structured key binding — matchable against KeyboardEvents. */
export interface KeyBinding {
	modifiers?: KeyModifier[];
	/** Lowercase key name: 'h', 'k', 'enter', 'backspace', ',', '/', etc. */
	key: string;
}

/** Ergonomic KeyBinding factory. */
export function kbd(key: string, ...modifiers: KeyModifier[]): KeyBinding {
	return modifiers.length > 0 ? { key, modifiers } : { key };
}

/** Platform detection with SSR fallback (assumes non-Mac). */
export function isMac(): boolean {
	if (typeof navigator === 'undefined') return false;
	return /mac|ipod|iphone|ipad/i.test(navigator.platform ?? '');
}

/** Check if event target is an editable element (input, textarea, select, contenteditable). */
export function isEditableTarget(target: EventTarget | null): boolean {
	if (!target || !(target instanceof HTMLElement)) return false;
	const tag = target.tagName;
	if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return true;
	return target.contentEditable === 'true';
}

/** Match a KeyboardEvent against a KeyBinding with strict modifier check. */
export function matchKeyBinding(event: KeyboardEvent, binding: KeyBinding): boolean {
	// Compare key (case-insensitive)
	if (event.key.toLowerCase() !== binding.key.toLowerCase()) return false;

	const mods = binding.modifiers ?? [];
	const wantMod = mods.includes('mod');
	const wantShift = mods.includes('shift');
	const wantAlt = mods.includes('alt');

	// On Mac, 'mod' maps to metaKey; elsewhere, ctrlKey
	const modPressed = isMac() ? event.metaKey : event.ctrlKey;

	// Strict: every required modifier must be pressed, no extras
	if (wantMod !== modPressed) return false;
	if (wantShift !== event.shiftKey) return false;
	if (wantAlt !== event.altKey) return false;

	// Prevent false positives: if mod maps to meta on Mac, ctrl shouldn't be pressed (and vice versa)
	if (isMac()) {
		if (!wantMod && event.ctrlKey) return false;
	} else {
		if (!wantMod && event.metaKey) return false;
	}

	return true;
}

/**
 * DEFAULT_KEYMAP + resolveKeyCommand (P4 Phase 1).
 *
 * A keymap is an ordered Binding[]; `resolveKeyCommand` returns the FIRST matching
 * binding's command id (first-match-wins) or `null` when nothing matches — including
 * for an unbound PRINTABLE key, so the dispatch funnel can fall to the `editor.typeToEdit`
 * sentinel (the printable-key path is NOT in the keymap; the funnel routes it explicitly).
 *
 * Triggers come in three kinds — `key` (matched here via the copied matchKeyBinding),
 * `pointer` (gesture, wired in Stage B / Phase 2), and `native` (a raw DOM event name).
 * Pointer + native triggers are declared in the table for invariant completeness even
 * though only key triggers resolve through `resolveKeyCommand`.
 *
 * `Mod` is ctrl on win/linux, cmd on mac — encoded as the copied `'mod'` KeyModifier, so
 * matchKeyBinding's platform branch (isMac) picks the right physical key.
 */

import { kbd, matchKeyBinding, type KeyBinding } from './keybinding';

/** A pointer gesture name (resolved by the pointer handlers, not the key funnel). */
export type PointerGesture = 'click' | 'shiftClick' | 'dblclick' | 'headerClick' | 'rowToggle' | 'rowToggleAll';

/** What fires a command. */
export type Trigger =
	| { kind: 'key'; binding: KeyBinding }
	| { kind: 'pointer'; gesture: PointerGesture }
	| { kind: 'native'; event: string };

/** A trigger -> command id mapping. */
export interface Binding {
	trigger: Trigger;
	command: string;
}

/** key-trigger shorthand. */
function key(binding: KeyBinding, command: string): Binding {
	return { trigger: { kind: 'key', binding }, command };
}

/** pointer-trigger shorthand. */
function pointer(gesture: PointerGesture, command: string): Binding {
	return { trigger: { kind: 'pointer', gesture }, command };
}

/**
 * The default key + pointer + native bindings. Order matters for the key kind
 * (first-match-wins). matchKeyBinding is STRICT on modifiers, so the undo (Mod+Z) and
 * redo (Mod+Shift+Z) chords never alias even though they share the 'z' key.
 */
export const DEFAULT_KEYMAP: Binding[] = [
	// undo / redo
	key(kbd('z', 'mod'), 'edit.undo'),
	key(kbd('z', 'mod', 'shift'), 'edit.redo'),
	key(kbd('y', 'mod'), 'edit.redo'),

	// select all
	key(kbd('a', 'mod'), 'selection.all'),

	// clear cells (Delete / Backspace → null over the active range). The funnel bails
	// while an overlay editor is open, so these still edit text inside an editor.
	key(kbd('Delete'), 'cell.clear'),
	key(kbd('Backspace'), 'cell.clear'),

	// fill (Mod = Cmd/mac, Ctrl/win)
	key(kbd('d', 'mod'), 'fill.down'),
	key(kbd('r', 'mod'), 'fill.right'),

	// arrow move (plain)
	key(kbd('ArrowUp'), 'cell.moveUp'),
	key(kbd('ArrowDown'), 'cell.moveDown'),
	key(kbd('ArrowLeft'), 'cell.moveLeft'),
	key(kbd('ArrowRight'), 'cell.moveRight'),

	// arrow extend (shift)
	key(kbd('ArrowUp', 'shift'), 'cell.extendUp'),
	key(kbd('ArrowDown', 'shift'), 'cell.extendDown'),
	key(kbd('ArrowLeft', 'shift'), 'cell.extendLeft'),
	key(kbd('ArrowRight', 'shift'), 'cell.extendRight'),

	// absolute nav — base + ctrl/meta + shift variants all resolve to one command (the
	// command body branches on the payload via computeKeyNavTarget, matching the original).
	key(kbd('Tab'), 'cell.navAbsolute'),
	key(kbd('Tab', 'shift'), 'cell.navAbsolute'),
	key(kbd('Home'), 'cell.navAbsolute'),
	key(kbd('Home', 'mod'), 'cell.navAbsolute'),
	key(kbd('End'), 'cell.navAbsolute'),
	key(kbd('End', 'mod'), 'cell.navAbsolute'),
	key(kbd('PageUp'), 'cell.navAbsolute'),
	key(kbd('PageDown'), 'cell.navAbsolute'),

	// open editor at active cell
	key(kbd('Enter'), 'editor.openActive'),
	key(kbd('F2'), 'editor.openActive'),

	// pointer gestures (wired Stage B / Phase 2)
	pointer('click', 'cell.activate'),
	pointer('shiftClick', 'cell.extendToClicked'),
	pointer('dblclick', 'editor.open'),
	pointer('headerClick', 'header.sortToggle'),
	pointer('rowToggle', 'rowmarker.toggleRow'),
	pointer('rowToggleAll', 'rowmarker.toggleAll'),
];

/**
 * Resolve a KeyboardEvent to a command id via the keymap (first key-trigger match wins).
 * Returns `null` when no key binding matches — including unbound printable keys — so the
 * caller can fall to the `editor.typeToEdit` sentinel. Pointer / native triggers are
 * ignored here (they are not key events).
 */
export function resolveKeyCommand(event: KeyboardEvent, keymap: Binding[] = DEFAULT_KEYMAP): string | null {
	for (const binding of keymap) {
		if (binding.trigger.kind !== 'key') continue;
		if (matchKeyBinding(event, binding.trigger.binding)) return binding.command;
	}
	return null;
}

/**
 * DEFAULT_COMMANDS + createGridCommandRegistry (P4 Phase 1).
 *
 * Each command body is LIFTED VERBATIM from grid/sheets.tsx's handleGridKeyDown /
 * handleActivateCell / openEditor / openEditorAtActiveCell branches — same dispatcher
 * calls, same anchor resets, same clamp/scroll order. The handler's local guards
 * (`if (rows === 0 || colCount === 0) return`) are preserved as `canRun` where the
 * original returned WITHOUT preventing default, and inline where the original DID
 * prevent default first (Ctrl+A / arrows / nav: the original called preventDefault()
 * before the empty-grid early return, so the no-op must still preventDefault — that is
 * the core's job once the command resolves, and the body simply returns early).
 *
 * Phase 1 is a refactor: these bodies call `ctx.<dispatcher>` (the existing stable fns).
 */

import { computeKeyNavTarget, emptySheetsSelection, selectAllCells } from '../selection/selection-model';
import type { SelectionRect } from '../selection/selection-model';
import { parseTSV, tileMatrix } from '../selection/tsv';
import { fillDownWrites, fillRightWrites, extendedFillRect, fillDragWrites } from '../selection/fill';
import type { CellWrite } from '../grid/hooks/use-batch-commit';
import type { GridCommand, GridCommandRegistry } from './types';
import type { GridCommandContext, CellMatrix } from './context';

/** Payload for `cell.activate` / `cell.extendToClicked` (pointer). */
export interface CellPointerPayload {
	col: number;
	row: number;
}

/** Payload for `editor.open` (dblclick). */
export interface EditorOpenPayload {
	rowIndex: number;
	colKey: string;
	anchorRect: DOMRect;
	initialText?: string;
}

/** Payload for `editor.typeToEdit` (printable key sentinel). */
export interface TypeToEditPayload {
	char: string;
}

/** Payload for `cell.navAbsolute` (Tab/Home/End/PageUp/PageDown). */
export interface NavAbsolutePayload {
	key: string;
	ctrlOrMeta: boolean;
	shift: boolean;
	/** Visible page span (rows); the funnel derives this from the scroll element clientHeight. */
	pageRows: number;
}

/** Payload for `header.sortToggle`. */
export interface SortTogglePayload {
	colKey: string;
}

/** Payload for `rowmarker.toggleRow`. */
export interface ToggleRowPayload {
	rowIndex: number;
	shift: boolean;
}

/** Payload for `fill.drag` (fill-handle nub release). `from` = source band, `to` = `[col,row]` under the pointer. */
export interface FillDragPayload {
	from: SelectionRect;
	to: [number, number];
}

/**
 * The minimal `DataTransfer` slice the clipboard commands read/write — `ClipboardEvent.clipboardData`
 * conforms (so does a test stub). Kept narrow so the command never depends on the full DOM type.
 */
export interface ClipboardLike {
	getData(format: string): string;
	setData(format: string, data: string): void;
}

/** Payload for `clipboard.copy` / `clipboard.cut` / `clipboard.paste` (native clipboard event). */
export interface ClipboardPayload {
	clipboard: ClipboardLike | null;
}

/** Shared empty-grid guard (the original `rows === 0 || colCount === 0` short-circuit). */
function gridNonEmpty(ctx: GridCommandContext): boolean {
	return ctx.rowCount > 0 && ctx.colCount > 0;
}

/**
 * The cell range the clipboard commands act on: the active selection range when present,
 * else a 1×1 rect at the active cell. `null` when there is no active cell (empty grid /
 * no cursor) — the copy/cut/paste `canRun` guards return false on null.
 */
function clipboardRange(ctx: GridCommandContext): SelectionRect | null {
	const range = ctx.selection?.current?.range;
	if (range) return range;
	const cell = ctx.activeCell;
	if (!cell) return null;
	return { x: cell[0], y: cell[1], width: 1, height: 1 };
}

/** Build a `null` write for every cell in `rect` (clamped to the column keys). */
function clearRangeWrites(rect: SelectionRect, columnKeys: readonly string[]): CellWrite[] {
	const writes: CellWrite[] = [];
	for (let r = 0; r < rect.height; r++) {
		for (let c = 0; c < rect.width; c++) {
			const colKey = columnKeys[rect.x + c];
			if (colKey == null) continue;
			writes.push({ rowIndex: rect.y + r, colKey, value: null });
		}
	}
	return writes;
}

/** True when the async `navigator.clipboard` API is reachable (secure context, browser). */
function navigatorClipboard(): Clipboard | null {
	return typeof navigator !== 'undefined' && navigator.clipboard ? navigator.clipboard : null;
}

/** The `null` writes that clear every cell of a copied/cut matrix (cut's source clear). */
function cutRangeWrites(matrix: CellMatrix): CellWrite[] {
	const writes: CellWrite[] = [];
	for (let r = 0; r < matrix.rows.length; r++) {
		for (let c = 0; c < matrix.cols.length; c++) {
			const colKey = matrix.cols[c];
			if (colKey == null) continue;
			writes.push({ rowIndex: matrix.rows[r], colKey, value: null });
		}
	}
	return writes;
}

/**
 * Tile a parsed TSV `source` onto the target and build the clamped writes — the shared body
 * of both paste paths (native event + navigator fallback). `anchor` is the active cell's
 * top-left; `range` (when present + larger than the source) drives tiling.
 */
function pasteWrites(ctx: GridCommandContext, anchor: readonly [number, number], text: string): CellWrite[] {
	const source = parseTSV(text);
	const range = ctx.selection?.current?.range;
	const targetW = range ? range.width : source[0]?.length ?? 0;
	const targetH = range ? range.height : source.length;
	const matrix = tileMatrix(source, targetW, targetH);

	const [anchorCol, anchorRow] = anchor;
	const writes: CellWrite[] = [];
	for (let r = 0; r < matrix.length; r++) {
		const rowIndex = anchorRow + r;
		if (rowIndex >= ctx.rowCount) break; // clamp to grid bottom
		const line = matrix[r];
		for (let c = 0; c < line.length; c++) {
			const colIndex = anchorCol + c;
			if (colIndex >= ctx.colCount) break; // clamp to grid right
			const colKey = ctx.columnKeys[colIndex];
			if (colKey == null) continue;
			writes.push({ rowIndex, colKey, value: line[c] });
		}
	}
	return writes;
}

/**
 * The default command set. Authored as plain objects (no classes). Frozen array so the
 * registry factory can clone it; consumer overrides replace by id (Phase 2 seam).
 */
export const DEFAULT_COMMANDS: GridCommand[] = [
	// ---- UNDO / REDO (lifted: handleGridKeyDown undo/redo branch) ----
	{
		id: 'edit.undo',
		run: (ctx) => {
			void ctx.undo();
		},
	},
	{
		id: 'edit.redo',
		run: (ctx) => {
			void ctx.redo();
		},
	},

	// ---- SELECT ALL (lifted: Ctrl/Cmd+A branch) ----
	{
		id: 'selection.all',
		canRun: gridNonEmpty,
		run: (ctx) => {
			ctx.setAnchor([0, 0]);
			ctx.setSelection(selectAllCells(ctx.selection ?? emptySheetsSelection, ctx.colCount, ctx.rowCount));
		},
	},

	// ---- CLIPBOARD COPY (serialize range → TSV → clipboard) ----
	// Serializes the active range (or the 1×1 active cell) to TSV. TWO paths:
	//   • NATIVE: `payload.clipboard` is the `copy` event's DataTransfer — write it synchronously.
	//     preventDefault happens in the dispatch CORE (so the browser does not ALSO copy its own —
	//     empty — selection).
	//   • MENU/PROGRAMMATIC: no DataTransfer (the context menu has no native event) — fall back to
	//     the async `navigator.clipboard.writeText` (rejection caught → no-op; secure-context gated).
	// canRun gates on an active cell/range existing.
	{
		id: 'clipboard.copy',
		canRun: (ctx) => clipboardRange(ctx) !== null,
		run: (ctx, payload) => {
			const range = clipboardRange(ctx);
			if (!range) return;
			const tsv = ctx.toTSV(ctx.getCellsInRange(range).values);
			const clipboard = (payload as ClipboardPayload | undefined)?.clipboard;
			if (clipboard) {
				clipboard.setData('text/plain', tsv);
				return;
			}
			const nav = navigatorClipboard();
			if (nav) return nav.writeText(tsv).catch(() => {});
		},
	},

	// ---- CLIPBOARD CUT (copy serialize + clear the source range) ----
	// Runs the copy serialize (native DataTransfer or navigator fallback, same branch as copy),
	// then commits `null` across every cell of the source range as ONE undo-aware batch
	// (commitCells skips readonly/UUID cells internally). Same range source.
	{
		id: 'clipboard.cut',
		canRun: (ctx) => clipboardRange(ctx) !== null,
		run: (ctx, payload) => {
			const range = clipboardRange(ctx);
			if (!range) return;
			const matrix = ctx.getCellsInRange(range);
			const tsv = ctx.toTSV(matrix.values);
			const writes = cutRangeWrites(matrix);
			const clipboard = (payload as ClipboardPayload | undefined)?.clipboard;
			if (clipboard) {
				clipboard.setData('text/plain', tsv);
				void ctx.commitCells(writes);
				return;
			}
			const nav = navigatorClipboard();
			if (!nav) return;
			// Clear only once the write resolves so a clipboard rejection leaves the source intact.
			return nav.writeText(tsv).then(() => {
				void ctx.commitCells(writes);
			}).catch(() => {});
		},
	},

	// ---- CLIPBOARD PASTE (parse TSV → tile → commitCells) ----
	// Parses the clipboard TSV, TILES it onto the target (a 1×N / N×1 source repeats to fill a
	// larger selection range; a 2-D block writes from the anchor as-is), clamps to grid bounds, and
	// commits ONE batch (single optimistic patch + coalesced per-row mutations + ONE undo entry).
	// commitCells skips readonly/UUID cells. The anchor is the active cell's top-left. TWO paths:
	//   • NATIVE: `payload.clipboard` is the `paste` event's DataTransfer — read it synchronously.
	//   • MENU/PROGRAMMATIC: no DataTransfer — fall back to async `navigator.clipboard.readText`
	//     (rejection caught → no-op; secure-context gated).
	{
		id: 'clipboard.paste',
		canRun: (ctx) => ctx.activeCell != null,
		run: (ctx, payload) => {
			const anchor = ctx.activeCell;
			if (!anchor) return;
			const clipboard = (payload as ClipboardPayload | undefined)?.clipboard;
			if (clipboard) {
				const text = clipboard.getData('text/plain');
				if (!text) return;
				const writes = pasteWrites(ctx, anchor, text);
				if (writes.length) void ctx.commitCells(writes);
				return;
			}
			const nav = navigatorClipboard();
			if (!nav) return;
			return nav.readText().then((text) => {
				if (!text) return;
				const writes = pasteWrites(ctx, anchor, text);
				if (writes.length) void ctx.commitCells(writes);
			}).catch(() => {});
		},
	},

	// ---- CELL CLEAR (Delete / Backspace: write null over the active range) ----
	// range = the active selection range, else a 1×1 rect at the active cell. Builds a
	// {rowIndex, colKey, value: null} write for every cell in the rect and commits ONE
	// undo-aware batch (commitCells skips readonly/UUID internally; non-nullable columns
	// reject server-side and the optimistic patch reverts — null is the DB-clear default).
	// canRun gates on an active cell/range existing.
	{
		id: 'cell.clear',
		canRun: (ctx) => clipboardRange(ctx) !== null,
		run: (ctx) => {
			const range = clipboardRange(ctx);
			if (!range) return;
			const writes = clearRangeWrites(range, ctx.columnKeys);
			if (writes.length) void ctx.commitCells(writes);
		},
	},

	// ---- FILL DOWN (Mod+D: replicate the TOP row of the range downward) ----
	// SOURCE = the range's top row; every lower row in the range gets the seed value of the
	// column above it. ONE undo-aware batch via commitCells (readonly/UUID skipped internally).
	// SCOPE: value replication only — numeric/date SERIES detection is DEFERRED.
	{
		id: 'fill.down',
		canRun: (ctx) => {
			const range = ctx.selection?.current?.range;
			return !!range && range.height > 1;
		},
		run: (ctx) => {
			const range = ctx.selection?.current?.range;
			if (!range) return;
			const writes = fillDownWrites(range, ctx.combinedRows, ctx.columnKeys);
			if (writes.length) void ctx.commitCells(writes);
		},
	},

	// ---- FILL RIGHT (Mod+R: replicate the LEFT column of the range rightward) ----
	// SOURCE = the range's left column; every column to its right gets that row's left-column
	// seed. ONE undo-aware batch. SCOPE: value replication only — SERIES detection DEFERRED.
	{
		id: 'fill.right',
		canRun: (ctx) => {
			const range = ctx.selection?.current?.range;
			return !!range && range.width > 1;
		},
		run: (ctx) => {
			const range = ctx.selection?.current?.range;
			if (!range) return;
			const writes = fillRightWrites(range, ctx.combinedRows, ctx.columnKeys);
			if (writes.length) void ctx.commitCells(writes);
		},
	},

	// ---- FILL DRAG (fill-handle nub release: extend `from` toward `to`, tile the source) ----
	// The pointer-driven analogue of fill.down/right: extend the SOURCE band toward the dropped
	// cell along the dominant axis, REPLICATE the band across the new cells (one undo-aware batch),
	// then WIDEN the selection to the extended rect so the band grows to match. canRun gates on a
	// payload (from + to) being present. SCOPE: value replication only — SERIES detection DEFERRED.
	{
		id: 'fill.drag',
		canRun: (_ctx, payload) => {
			const p = payload as FillDragPayload | undefined;
			return !!p && !!p.from && !!p.to;
		},
		run: (ctx, payload) => {
			const { from, to } = payload as FillDragPayload;
			const extended = extendedFillRect(from, to);
			// Target inside the source band — nothing to extend.
			if (extended.width === from.width && extended.height === from.height && extended.x === from.x && extended.y === from.y)
				return;
			const writes = fillDragWrites(from, extended, ctx.combinedRows, ctx.columnKeys);
			if (writes.length) void ctx.commitCells(writes);
			// Grow the band: active cell parks on the far corner, range becomes the extended rect.
			const base = ctx.selection ?? emptySheetsSelection;
			ctx.setSelection({
				...base,
				current: {
					cell: [extended.x + extended.width - 1, extended.y + extended.height - 1],
					range: extended,
				},
			});
		},
	},

	// ---- ARROW MOVE (plain arrow: setAnchor + moveActiveCell + scroll) ----
	// Each direction is its own named command; the funnel resolves the arrow key to it.
	makeMoveCommand('cell.moveUp', 0, -1),
	makeMoveCommand('cell.moveDown', 0, 1),
	makeMoveCommand('cell.moveLeft', -1, 0),
	makeMoveCommand('cell.moveRight', 1, 0),

	// ---- ARROW EXTEND (shift+arrow: extendToCell + scroll) ----
	makeExtendCommand('cell.extendUp', 0, -1),
	makeExtendCommand('cell.extendDown', 0, 1),
	makeExtendCommand('cell.extendLeft', -1, 0),
	makeExtendCommand('cell.extendRight', 1, 0),

	// ---- ABSOLUTE NAV (Tab/Home/End/PageUp/PageDown: computeKeyNavTarget) ----
	{
		id: 'cell.navAbsolute',
		canRun: gridNonEmpty,
		run: (ctx, payload) => {
			const p = payload as NavAbsolutePayload;
			const base = ctx.selection?.current?.cell ?? [0, 0];
			const target = computeKeyNavTarget(
				p.key,
				{ ctrlOrMeta: p.ctrlOrMeta, shift: p.shift },
				base,
				ctx.colCount,
				ctx.rowCount,
				p.pageRows,
			);
			if (!target) return;
			// Absolute moves are plain activates — reset the range anchor to the landing cell.
			ctx.setAnchor([target[0], target[1]]);
			ctx.setActiveCell(target[0], target[1]);
			ctx.scrollToCell(target[0], target[1]);
		},
	},

	// ---- OPEN EDITOR AT ACTIVE (Enter / F2) ----
	{
		id: 'editor.openActive',
		// Mirrors the original `if (openEditorAtActiveCell()) e.preventDefault()`: only
		// prevent default when an overlay actually opened. canRun probes the same path.
		canRun: (ctx) => ctx.openEditorAtActive(),
		run: () => {
			// canRun already opened the editor (it returns true only when it opened) — running
			// again would double-open, so the effect lives in canRun and run is a no-op. This is
			// the verbatim "open then conditionally preventDefault" semantics, expressed through
			// the gate so a non-opening Enter falls through WITHOUT preventDefault.
		},
	},

	// ---- TYPE-TO-EDIT SENTINEL (printable key: openEditorAtActive(char)) ----
	// The LAST-RESOLVED sentinel for printable keys — it goes THROUGH dispatch (so it is
	// interceptable), NOT an out-of-band fallback. canRun opens with the seed char and gates
	// preventDefault on a real open (readonly cells return false → key falls through).
	{
		id: 'editor.typeToEdit',
		canRun: (ctx, payload) => ctx.openEditorAtActive((payload as TypeToEditPayload).char),
		run: () => {
			// effect performed in canRun (same conditional-preventDefault rationale as openActive).
		},
	},

	// ---- POINTER ACTIVATE (click: setAnchor + setActiveCell) ----
	{
		id: 'cell.activate',
		run: (ctx, payload) => {
			const { col, row } = payload as CellPointerPayload;
			ctx.setAnchor([col, row]);
			ctx.setActiveCell(col, row);
		},
	},

	// ---- POINTER SHIFT-EXTEND (shift-click: extendToCell) ----
	{
		id: 'cell.extendToClicked',
		run: (ctx, payload) => {
			const { col, row } = payload as CellPointerPayload;
			ctx.extendToCell(col, row);
		},
	},

	// ---- DBLCLICK OPEN (openEditorAt) ----
	{
		id: 'editor.open',
		run: (ctx, payload) => {
			const { rowIndex, colKey, anchorRect, initialText } = payload as EditorOpenPayload;
			ctx.openEditorAt(rowIndex, colKey, anchorRect, initialText);
		},
	},

	// ---- STRUCTURAL POINTER (routed through dispatch for invariant completeness) ----
	{
		id: 'header.sortToggle',
		run: (ctx, payload) => {
			ctx.sortToggle((payload as SortTogglePayload).colKey);
		},
	},
	{
		id: 'rowmarker.toggleRow',
		run: (ctx, payload) => {
			const { rowIndex, shift } = payload as ToggleRowPayload;
			// Delegated to the existing rowMarker.onToggleRow (anchor + selectRange/toggleRow). Phase 1
			// keeps that handler the source of truth; the command threads it so the id exists in the map.
			ctx.toggleRow(rowIndex, shift);
		},
	},
	{
		id: 'rowmarker.toggleAll',
		run: (ctx) => {
			ctx.toggleAll();
		},
	},
];

/**
 * Plain-arrow MOVE command factory (verbatim: arrow branch, non-shift path). Computes the
 * clamped target off the LATEST selection, RESETS the anchor, moves, then scrolls.
 */
function makeMoveCommand(id: string, dCol: number, dRow: number): GridCommand {
	return {
		id,
		canRun: gridNonEmpty,
		run: (ctx) => {
			const base = ctx.selection?.current?.cell ?? [0, 0];
			const nextCol = Math.max(0, Math.min(base[0] + dCol, ctx.colCount - 1));
			const nextRow = Math.max(0, Math.min(base[1] + dRow, ctx.rowCount - 1));
			ctx.setAnchor([nextCol, nextRow]);
			ctx.moveActiveCell(dCol, dRow, ctx.colCount, ctx.rowCount);
			ctx.scrollToCell(nextCol, nextRow);
		},
	};
}

/**
 * Shift-arrow EXTEND command factory (verbatim: arrow branch, shift path). Extends the
 * range from the FIXED anchor to the clamped target, then scrolls the target into view.
 */
function makeExtendCommand(id: string, dCol: number, dRow: number): GridCommand {
	return {
		id,
		canRun: gridNonEmpty,
		run: (ctx) => {
			const base = ctx.selection?.current?.cell ?? [0, 0];
			const nextCol = Math.max(0, Math.min(base[0] + dCol, ctx.colCount - 1));
			const nextRow = Math.max(0, Math.min(base[1] + dRow, ctx.rowCount - 1));
			ctx.extendToCell(nextCol, nextRow);
			ctx.scrollToCell(nextCol, nextRow);
		},
	};
}

/**
 * Build a command registry: DEFAULT_COMMANDS, with optional consumer overrides folded in
 * LAST so a matching id REPLACES the default and a new id ADDS a command (Phase 2 seam).
 */
export function createGridCommandRegistry(overrides?: GridCommand[]): GridCommandRegistry {
	const registry: GridCommandRegistry = new Map();
	for (const cmd of DEFAULT_COMMANDS) registry.set(cmd.id, cmd);
	if (overrides) {
		for (const cmd of overrides) registry.set(cmd.id, cmd);
	}
	return registry;
}

/**
 * Internal event->command core types (P4 Phase 1).
 *
 * Every existing grid interaction maps to exactly ONE named {@link GridCommand},
 * and every command runs through ONE {@link makeDispatch} pipeline. Commands are
 * PLAIN OBJECTS (no classes — project rule); they receive a {@link GridCommandContext}
 * and an optional payload, call the EXISTING stable dispatchers verbatim, and never
 * own state.
 *
 * Phase 1 is a REFACTOR ONLY: behavior must stay byte-for-byte identical. No public
 * API props ship this phase — the interceptor seam is internal-first.
 */

import type { GridCommandContext } from './context';

/**
 * A named, dispatchable grid action. `run` performs the effect (calling
 * `ctx.<dispatcher>`); the optional `canRun` is a synchronous guard checked AFTER
 * the interceptor chain — a `false` no-ops the command (and skips `native.preventDefault`).
 * `run` is synchronous-returning by contract; it MAY kick a Promise (undo/redo), but
 * the dispatch pipeline never awaits it (no async-dispatch / re-entrancy machinery).
 */
export interface GridCommand<P = unknown> {
	id: string;
	run(ctx: GridCommandContext, payload?: P): void | Promise<void>;
	canRun?(ctx: GridCommandContext, payload?: P): boolean;
}

/** The command registry: id -> command. Mutable so consumers can override (Phase 2). */
export type GridCommandRegistry = Map<string, GridCommand>;

/**
 * Centralized concurrency limits for Sheets async workflows.
 * Keep these values conservative to avoid overloading API endpoints.
 */
export const SHEETS_CONCURRENCY = {
	draftSubmit: 3,
	bulkDelete: 4,
} as const;

import { createContext, useContext } from 'react';
import type { QueryClient } from '@tanstack/react-query';

import type { SheetsExecuteFn, SheetsUploadFn } from './sheets-execute';
import type { SheetsLogger } from '../utils/sheets-logger';
import type { CellTypePlugin } from '../cell-types/define-cell-type';
import type { SheetsBackendAdapter } from '../adapter/sheets-adapter';

export interface SheetsAuthEmbedded {
	mode: 'embedded';
	getToken: () => string | null;
	/**
	 * Stable, non-secret identity used to isolate cached data between users.
	 * Hosts should return the authenticated user/session id, never the token.
	 * When omitted, the provider uses an opaque key that changes with the token.
	 */
	getIdentityKey?: () => string | null;
}

export interface SheetsAuthStandalone {
	mode: 'standalone';
}

export interface SheetsConfig {
	/** Data endpoint (app-public GraphQL) */
	endpoint: string;
	/** Auth endpoint (auth GraphQL) — required for standalone mode */
	authEndpoint?: string;
	/** Database ID for multi-tenant scoping */
	databaseId?: string;
	/** Auth mode */
	auth: SheetsAuthEmbedded | SheetsAuthStandalone;
	/** Field type overrides (replaces schema-builder smart tags) */
	fieldTypeOverrides?: Record<string, string>;
	/** Optional: BCP-47 locale for locale-aware date/number formatting (default 'en-US'). */
	locale?: string;
	/** Optional: inject custom execute function */
	execute?: SheetsExecuteFn;
	/** Optional: inject custom upload function */
	executeUpload?: SheetsUploadFn;
	/** Optional upload settings. `bucketKey` defaults to "public". */
	upload?: { bucketKey?: string };
	/** Optional: inject existing QueryClient */
	queryClient?: QueryClient;
	/** Optional: inject a custom backend adapter. Defaults to the PostGraphile adapter. */
	adapter?: SheetsBackendAdapter;
	/** Optional: provider-level cell-type plugins (consumer override layer). */
	plugins?: CellTypePlugin[];
	/** Called on 401/UNAUTHENTICATED before the error is thrown. Host app handles token cleanup. */
	onAuthError?: () => void;
	/** Optional: inject a custom logger. Installed into the module logger singleton by the provider. */
	logger?: SheetsLogger;
	/** Optional: called when a grid/editor/mutation/upload error surfaces. Host app handles reporting. */
	onError?: (
		error: unknown,
		ctx?: { source?: 'grid' | 'editor' | 'mutation' | 'upload'; tableName?: string },
	) => void;
}

export interface SheetsContextValue {
	config: SheetsConfig;
	execute: SheetsExecuteFn;
	executeUpload: SheetsUploadFn;
	scopeKey: SheetsScopeKey;
}

export interface SheetsScopeKey {
	databaseId: string | null;
	endpoint: string;
	identityKey: string | null;
}

export const SheetsContext = createContext<SheetsContextValue | null>(null);

export function useSheetsContext(): SheetsContextValue {
	const ctx = useContext(SheetsContext);
	if (!ctx) {
		throw new Error('useSheetsContext must be used within a <SheetsProvider>');
	}
	return ctx;
}

import type { DocumentNode } from 'graphql';
import { print } from 'graphql';

import { ConstructiveError, createError, TypedDocumentString } from '@constructive-io/data';

import type { SheetsConfig } from './sheets-context';
import {
	callUploadOp,
	discoverUploadCapability,
	fetchDownloadUrl,
	presignedPut,
	sha256HexFromBuffer,
} from './sheets-upload-presigned';

// ============================================================================
// Types
// ============================================================================

type ExecutableDocument = TypedDocumentString<any, any> | DocumentNode | string | unknown;

export type SheetsExecuteFn = <T = unknown>(
	document: ExecutableDocument,
	variables?: Record<string, unknown>,
) => Promise<T>;

/**
 * Result of an upload through the seam. `url` is the only guaranteed field;
 * the REST upload endpoint also returns `{ filename, mime, size }` (and may
 * return server-internal extras). Keeping it open-ended lets callers read the
 * richer metadata while a bare `{ url }` (e.g. the mock) still satisfies it.
 */
export type SheetsUploadResult = { url: string } & Record<string, unknown>;

/**
 * Optional upload metadata carried through the seam (third arg). Lets an
 * injected `executeUpload` see the destination field/row and report progress.
 * All fields optional, so existing `(file, path?)` callers stay valid.
 */
export interface SheetsUploadOptions {
	tableName?: string;
	fieldName?: string;
	recordId?: string | number;
	onProgress?: (progress: { loaded: number; total: number; percentage: number }) => void;
}

export type SheetsUploadFn = (
	file: File,
	path?: string,
	options?: SheetsUploadOptions,
) => Promise<SheetsUploadResult>;

// ============================================================================
// Helpers
// ============================================================================

function documentToString(document: ExecutableDocument): string {
	if (typeof document === 'string') return document;
	if (document instanceof String) return document.toString();
	if (document && typeof document === 'object' && 'kind' in (document as DocumentNode)) {
		return print(document as DocumentNode);
	}
	if (document === null || document === undefined) {
		throw createError.badRequest('Invalid GraphQL document: null or undefined');
	}
	return String(document);
}

// ============================================================================
// GraphQL Response Parsing
// ============================================================================

interface GraphQLResponseError {
	message: string;
	extensions?: { code?: string };
}

interface GraphQLResponse {
	data?: unknown;
	errors?: GraphQLResponseError[];
}

function hasAuthMessage(message: string | undefined): boolean {
	const normalized = String(message ?? '').toLowerCase();
	return (
		normalized.includes('unauthenticated') ||
		normalized.includes('unauthorized') ||
		normalized.includes('authentication')
	);
}

function parseGraphQLResponse(response: GraphQLResponse, onAuthError?: () => void): ConstructiveError | null {
	if (!response.errors?.length) return null;

	const error = response.errors[0];
	const code = error.extensions?.code;
	const message = error.message || 'GraphQL query failed';

	if (code === 'UNAUTHENTICATED' || hasAuthMessage(message)) {
		onAuthError?.();
		return createError.unauthorized('Authentication required. Please log in again.');
	}

	if (code === 'FORBIDDEN') {
		return createError.forbidden('You do not have permission to perform this action.');
	}

	return createError.graphql(message, code);
}

// ============================================================================
// Factory
// ============================================================================

export function createSheetsExecute(
	config: SheetsConfig,
	getToken: () => string | null,
): SheetsExecuteFn {
	return async <T = unknown>(
		document: ExecutableDocument,
		variables?: Record<string, unknown>,
	): Promise<T> => {
		const url = config.endpoint;
		if (!url) {
			throw createError.badRequest('No GraphQL endpoint configured.');
		}

		const token = getToken();
		const headers: Record<string, string> = {
			'Content-Type': 'application/json',
			Accept: 'application/graphql-response+json',
		};
		if (token) {
			headers['Authorization'] = `Bearer ${token}`;
		}

		let response: Response;
		try {
			response = await fetch(url, {
				method: 'POST',
				headers,
				body: JSON.stringify({
					query: documentToString(document),
					...(variables !== undefined && { variables }),
				}),
			});
		} catch (error) {
			throw createError.network(error instanceof Error ? error : undefined);
		}

		if (!response.ok) {
			const { status, statusText } = response;
			if (status === 401) {
				config.onAuthError?.();
				throw createError.unauthorized('Authentication required. Please log in again.');
			}
			if (status === 403) {
				throw createError.forbidden('You do not have permission to perform this action.');
			}
			if (status === 404) {
				throw createError.notFound('The requested endpoint does not exist.');
			}
			try {
				const body = await response.json();
				if (body.errors?.length) {
					throw createError.graphql(body.errors[0].message || `Request failed: ${status}`, body.errors[0].extensions?.code);
				}
			} catch (e) {
				if (e instanceof ConstructiveError) throw e;
			}
			throw createError.badRequest(`Request failed: ${status} ${statusText}`);
		}

		const result: GraphQLResponse = await response.json();
		const graphqlError = parseGraphQLResponse(result, config.onAuthError);
		if (graphqlError) {
			throw graphqlError;
		}

		return result.data as T;
	};
}

/**
 * Presigned-URL cell-upload seam.
 *
 * Replaces the legacy multipart `<endpoint>/upload` POST entirely. The flow:
 *   1. Read + SHA-256 hash the file bytes (Web Crypto)
 *   2. Discover (cached per endpoint) the upload op + downloadUrl-by-id field
 *      via GraphQL introspection — the root `upload<Type>File` mutation, matched
 *      by FIELD/TYPE SHAPE (LOCKED: no hardcoded names)
 *   3. Call the upload op with input `{ bucketKey, contentHash, contentType,
 *      size, filename }` — NO `ownerId` (app-scoped buckets have no owner_id)
 *   4. If `uploadUrl` is non-null, PUT the raw bytes to it with ONLY the signed
 *      `Content-Type` header (NO Authorization). Skipped when `deduplicated`.
 *   5. Resolve the stable public `downloadUrl` for the returned fileId.
 *
 * Returns `{ url, filename, mime, size, key, fileId }` where `url` is the stable
 * download URL — the same cell value shape callers/Step-2 already consume.
 *
 * `path` is ignored (content-addressed buckets key on `contentHash`).
 */
export function createSheetsUpload(config: SheetsConfig, getToken: () => string | null): SheetsUploadFn {
	// Reuse the kept GraphQL executor so canonical error normalization + onAuthError
	// (401/UNAUTHENTICATED) apply to introspection, the upload op, and the
	// downloadUrl query alike.
	const execute = config.execute ?? createSheetsExecute(config, getToken);

	return async (file: File, _path?: string, options?: SheetsUploadOptions): Promise<SheetsUploadResult> => {
		if (!config.endpoint) {
			throw createError.badRequest('No GraphQL endpoint configured.');
		}

		const bucketKey = config.upload?.bucketKey ?? 'public';
		const contentType = file.type || 'application/octet-stream';

		// Single read of the bytes — reused for both hashing and the PUT body.
		const buffer = await file.arrayBuffer();
		const contentHash = await sha256HexFromBuffer(buffer);

		const cap = await discoverUploadCapability(config.endpoint, execute);

		const payload = await callUploadOp(execute, cap, {
			bucketKey,
			contentHash,
			contentType,
			size: file.size,
			filename: file.name,
		});

		// Dedup (deduplicated ⇒ uploadUrl === null) means the row + S3 object already
		// exist; skip the PUT. A non-deduplicated payload MUST carry an uploadUrl — a
		// null there is a server-contract violation, so fail loudly rather than
		// resolving a downloadUrl for an object that was never uploaded.
		if (!payload.deduplicated) {
			if (!payload.uploadUrl) {
				throw createError.badRequest('Upload failed: server returned no uploadUrl for a non-deduplicated file.');
			}
			await presignedPut(payload.uploadUrl, buffer, contentType, options?.onProgress);
		} else {
			options?.onProgress?.({ loaded: file.size, total: file.size, percentage: 100 });
		}

		const url = await fetchDownloadUrl(execute, cap, payload.fileId);

		return {
			url,
			filename: file.name,
			mime: file.type,
			size: file.size,
			key: payload.key,
			fileId: payload.fileId,
		};
	};
}

export { ConstructiveError } from '@constructive-io/data';

import { useEffect, useId, useMemo, useRef } from 'react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { useStore as useZustandStore, type StoreApi } from 'zustand';

import { SheetsContext, type SheetsConfig, type SheetsContextValue, type SheetsScopeKey } from './sheets-context';
import { createSheetsExecute, createSheetsUpload, type SheetsExecuteFn, type SheetsUploadFn } from './sheets-execute';
import { createSheetsStore, SheetsStoreContext, type SheetsStoreState } from '../store/sheets-store';
import { getStoredToken } from '../auth/utils/token-store';
import { setSheetsLogger } from '../utils/sheets-logger';
import { setSheetsLocale } from '../utils/sheets-i18n';
import { sheetsQueryKeys } from '../hooks/query-keys';

interface SheetsProviderProps {
	config: SheetsConfig;
	children: React.ReactNode;
}

export function SheetsProvider({ config, children }: SheetsProviderProps) {
	const providerInstanceId = useId();
	// Create store once
	const storeRef = useRef<StoreApi<SheetsStoreState> | null>(null);
	if (!storeRef.current) {
		storeRef.current = createSheetsStore();
	}
	const store = storeRef.current;
	const standaloneIdentityKey = useZustandStore(store, (state) => state.identityKey);
	const standaloneAccessToken = useZustandStore(store, (state) => state.accessToken);

	// Install the host logger + locale synchronously so they apply before first paint.
	setSheetsLogger(config.logger);
	setSheetsLocale(config.locale);

	// Keep the module singletons in sync if the host swaps them across renders.
	useEffect(() => {
		setSheetsLogger(config.logger);
		setSheetsLocale(config.locale);
	}, [config.logger, config.locale]);

	// Restore persisted token for standalone mode
	useEffect(() => {
		const store = storeRef.current?.getState();
		if (!store) return;

		if (config.auth.mode !== 'standalone') {
			// Prevent leaking stale standalone tokens when switching auth modes.
			store.setUnauthenticated();
			return;
		}
		const databaseId = config.databaseId || 'default';
		const stored = getStoredToken(databaseId);
		if (!stored) {
			store.setUnauthenticated();
			return;
		}

		// Only restore if not expired
		const expiresAt = new Date(stored.expiresAt);
		if (expiresAt > new Date()) {
			store.setAuthenticated(stored.accessToken, stored.expiresAt, stored.identityKey ?? null);
			return;
		}

		store.setUnauthenticated();
	}, [config.auth.mode, config.databaseId]);

	// Always provide a QueryClient context. If consumer injects one, reuse it.
	const internalQueryClient = useMemo(
		() =>
			new QueryClient({
				defaultOptions: {
					queries: {
						staleTime: 5 * 60 * 1000,
						gcTime: 30 * 60 * 1000,
						retry: 1,
					},
				},
			}),
		[],
	);
	const queryClient = config.queryClient ?? internalQueryClient;

	// Token getter: embedded mode uses config.auth.getToken, standalone uses store
	const getToken = useMemo(() => {
		if (config.auth.mode === 'embedded') {
			return config.auth.getToken;
		}
		// Standalone: read from store
		return () => store.getState().accessToken ?? null;
	}, [config.auth, store]);

	// Create execute function
	const execute: SheetsExecuteFn = useMemo(() => {
		if (config.execute) return config.execute;
		return createSheetsExecute(config, getToken);
	}, [config, getToken]);

	// Create upload function
	const executeUpload: SheetsUploadFn = useMemo(() => {
		if (config.executeUpload) return config.executeUpload;
		return createSheetsUpload(config, getToken);
	}, [config, getToken]);

	const configuredIdentityKey =
		config.auth.mode === 'embedded'
			? (config.auth.getIdentityKey?.() ?? null)
			: standaloneIdentityKey;
	const activeToken = config.auth.mode === 'embedded' ? config.auth.getToken() : standaloneAccessToken;
	const authGenerationRef = useRef({ mode: config.auth.mode, token: activeToken, generation: 0 });
	if (
		authGenerationRef.current.mode !== config.auth.mode ||
		authGenerationRef.current.token !== activeToken
	) {
		authGenerationRef.current = {
			mode: config.auth.mode,
			token: activeToken,
			generation: authGenerationRef.current.generation + 1,
		};
	}
	// If an older host has not supplied a user id, isolate each observed auth
	// token generation behind an opaque provider-local key. Tokens never enter
	// TanStack Query keys or devtools.
	const identityKey =
		configuredIdentityKey ??
		`anonymous:${providerInstanceId}:${authGenerationRef.current.generation}`;

	// Scope metadata, rows, and mutations by endpoint and non-secret identity.
	const scopeKey: SheetsScopeKey = useMemo(
		() => ({
			databaseId: config.databaseId ?? null,
			endpoint: config.endpoint,
			identityKey,
		}),
		[config.databaseId, config.endpoint, identityKey],
	);

	// Changing database, endpoint, or user invalidates in-flight work from the
	// previous scope. Its cached data remains isolated under its old key.
	useEffect(() => {
		return () => {
			void queryClient.cancelQueries({ queryKey: sheetsQueryKeys.scope(scopeKey) });
		};
	}, [queryClient, scopeKey]);

	const contextValue: SheetsContextValue = useMemo(
		() => ({ config, execute, executeUpload, scopeKey }),
		[config, execute, executeUpload, scopeKey],
	);

	return (
		<QueryClientProvider client={queryClient}>
			<SheetsStoreContext.Provider value={store}>
				<SheetsContext.Provider value={contextValue}>{children}</SheetsContext.Provider>
			</SheetsStoreContext.Provider>
		</QueryClientProvider>
	);
}

/**
 * Presigned-URL upload helpers for the sheets cell-upload seam.
 *
 * Replaces the legacy multipart `<endpoint>/upload` POST. The flow is:
 *   1. SHA-256 hash the file bytes (Web Crypto, zero new deps)
 *   2. Call the presigned upload op (discovered via introspection) to get a
 *      presigned PUT url + fileId
 *   3. PUT the raw bytes to that url (only Content-Type, NO Authorization)
 *   4. Resolve the stable public `downloadUrl` for the fileId
 *
 * `confirmUpload` is intentionally skipped: the backend plugin creates the file
 * row inside the upload op, so `downloadUrl` resolves immediately.
 *
 * The upload op is discovered via runtime introspection, matched by FIELD/TYPE
 * SHAPE (never a hardcoded name): a root mutation `upload<Type>File(input: {...})`
 * whose input + payload carry the upload shape.
 *
 * The downloadUrl-by-id field is likewise shape-discovered. Three read shapes,
 * preferred in order: the inflected singular `appFile(id:)`; a filtered
 * connection `appFiles(where:{id:{equalTo:$id}}){ nodes { downloadUrl } }`
 * (Relay-disabled backends); and the Relay `node(nodeId:)` fallback.
 */

import { getIntrospectionQuery } from 'graphql';

import { createError } from '@constructive-io/data';

import type { SheetsExecuteFn } from './sheets-execute';

// ============================================================================
// Capability discovery types
// ============================================================================

export interface UploadCapability {
	/** Upload mutation field name, discovered by shape, e.g. 'uploadAppFile'. */
	uploadFieldName: string;
	/** The upload input object type name, e.g. 'UploadAppFileInput'. */
	inputTypeName: string;
	/** Query field used to resolve the stable downloadUrl by id, e.g. 'appFile' | 'node' | 'appFiles'. */
	fileByIdField: string;
	/**
	 * Which downloadUrl-by-id resolution shape was discovered:
	 *   - 'id'         inflected singular `appFile(id:)`
	 *   - 'connection' filtered connection `appFiles(where:{id:{equalTo:$id}}){ nodes { downloadUrl } }`
	 *   - 'nodeId'     Relay `node(nodeId:)` (last-resort fallback)
	 */
	fileByIdArgName: 'id' | 'nodeId' | 'connection';
	/** The file object type name (used to spread `... on <Type>` on the Relay node path). */
	fileTypeName: string;
	/** The GraphQL scalar type name for the `$id` variable (e.g. 'UUID'), discovered by shape. */
	idScalarName?: string;
	/** connection kind only — the filter arg name on the connection field, e.g. 'where' | 'filter' | 'condition'. */
	connectionFilterArgName?: string;
	/** connection kind only — the id field name inside the filter input, e.g. 'id'. */
	connectionIdField?: string;
	/** connection kind only — the equality operator field for style (a), e.g. 'equalTo'. Absent for condition style (b). */
	connectionIdOperator?: string;
	/** connection kind only — the field on the connection object holding the file rows, e.g. 'nodes'. */
	connectionNodesField?: string;
}

interface UploadPayload {
	uploadUrl: string | null;
	fileId: string;
	key: string;
	deduplicated: boolean;
}

// ============================================================================
// SHA-256 (Web Crypto)
// ============================================================================

/**
 * SHA-256 hex digest of an already-read ArrayBuffer. Lowercase, 64 chars —
 * matches the server regex `^[a-f0-9]{64}$`. We reuse the same buffer for the
 * PUT body to avoid a second `file.arrayBuffer()` read.
 */
export async function sha256HexFromBuffer(buffer: ArrayBuffer): Promise<string> {
	if (!globalThis.crypto?.subtle) {
		throw createError.badRequest('Web Crypto (crypto.subtle) is unavailable; cannot hash file for upload.');
	}
	const digest = await crypto.subtle.digest('SHA-256', buffer);
	const bytes = new Uint8Array(digest);
	let hex = '';
	for (let i = 0; i < bytes.length; i++) {
		hex += bytes[i].toString(16).padStart(2, '0');
	}
	return hex;
}

// ============================================================================
// Introspection-based capability discovery (cached per endpoint)
// ============================================================================

const capabilityCache = new Map<string, Promise<UploadCapability>>();

/** Test-only: clear the per-endpoint capability cache between cases. */
export function __resetUploadCapabilityCache(): void {
	capabilityCache.clear();
}

/**
 * Discover the upload op + downloadUrl-by-id field for an endpoint, by shape.
 * Cached per `endpoint`; concurrent uploads share one in-flight introspection.
 */
export function discoverUploadCapability(endpoint: string, execute: SheetsExecuteFn): Promise<UploadCapability> {
	const cached = capabilityCache.get(endpoint);
	if (cached) return cached;

	const promise = (async () => {
		const data = await execute<{ __schema: IntrospectionSchema }>(getIntrospectionQuery());
		const schema = data?.__schema;
		if (!schema) {
			throw createError.badRequest('Uploads are not enabled for this endpoint.');
		}
		return resolveUploadCapability(schema);
	})();

	// Don't cache a rejected discovery — let the next attempt retry.
	promise.catch(() => capabilityCache.delete(endpoint));
	capabilityCache.set(endpoint, promise);
	return promise;
}

// --- Minimal introspection shapes (only what discovery reads) ---

// Loose, structural shapes for the slice of introspection that discovery
// reads. `ofType` recurses with `any` so hand-built fixtures and the real
// `IntrospectionQuery['__schema']` (from `graphql`) both satisfy these without
// exact-match friction — discovery validates by runtime shape regardless.
interface IntrospectionTypeRef {
	kind: string;
	name?: string | null;
	ofType?: any;
}

interface IntrospectionInputValue {
	name: string;
	type: IntrospectionTypeRef;
}

interface IntrospectionField {
	name: string;
	args: ReadonlyArray<IntrospectionInputValue>;
	type: IntrospectionTypeRef;
}

interface IntrospectionType {
	kind: string;
	name?: string | null;
	fields?: ReadonlyArray<IntrospectionField> | null;
	inputFields?: ReadonlyArray<IntrospectionInputValue> | null;
}

/** Loose structural shape of an introspection `__schema` (accepts fixtures + real). */
export interface IntrospectionSchema {
	queryType?: { name: string } | null;
	mutationType?: { name: string } | null;
	types: ReadonlyArray<IntrospectionType>;
}

/** Unwrap NON_NULL / LIST wrappers down to the named type. */
function namedTypeName(ref: IntrospectionTypeRef | null | undefined): string | null {
	let cur = ref;
	while (cur && (cur.kind === 'NON_NULL' || cur.kind === 'LIST')) {
		cur = cur.ofType ?? null;
	}
	return cur?.name ?? null;
}

/**
 * True if `ref` is a LIST (optionally NON_NULL-wrapped) at the outer level, i.e.
 * the field is plural. Unwraps only leading NON_NULL wrappers (e.g. `[AppFile]!`)
 * before checking for the LIST — distinguishes `nodes: [AppFile]` from a singular
 * `appFile: AppFile`.
 */
function isListTypeRef(ref: IntrospectionTypeRef | null | undefined): boolean {
	let cur = ref;
	while (cur && cur.kind === 'NON_NULL') {
		cur = cur.ofType ?? null;
	}
	return cur?.kind === 'LIST';
}

/**
 * PostGraphile names the primary-key column `id` on every row type, so the
 * filter input field that selects a single file by primary key is `id`. This is
 * the same convention the singular by-id branch (`appFile(id:)`) relies on.
 */
const PK_FIELD_NAME = 'id';

/**
 * Pure resolver over an introspection __schema. Exported for direct unit tests
 * (no fetch). Matches by field/type SHAPE, never by a literal name.
 */
export function resolveUploadCapability(schema: IntrospectionSchema): UploadCapability {
	const typeByName = new Map<string, IntrospectionType>();
	for (const t of schema.types) {
		if (t.name) typeByName.set(t.name, t);
	}

	const objectHasFields = (typeName: string | null, names: string[]): boolean => {
		if (!typeName) return false;
		const t = typeByName.get(typeName);
		if (!t?.fields) return false;
		const present = new Set(t.fields.map((f) => f.name));
		return names.every((n) => present.has(n));
	};

	const inputHasFields = (typeName: string | null, names: string[]): boolean => {
		if (!typeName) return false;
		const t = typeByName.get(typeName);
		if (!t?.inputFields) return false;
		const present = new Set(t.inputFields.map((f) => f.name));
		return names.every((n) => present.has(n));
	};

	const PAYLOAD_FIELDS = ['uploadUrl', 'fileId', 'deduplicated'];
	const INPUT_FIELDS = ['contentHash', 'bucketKey', 'contentType', 'size'];

	const mutationType = schema.mutationType ? typeByName.get(schema.mutationType.name) : null;
	const queryType = schema.queryType ? typeByName.get(schema.queryType.name) : null;

	// rootUpload discovery: a Mutation field with a single `input` arg whose input
	// type carries the upload-input shape and whose payload carries the
	// upload-payload shape. (The legacy bucket-centric `requestUploadUrl` shape was
	// removed from the backend on 2026-05-08; only the root upload mutation exists.)
	let upload: Pick<UploadCapability, 'uploadFieldName' | 'inputTypeName'> | null = null;

	for (const field of mutationType?.fields ?? []) {
		const inputArg = field.args.find((a) => a.name === 'input');
		if (!inputArg) continue;
		const inputTypeName = namedTypeName(inputArg.type);
		const payloadTypeName = namedTypeName(field.type);
		if (
			inputHasFields(inputTypeName, INPUT_FIELDS) &&
			objectHasFields(payloadTypeName, PAYLOAD_FIELDS)
		) {
			upload = { uploadFieldName: field.name, inputTypeName: inputTypeName as string };
			break;
		}
	}

	if (!upload) {
		throw createError.badRequest('Uploads are not enabled for this endpoint.');
	}

	// --- File object type + by-id field for downloadUrl ---
	const downloadById = resolveDownloadByIdField(schema, typeByName, queryType, upload.uploadFieldName);

	return {
		...upload,
		...downloadById,
	};
}

type DownloadByIdResult = Omit<UploadCapability, 'uploadFieldName' | 'inputTypeName'>;

function resolveDownloadByIdField(
	schema: IntrospectionSchema,
	typeByName: Map<string, IntrospectionType>,
	queryType: IntrospectionType | null | undefined,
	uploadFieldName: string,
): DownloadByIdResult {
	// The file object type carries a `downloadUrl` field (grounded on
	// download-url-field.ts which adds `downloadUrl: String` to @storageFiles).
	const fileTypesWithDownloadUrl = new Set<string>();
	for (const t of schema.types) {
		if (t.kind === 'OBJECT' && t.name && t.fields?.some((f) => f.name === 'downloadUrl')) {
			fileTypesWithDownloadUrl.add(t.name);
		}
	}

	// 1. Prefer the inflected by-id form: a Query field whose return type has a
	//    `downloadUrl` field and that takes a single `id` arg. e.g. appFile(id:).
	//    The `$id` variable type is the actual scalar of that id arg (NOT a
	//    hardcoded UUID) — derived by shape.
	for (const field of queryType?.fields ?? []) {
		const returnTypeName = namedTypeName(field.type);
		if (!returnTypeName || !fileTypesWithDownloadUrl.has(returnTypeName)) continue;
		if (field.args.length === 1 && field.args[0].name === PK_FIELD_NAME) {
			return {
				fileByIdField: field.name,
				fileByIdArgName: 'id',
				fileTypeName: returnTypeName,
				idScalarName: namedTypeName(field.args[0].type) ?? undefined,
			};
		}
	}

	// 2. Connection fallback (Relay-disabled backends, incl. the live tenant API):
	//    a Query field returning a connection whose `nodes` element is a
	//    downloadUrl-bearing file type, filtered by id. e.g.
	//      appFiles(where: { id: { equalTo: $id } }, first: 1) { nodes { downloadUrl } }
	//    All names (connection field, filter arg, id field, equality operator,
	//    nodes field, id scalar) are discovered by SHAPE, never hardcoded.
	//    Preferred over the Relay node path: it consumes the raw fileId directly,
	//    so it needs no client-side global-id construction.
	const connection = resolveConnectionDownloadField(typeByName, queryType, fileTypesWithDownloadUrl, uploadFieldName);
	if (connection) return connection;

	// 3. Relay fallback: `node(nodeId: ID!)`. Last resort — only when neither a
	//    singular `id` accessor nor a filtered connection exists. Caller spreads
	//    `... on <FileType> { downloadUrl }` and encodes the global id.
	const nodeField = queryType?.fields?.find(
		(f) => f.name === 'node' && f.args.some((a) => a.name === 'nodeId'),
	);
	if (nodeField && fileTypesWithDownloadUrl.size > 0) {
		// Deterministic file type for the inline fragment: prefer the type named
		// after the upload op (uploadAppFile → AppFile); else the first-declared
		// downloadUrl-bearing type. (Was alphabetical `.sort()[0]`, which could pick
		// the wrong type when several expose downloadUrl, e.g. DataRoomFile.)
		const preferred = uploadFieldName.replace(/^upload/, '');
		const fileTypeName = fileTypesWithDownloadUrl.has(preferred)
			? preferred
			: [...fileTypesWithDownloadUrl][0];
		return { fileByIdField: 'node', fileByIdArgName: 'nodeId', fileTypeName };
	}

	throw createError.badRequest('Uploads are not enabled for this endpoint.');
}

/**
 * Discover a filtered-connection downloadUrl-by-id path. Returns null if the
 * schema exposes no such connection. Supports two filter input styles:
 *   (a) operator filter  — `where: { id: { equalTo: $id } }` (connection-filter
 *       plugin): the id field's input type carries an equality operator.
 *   (b) condition filter — `condition: { id: $id }`: the id field is the scalar
 *       directly.
 */
function resolveConnectionDownloadField(
	typeByName: Map<string, IntrospectionType>,
	queryType: IntrospectionType | null | undefined,
	fileTypesWithDownloadUrl: Set<string>,
	uploadFieldName: string,
): DownloadByIdResult | null {
	// Equality operator names we recognize on a filter-input field, in priority
	// order (exact-match equality first).
	const EQUALITY_OPERATORS = ['equalTo', 'eq'];

	// Collect every matching connection, then pick deterministically — a tenant
	// with multiple @storageFiles tables exposes several file connections
	// (appFiles, dataRoomFiles, …), all carrying downloadUrl-bearing nodes.
	const candidates: DownloadByIdResult[] = [];

	for (const field of queryType?.fields ?? []) {
		const connTypeName = namedTypeName(field.type);
		if (!connTypeName) continue;
		const connType = typeByName.get(connTypeName);
		if (connType?.kind !== 'OBJECT' || !connType.fields) continue;

		// Find the `nodes` field whose element type is a downloadUrl-bearing file.
		// Require it to be a LIST (plural) so a singular `appFile: AppFile` field on
		// some object does NOT false-match as a connection (fetchDownloadUrl indexes
		// [nodesField][0], which only makes sense on an array).
		const nodesField = connType.fields.find((f) => {
			if (!isListTypeRef(f.type)) return false;
			const elem = namedTypeName(f.type);
			return elem != null && fileTypesWithDownloadUrl.has(elem);
		});
		if (!nodesField) continue;
		const fileTypeName = namedTypeName(nodesField.type) as string;

		// Find a filter arg whose input type has an `id` field.
		for (const arg of field.args) {
			const filterTypeName = namedTypeName(arg.type);
			const filterType = filterTypeName ? typeByName.get(filterTypeName) : null;
			if (filterType?.kind !== 'INPUT_OBJECT' || !filterType.inputFields) continue;
			const idField = filterType.inputFields.find((f) => f.name === PK_FIELD_NAME);
			if (!idField) continue;

			const idFieldTypeName = namedTypeName(idField.type);
			const idFieldType = idFieldTypeName ? typeByName.get(idFieldTypeName) : null;

			// Style (a): the id field is itself an input type carrying an equality
			// operator (e.g. UUIDFilter.equalTo). The `$id` scalar is the operator's
			// type.
			if (idFieldType?.kind === 'INPUT_OBJECT' && idFieldType.inputFields) {
				const opField = EQUALITY_OPERATORS.map((op) =>
					idFieldType.inputFields!.find((f) => f.name === op),
				).find((f) => f != null);
				if (opField) {
					candidates.push({
						fileByIdField: field.name,
						fileByIdArgName: 'connection',
						fileTypeName,
						idScalarName: namedTypeName(opField.type) ?? undefined,
						connectionFilterArgName: arg.name,
						connectionIdField: idField.name,
						connectionIdOperator: opField.name,
						connectionNodesField: nodesField.name,
					});
					break;
				}
				// id field is an input object but with no recognized equality op — skip.
				continue;
			}

			// Style (b): the id field is a scalar directly (condition style). The
			// `$id` scalar is that field's type.
			if (idFieldType?.kind === 'SCALAR' || (!idFieldType && idFieldTypeName)) {
				candidates.push({
					fileByIdField: field.name,
					fileByIdArgName: 'connection',
					fileTypeName,
					idScalarName: idFieldTypeName ?? undefined,
					connectionFilterArgName: arg.name,
					connectionIdField: idField.name,
					connectionNodesField: nodesField.name,
				});
				break;
			}
		}
	}

	if (candidates.length === 0) return null;

	// Deterministic pick: prefer the connection whose file type matches the upload
	// op (uploadAppFile → AppFile), else the first-declared. This is the LIVE
	// production path — the only downloadUrl shape on a Relay-disabled, unique-
	// lookup-disabled tenant API — so resolving the WRONG file connection (e.g.
	// reading a DataRoomFile id through appFiles) yields 0 nodes and fails every
	// upload. Mirrors the node-branch determinism, where it matters far more.
	const preferred = uploadFieldName.replace(/^upload/, '');
	return candidates.find((c) => c.fileTypeName === preferred) ?? candidates[0];
}

// ============================================================================
// Upload op call
// ============================================================================

interface UploadOpInput {
	bucketKey: string;
	contentHash: string;
	contentType: string;
	size: number;
	filename: string;
}

/**
 * Invoke the discovered upload op and normalize its payload.
 * App-scoped buckets have NO owner_id column, so `ownerId` is NEVER sent.
 */
export async function callUploadOp(
	execute: SheetsExecuteFn,
	cap: UploadCapability,
	input: UploadOpInput,
): Promise<UploadPayload> {
	const mutation = `
		mutation SheetsUpload($input: ${cap.inputTypeName}!) {
			${cap.uploadFieldName}(input: $input) {
				uploadUrl
				fileId
				key
				deduplicated
			}
		}
	`.trim();
	const data = await execute<Record<string, UploadPayload | null>>(mutation, {
		input: {
			bucketKey: input.bucketKey,
			contentHash: input.contentHash,
			contentType: input.contentType,
			size: input.size,
			filename: input.filename,
		},
	});
	const payload = data?.[cap.uploadFieldName];
	if (!payload) {
		throw createError.badRequest('Upload failed: no payload returned from upload mutation.');
	}
	return payload;
}

// ============================================================================
// Presigned PUT
// ============================================================================

/**
 * PUT the raw bytes to the presigned url. Sends ONLY the signed `Content-Type`
 * header — NO Authorization (the signature lives in the url query string), no
 * cookies, no Accept override. The browser supplies Content-Length from the body.
 *
 * When `onProgress` is provided and XHR is available, uses XHR for byte
 * progress; otherwise a plain fetch PUT.
 */
export async function presignedPut(
	url: string,
	buffer: ArrayBuffer,
	contentType: string,
	onProgress?: (progress: { loaded: number; total: number; percentage: number }) => void,
): Promise<void> {
	const total = buffer.byteLength;

	if (onProgress && typeof XMLHttpRequest !== 'undefined') {
		await putWithXHR(url, buffer, contentType, total, onProgress);
		return;
	}

	let response: Response;
	try {
		response = await fetch(url, {
			method: 'PUT',
			headers: { 'Content-Type': contentType },
			body: buffer,
		});
	} catch (error) {
		throw createError.network(error instanceof Error ? error : undefined);
	}

	if (!response.ok) {
		const body = await response.text().catch(() => '');
		throw createError.badRequest(`Upload failed: ${response.status} ${response.statusText}${body ? ` — ${body}` : ''}`);
	}
	onProgress?.({ loaded: total, total, percentage: 100 });
}

function putWithXHR(
	url: string,
	buffer: ArrayBuffer,
	contentType: string,
	total: number,
	onProgress: (progress: { loaded: number; total: number; percentage: number }) => void,
): Promise<void> {
	return new Promise((resolve, reject) => {
		const xhr = new XMLHttpRequest();
		xhr.open('PUT', url);
		xhr.setRequestHeader('Content-Type', contentType);

		xhr.upload.addEventListener('progress', (event) => {
			if (event.lengthComputable) {
				onProgress({
					loaded: event.loaded,
					total: event.total,
					percentage: Math.round((event.loaded / event.total) * 100),
				});
			}
		});

		xhr.addEventListener('load', () => {
			if (xhr.status >= 200 && xhr.status < 300) {
				onProgress({ loaded: total, total, percentage: 100 });
				resolve();
			} else {
				reject(createError.badRequest(`Upload failed: ${xhr.status} ${xhr.statusText}${xhr.responseText ? ` — ${xhr.responseText}` : ''}`));
			}
		});

		xhr.addEventListener('error', () => reject(createError.network()));

		xhr.send(buffer);
	});
}

// ============================================================================
// downloadUrl resolution
// ============================================================================

/**
 * Encode a PostGraphile global id (Relay `node` id) from a row's primary key,
 * using the default base64JSON codec: `base64(JSON.stringify([typeName, pk]))`.
 */
function toGlobalId(typeName: string, id: string): string {
	if (typeof btoa !== 'function') {
		throw createError.badRequest('Cannot encode the file node id: btoa is unavailable in this environment.');
	}
	return btoa(JSON.stringify([typeName, id]));
}

/**
 * Resolve the stable public download URL for a file id via the discovered
 * by-id field. For public files the backend returns a permanent public URL
 * (its exact path shape is the backend's concern) — stored opaquely in the cell.
 */
export async function fetchDownloadUrl(
	execute: SheetsExecuteFn,
	cap: UploadCapability,
	fileId: string,
): Promise<string> {
	if (cap.fileByIdArgName === 'nodeId') {
		// The upload payload returns the RAW primary key as `fileId`, but
		// `node(nodeId:)` expects the opaque PostGraphile global id. Encode it with
		// the default base64JSON codec (`base64([typeName, pk])`). NOTE: the live
		// tenant API is Relay-disabled and resolves via the connection branch; this
		// path is mock-covered only and assumes the default node-id codec.
		const nodeId = toGlobalId(cap.fileTypeName, fileId);
		const query = `
			query SheetsDownloadUrl($nodeId: ID!) {
				${cap.fileByIdField}(nodeId: $nodeId) {
					... on ${cap.fileTypeName} {
						downloadUrl
					}
				}
			}
		`.trim();
		const data = await execute<Record<string, { downloadUrl?: string | null } | null>>(query, { nodeId });
		const node = data?.[cap.fileByIdField];
		const url = node?.downloadUrl;
		if (!url) {
			throw createError.badRequest('Upload succeeded but no downloadUrl was returned for the file.');
		}
		return url;
	}

	// Connection fallback (Relay-disabled): filter the connection by id and read
	// the first node's downloadUrl. The filter literal is built per the discovered
	// style — operator (`{ id: { equalTo: $id } }`) or condition (`{ id: $id }`).
	if (cap.fileByIdArgName === 'connection') {
		const idScalar = cap.idScalarName ?? 'ID';
		const filterArg = cap.connectionFilterArgName as string;
		const idField = cap.connectionIdField as string;
		const nodesField = cap.connectionNodesField as string;
		const filterLiteral = cap.connectionIdOperator
			? `{ ${idField}: { ${cap.connectionIdOperator}: $id } }`
			: `{ ${idField}: $id }`;
		const query = `
			query SheetsDownloadUrl($id: ${idScalar}!) {
				${cap.fileByIdField}(${filterArg}: ${filterLiteral}, first: 1) {
					${nodesField} {
						downloadUrl
					}
				}
			}
		`.trim();
		const data = await execute<Record<string, Record<string, Array<{ downloadUrl?: string | null }> | null> | null>>(
			query,
			{ id: fileId },
		);
		const conn = data?.[cap.fileByIdField];
		const url = conn?.[nodesField]?.[0]?.downloadUrl;
		if (!url) {
			throw createError.badRequest('Upload succeeded but no downloadUrl was returned for the file.');
		}
		return url;
	}

	const idScalar = cap.idScalarName ?? 'ID';
	const query = `
		query SheetsDownloadUrl($id: ${idScalar}!) {
			${cap.fileByIdField}(id: $id) {
				id
				downloadUrl
			}
		}
	`.trim();
	const data = await execute<Record<string, { downloadUrl?: string | null } | null>>(query, { id: fileId });
	const file = data?.[cap.fileByIdField];
	const url = file?.downloadUrl;
	if (!url) {
		throw createError.badRequest('Upload succeeded but no downloadUrl was returned for the file.');
	}
	return url;
}

/**
 * Resolve a file's signed `downloadUrl` by id — the public entry point for callers
 * OUTSIDE the upload flow (e.g. a storage browser fetching the preview/copy link for
 * an already-uploaded file).
 *
 * `downloadUrl` is a Grafast computed field, so it cannot be selected through the
 * runtime query builder (`buildSelect` intersects the select against pg columns and
 * drops computed fields). This discovers the by-id field once per endpoint (cached)
 * and reads it through the SAME resolver the upload path uses. Returns null on any
 * failure — a missing url is not exceptional for the caller (it just disables
 * copy/download), so the throwing internals are swallowed here.
 */
export async function resolveDownloadUrl(
	execute: SheetsExecuteFn,
	endpoint: string,
	fileId: string,
): Promise<string | null> {
	try {
		const cap = await discoverUploadCapability(endpoint, execute);
		return await fetchDownloadUrl(execute, cap, fileId);
	} catch {
		return null;
	}
}

import { mapToFrontendCellType } from '../cell-types/type-mapping';

import { createMetadataHash } from './metadata-hash';
import type {
	BuildFormSpecOptions,
	DynamicFormSpec,
	MetaField,
	MetaTable,
	ScalarFieldKind,
	ScalarFieldSpec,
} from './types';

const SCALAR_CELL_TYPE_TO_KIND: Partial<Record<string, ScalarFieldKind>> = {
	text: 'text',
	textarea: 'multiline',
	citext: 'text',
	bpchar: 'text',
	email: 'email',
	url: 'url',
	phone: 'phone',
	uuid: 'uuid',
	inet: 'inet',
	number: 'number',
	integer: 'integer',
	smallint: 'smallint',
	decimal: 'decimal',
	currency: 'currency',
	percentage: 'percentage',
	boolean: 'boolean',
	bit: 'bit',
	date: 'date',
	datetime: 'datetime',
	time: 'time',
	timestamptz: 'timestamptz',
	json: 'json',
	jsonb: 'json',
	tsvector: 'tsvector',
};

const HUMAN_CASE_REGEX = /([a-z0-9])([A-Z])/g;

export function buildScalarFormSpec(metaTable: MetaTable, options: BuildFormSpecOptions = {}): DynamicFormSpec | null {
	const fields: ScalarFieldSpec[] = [];
	const uniqueFieldSet = collectSingleFieldUniqueNames(metaTable);
	const primaryFieldSet = collectSingleFieldPrimaryNames(metaTable);

	for (const field of metaTable.fields ?? []) {
		if (!field) continue;

		const spec = createScalarFieldSpec(field, options, uniqueFieldSet, primaryFieldSet);
		if (!spec) continue;

		fields.push(spec);
	}

	if (fields.length === 0) {
		return null;
	}

	const versionHash = createMetadataHash({
		table: metaTable.name,
		fields: fields.map((f) => ({
			name: f.name,
			kind: f.kind,
			nullable: f.nullable,
			metadata: f.metadata,
			maxLength: f.maxLength,
			minLength: f.minLength,
			minimum: f.minimum,
			maximum: f.maximum,
			enumValues: f.enumValues,
		})),
	});

	return {
		tableName: metaTable.name,
		versionHash,
		fields,
	};
}

export function findTableFormSpec(
	meta: MetaTable[] | null | undefined,
	tableName: string,
	options: BuildFormSpecOptions = {},
): DynamicFormSpec | null {
	if (!meta) return null;
	const table = meta.find((item) => item?.name === tableName);
	if (!table) return null;
	return buildScalarFormSpec(table, options);
}

function createScalarFieldSpec(
	metaField: MetaField,
	options: BuildFormSpecOptions,
	uniqueFields: Set<string>,
	primaryFields: Set<string>,
): ScalarFieldSpec | null {
	const { multilineFields } = options;
	const cellType = mapToFrontendCellType({
		gqlType: metaField.type.gqlType,
		isArray: metaField.type.isArray,
		pgAlias: metaField.type.pgAlias,
		pgType: metaField.type.pgType,
		subtype: metaField.type.subtype ?? undefined,
		encoding: metaField.type.encoding,
	});

	if (metaField.type.isArray) {
		return null;
	}

	let kind = SCALAR_CELL_TYPE_TO_KIND[cellType];

	if (!kind && cellType === 'text' && multilineFields?.has(metaField.name)) {
		kind = 'multiline';
	}

	if (!kind) {
		return null;
	}

	const nullable = isFieldNullable(metaField);
	const { maxLength, numericPrecision, numericScale } = extractTypmodConstraints(metaField);

	const label = humanize(metaField.name);
	const description = buildDescription(metaField);

	const spec: ScalarFieldSpec = {
		name: metaField.name,
		label,
		description,
		kind,
		nullable,
		metadata: {
			cellType,
			gqlType: metaField.type.gqlType,
			pgAlias: metaField.type.pgAlias ?? undefined,
			pgType: metaField.type.pgType ?? undefined,
			subtype: metaField.type.subtype ?? undefined,
			typmod: metaField.type.typmod ?? undefined,
			encoding: metaField.type.encoding ?? undefined,
		},
		constraints: {
			isUnique: uniqueFields.has(metaField.name) || undefined,
			isPrimaryKey: primaryFields.has(metaField.name) || undefined,
		},
	};

	if (metaField.enumValues?.values?.length) {
		spec.enumValues = [...metaField.enumValues.values];
	}

	if (maxLength != null) {
		spec.maxLength = maxLength;
	}

	if (numericPrecision != null) {
		spec.numericPrecision = numericPrecision;
	}

	if (numericScale != null) {
		spec.numericScale = numericScale;
	}

	if (
		kind === 'decimal' ||
		kind === 'number' ||
		kind === 'integer' ||
		kind === 'smallint' ||
		kind === 'currency' ||
		kind === 'percentage'
	) {
		const { minimum, maximum } = extractNumericCheckBounds(metaField);
		if (minimum != null) spec.minimum = minimum;
		if (maximum != null) spec.maximum = maximum;
	}

	if (kind === 'json') {
		spec.description = description ?? 'JSON value';
	}

	if (kind === 'boolean') {
		spec.defaultValue = false;
	}

	return spec;
}

function buildDescription(metaField: MetaField): string | undefined {
	if (metaField.description) return metaField.description;
	const details: string[] = [];
	const { pgAlias, pgType, subtype } = metaField.type;

	if (pgAlias && pgAlias !== pgType) {
		details.push(pgAlias);
	}
	if (pgType) {
		details.push(pgType);
	}
	if (subtype) {
		details.push(subtype);
	}

	return details.length > 0 ? details.join(' • ') : undefined;
}

function humanize(name: string): string {
	return name.replace(HUMAN_CASE_REGEX, '$1 $2').replace(/^./, (str) => str.toUpperCase());
}

function isFieldNullable(metaField: MetaField): boolean {
	if (metaField.isNotNull === true || metaField.type.isNotNull === true) return false;
	const gqlType = metaField.type.gqlType;
	if (gqlType.endsWith('!')) return false;
	// Note: modifier is a numeric code from PostgreSQL, not a string enum
	// The gqlType check above is the primary indicator of non-nullability
	return true;
}

function extractTypmodConstraints(metaField: MetaField): {
	maxLength?: number;
	numericPrecision?: number;
	numericScale?: number;
} {
	const typmod = metaField.type.typmod ?? null;
	const pgType = metaField.type.pgType?.toLowerCase();

	if (typmod == null || typmod < 0) {
		return {};
	}

	if (pgType === 'varchar' || pgType === 'character varying' || pgType === 'bpchar' || pgType === 'character') {
		return { maxLength: Math.max(0, typmod - 4) };
	}

	if (pgType === 'numeric' || pgType === 'decimal') {
		const precision = ((typmod - 4) >> 16) & 65535;
		const scale = (typmod - 4) & 65535;
		return {
			numericPrecision: precision || undefined,
			numericScale: scale || undefined,
		};
	}

	return {};
}

function extractNumericCheckBounds(_metaField: MetaField): { minimum?: number; maximum?: number } {
	// Placeholder for future enhancements: currently return empty bounds.
	// Backend check constraints can be parsed here when the metadata exposes readable expressions.
	return {};
}

function collectSingleFieldUniqueNames(metaTable: MetaTable): Set<string> {
	const result = new Set<string>();

	for (const constraint of metaTable.uniqueConstraints ?? []) {
		if (!constraint || !constraint.fields) continue;
		const fields = constraint.fields.filter((field): field is MetaField => Boolean(field));
		if (fields.length === 1) {
			result.add(fields[0].name);
		}
	}

	return result;
}

function collectSingleFieldPrimaryNames(metaTable: MetaTable): Set<string> {
	const result = new Set<string>();
	for (const constraint of metaTable.primaryKeyConstraints ?? []) {
		if (!constraint) continue;
		const fields = constraint.fields?.filter((field): field is MetaField => Boolean(field));
		if (fields && fields.length === 1) {
			result.add(fields[0].name);
		}
	}
	return result;
}

export * from './types';
export * from './metadata-hash';
export * from './form-spec-builder';
export * from './zod-schema';
export * from './mutations';

export function createMetadataHash(value: unknown): string {
	const serialized = JSON.stringify(value, stableReplacer);
	let hash = 0;
	for (let index = 0; index < serialized.length; index += 1) {
		hash = (hash * 33) ^ serialized.charCodeAt(index);
	}

	return `h${(hash >>> 0).toString(16)}`;
}

function stableReplacer(_key: string, value: unknown): unknown {
	if (value && typeof value === 'object' && !Array.isArray(value)) {
		return Object.keys(value)
			.sort()
			.reduce<Record<string, unknown>>((acc, key) => {
				acc[key] = (value as Record<string, unknown>)[key];
				return acc;
			}, {});
	}
	return value;
}

import * as React from 'react';

import { useSheetsTable } from '../hooks/use-sheets-table';
import type { SheetsRowIdentifier } from '../row-identity';

export interface DynamicMutationResult<TData = unknown> {
	submit: (values: Record<string, unknown>) => Promise<TData | null>;
	isSubmitting: boolean;
	error: Error | null;
}

export function useDynamicCreate(tableName: string): DynamicMutationResult {
	const table = useSheetsTable(tableName, { enabled: false });

	const submit = React.useCallback(
		async (values: Record<string, unknown>) => {
			const result = await table.create(values);
			return result.createdRow ?? null;
		},
		[table],
	);

	return {
		submit,
		isSubmitting: table.isCreating,
		error: table.createError,
	};
}

export function useDynamicUpdate(tableName: string, rowId: SheetsRowIdentifier): DynamicMutationResult {
	const table = useSheetsTable(tableName, { enabled: false });

	const submit = React.useCallback(
		async (values: Record<string, unknown>) => {
			const result = await table.update(rowId, values);
			return result.updatedRow ?? null;
		},
		[table, rowId],
	);

	return {
		submit,
		isSubmitting: table.isUpdating,
		error: table.updateError,
	};
}

