// The SINGLE edit-intent resolver — the host's one entry point for "what happens
// when this cell is activated?". It replaces the host's brittle
// `resolveNativeEditor(cell.meta?.cellType ?? 'text')` lookup (which mis-routed
// EVERY non-text cell to TextEditor) with an AUTHORITATIVE, exhaustive mapping
// from a `typeKey` (CellType) + the cell's readonly flag to exactly one of:
//   • { mode: 'inline-toggle' } — no overlay; the host commits `!currentBool`.
//   • { mode: 'inline-edit' }   — no overlay; the host edits IN PLACE with a bare
//                                 single-line <input> (the SIMPLE text-representable
//                                 types: text-like + number-like). url/inet are NOT
//                                 here — they keep their specialised overlay editors.
//   • { mode: 'overlay', editor } — open the resolved native overlay editor.
//   • { mode: 'none' }           — not editable (readonly / non-editable type).
//
// EXHAUSTIVENESS is structural: the buckets are DRIVEN OFF the canonical
// cell-type-groups Sets (BOOLEAN_TYPES / NUMBER_TYPES / DATE_TIME_TYPES /
// GEOMETRY_TYPES / MEDIA_TYPES / isArrayCellType / NON_EDITABLE_TYPES /
// VIEWER_ONLY_TYPES), never a hand-maintained list — so adding a member to a
// group automatically routes it here. Every CellType in cell-types/types.ts lands
// in exactly one bucket; anything unrecognised falls through to the text default
// (TextEditor), matching the `unknown` cell-type contract.
//
// CONSUMER OVERRIDE: a registered `def.editorComponent` for the typeKey (looked up
// via the injected `consumer`, i.e. `registry.getEditorComponent`) WINS as the
// overlay editor for any type that opens an overlay — same precedence the glide
// path gave `def.editor`. It does NOT override inline-toggle or readonly `none`.

import type { ComponentType } from 'react';

import {
	BOOLEAN_TYPES,
	DATE_TIME_TYPES,
	GEOMETRY_TYPES,
	MEDIA_TYPES,
	NON_EDITABLE_TYPES,
	NUMBER_TYPES,
	VIEWER_ONLY_TYPES,
	isArrayCellType,
} from '../../cell-types/cell-type-groups';
import { DOM_EDITOR_REGISTRY, type NativeEditor } from './editor-registry-dom';
import type { EditorProps } from './editor-props';

export type EditIntent =
	| { mode: 'overlay'; editor: NativeEditor }
	| { mode: 'inline-toggle' }
	| { mode: 'inline-edit' }
	| { mode: 'none' };

type EditorConsumer = (typeKey: string) => ComponentType<EditorProps> | undefined;

/** Build the overlay intent for a typeKey: consumer override wins, else the registry entry. */
function overlay(typeKey: string, consumer: EditorConsumer | undefined): EditIntent {
	const editor = (consumer?.(typeKey) as NativeEditor | undefined) ?? DOM_EDITOR_REGISTRY[typeKey];
	// No editor resolved for a type that should open one — degrade to no-edit rather
	// than portal an empty overlay. (Cannot happen for the buckets below: every one
	// has a DOM_EDITOR_REGISTRY entry.)
	return editor ? { mode: 'overlay', editor } : { mode: 'none' };
}

/**
 * Simple text-representable types (text-like + number-like) edit IN PLACE with a bare
 * <input> — no overlay. A registered consumer editor for the typeKey still WINS as an
 * overlay editor (same override precedence the overlay types give `def.editor`); only
 * the built-in path becomes inline. The host derives text-vs-number from the cell kind.
 */
function inlineOrOverride(typeKey: string, consumer: EditorConsumer | undefined): EditIntent {
	const editor = consumer?.(typeKey) as NativeEditor | undefined;
	if (editor) return { mode: 'overlay', editor };
	return { mode: 'inline-edit' };
}

/**
 * Resolve the edit intent for a cell.
 *
 * @param typeKey  - resolved CellType key (the `SheetsCellResolution.typeKey`).
 * @param opts     - `readonly` mirrors the cell's readonly flag (READONLY_CONDITIONS / draft-id / relation-not-inline).
 * @param consumer - optional per-instance editor override (`registry.getEditorComponent`).
 */
export function resolveEditIntent(
	typeKey: string,
	opts: { readonly?: boolean },
	consumer?: EditorConsumer,
): EditIntent {
	// 1) Readonly cell — never editable, regardless of type (matches the host already
	//    skipping `cell.readonly`). Also covers NON_EDITABLE types that are not viewers.
	if (opts.readonly) return { mode: 'none' };

	// 2) Non-editable types that are NOT viewer-only → no edit. (tsvector is in
	//    NON_EDITABLE_TYPES but is viewer-only, so it falls through to its viewer
	//    overlay below; this guard catches any future non-viewer non-editable type.)
	if (NON_EDITABLE_TYPES.has(typeKey) && !VIEWER_ONLY_TYPES.has(typeKey)) return { mode: 'none' };

	// 3) Booleans → inline toggle (no overlay; the host commits `!currentBool`).
	if (BOOLEAN_TYPES.has(typeKey)) return { mode: 'inline-toggle' };

	// 4) Number-like → inline edit (simple text-representable). Overlay families below stay
	//    overlay, driven off the canonical groups so they stay exhaustive.
	if (NUMBER_TYPES.has(typeKey)) return inlineOrOverride(typeKey, consumer);
	if (DATE_TIME_TYPES.has(typeKey)) return overlay(typeKey, consumer);
	if (isArrayCellType(typeKey)) return overlay(typeKey, consumer);
	if (GEOMETRY_TYPES.has(typeKey)) return overlay(typeKey, consumer);
	if (MEDIA_TYPES.has(typeKey)) return overlay(typeKey, consumer);

	// 5) Singleton overlay types (each has a DOM_EDITOR_REGISTRY entry).
	if (typeKey === 'interval') return overlay(typeKey, consumer);
	if (typeKey === 'json' || typeKey === 'jsonb') return overlay(typeKey, consumer);
	if (typeKey === 'inet') return overlay(typeKey, consumer);
	if (typeKey === 'relation') return overlay(typeKey, consumer);
	if (typeKey === 'url') return overlay(typeKey, consumer);
	// tsvector — VIEWER_ONLY, but still opens a read-only viewer overlay.
	if (VIEWER_ONLY_TYPES.has(typeKey)) return overlay(typeKey, consumer);

	// 6) Text-like default (text/textarea/email/phone/citext/bpchar/uuid/color/
	//    origin/unknown + anything unrecognised) → inline edit. `color` is NOT a real
	//    backend data type — just a hex/text string — so it edits inline too (no dedicated
	//    color editor). A consumer override on a text-like typeKey still wins as an overlay
	//    editor via `inlineOrOverride`; otherwise the cell edits in place.
	return inlineOrOverride(typeKey, consumer);
}

// Public contract for a NATIVE (DOM React-portal) overlay editor. Pure types.
//
// The Phase-4 analogue of the glide `ProvideEditorComponent` payload, but value-
// native: VALUE editors (text/json/…) call `onCommit(next)` to push a value down
// the glide value-commit path (onCellEdited -> editCell), and `onCancel()` to
// dismiss with no write. SELF-COMMITTING editors (relation/image, Phase 5) use
// the optimistic `onSubmitDraftRow`/`onInvalidateData` callbacks instead.
//
// `overlay` carries the geometry the OverlayManager already computed (via the
// reused `computeOverlayGeometry`) so editors can size/scroll without re-measuring.

import type { FieldMetadata } from '../../cell-types/cell-type-resolver';
import type { SheetsCell } from '../../cell-model/sheets-cell';
import type { RelationInfo } from '../../store/relation-info-slice';

export interface EditorProps {
	value: unknown;
	cell: SheetsCell;
	colKey: string;
	rowId: string;
	rowIndex: number;
	tableName?: string;
	fieldMeta?: FieldMetadata;
	relationInfo?: RelationInfo;
	/**
	 * Type-to-edit seed: when the overlay was opened by typing a printable char on the
	 * active cell, this carries that char. Value editors (text/number) initialize their
	 * input to it in OVERWRITE mode (replacing the cell value); other editors ignore it.
	 */
	initialText?: string;
	/** Commit a value down the glide value-commit path (onCellEdited -> editCell). */
	onCommit: (next: unknown) => void;
	/**
	 * Self-committing editors (relation/image): commit a MULTI-field patch after an
	 * out-of-band server mutation, routed through the existing optimistic-update path
	 * (handleEditorSaveComplete). Value editors use {@link onCommit} instead.
	 */
	onCommitPatch?: (patch: Record<string, unknown>) => void;
	/** Dismiss the overlay with no write. */
	onCancel: () => void;
	/** Self-committing editors: submit a client-side draft row, resolving to the server row. */
	onSubmitDraftRow?: (draftRowId: string) => Promise<unknown>;
	/** Self-committing editors: invalidate cached data after an out-of-band mutation. */
	onInvalidateData?: () => void;
	/** Geometry pre-computed by the OverlayManager (reused `computeOverlayGeometry`). */
	overlay: { maxHeight: number; flipped: boolean };
}

// Native (DOM React-portal) editor registry — the Phase-4 analogue of the glide
// `grid/editor-registry.ts` `EDITOR_REGISTRY` + `createEditor`, but value-native.
//
// The OverlayManager already supplies the focus-trap, error-guard, flip geometry
// and overlay-preset width class, so a native editor is just a `ComponentType<
// EditorProps>` — no glide `ProvideEditorCallbackResult`/`disableStyling` wrapper.
// `wrapNativeEditor` is therefore a thin passthrough that only TAGS a preset width
// class (so the OverlayManager can read it) — it does NOT re-wrap the trap/guard.
//
// `resolveNativeEditor` mirrors the glide precedence: a consumer override
// (`def.editor`, looked up via the injected `consumer` fn) wins, else the
// built-in `DOM_EDITOR_REGISTRY` entry. The `consumer` lookup is injected (not the
// CellTypeRegistry directly) so this module stays decoupled from the registry
// shape; Stage 3+ wires `registry.getEditorComponent` in at the call site.
//
// PER-EDITOR COMMIT PATTERN (Phase 5 fan-out — every native re-host must follow one):
//   • VALUE editors (text/json/date/geometry/interval/inet/array/tsvector/url):
//       read the initial value from `EditorProps.value`; on save call
//       `onCommit(nextRawValue)` (the host serialises + builds the cell). Cancel ->
//       `onCancel()`. These DO NOT mutate the server.
//   • IMAGE/upload (self-committing): the editor uploads, then
//       `onCommitPatch({ [colKey]: imageData })` (single field). On a DRAFT row it
//       must first `onSubmitDraftRow(draftRowId)` to obtain a real id, and use
//       `onInvalidateData` as the post-upload `onDraftUploadComplete`.
//   • RELATION (self-committing): the editor mutates, then
//       `onCommitPatch({ [foreignKeyField]: fkValue, [relationField ?? colKey]: relationData })`
//       (MULTI field for belongsTo). FK/display fields come from EditorProps.relationInfo.
//   The host wires onCommit/onCommitPatch/onSubmitDraftRow/onInvalidateData/onCancel
//   in SheetsDomInner; an editor only PICKS the matching callback(s) for its kind.

import type { ComponentType } from 'react';

import { ArrayEditorDom } from './array-editor';
import { DateEditorDom } from './date-editor';
import type { EditorProps } from './editor-props';
import { GeometryEditorDom } from './geometry-editor';
import { ImageEditorDom } from './image-editor';
import { InetEditorDom } from './inet-editor';
import { IntervalEditorDom } from './interval-editor';
import { JsonEditorDom } from './json-editor';
import { NumberEditorDom } from './number-editor';
import { RelationEditorDom } from './relation-editor';
import { TextEditor } from './text-editor';
import { TsvectorEditorDom } from './tsvector-editor';
import { UrlEditorDom } from './url-editor';

/**
 * A native editor that optionally advertises its overlay-preset width class and whether it
 * commits-on-click-away (Stage B): `commitsOnBlur` editors own an `onBlur → onCommit` path,
 * so the OverlayManager dismisses them with `dismissMode='commit'` (blur the input → commit)
 * instead of cancelling. Editors without it keep cancel-on-outside.
 */
export type NativeEditor = ComponentType<EditorProps> & { overlayPresetClass?: string; commitsOnBlur?: boolean };

/**
 * Tag a native editor with an overlay-preset width class so the OverlayManager can
 * size the portal. Thin passthrough — the trap/guard/geometry are the manager's job.
 */
export function wrapNativeEditor(Editor: ComponentType<EditorProps>, presetClass?: string): NativeEditor {
	if (!presetClass) return Editor;
	const wrapped = Editor as NativeEditor;
	// Tag in place — no re-render wrapper needed; the manager reads the class off
	// the resolved component. (A fresh object would break referential identity of
	// memoised editors, so we annotate the component the registry already holds.)
	wrapped.overlayPresetClass = presetClass;
	return wrapped;
}

// Built-in native editors, keyed by cell-type key. This is the CONSUMER-FACING
// overlay-editor table — the type->component map `resolveEditIntent` reads when it
// decides a type opens an overlay. It now covers EVERY type the authoritative
// edit-intent enumeration routes to an overlay (edit-intent.ts), so the host never
// falls back to TextEditor for a typed cell:
//   • number/integer/smallint/decimal/currency/percentage/rating -> NumberEditorDom.
//   • url -> UrlEditorDom (native, wired here — went through the text overlay before
//     the routing fix). NOTE: `color` is NOT here — it is not a real backend data
//     type (just a hex/text string), so it routes to the plain TextEditor via the
//     edit-intent text-like default; there is no dedicated color editor.
//   • image/file/video/audio/upload -> ImageEditorDom (the media family).
// (Booleans are NOT here — they are an inline toggle with no overlay; see edit-intent.)
export const DOM_EDITOR_REGISTRY: Record<string, NativeEditor> = {
	// Text types
	text: TextEditor,
	varchar: TextEditor,
	// Number types (the whole NUMBER_TYPES family, incl. rating)
	number: NumberEditorDom,
	integer: NumberEditorDom,
	smallint: NumberEditorDom,
	decimal: NumberEditorDom,
	currency: NumberEditorDom,
	percentage: NumberEditorDom,
	rating: NumberEditorDom,
	// Media types (the whole MEDIA_TYPES family reuses the image editor, as in glide)
	image: ImageEditorDom,
	file: ImageEditorDom,
	video: ImageEditorDom,
	audio: ImageEditorDom,
	upload: ImageEditorDom,
	// Date/time types
	date: DateEditorDom,
	datetime: DateEditorDom,
	timestamptz: DateEditorDom,
	time: DateEditorDom,
	// Geometry types
	geometry: GeometryEditorDom,
	'geometry-point': GeometryEditorDom,
	'geometry-collection': GeometryEditorDom,
	// Other complex types
	interval: IntervalEditorDom,
	relation: RelationEditorDom,
	tsvector: TsvectorEditorDom,
	inet: InetEditorDom,
	url: UrlEditorDom,
	// Array types
	array: ArrayEditorDom,
	'text-array': ArrayEditorDom,
	'uuid-array': ArrayEditorDom,
	'number-array': ArrayEditorDom,
	'integer-array': ArrayEditorDom,
	'date-array': ArrayEditorDom,
	tags: ArrayEditorDom,
	// JSON types
	json: JsonEditorDom,
	jsonb: JsonEditorDom,
};

/**
 * Resolve the native editor for a type key. A consumer override wins (mirrors the
 * glide `def.editor` precedence), else the built-in `DOM_EDITOR_REGISTRY` entry.
 *
 * @param typeKey - resolved cell-type key (e.g. `text`, `json`).
 * @param consumer - optional per-instance override lookup (`registry.getEditorComponent`).
 */
export function resolveNativeEditor(
	typeKey: string,
	consumer?: (typeKey: string) => ComponentType<EditorProps> | undefined,
): NativeEditor | undefined {
	return consumer?.(typeKey) ?? DOM_EDITOR_REGISTRY[typeKey];
}

