// Native number editor — value-native single-line numeric <input> for the
// NUMBER_TYPES family (number/integer/smallint/decimal/currency/percentage/
// rating). Sibling of TextEditor: dependency-light (no glide cell types), the
// OverlayManager hosts the focus-trap + error-guard + width sizing, so this is
// just the input + a Save affordance. Glide-free by construction.
//
// VALUE editor (no server mutation): seeds from EditorProps.value, parses the
// text on commit and pushes a `number` (or `null` for empty) down the glide
// value-commit path (onCommit). Non-numeric text is rejected — Save is disabled
// and Enter is a no-op while the field cannot parse — so the last committed
// value is never clobbered by garbage.

import { useRef, useState } from 'react';

import { Button } from '@/components/ui/button';

import { OVERLAY_SM } from '../../grid/editors/overlay-presets';
import { cn } from '../../utils/cn';
import type { EditorProps } from './editor-props';

/** Seed the input text from the raw value (number or numeric string), else ''. */
function seedText(value: unknown): string {
	if (value === null || value === undefined) return '';
	if (typeof value === 'number') return Number.isFinite(value) ? String(value) : '';
	return String(value);
}

/** Parse the input text to the committed value: '' -> null, else a finite number or NaN. */
function parseValue(text: string): number | null {
	const trimmed = text.trim();
	if (trimmed === '') return null;
	return Number(trimmed);
}

export function NumberEditorDom({ value, initialText, colKey, fieldMeta, onCommit, onCancel }: EditorProps) {
	// Type-to-edit seed (OVERWRITE): a typed printable char replaces the cell value; the
	// parse/canSave guard below still rejects non-numeric content (e.g. a typed letter).
	const [text, setText] = useState(() => (initialText != null ? initialText : seedText(value)));
	// COMMIT-ON-BLUR GUARD (Stage B): an Escape-cancel also blurs the input as it unmounts —
	// `escapedRef` tells the blur handler to skip its commit so Escape never double-fires.
	const escapedRef = useRef(false);

	const parsed = parseValue(text);
	// Save is blocked only when the field has content that does not parse to a
	// finite number; an empty field is a valid `null` commit.
	const canSave = parsed === null || Number.isFinite(parsed);

	function commit() {
		if (!canSave) return;
		onCommit(parsed);
	}

	function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
		if (e.key === 'Enter') {
			e.preventDefault();
			commit();
			return;
		}
		if (e.key === 'Escape') {
			e.preventDefault();
			escapedRef.current = true;
			onCancel();
		}
	}

	// Commit-on-click-away: commit only when focus genuinely leaves the whole overlay (the
	// focus-trap `[role="dialog"]`) — testing the element focus actually moved to (relatedTarget,
	// else post-blur document.activeElement) against the dialog root, NOT the slot. This avoids a
	// spurious commit on the open-time focus churn (focus momentarily lands on the trap container,
	// inside the dialog), while the in-overlay Save button (focus stays inside) does NOT
	// double-commit. Non-numeric garbage is still rejected (`commit()` no-ops when !canSave,
	// mirroring the Enter no-op). Skipped right after an Escape-cancel.
	function handleBlur(e: React.FocusEvent<HTMLInputElement>) {
		if (escapedRef.current) return;
		// Containment root: the focus-trap dialog in production (so the trap container counts as
		// "inside"); the editor slot when rendered bare (tests). Use whichever encloses the input.
		const root = e.currentTarget.closest('[role="dialog"]') ?? e.currentTarget.closest('[data-slot="number-editor"]');
		const landed = (e.relatedTarget as Node | null) ?? document.activeElement;
		if (root && landed && root.contains(landed)) return;
		commit();
	}

	return (
		<div
			data-slot='number-editor'
			className={cn('bg-popover flex items-center gap-2 rounded-lg border p-2.5 shadow-lg', OVERLAY_SM)}
		>
			<input
				aria-label={`Edit ${fieldMeta?.name ?? colKey}`}
				value={text}
				onChange={(e) => setText(e.target.value)}
				onKeyDown={handleKeyDown}
				onBlur={handleBlur}
				inputMode='decimal'
				spellCheck={false}
				className='bg-muted/40 border-border/40 min-w-0 flex-1 rounded-md border px-2.5 py-1.5 font-sans text-sm outline-none'
				autoFocus
			/>
			<Button onClick={commit} disabled={!canSave} size='xs' variant='default' className='shrink-0'>
				Save
			</Button>
		</div>
	);
}

// Opt into commit-on-click-away (Stage B) — see TextEditor.commitsOnBlur. The OverlayManager
// reads this to pick `dismissMode='commit'` (blur → onBlur commits) instead of cancelling.
NumberEditorDom.commitsOnBlur = true as const;

'use client';

// Native relation editor — a thin EditorProps adapter that RE-HOSTS the (now value-
// native) SELF-COMMITTING `RelationEditor` verbatim. The UI (current-relations list,
// search + "Add from" picker, OVERLAY_MD width, own EditorFocusTrap, Ctrl+Enter save)
// is reused as-is; the contract maps directly onto EditorProps:
//   • value         -> resolved `currentValue`, replicating the original factory's
//                      bare-string -> { id } wrap (draft FK values are left untouched).
//   • tableName     -> EditorProps.tableName.
//   • recordId      -> EditorProps.rowId (may be a "draft:" id; the editor handles it).
//   • fieldName     -> EditorProps.colKey.
//   • onSaveComplete(RelationSaveData) -> onCommitPatch(patch) — a MULTI-field patch:
//     belongsTo sets [foreignKeyField] = foreignKeyValue, and [relationField || colKey]
//     = relationData (the display field).
//   • onFinishedEditing() -> onCancel() (a CLOSE; the mutation self-commits via
//     onSaveComplete, so the value path is never used for relation).
// The reused RelationEditor ignores its `value` prop (it reads `currentValue`), so it
// is not passed. No Suspense: the editor renders eagerly.

import { RelationEditor, type RelationSaveData } from '../../grid/editors/relation-editor';
import type { EditorProps } from './editor-props';

const DRAFT_PREFIX = 'draft:';

/**
 * Resolve the raw relation value into the shape the reused editor matches against,
 * replicating the original factory: a bare (non-draft) FK string is wrapped into
 * `{ id }`; everything else (object / array / null) is passed through and the editor's
 * `coerceToArray` normalises it.
 */
function resolveCurrentValue(value: unknown): unknown {
	if (typeof value === 'string' && value && !value.startsWith(DRAFT_PREFIX)) {
		return { id: value };
	}
	return value;
}

export function RelationEditorDom({
	value,
	colKey,
	rowId,
	tableName,
	relationInfo,
	onCommitPatch,
	onCancel,
}: EditorProps) {
	// Self-commit: the editor mutates server-side (or, for draft belongsTo, resolves
	// the FK locally), then hands back the saved data — route it as a MULTI-field
	// optimistic patch.
	const handleSaveComplete = onCommitPatch
		? (saveData: RelationSaveData) => {
				const patch: Record<string, unknown> = {};
				if (relationInfo?.kind === 'belongsTo' && relationInfo.foreignKeyField) {
					patch[relationInfo.foreignKeyField] = saveData.foreignKeyValue;
				}
				const displayField = relationInfo?.relationField || colKey;
				patch[displayField] = saveData.relationData;
				onCommitPatch(patch);
			}
		: undefined;

	return (
		<div data-slot='relation-editor'>
			<RelationEditor
				onFinishedEditing={() => onCancel()}
				tableName={tableName ?? ''}
				recordId={rowId}
				fieldName={colKey}
				currentValue={resolveCurrentValue(value)}
				onSaveComplete={handleSaveComplete}
			/>
		</div>
	);
}

'use client';

// Native text editor — value-native single-line <input> for text/varchar cells.
// The Phase-4 analogue of glide's built-in text overlay (text/varchar return
// `undefined` from the glide factory to use it). Dependency-light: no UI-package
// Button, no glide types. Commit/cancel flow through EditorProps; the
// OverlayManager already hosts the focus-trap + error-guard + width sizing, so
// this is just the input + a Save affordance.

import { useRef, useState } from 'react';

import { Button } from '@/components/ui/button';

import { OVERLAY_SM } from '../../grid/editors/overlay-presets';
import { cn } from '../../utils/cn';
import type { EditorProps } from './editor-props';

export function TextEditor({ value, initialText, colKey, fieldMeta, onCommit, onCancel }: EditorProps) {
	// Type-to-edit seed (OVERWRITE): when opened by typing a printable char, start from that
	// char instead of the cell value; otherwise seed from the cell value as usual.
	const [text, setText] = useState(() => (initialText != null ? initialText : String(value ?? '')));
	// COMMIT-ON-BLUR GUARD (Stage B): Escape cancels WITHOUT committing, but the cancel also
	// blurs the input as it unmounts — `escapedRef` tells the blur handler to skip its commit
	// so an Escape never double-fires as a commit.
	const escapedRef = useRef(false);

	function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
		if (e.key === 'Enter') {
			e.preventDefault();
			onCommit(text);
			return;
		}
		if (e.key === 'Escape') {
			e.preventDefault();
			escapedRef.current = true;
			onCancel();
		}
	}

	// Commit-on-click-away: commit the current value only when focus genuinely leaves the whole
	// overlay (the focus-trap `[role="dialog"]`). We test the element focus actually MOVED TO —
	// `e.relatedTarget` when set, else the post-blur `document.activeElement` — against the
	// dialog root, NOT the text-editor slot. This is what distinguishes a real click-away (focus
	// lands on body / an outside element) from the open-time focus churn the EditorFocusTrap
	// causes (focus momentarily lands on the trap CONTAINER, which is inside the dialog but
	// outside the slot — committing on that would fire a spurious commit on mount). Clicking the
	// in-overlay Save button keeps focus inside the dialog, so it does NOT double-commit either.
	// Skipped right after an Escape-cancel (escapedRef).
	function handleBlur(e: React.FocusEvent<HTMLInputElement>) {
		if (escapedRef.current) return;
		// Containment root: the focus-trap dialog in production (so the trap container counts as
		// "inside"); the editor slot when rendered bare (tests). Use whichever encloses the input.
		const root = e.currentTarget.closest('[role="dialog"]') ?? e.currentTarget.closest('[data-slot="text-editor"]');
		const landed = (e.relatedTarget as Node | null) ?? document.activeElement;
		if (root && landed && root.contains(landed)) return;
		onCommit(text);
	}

	return (
		<div data-slot='text-editor' className={cn('bg-popover flex items-center gap-2 rounded-lg border p-2.5 shadow-lg', OVERLAY_SM)}>
			<input
				aria-label={`Edit ${fieldMeta?.name ?? colKey}`}
				value={text}
				onChange={(e) => setText(e.target.value)}
				onKeyDown={handleKeyDown}
				onBlur={handleBlur}
				spellCheck={false}
				className='bg-muted/40 border-border/40 min-w-0 flex-1 rounded-md border px-2.5 py-1.5 font-sans text-sm outline-none'
				autoFocus
			/>
			<Button onClick={() => onCommit(text)} size='xs' variant='default' className='shrink-0'>
				Save
			</Button>
		</div>
	);
}

// Opt this editor into commit-on-click-away (Stage B): the OverlayManager reads this off the
// resolved component to pick `dismissMode='commit'` (blur the input → onBlur commits) instead
// of cancelling. Only editors with a real `onBlur → onCommit` set this.
TextEditor.commitsOnBlur = true as const;

