// Native URL editor — a thin EditorProps adapter that RE-HOSTS the (now value-
// native) `UrlEditor` verbatim. Its UI (input + preview + test-link + OVERLAY.md
// width + own EditorFocusTrap) is reused as-is; the contract maps directly to
// value-native EditorProps.
//
// VALUE editor (no server mutation): the editor reads the raw row value and emits
// the formatted URL string back, so the value flows straight through:
// `onFinishedEditing(next)` -> `onCommit(next)`, `onFinishedEditing(undefined)`
// (cancel / Escape) -> `onCancel()`. Parity note: glide url cells fell back to the
// built-in text overlay, so this is a ported, consumer-overridable editor (not
// registry-wired by default).

import { UrlEditor } from '../../grid/editors/url-editor';
import type { EditorProps } from './editor-props';

export function UrlEditorDom({ value, onCommit, onCancel }: EditorProps) {
	return (
		<div data-slot='url-editor'>
			<UrlEditor
				value={value}
				onFinishedEditing={(next) => (next === undefined ? onCancel() : onCommit(next))}
			/>
		</div>
	);
}

'use client';

// Inline (in-cell) editor — a bare single-line <input> rendered DIRECTLY inside the
// cell for the SIMPLE text-representable types (text-like + number-like). The
// non-overlay counterpart of the portal editors: there is no card, no Save button and
// no React portal — the input fills the cell (`absolute inset-0`) and overlays the
// cell view while editing. Routed here by `resolveEditIntent` → `{ mode: 'inline-edit' }`
// (url/inet/json/date/relation/… keep their specialised overlay editors).
//
// COMMIT MODEL (mirrors the overlay text/number editors, minus the chrome):
//   • Enter / blur (click-away)  → commit. Escape → cancel. A numeric field that does
//     not parse blocks Enter (stay editing) and discards on blur (never clobbers the
//     value with garbage) — same guard as the overlay NumberEditor.
//   • `doneRef` makes commit/cancel idempotent: the explicit path returns focus to the
//     grid root (so keyboard nav resumes), and the blur THAT focus shift triggers is
//     short-circuited so it never double-fires.
//   • Pointer events stopPropagation so selecting text with the mouse does not trip the
//     cell's click-to-activate / range-drag handlers on the host wrapper.

import { useLayoutEffect, useRef, useState } from 'react';

import { cn } from '../utils/cn';

interface InlineCellEditorProps {
	/** Accessible name derived from the owning column. */
	ariaLabel: string;
	/** The cell's committed value — seeds the input unless `initialText` overrides (type-to-edit). */
	value: unknown;
	/** Type-to-edit seed (OVERWRITE): a printable char that opened the editor replaces the value. */
	initialText?: string;
	/** Number-like cell — parse to a finite number (or null) on commit and right-align like the view. */
	numeric?: boolean;
	/** Commit the next raw value (string, or number|null when numeric). */
	onCommit: (next: unknown) => void;
	/** Discard — Escape, or an unparseable numeric field on blur. */
	onCancel: () => void;
}

/** Seed the input text from the raw value (anything stringifiable), else ''. */
function seedText(value: unknown): string {
	if (value === null || value === undefined) return '';
	return String(value);
}

/** Parse numeric input: '' → null (a valid clear); else a finite number, or `ok:false` for garbage. */
function parseNumeric(text: string): { ok: boolean; value: number | null } {
	const trimmed = text.trim();
	if (trimmed === '') return { ok: true, value: null };
	const n = Number(trimmed);
	return Number.isFinite(n) ? { ok: true, value: n } : { ok: false, value: null };
}

export function InlineCellEditor({ ariaLabel, value, initialText, numeric, onCommit, onCancel }: InlineCellEditorProps) {
	const [text, setText] = useState(() => (initialText != null ? initialText : seedText(value)));
	const inputRef = useRef<HTMLInputElement | null>(null);
	// The grid root (role=grid, tabIndex=0) — focus returns here on commit/cancel so arrow-key
	// nav resumes (the input unmounts and would otherwise drop focus to <body>). Captured once.
	const gridRef = useRef<HTMLElement | null>(null);
	// Guards commit/cancel idempotency: set before the explicit focus-return so the resulting
	// blur skips its commit-on-blur (no double commit, no commit-after-Escape).
	const doneRef = useRef(false);

	useLayoutEffect(() => {
		const el = inputRef.current;
		gridRef.current = (el?.closest('[role="grid"]') as HTMLElement | null) ?? null;
		// Seeded from the cell value (Enter / F2 / double-click) → select all so the first keystroke
		// replaces. A type-to-edit seed already IS the replacement, so leave the caret at the end.
		if (el && initialText == null) el.select();
	}, [initialText]);

	function finish(commit: boolean) {
		if (doneRef.current) return;
		doneRef.current = true;
		// Return focus to the grid BEFORE the input unmounts; doneRef makes the blur a no-op.
		gridRef.current?.focus();
		if (!commit) {
			onCancel();
			return;
		}
		if (numeric) {
			const parsed = parseNumeric(text);
			if (!parsed.ok) {
				onCancel(); // unparseable on commit-by-blur → discard rather than clobber
				return;
			}
			onCommit(parsed.value);
			return;
		}
		onCommit(text);
	}

	function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
		if (e.key === 'Enter') {
			e.preventDefault();
			// Unparseable number on Enter → stay editing (mirror the overlay editor's Enter no-op).
			if (numeric && !parseNumeric(text).ok) return;
			finish(true);
			return;
		}
		if (e.key === 'Escape') {
			e.preventDefault();
			finish(false);
		}
		// Other keys (incl. arrows / Home / End) act on the input text. They bubble to the grid
		// root, which ignores keys while an editor is active, so they never move the grid cursor.
	}

	return (
		<input
			aria-label={ariaLabel}
			ref={inputRef}
			value={text}
			onChange={(e) => setText(e.target.value)}
			onKeyDown={handleKeyDown}
			onBlur={() => finish(true)}
			onPointerDown={(e) => e.stopPropagation()}
			onClick={(e) => e.stopPropagation()}
			onDoubleClick={(e) => e.stopPropagation()}
			inputMode={numeric ? 'decimal' : undefined}
			spellCheck={false}
			data-slot='inline-cell-editor'
			className={cn(
				'bg-background ring-primary absolute inset-0 h-full w-full px-3 font-sans text-sm outline-none ring-2 ring-inset',
				numeric && 'text-right tabular-nums',
			)}
			autoFocus
		/>
	);
}

'use client';

// Native (DOM React-portal) overlay container — the Phase-4 analogue of glide's
// `#portal` fixed host, but it anchors off the cell DOM node's measured rect and
// portals straight into `document.body` (viewport coords, matching the
// `window.innerHeight` assumption in `computeOverlayGeometry`). It REUSES the pure
// flip math + `EditorFocusTrap` + `EditorErrorGuard` + overlay-preset width class.
// It NEVER mutates `.gdg-clip-region` — that DOM coupling stays in the canvas
// `OverlayViewportGuard` so the glide path is untouched.

import React, { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';

import { computeOverlayGeometry, OverlayMeasureContext } from '../../grid/editors/overlay-viewport-guard';
import { EditorFocusTrap } from '../../grid/editors/editor-focus-trap';
import { EditorErrorGuard } from '../../grid/feedback/editor-error-boundary';
import { cn } from '../../utils/cn';

const MARGIN_PX = 12;
const MIN_BELOW_PX = 320;

// Nested floating layers an editor MIGHT portal outside the overlay (Base UI / Radix
// / Floating UI popover, select, menu, dialog, tooltip). A pointerdown inside one of
// these must NOT dismiss the overlay. The current editors render their pickers inline
// inside the overlay, so this is a forward-looking safety net.
const FLOATING_LAYER_SELECTOR =
	'[role="listbox"],[role="menu"],[role="dialog"],[role="tooltip"],[data-floating-ui-portal],[data-base-ui-positioner],[data-radix-popper-content-wrapper]';

interface OverlayManagerProps {
	anchorRect: DOMRect | null;
	open: boolean;
	presetClass?: string;
	onCancel: () => void;
	/**
	 * Outside-pointerdown policy (Stage B). `'cancel'` (default) dismisses with no write
	 * — for editors that DON'T commit-on-blur (relation/date/json/url/inet/…). `'commit'`
	 * — for the commit-on-blur value editors (text/number) — instead BLURS the focused
	 * element inside the overlay so its `onBlur → onCommit` fires (commit-on-click-away),
	 * rather than cancelling. The blur path then commits AND closes; the manager does NOT
	 * also call onCancel, so there is exactly one dismiss per click-away.
	 */
	dismissMode?: 'cancel' | 'commit';
	children: React.ReactNode;
}

export function OverlayManager({ anchorRect, open, presetClass, onCancel, dismissMode = 'cancel', children }: OverlayManagerProps): React.ReactNode {
	const containerRef = useRef<HTMLDivElement | null>(null);
	// Measured, viewport-clamped position (both axes). Null until the overlay has been
	// measured once, so first paint stays hidden rather than flashing at an unclamped
	// spot. Covers the FLIP (no room below -> open above) AND the horizontal shift (an
	// anchor near the right edge -> slide left so the overlay stays on-screen instead of
	// overflowing off the viewport, e.g. the last column's editor).
	const [pos, setPos] = useState<{ left: number; top: number } | null>(null);

	const targetY = anchorRect?.top;
	const targetH = anchorRect?.height;
	const vh = typeof window !== 'undefined' ? window.innerHeight : 800;
	const { shouldFlip, maxHeight } = computeOverlayGeometry(vh, targetY, targetH, MARGIN_PX, MIN_BELOW_PX);

	// Geometry an editor needs to self-bound its internal scroll areas (the canvas path
	// supplied this via OverlayViewportGuard; the DOM host must too). WITHOUT it, editors
	// that read OverlayMeasureContext (relation/image/geometry) see the default maxHeight:0,
	// skip their scroll-budget effect, and render UNBOUNDED lists — so a relation editor's
	// infinite "related records" sentinel stays permanently in view and pages continuously.
	const overlayMeasure = useMemo(() => ({ maxHeight, shouldFlip }), [maxHeight, shouldFlip]);

	// Measure the rendered overlay, then position it: vertically below the anchor (or
	// flipped above when there's no room), horizontally left-aligned to the anchor (or
	// shifted left to stay on-screen), clamped into the viewport on BOTH axes. DOM-read
	// only — mirrors the canvas guard's layout-effect measure; no hasMounted flag.
	useLayoutEffect(() => {
		if (!open || !anchorRect) {
			setPos(null);
			return;
		}
		const el = containerRef.current;
		if (!el) return;
		const rect = el.getBoundingClientRect();
		const vw = window.innerWidth;
		const vhNow = window.innerHeight;

		let left = anchorRect.left;
		left = Math.max(MARGIN_PX, Math.min(left, vw - MARGIN_PX - rect.width));
		if (!Number.isFinite(left)) left = MARGIN_PX;

		let top = shouldFlip ? anchorRect.top - rect.height : anchorRect.bottom;
		top = Math.max(MARGIN_PX, Math.min(top, vhNow - MARGIN_PX - rect.height));
		if (!Number.isFinite(top)) top = MARGIN_PX;

		setPos({ left, top });
	}, [open, shouldFlip, anchorRect, maxHeight]);

	// Dismiss on a pointerdown OUTSIDE the overlay — standard popover behaviour. The
	// overlay was previously only closable via Esc / commit / scroll, so a click in the
	// grid or page left it stuck open. Attached in an effect (after commit) so the
	// activating double-click that OPENED the overlay has fully settled and cannot
	// self-dismiss; capture phase so an inner editor that stops propagation can't
	// suppress it. Clicks inside the overlay (or a nested floating layer it portals)
	// are ignored.
	useEffect(() => {
		if (!open) return;
		const onPointerDown = (e: PointerEvent) => {
			const el = containerRef.current;
			const target = e.target as Node | null;
			if (!el || (target && el.contains(target))) return;
			if (target instanceof Element && target.closest(FLOATING_LAYER_SELECTOR)) return;
			// COMMIT-ON-CLICK-AWAY (Stage B): for commit-on-blur editors, move DOM focus out of
			// the overlay so the focused input's `onBlur → onCommit` fires (commit, then close).
			// We DON'T also call onCancel — the blur path closes the overlay, so this is exactly
			// one dismiss. A bare outside element may not be focusable (so a natural focus shift
			// wouldn't fire), hence we blur explicitly. Falls back to onCancel when nothing in the
			// overlay is focused. `'cancel'` editors discard as before.
			if (dismissMode === 'commit') {
				const focused = document.activeElement;
				if (focused instanceof HTMLElement && el.contains(focused)) {
					focused.blur();
					return;
				}
			}
			onCancel();
		};
		document.addEventListener('pointerdown', onPointerDown, true);
		return () => document.removeEventListener('pointerdown', onPointerDown, true);
	}, [open, onCancel, dismissMode]);

	if (!open || !anchorRect || typeof document === 'undefined') return null;

	// Animate only once the measured, viewport-clamped position is applied, so the
	// entrance transform never fights the layout-effect measure.
	const positioned = pos !== null;
	const style: React.CSSProperties = {
		position: 'fixed',
		// Pre-measure default = the ANCHOR position (below, or above when flipping), NOT a
		// screen corner. So an overlay that fits (the common case) renders at its FINAL spot
		// with zero left/top change once measured — no travel. It stays hidden until measured
		// and `transition-none` keeps the rare off-screen clamp instant, so the overlay is
		// never seen sliding to the anchor (the correction happens off-screen, pre-reveal).
		left: pos ? pos.left : anchorRect.left,
		top: pos ? pos.top : shouldFlip ? anchorRect.top : anchorRect.bottom,
		maxHeight,
		// Hidden until measured to avoid a 1-frame flash at an unclamped position.
		visibility: positioned ? 'visible' : 'hidden',
		// Join the shared design-system overlay layer instead of an
		// arbitrary z, so the editor and any popover/tooltip it opens (e.g. the relation
		// "Record Data" popover, which portals into #portal-root) stack coherently.
		zIndex: 'var(--z-layer-floating)',
	};

	// Portal into the app's shared floating-overlay host (#portal-root) so the editor and
	// nested UI popovers live in the SAME stacking context (siblings) — fixing the
	// host-dependent z-index race where the editor could paint OVER a popover opened from
	// within it. Fall back to <body> when no portal root is mounted (e.g. tests). The host
	// has pointer-events:none, so the overlay opts back in with pointer-events-auto.
	const portalHost = document.getElementById('portal-root') ?? document.body;

	return createPortal(
		<div
			ref={containerRef}
			style={style}
			className={cn(
				// `transition-none`: the entrance is an ANIMATION (scale + fade); left/top must NEVER
				// transition, or measuring/clamping the position would visibly slide the overlay across
				// the screen to its anchor. This keeps the position application instant.
				'pointer-events-auto transition-none',
				// Origin-aware entrance (DESIGN_SPEC §10 / Emil standards): subtle scale + fade from the
				// cell corner, reusing the UI popover's tw-animate utilities for a consistent feel. Gated
				// on `positioned` so the overlay animates only after its measured position is applied.
				positioned && 'animate-[fade-scale-in_var(--duration-moderate)_ease-out] motion-reduce:animate-none',
				shouldFlip ? 'origin-bottom-left' : 'origin-top-left'
			)}
		>
			{/* Provide the overlay geometry so editors (relation/image/geometry) can self-bound their
			    internal scroll lists; without it they read maxHeight:0 and render unbounded (the
			    relation infinite-scroll bug). Mirrors the canvas OverlayViewportGuard's provider. */}
			<OverlayMeasureContext.Provider value={overlayMeasure}>
				<EditorErrorGuard onClose={onCancel}>
					{/* overflow-VISIBLE, never auto/hidden: each editor renders its own rounded card with a
					    `shadow-lg`, and a clipping wrapper the same size as the card squares off that shadow
					    into the "weird halo" around the rounded corners. Editors self-bound their height
					    (relation/image/json scroll internally), so the wrapper never needs to scroll. */}
					<EditorFocusTrap onEscape={onCancel} className={cn('overflow-visible', presetClass)}>
						{children}
					</EditorFocusTrap>
				</EditorErrorGuard>
			</OverlayMeasureContext.Provider>
		</div>,
		portalHost,
	);
}

// Native overlay open/close state machine. The Phase-4 analogue of glide's
// imperative editor activation, but as a tiny React hook with NO heavy effects:
// `open(cell)` records the active cell (rect captured by the caller from the cell
// DOM node), `close()` clears it. `handleKeyDown` is a host-attachable helper —
// Enter/F2 open (the caller supplies the cell to open, since only the host knows
// which DOM node is focused), Escape closes.
//
// TODO(Phase 7): Tab should commit-and-open-next; today Tab is left to default.

import { useCallback, useState } from 'react';

export interface OverlayCell {
	rowIndex: number;
	colKey: string;
	anchorRect: DOMRect;
	/** Type-to-edit seed: when set, value editors initialize the input to this char (overwrite). */
	initialText?: string;
	/**
	 * Edit surface for this active cell. `'overlay'` (default when omitted) renders the portal
	 * editor; `'inline'` edits IN PLACE inside the cell (no portal — the cell host renders the
	 * input) yet still rides this controller so nav/clipboard suppression + scroll commit-on-unmount
	 * are shared. The portal (`OverlayManager` / `editorNode`) is skipped for `'inline'`.
	 */
	mode?: 'overlay' | 'inline';
}

export interface OverlayController {
	active: OverlayCell | null;
	isOpen: boolean;
	open: (cell: OverlayCell) => void;
	close: () => void;
	/**
	 * Re-anchor the open overlay to a freshly-measured rect WITHOUT changing the active
	 * cell — the editor-follows-cell-on-scroll path (Stage B). No-op when closed. Keeps
	 * the same {@link OverlayCell} identity for every field except `anchorRect`, so the
	 * editor's local state (in-progress value, focus) survives the reposition.
	 */
	reanchor: (anchorRect: DOMRect) => void;
	/**
	 * Host key handler. Enter/F2 open the cell returned by `resolveCell` (the host
	 * resolves the focused cell + measures its rect); Escape closes. `resolveCell`
	 * may return null (nothing focused / not editable) — then the open is skipped.
	 */
	handleKeyDown: (e: React.KeyboardEvent, resolveCell: () => OverlayCell | null) => void;
}

export function useOverlayController(): OverlayController {
	const [active, setActive] = useState<OverlayCell | null>(null);

	const open = useCallback((cell: OverlayCell) => {
		setActive(cell);
	}, []);

	const close = useCallback(() => {
		setActive(null);
	}, []);

	const reanchor = useCallback((anchorRect: DOMRect) => {
		setActive((prev) => (prev ? { ...prev, anchorRect } : prev));
	}, []);

	const handleKeyDown = useCallback(
		(e: React.KeyboardEvent, resolveCell: () => OverlayCell | null) => {
			if (e.key === 'Enter' || e.key === 'F2') {
				const cell = resolveCell();
				if (!cell) return;
				e.preventDefault();
				setActive(cell);
				return;
			}
			if (e.key === 'Escape') {
				e.preventDefault();
				setActive(null);
			}
			// TODO(Phase 7): Tab -> commit current + open next cell.
		},
		[],
	);

	return { active, isOpen: active != null, open, close, reanchor, handleKeyDown };
}

// The DOM cell host — the `getCellContent` → React port. Given a v9 cell it asks
// the injected resolver for the {@link SheetsCellResolution} ({ cell, component? })
// and renders the consumer component when present, else dispatches on the neutral
// `kind` to the matching built-in view (cell-model/views/*).
//
// Phase 3 replaces the Phase-1 value→kind STOPGAP (`deriveSheetsCell`) with
// registry-driven resolution: the host no longer guesses a kind from the JS value
// — `getSheetsCellContent(rowIndex, colKey)` runs the full `createCellContent` →
// `toSheetsCell` routing and (when the consumer registered a `cellComponent` for
// the resolved typeKey) hands back the component to render instead of a built-in
// view. SheetsDomInner injects the resolver via the `renderCell` closure.
//
// The kind→view map covers every native SheetsCellKind. datetime/interval cells
// carry kind 'text' (formatted text in v1), so they route through TextCellView
// alongside the grid-internal kinds (loading/draft-action/custom); their dedicated
// DateTimeCellView/IntervalCellView stay exported for per-typeKey use later.
// Dependency-light: local `cn` only, with no shared primitive dependency.
import { memo, useCallback, useRef } from 'react';
import type React from 'react';
import type { Cell } from '@tanstack/react-table';

import { cn } from '../utils/cn';
import { getDraftMeta, type SheetsRow } from '../grid/row-model';
import { DRAFT_ACTION_COLUMN_KEY } from '../grid/sheets.constants';
import type { SheetsTableFeatures } from '../table/features';
import type { RenderCellContext } from '../table/grid-viewport';
import type { CellProps } from '../cell-model/cell-props';
import { BadgesCellView } from '../cell-model/views/badges-view';
import { BooleanCellView } from '../cell-model/views/boolean-view';
import { DraftActionCellView, type DraftActionStatus } from '../cell-model/views/draft-action-view';
import { GeometryCellView } from '../cell-model/views/geometry-view';
import { ImageCellView } from '../cell-model/views/image-view';
import { LoadingCellView } from '../cell-model/views/loading-view';
import { NumberCellView } from '../cell-model/views/number-view';
import { RelationCellView } from '../cell-model/views/relation-view';
import { TextCellView } from '../cell-model/views/text-view';
import { UriCellView } from '../cell-model/views/uri-view';
import { InlineCellEditor } from './inline-cell-editor';
import type { SheetsCellResolution } from './use-sheets-content';

type SheetsTableCell = Cell<SheetsTableFeatures, SheetsRow, unknown>;

/** Native DOM content resolver injected by the shell — mirrors `getCellContent`. */
export type GetSheetsCellContent = (rowIndex: number, colKey: string) => SheetsCellResolution;

/**
 * Open the native overlay editor for a cell. Threaded from `SheetsDomInner` through
 * `renderCell` so only the host knows the cell's DOM node (it measures the anchor
 * rect off `getBoundingClientRect`). Phase-4 additive — the canvas path is untouched.
 */
export type OpenEditor = (rowIndex: number, colKey: string, anchorRect: DOMRect, initialText?: string) => void;

/**
 * Submit a client-side draft row by its draft id. Threaded from `SheetsDomInner` (the
 * shell's `submitDraftRow`) so the draft-action cell's REAL `<Button>` can wire its
 * onClick. Phase-7 Stage-4 consumes it; Stage-2 only plumbs it through.
 */
export type SubmitDraftRow = (draftRowId: string) => Promise<unknown>;

// COMPLETE kind→view map. `loading` routes to its skeleton view; `draft-action` is
// special-cased UPSTREAM (rendered as DraftActionCellView with explicit props, never
// reaching here), so it — like `custom`/`text` — falls back to TextCellView if it ever does.
function renderKindView(props: CellProps) {
	switch (props.cell.kind) {
		case 'number':
			return <NumberCellView {...props} />;
		case 'boolean':
			return <BooleanCellView {...props} />;
		case 'badges':
			return <BadgesCellView {...props} />;
		case 'uri':
			return <UriCellView {...props} />;
		case 'image':
			return <ImageCellView {...props} />;
		case 'geometry':
			return <GeometryCellView {...props} />;
		case 'relation':
			return <RelationCellView {...props} />;
		case 'loading':
			return <LoadingCellView {...props} />;
		case 'text':
		case 'draft-action':
		case 'custom':
		default:
			return <TextCellView {...props} />;
	}
}

/** Explicit draft-action descriptor for a draft row, derived from its DraftMeta. */
interface DraftActionInfo {
	draftRowId: string;
	status: DraftActionStatus;
	errored: boolean;
	disabled: boolean;
}

/**
 * Derive the draft-action cell's props from a row's draft metadata — the DOM analogue
 * of the canvas draft-action-cell reading the draft slice. `errored`/`disabled` mirror
 * the canvas: an error status surfaces the red dot but keeps the button live (the canvas
 * painter never disabled on error); `saving` disables (DraftActionCellView also self-locks).
 */
function deriveDraftActionInfo(row: SheetsRow | undefined): DraftActionInfo | null {
	const meta = getDraftMeta(row);
	if (!meta) return null;
	const status: DraftActionStatus = meta.status;
	return { draftRowId: meta.draftRowId, status, errored: status === 'error', disabled: status === 'saving' };
}

interface SheetsCellHostInnerProps {
	resolution: SheetsCellResolution;
	rowId: string;
	colKey: string;
	rowIndex: number;
	columnIndex: number;
	value: unknown;
	isEditing: boolean;
	/** True when this is the active (keyboard cursor) cell — drives the focus ring + aria-selected + id. */
	isActive: boolean;
	/** Open the overlay editor for this cell; undefined on render paths without editing (e.g. tests). */
	openEditor?: OpenEditor;
	/** Type-to-edit seed for the inline editor (only meaningful when `isEditing`). */
	inlineInitialText?: string;
	/** Commit an inline (in-cell) edit. Set on the inline-edit render path; reuses the host's
	 * value-commit pipeline (bulk-or-single). */
	onInlineCommit?: (rowIndex: number, colKey: string, value: unknown) => void;
	/** Cancel an inline (in-cell) edit — discards and closes. */
	onInlineCancel?: () => void;
	/** Park the active cell on this cell (click-to-activate). `shiftKey` extends the range from the
	 * anchor instead of resetting it. Undefined on render paths without nav. */
	onActivateCell?: (col: number, row: number, shiftKey?: boolean) => void;
	/** Right-click this cell — opens the grid context menu anchored at the pointer. The grid first
	 * activates the cell when it is outside the current selection, so the menu acts on it. */
	onContextMenu?: (col: number, row: number, clientX: number, clientY: number) => void;
	/** Submit a draft row by id — wired to the draft-action cell's Button (Stage 4). */
	onSubmitDraftRow?: SubmitDraftRow;
	/** Draft-action descriptor when this is the draft-action column of a draft row; null otherwise. */
	draftAction?: DraftActionInfo | null;
	className?: string;
}

/** Build the full {@link CellProps} for a resolved cell. `onStartEdit` is supplied by the host. */
function toCellProps(props: SheetsCellHostInnerProps, onStartEdit: () => void): CellProps {
	const { cell } = props.resolution;
	return {
		cell,
		value: props.value,
		colKey: props.colKey,
		rowId: props.rowId,
		rowIndex: props.rowIndex,
		column: { key: props.colKey, name: props.colKey, cellType: cell.meta?.cellType ?? 'unknown' },
		isEditing: props.isEditing,
		onStartEdit,
		disabled: false,
	};
}

// Memoized on (rowId, colKey, value, isEditing, openEditor) — the DOM analogue of
// glide's `updateCells`: only the changed cell re-renders, never the whole window.
// The resolution is derived from the first four inputs, so they fully gate the
// output; openEditor is added so the wrapper's handlers stay current.
const SheetsCellHostInner = memo(
	function SheetsCellHostInner(props: SheetsCellHostInnerProps) {
		const wrapperRef = useRef<HTMLDivElement | null>(null);

		// Start editing anchored to THIS cell's DOM node — the host is the only place
		// that knows the cell's rect (read off getBoundingClientRect, viewport coords,
		// matching the OverlayManager's window.innerHeight assumption). No-op when the
		// cell is readonly or no openEditor was threaded in.
		const startEdit = useCallback(() => {
			const open = props.openEditor;
			const el = wrapperRef.current;
			if (!open || !el || props.resolution.cell.readonly) return;
			open(props.rowIndex, props.colKey, el.getBoundingClientRect());
		}, [props.openEditor, props.rowIndex, props.colKey, props.resolution.cell.readonly]);

		// Click parks the active cell here (the grid root owns keys via aria-activedescendant).
		// A shift-click EXTENDS the cell range from the latched anchor instead of resetting it.
		const onActivateCell = props.onActivateCell;
		const columnIndex = props.columnIndex;
		const cellRowIndex = props.rowIndex;
		const activate = useCallback((e: React.MouseEvent) => {
			onActivateCell?.(columnIndex, cellRowIndex, e.shiftKey);
		}, [onActivateCell, columnIndex, cellRowIndex]);

		// Right-click: open the grid context menu at the pointer. preventDefault suppresses the
		// browser menu; the grid handler activates this cell first when it is outside the selection.
		const onContextMenu = props.onContextMenu;
		const contextMenu = useCallback((e: React.MouseEvent) => {
			if (!onContextMenu) return;
			e.preventDefault();
			onContextMenu(columnIndex, cellRowIndex, e.clientX, e.clientY);
		}, [onContextMenu, columnIndex, cellRowIndex]);

		const onSubmitDraftRow = props.onSubmitDraftRow;
		const draftAction = props.draftAction;
		const submitDraft = useCallback(() => {
			if (draftAction && onSubmitDraftRow) void onSubmitDraftRow(draftAction.draftRowId);
		}, [draftAction, onSubmitDraftRow]);

		const cellProps = toCellProps(props, startEdit);
		const Component = props.resolution.component;
		const styleHint = props.resolution.cell.styleHint;
		// DOM equivalent of applyDraftDisabledStyle / applyDraftErrorStyle: a draft cell
		// fades (muted text + tinted bg); a per-cell error overrides with a red bg/text.
		const draftClasses = cn(
			styleHint?.draft && 'bg-muted/40 text-muted-foreground',
			styleHint?.error && 'bg-destructive/10 text-destructive',
		);
		// The draft-action column renders the REAL <Button> (DraftActionCellView), which
		// takes its own prop shape — bypass the kind→view map and the value/editor wiring.
		const isDraftActionCell = props.colKey === DRAFT_ACTION_COLUMN_KEY || props.resolution.cell.kind === 'draft-action';
		// Border wrapper carries the mouse activation handlers (click parks the active cell,
		// double-click opens the editor). Keys are owned by the grid root (aria-activedescendant
		// pattern), so the wrapper is NOT individually focusable. The gridcell role lives on the
		// built-in view (or the consumer component) inside, so the host adds no second role="gridcell".
		return (
			<div
				ref={wrapperRef}
				id={`sheets-cell-${props.rowIndex}-${props.columnIndex}`}
				aria-selected={props.isActive || undefined}
				onClick={activate}
				onDoubleClick={startEdit}
				onContextMenu={contextMenu}
				className={cn(
					'relative h-full w-full overflow-hidden outline-none',
					props.isActive && 'z-20 ring-2 ring-inset ring-primary',
					draftClasses,
					props.className,
				)}
			>
				{isDraftActionCell ? (
					draftAction ? (
						<DraftActionCellView
							status={draftAction.status}
							errored={draftAction.errored}
							disabled={draftAction.disabled}
							onSubmit={submitDraft}
						/>
					) : null
				) : props.isEditing ? (
					// Inline (in-cell) edit for the simple text-representable types — a bare <input>
					// overlaying the view. `isEditing` is set true ONLY for inline-edit intents (the
					// shell short-circuits inline-toggle/overlay/none before here), so the cell kind is
					// always text or number → derive the numeric variant from it.
					<InlineCellEditor
						ariaLabel={`Edit ${props.resolution.fieldMeta?.name ?? props.colKey}`}
						value={props.value}
						initialText={props.inlineInitialText}
						numeric={props.resolution.cell.kind === 'number'}
						onCommit={(next) => props.onInlineCommit?.(props.rowIndex, props.colKey, next)}
						onCancel={() => props.onInlineCancel?.()}
					/>
				) : Component ? (
					<Component {...cellProps} />
				) : (
					renderKindView(cellProps)
				)}
			</div>
		);
	},
	(prev, next) =>
		prev.rowId === next.rowId &&
		prev.colKey === next.colKey &&
		prev.value === next.value &&
		prev.isEditing === next.isEditing &&
		// initialText seeds the inline editor on open; it only differs for the editing cell.
		prev.inlineInitialText === next.inlineInitialText &&
		prev.onInlineCommit === next.onInlineCommit &&
		prev.onInlineCancel === next.onInlineCancel &&
		// isActive must gate the memo or the focus ring will not move between cells.
		prev.isActive === next.isActive &&
		prev.openEditor === next.openEditor &&
		prev.onActivateCell === next.onActivateCell &&
		prev.onContextMenu === next.onContextMenu &&
		prev.onSubmitDraftRow === next.onSubmitDraftRow &&
		// styleHint.draft/error and the draft-action status can flip while `value` is
		// unchanged (validation result arrives, save in flight), so gate on them too.
		prev.resolution.cell.styleHint?.draft === next.resolution.cell.styleHint?.draft &&
		prev.resolution.cell.styleHint?.error === next.resolution.cell.styleHint?.error &&
		sameDraftAction(prev.draftAction, next.draftAction)
);

/** Draft-action equality for the memo gate — status/errored/disabled drive the Button. */
function sameDraftAction(a: DraftActionInfo | null | undefined, b: DraftActionInfo | null | undefined): boolean {
	if (a === b) return true;
	if (!a || !b) return false;
	return a.draftRowId === b.draftRowId && a.status === b.status && a.errored === b.errored && a.disabled === b.disabled;
}

export interface SheetsCellHostProps {
	cell: SheetsTableCell;
	ctx: RenderCellContext;
	getSheetsCellContent: GetSheetsCellContent;
	/** Open the overlay editor for the activated cell (double-click; grid root owns Enter / F2). */
	openEditor?: OpenEditor;
	/** True when this cell is being edited IN PLACE (inline-edit intent); renders the bare <input>. */
	isEditing?: boolean;
	/** Type-to-edit seed for the inline editor (only meaningful when `isEditing`). */
	inlineInitialText?: string;
	/** Commit an inline (in-cell) edit — reuses the host value-commit pipeline. */
	onInlineCommit?: (rowIndex: number, colKey: string, value: unknown) => void;
	/** Cancel an inline (in-cell) edit. */
	onInlineCancel?: () => void;
	/** Park the active cell on click; `shiftKey` extends the cell range from the anchor. */
	onActivateCell?: (col: number, row: number, shiftKey?: boolean) => void;
	/** Right-click → open the grid context menu anchored at the pointer. */
	onContextMenu?: (col: number, row: number, clientX: number, clientY: number) => void;
	/** Submit a draft row by id — wired to the draft-action cell's Button (Stage 4). */
	onSubmitDraftRow?: SubmitDraftRow;
	className?: string;
}

/**
 * Render a v9 cell as DOM. Wire via the {@link GridViewport} `renderCell` closure,
 * which injects the shell's resolver: `(c, ctx) => <SheetsCellHost cell={c} ctx={ctx}
 * getSheetsCellContent={getSheetsCellContent} openEditor={openEditor} />`.
 */
export function SheetsCellHost({ cell, ctx, getSheetsCellContent, openEditor, isEditing, inlineInitialText, onInlineCommit, onInlineCancel, onActivateCell, onContextMenu, onSubmitDraftRow, className }: SheetsCellHostProps) {
	const rowIndex = cell.row.index;
	const colKey = cell.column.id;
	const value = cell.getValue();
	const resolution = getSheetsCellContent(rowIndex, colKey);
	// Only the draft-action column needs the row's draft status; for every other column
	// this is null and the inner skips the Button branch. `cell.row.original` carries the
	// Symbol-keyed DraftMeta (it's the live row ref, never spread away by the table).
	const draftAction = colKey === DRAFT_ACTION_COLUMN_KEY ? deriveDraftActionInfo(cell.row.original) : null;
	return (
		<SheetsCellHostInner
			resolution={resolution}
			rowId={cell.row.id}
			colKey={colKey}
			rowIndex={rowIndex}
			columnIndex={ctx.columnIndex}
			value={value}
			isEditing={!!isEditing}
			inlineInitialText={inlineInitialText}
			onInlineCommit={onInlineCommit}
			onInlineCancel={onInlineCancel}
			isActive={ctx.isActive}
			openEditor={openEditor}
			onActivateCell={onActivateCell}
			onContextMenu={onContextMenu}
			onSubmitDraftRow={onSubmitDraftRow}
			draftAction={draftAction}
			className={className}
		/>
	);
}

// The DOM content resolver — the native analogue of the canvas `useGridContent`
// (grid/hooks/use-grid-content.ts). It MIRRORS that hook's routing steps 1:1 but
// produces a neutral {@link SheetsCell} (+ the resolved view component) instead of
// a glide `GridCell`, so the DOM grid never touches the canvas render path.
//
// It deliberately does NOT own the `ensureRelationInfo` effect: the canvas
// `useGridContent` already runs that effect for the same table, so this hook takes
// `relationInfoByField` + `meta` as INPUTS to avoid a duplicate store write/effect.
// Draft VISUAL styling (faded/error theme overrides) is intentionally deferred to
// Phase 7 — here we only blank the leaked draft-id text and tag `styleHint.draft`
// so Phase 7 can style from a neutral flag (no glide theme imports).

import { useCallback, useMemo } from 'react';

import type { CellTypeRegistry } from '../cell-types/cell-type-registry';
import type { FieldMetadata } from '../cell-types/cell-type-resolver';
import type { CellCreationMetadata } from '../grid/grid-cell-types';
import type { CellProps } from '../cell-model/cell-props';
import type { SheetsCell } from '../cell-model/sheets-cell';
import type { SheetsRow } from '../grid/row-model';
import type { RelationInfo } from '../store/relation-info-slice';
import type { MetaQuery } from '@constructive-io/data';
import { buildRelationFieldNameSet, resolveGridCellRoute } from '../grid/cell-routing';
import { getDraftMeta } from '../grid/row-model';
import { unwrapRelationValue } from '../grid/sheets.utils';
import { MEDIA_TYPES } from '../cell-types/cell-type-groups';
import type { SheetsRowIdentifier } from '../row-identity';

interface RelationOptions {
	relationChipLimit?: number;
	relationLabelMaxLength?: number;
}

/** Resolved DOM cell payload: the neutral cell plus its (optional) view component. */
export interface SheetsCellResolution {
	cell: SheetsCell;
	component?: React.ComponentType<CellProps>;
	colKey: string;
	/**
	 * The resolved cell-type key (post detection-override) — the SINGLE source of
	 * truth the host feeds to `resolveEditIntent` to route activation. Always set;
	 * `'text'` for the loading/empty fallthrough cells that carry no type. (Mirror
	 * of the `meta.cellType` the cell itself now self-describes.)
	 */
	typeKey: string;
	/** Field metadata for the column — fed to a native overlay editor's EditorProps.fieldMeta. */
	fieldMeta?: FieldMetadata;
	/** Relation info for the column (when relational) — fed to a native overlay editor's EditorProps.relationInfo. */
	relationInfo?: RelationInfo;
}

export interface UseSheetsContentArgs {
	data: SheetsRow[];
	columnKeys: string[];
	fieldMetaMap: ReadonlyMap<string, FieldMetadata>;
	registry: CellTypeRegistry;
	tableName?: string;
	options?: RelationOptions;
	/** Relation info per field — owned by the canvas `useGridContent` ensureRelationInfo effect. */
	relationInfoByField: ReadonlyMap<string, RelationInfo>;
	/** Schema meta (same value the canvas path reads via useSheetsMeta). */
	meta: MetaQuery | undefined;
	/** Disable every persisted-row editor when the table cannot expose update mutations. */
	serverRowsReadOnly?: boolean;
	/** Primary-key fields are immutable after insertion because they define row identity. */
	serverReadOnlyFields?: ReadonlySet<string>;
	/** Resolve the GraphQL mutation identity; self-committing editors require a legacy scalar id. */
	getRowIdentifier?: (row: Readonly<Record<string, unknown>>) => SheetsRowIdentifier | null;
	/** Relation/upload editors still use scalar record APIs and must fail closed otherwise. */
	supportsScalarSelfCommit?: boolean;
}

function isDraftId(value: unknown): boolean {
	return typeof value === 'string' && value.startsWith('draft:');
}

/**
 * DISPLAY-LEVEL suppression of an internal draft key leaking as visible cell text —
 * the {@link SheetsCell} mirror of the canvas `suppressDraftIdText`. When the row is
 * a draft AND the value being rendered is the draft key (the `id` column starting
 * with `draft:`, or any value equal to the draft id), blank the cell's display/data
 * text while preserving kind and structural flags. Narrow by design: nothing else.
 */
export function suppressDraftIdText(
	cell: SheetsCell,
	args: { isDraftRow: boolean; colKey: string; rawValue: unknown; draftId: string | undefined },
): SheetsCell {
	const { isDraftRow, colKey, rawValue, draftId } = args;
	if (!isDraftRow) return cell;

	const isIdColumnDraftKey = colKey === 'id' && isDraftId(rawValue);
	const valueIsDraftId = typeof draftId === 'string' && rawValue === draftId;
	if (!isIdColumnDraftKey && !valueIsDraftId) return cell;

	return { ...cell, data: typeof cell.data === 'string' ? '' : cell.data, displayData: '' };
}

/**
 * Tag the cell as a draft row so the host can apply faded/error styling from a flag —
 * the DOM mirror of the canvas applyDraftDisabledStyle/applyDraftErrorStyle split.
 * `error` is set when draftMeta.errors carries a field-level error for THIS colKey
 * (canvas: applyDraftErrorStyle); `draft` always (canvas: faded/disabled visuals).
 */
function tagDraftStyle(cell: SheetsCell, hasError: boolean): SheetsCell {
	return { ...cell, styleHint: { ...cell.styleHint, draft: true, error: hasError } };
}

/**
 * Build the DOM content resolver. Returns `getSheetsCell(rowIndex, colKey)` which
 * mirrors the canvas `getCellContent` routing exactly (draftMeta → fieldMeta →
 * relationInfo → route → relation value unwrap → matchInput → resolveTypeKey →
 * metadata → registry.toSheetsCell), then suppresses any leaked draft-id text and
 * tags draft rows. The view component is resolved alongside via `getCellComponent`.
 */
export function useSheetsContent(args: UseSheetsContentArgs) {
	const {
		data,
		columnKeys,
		fieldMetaMap,
		registry,
		tableName,
		options,
		relationInfoByField,
		meta,
		serverRowsReadOnly = false,
		serverReadOnlyFields,
		getRowIdentifier,
		supportsScalarSelfCommit = true,
	} = args;

	const relationFieldNamesFromMeta = useMemo(() => buildRelationFieldNameSet(meta, tableName), [meta, tableName]);

	// PER-RESOLVER RESULT CACHE. The cell host calls `getSheetsCell` for every visible
	// cell on every re-render, almost always re-deriving an identical resolution. This
	// Map memoizes the last resolution per `rowIndex|colKey`, keyed on the cell's raw
	// VALUE: a repeat call whose value is reference-equal to the cached one returns the
	// cached resolution and skips the full pipeline (route → relation unwrap →
	// resolveTypeKey → toSheetsCell, which allocates ≥3 objects).
	//
	// SAFETY: the deps below are IDENTICAL to the `getSheetsCell` useCallback's deps, so
	// the cache is thrown away exactly when the resolver would change identity. Every
	// input that can change a cell's resolution flows through one of these deps — most
	// notably `data`: draft status/errors rebuild `combinedRows` (new array + new row
	// objects, see useDraftRows), and any server-data / optimistic change recreates the
	// rows array too. So `styleHint.draft/error` (derived from the row's DraftMeta) and
	// the relation-unwrap fields (read off the same row object) cannot change without a
	// new `data` reference resetting this cache — making the per-value compare sound:
	// within one resolver identity the row objects are immutable, so a value that is
	// reference-equal guarantees an identical resolution.
	const cache = useMemo(
		() => new Map<string, { value: unknown; resolution: SheetsCellResolution }>(),
		[data, columnKeys, fieldMetaMap, registry, relationFieldNamesFromMeta, relationInfoByField, options, serverRowsReadOnly, serverReadOnlyFields, getRowIdentifier, supportsScalarSelfCommit],
	);

	const getSheetsCell = useCallback(
		(rowIndex: number, colKey: string): SheetsCellResolution => {
			// UNLOADED INFINITE ROW → loading skeleton. In infinite-scroll mode `data` is the
			// null-backed proxy from useSheets: a server index whose page is still in flight reads
			// back as `null` (drafts are real objects, never null). Resolve those slots to a neutral
			// `kind: 'loading'` cell with NO component, so the host's kind→view map paints
			// LoadingCellView (the canvas analogue is glide's loadingCell). Without this the row
			// coerces to `{}` below and every cell renders as blank text instead of a skeleton.
			const rawRow = (data as any[])[rowIndex];
			const cacheKey = rowIndex + '|' + colKey;
			if (colKey && rawRow == null) {
				// Cache the loading slot keyed on its (null) value: when the page loads, the row
				// flips null → object, the value identity changes, and this naturally MISSES and
				// recomputes (a new `data` proxy also resets the whole cache, so this is belt-and-braces).
				const hit = cache.get(cacheKey);
				if (hit && hit.value === rawRow) return hit.resolution;
				const resolution: SheetsCellResolution = {
					cell: { kind: 'loading', data: null, displayData: '', readonly: true },
					colKey,
					typeKey: 'text',
				};
				cache.set(cacheKey, { value: rawRow, resolution });
				return resolution;
			}
			const rowData = rawRow ?? {};
			if (!colKey) {
				return { cell: { kind: 'text', data: '', displayData: '', readonly: false }, colKey, typeKey: 'text' };
			}

			const rawValue = rowData?.[colKey];

			// RESULT-CACHE FAST PATH: the resolution is fully determined by the row object's
			// fields (see the cache declaration), and the row object is immutable within this
			// resolver identity, so a reference-equal `rawValue` means an identical resolution.
			const hit = cache.get(cacheKey);
			if (hit && hit.value === rawValue) return hit.resolution;
			const draftMeta = getDraftMeta(rowData);
			const isDraftRow = Boolean(draftMeta?.isDraft);
			const isDraftIdCell = isDraftRow && colKey === 'id';

			const baseFieldMeta = fieldMetaMap.get(colKey);
			const relationInfo = relationInfoByField.get(colKey);
			const isRelationFallback = relationFieldNamesFromMeta.has(colKey);
			const isRelation = Boolean(relationInfo) || isRelationFallback;
			const foreignKeyField = relationInfo?.foreignKeyField;
			const canEditRelationInline =
				relationInfo?.kind === 'belongsTo' &&
				typeof foreignKeyField === 'string' &&
				fieldMetaMap.has(foreignKeyField);

			const fieldMeta: FieldMetadata | undefined = baseFieldMeta;
			const route = resolveGridCellRoute({
				colKey,
				fieldMeta,
				relationInfo,
				isRelationFallback,
				isDraftIdCell,
				hasForeignKeyField: canEditRelationInline,
			});
			const tableForcedReadOnly = !isDraftRow && (
				serverRowsReadOnly || Boolean(serverReadOnlyFields?.has(colKey))
			);

			let valueForCell = rawValue;

			if (relationInfo && relationInfo.relationField && relationInfo.relationField !== colKey) {
				const relatedValue = (rowData as any)?.[relationInfo.relationField];
				if (relatedValue !== undefined && relatedValue !== null) {
					valueForCell = relatedValue;
				} else if (typeof rawValue === 'string' && rawValue && !isDraftId(rawValue)) {
					valueForCell = { id: rawValue };
				}
			} else if (relationInfo && valueForCell == null) {
				const fkField = relationInfo.foreignKeyField;
				const fkValue = fkField ? (rowData as any)?.[fkField] : undefined;
				if (fkValue && !isDraftId(fkValue)) {
					valueForCell = { id: fkValue };
				}
			}

			if (isRelation) {
				valueForCell = unwrapRelationValue(valueForCell);
			}

			// Consumer detection override: a registered def's match() may override the
			// resolved typeKey. With no consumer cell types this returns route.cellType.
			const matchInput = {
				gqlType: fieldMeta?.type?.gqlType ?? '',
				isArray: Boolean(fieldMeta?.type?.isArray),
				pgAlias: fieldMeta?.type?.pgAlias ?? null,
				pgType: fieldMeta?.type?.pgType ?? null,
				subtype: fieldMeta?.type?.subtype ?? null,
				fieldName: colKey,
			};
			const cellType = registry.resolveTypeKey(matchInput, () => route.cellType);
			const rowIdentifier = !isDraftRow ? getRowIdentifier?.(rowData) : null;
			const selfCommittingEditor = isRelation || MEDIA_TYPES.has(cellType);
			const lacksScalarEditorIdentity =
				selfCommittingEditor &&
				(!supportsScalarSelfCommit || (
					rowIdentifier != null && typeof rowIdentifier === 'object'
				));
			const forcedReadOnly = tableForcedReadOnly || lacksScalarEditorIdentity;

			const metadata: CellCreationMetadata = {
				cellType,
				fieldName: colKey,
				fieldMeta,
				relationInfo,
				relationOptions: relationInfo ? options || {} : undefined,
				canEdit: route.canEdit && !forcedReadOnly,
				isReadonly: route.isReadonly || forcedReadOnly,
				activationBehavior: route.activationBehavior,
			};

			const resolvedCell = registry.toSheetsCell(cellType, valueForCell, { metadata });
			const cell = forcedReadOnly && !resolvedCell.readonly
				? { ...resolvedCell, readonly: true }
				: resolvedCell;

			// Blank any internal draft key that would otherwise render as visible text
			// (kind unchanged); narrow to the draft id, nothing else.
			const displaySafe = suppressDraftIdText(cell, {
				isDraftRow,
				colKey,
				rawValue,
				draftId: draftMeta?.draftRowId,
			});

			// Flag draft rows (faded) and per-cell errors (error) so the host can paint
			// the DOM equivalent of applyDraftDisabledStyle / applyDraftErrorStyle.
			const draftErrors = draftMeta?.errors ?? null;
			const hasCellError = Boolean(draftErrors && colKey in draftErrors);
			const styled = isDraftRow ? tagDraftStyle(displaySafe, hasCellError) : displaySafe;

			const component = registry.getCellComponent(cellType);
			// Surface the already-computed field/relation meta so a native overlay editor
			// (relation/image, Phase 5) can read EditorProps.fieldMeta / relationInfo without
			// re-resolving — no extra work, just exposing what this routing already derived.
			// `typeKey` is the resolved cellType — the single source of truth for edit-intent.
			const resolution: SheetsCellResolution = { cell: styled, component, colKey, typeKey: cellType, fieldMeta, relationInfo };
			cache.set(cacheKey, { value: rawValue, resolution });
			return resolution;
		},
		[data, columnKeys, fieldMetaMap, registry, relationFieldNamesFromMeta, relationInfoByField, options, serverRowsReadOnly, serverReadOnlyFields, getRowIdentifier, supportsScalarSelfCommit],
	);

	return { getSheetsCell };
}

import type { MetaQuery } from '@constructive-io/data';

import { resolveCellType, type FieldMetadata } from '../cell-types/cell-type-resolver';
import type { RelationInfo } from '../store/relation-info-slice';

type MetaTable = NonNullable<NonNullable<MetaQuery['_meta']>['tables']>[number];

export interface GridCellRouteInput {
	colKey: string;
	fieldMeta?: FieldMetadata;
	relationInfo?: RelationInfo;
	isRelationFallback?: boolean;
	isCustomGeometryCell?: boolean;
	isDraftIdCell?: boolean;
	hasForeignKeyField?: boolean;
}

export interface GridCellRoute {
	cellType: string;
	baseCellType: string;
	isRelation: boolean;
	canEdit: boolean;
	canActivate: boolean;
	isReadonly: boolean;
	activationBehavior: 'single-click' | 'double-click';
}

export function buildRelationFieldNameSet(meta: MetaQuery | undefined, tableName?: string): Set<string> {
	if (!tableName) return new Set<string>();

	const table = meta?._meta?.tables?.find((entry): entry is MetaTable => Boolean(entry && entry.name === tableName));
	if (!table?.relations) return new Set<string>();

	const out = new Set<string>();
	const push = (fieldName?: string | null) => {
		if (fieldName) out.add(fieldName);
	};

	table.relations.belongsTo?.forEach((relation) => {
		push(relation?.fieldName);
		relation?.keys?.forEach((key) => push(key?.name));
	});
	table.relations.hasOne?.forEach((relation) => push(relation?.fieldName));
	table.relations.hasMany?.forEach((relation) => push(relation?.fieldName));
	table.relations.manyToMany?.forEach((relation) => push(relation?.fieldName));

	return out;
}

export function resolveGridCellRoute({
	colKey,
	fieldMeta,
	relationInfo,
	isRelationFallback = false,
	isCustomGeometryCell = false,
	isDraftIdCell = false,
	hasForeignKeyField = false,
}: GridCellRouteInput): GridCellRoute {
	const base = resolveCellType(colKey, fieldMeta);
	const isRelation = Boolean(relationInfo) || isRelationFallback;
	const canEditRelationInline = Boolean(
		relationInfo && relationInfo.kind === 'belongsTo' && relationInfo.foreignKeyField && hasForeignKeyField,
	);

	const canEdit = isDraftIdCell ? false : isRelation ? canEditRelationInline : base.canEdit;
	const canActivate = isDraftIdCell ? false : isRelation ? true : base.canActivate;
	const isReadonly = isDraftIdCell ? true : isRelation ? !canEditRelationInline : base.isReadonly;

	let cellType = isRelation ? 'relation' : base.cellType;
	if (!isRelation && isCustomGeometryCell) {
		cellType = 'geometry';
	}

	return {
		cellType,
		baseCellType: base.cellType,
		isRelation,
		canEdit,
		canActivate,
		isReadonly,
		activationBehavior: base.activationBehavior,
	};
}

// Survivor types relocated out of `grid/editor-registry.ts` (deleted in the glide
// cutover). `DraftSubmitResult` is the result of submitting a client-side draft row;
// it is consumed by the draft-submission hook, use-sheets, and the image editor's
// DOM re-host.

/** Result of submitting a draft row */
export interface DraftSubmitResult {
	/** The created row with its metadata-defined primary-key fields. */
	createdRow: Record<string, unknown> | null;
}

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { XIcon } from 'lucide-react';

import { EditorFocusTrap } from './editor-focus-trap';
import { OVERLAY } from './overlay-presets';

const MAC_UA_RE = /Mac|iPod|iPhone|iPad/;

// Minimal editor component for scalar arrays using tag chips UI
// It works with Glide's provideEditor by emitting a Text cell with JSON string

type Props = {
	value: unknown[];
	onChange: (next: unknown[]) => void;
	onFinished: (next?: unknown[]) => void;
};

function parsePendingItems(input: string): string[] {
	if (!input) return [];
	return input
		.split(/[\n,]/g)
		.map((token) => token.trim())
		.filter((token) => token.length > 0);
}

export function mergeArrayEditorValues(list: unknown[], pendingInput: string): unknown[] {
	const pendingItems = parsePendingItems(pendingInput);
	if (!pendingItems.length) return list;
	return [...list, ...pendingItems];
}

export function ArrayEditor({ value, onChange, onFinished }: Props) {
	const items = useMemo(() => (Array.isArray(value) ? value : []), [value]);
	const [list, setList] = useState<unknown[]>(items);
	const [input, setInput] = useState('');
	const inputRef = useRef<HTMLInputElement>(null);
	const keyContainerRef = useRef<HTMLDivElement>(null);

	const handleCancel = useCallback(() => onFinished(undefined), [onFinished]);
	const handleSave = useCallback(() => {
		const next = mergeArrayEditorValues(list, input);
		setList(next);
		setInput('');
		onChange(next);
		onFinished(next);
	}, [input, list, onChange, onFinished]);

	const add = useCallback(() => {
		const next = mergeArrayEditorValues(list, input);
		if (next.length === list.length) return;
		setList(next);
		setInput('');
		onChange(next);
	}, [input, list, onChange]);

	const remove = useCallback(
		(idx: number) => {
			const next = list.filter((_, i) => i !== idx);
			setList(next);
			onChange(next);
			// Refocus input after removing a tag
			inputRef.current?.focus();
		},
		[list, onChange],
	);

	// Keep refs to latest callbacks/state so the native handler always has fresh values.
	const actionsRef = useRef({ add, handleSave, remove, handleCancel });
	actionsRef.current = { add, handleSave, remove, handleCancel };
	const stateRef = useRef({ input, listLength: list.length });
	stateRef.current = { input, listLength: list.length };

	// Native DOM keydown listener on a wrapper div.
	// Glide's overlay intercepts Enter/Tab/Escape via React onKeyDown on .gdg-clip-region.
	// React's stopPropagation doesn't reliably prevent this in portal contexts.
	// A native listener fires before React's root delegation, so we handle keys here
	// and stopPropagation to prevent Glide from closing the overlay.
	useEffect(() => {
		const el = keyContainerRef.current;
		if (!el) return;
		const handler = (e: KeyboardEvent) => {
			const { add, handleSave, remove, handleCancel } = actionsRef.current;
			const { input, listLength } = stateRef.current;

			if (e.key === 'Escape') {
				e.preventDefault();
				e.stopPropagation();
				handleCancel();
				return;
			}
			if (e.key === 'Backspace' && !input && listLength > 0) {
				e.preventDefault();
				e.stopPropagation();
				remove(listLength - 1);
				return;
			}
			if (e.key === 'Enter' && !e.metaKey && !e.ctrlKey) {
				e.preventDefault();
				e.stopPropagation();
				add();
				return;
			}
			if ((e.key === 'Enter' && (e.metaKey || e.ctrlKey)) || (e.key === 's' && (e.metaKey || e.ctrlKey))) {
				e.preventDefault();
				e.stopPropagation();
				handleSave();
				return;
			}
			if (e.key === 'Tab') {
				e.stopPropagation();
			}
		};
		el.addEventListener('keydown', handler);
		return () => el.removeEventListener('keydown', handler);
	}, []);

	const isMac = typeof navigator !== 'undefined' && MAC_UA_RE.test(navigator.userAgent);
	const modKey = isMac ? '⌘' : 'Ctrl';

	return (
		<EditorFocusTrap
			onEscape={handleCancel}
			className={`bg-popover ${OVERLAY.sm} rounded-lg border p-2.5 shadow-lg`}
		>
			{/* Key event boundary — native listener prevents Glide from intercepting */}
			<div ref={keyContainerRef}>
				{/* Unified tag surface — tags and input share one container */}
				<div
					className='flex min-h-[2.5rem] cursor-text flex-wrap items-center gap-2 rounded-md px-1 py-1'
					onClick={() => inputRef.current?.focus()}
				>
					{list.map((item, i) => (
						<Badge
							key={i}
							variant='outline'
							size='sm'
							className='group/tag !animate-none !transition-none gap-0.5 pe-0.5'
						>
							<span className='max-w-[180px] truncate'>{String(item)}</span>
							<button
								className='text-muted-foreground/60 hover:bg-muted hover:text-foreground -me-px inline-flex size-4 items-center justify-center rounded-xs transition-colors'
								onClick={(e) => {
									e.stopPropagation();
									remove(i);
								}}
								aria-label={`Remove ${String(item)}`}
								tabIndex={-1}
							>
								<XIcon className='size-3' />
							</button>
						</Badge>
					))}

					<input
						ref={inputRef}
						value={input}
						onChange={(e) => setInput(e.target.value)}
						placeholder={list.length === 0 ? 'Type and press Enter...' : 'Add more...'}
						className='placeholder:text-muted-foreground/50 min-w-[80px] flex-1 bg-transparent py-0.5 text-sm outline-none'
					/>
				</div>

				{/* Footer — hints + save */}
				<div className='mt-3 flex items-center justify-between gap-4 border-t px-1 pt-2.5'>
					<div className='text-muted-foreground flex items-center gap-3 text-xs'>
						<span className='inline-flex shrink-0 items-center gap-1'>
							<kbd className='bg-muted/60 border-border/40 inline-flex min-h-5 items-center justify-center rounded border px-1.5 font-sans text-[11px] leading-tight'>Enter</kbd>
							<span>add</span>
						</span>
						<span className='text-border'>|</span>
						<span className='inline-flex shrink-0 items-center gap-1'>
							<kbd className='bg-muted/60 border-border/40 inline-flex min-h-5 min-w-5 items-center justify-center rounded border font-sans text-[11px] leading-tight'>{modKey}</kbd>
							<kbd className='bg-muted/60 border-border/40 inline-flex min-h-5 min-w-5 items-center justify-center rounded border font-sans text-[11px] leading-tight'>↵</kbd>
							<span>save</span>
						</span>
						<span className='inline-flex shrink-0 items-center gap-1'>
							<kbd className='bg-muted/60 border-border/40 inline-flex min-h-5 min-w-5 items-center justify-center rounded border font-sans text-[11px] leading-tight'>⌫</kbd>
							<span>remove</span>
						</span>
					</div>
					<Button onClick={handleSave} size='xs' variant='default' className='shrink-0'>
						Save
					</Button>
				</div>
			</div>
		</EditorFocusTrap>
	);
}

import React, { useCallback, useEffect, useRef, useState } from 'react';
import { parseDate as parseAriaDate } from '@internationalized/date';
import type { DateValue as DateValueType } from 'react-aria-components';

import { Button } from '@/components/ui/button';
import { Calendar } from '@/components/ui/calendar-rac';

import { DATE_TIME_TYPES } from '../../cell-types/cell-type-groups';
import { sheetsLocale } from '../../utils/sheets-i18n';

import { EditorFocusTrap } from './editor-focus-trap';
import { OVERLAY } from './overlay-presets';

const TIME_RE = /(\d{1,2}):(\d{2})(?::(\d{2}))?(?:\.\d+)?/;
const MAC_UA_RE = /Mac|iPod|iPhone|iPad/;

export type DateEditorType = 'date' | 'datetime' | 'timestamptz' | 'time';

const DATE_ONLY_RE = /^\d{4}-\d{2}-\d{2}/;

function pad2(value: number): string {
	return String(value).padStart(2, '0');
}

// Format a Date as a calendar date string using LOCAL getters (never UTC).
// This is the correct serialization for date-only values: the wall-clock day
// the user picked is preserved regardless of timezone.
export function toLocalDateString(d: Date): string {
	return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
}

// If the value is a string whose literal calendar date is already known
// (starts with YYYY-MM-DD), return that 10-char slice verbatim. Otherwise null.
// Date-only strings must never round-trip through a Date object.
export function extractDateOnly(v: unknown): string | null {
	if (typeof v === 'string' && DATE_ONLY_RE.test(v)) {
		return v.slice(0, 10);
	}
	return null;
}

function normalizeTimeValue(value: unknown): string {
	if (value == null) return '';

	if (value instanceof Date) {
		if (isNaN(value.getTime())) return '';
		return `${pad2(value.getHours())}:${pad2(value.getMinutes())}:${pad2(value.getSeconds())}`;
	}

	const asString = String(value).trim();
	if (!asString) return '';

	// Match both time-only values and datetime-like values with a time component.
	const match = asString.match(TIME_RE);
	if (!match) return '';

	const hours = Number(match[1] ?? 0);
	const minutes = Number(match[2] ?? 0);
	const seconds = Number(match[3] ?? 0);
	if (
		!Number.isFinite(hours) ||
		!Number.isFinite(minutes) ||
		!Number.isFinite(seconds) ||
		hours < 0 ||
		hours > 23 ||
		minutes < 0 ||
		minutes > 59 ||
		seconds < 0 ||
		seconds > 59
	) {
		return '';
	}

	return `${pad2(hours)}:${pad2(minutes)}:${pad2(seconds)}`;
}

// Determine date type from cell data or explicit context
export const getDateType = (value: any): DateEditorType => {
	// Try to infer from the value format
	if (typeof value === 'string') {
		if (value.includes('T') || value.includes(' ')) {
			return value.includes('+') || value.includes('Z') ? 'timestamptz' : 'datetime';
		}
		if (value.includes(':') && !value.includes('-')) {
			return 'time';
		}
	}
	return 'date'; // Default fallback
};

export function resolveDateType(value: unknown, explicitType?: string): DateEditorType {
	if (explicitType && DATE_TIME_TYPES.has(explicitType)) {
		return explicitType as DateEditorType;
	}
	return getDateType(value);
}

// Format date for display based on type
export const formatDate = (val: unknown, dateType: DateEditorType): string => {
	if (!val) return '';

	if (dateType === 'time') {
		if (typeof val === 'string') {
			return val.trim();
		}
		const normalized = normalizeTimeValue(val);
		return normalized || String(val);
	}

	try {
		// Date-only display must use the literal calendar date, never a UTC
		// conversion (which shifts the day in any UTC+ zone). Prefer the literal
		// slice and never round-trip a Date.
		if (dateType === 'date') {
			const literal = extractDateOnly(val);
			if (literal) return literal;
			if (val instanceof Date) {
				return isNaN(val.getTime()) ? String(val) : toLocalDateString(val);
			}
			return String(val);
		}

		let date: Date;
		if (val instanceof Date) {
			date = val;
		} else if (typeof val === 'string') {
			date = new Date(val);
		} else {
			return String(val);
		}

		if (isNaN(date.getTime())) return String(val);

		switch (dateType) {
			case 'datetime':
			case 'timestamptz':
				return date.toLocaleDateString(sheetsLocale(), {
					year: 'numeric',
					month: 'short',
					day: 'numeric',
					hour: '2-digit',
					minute: '2-digit',
					hour12: false,
				});
			default: {
				// Default branch is treated as date-only semantics.
				const literal = extractDateOnly(val);
				if (literal) return literal;
				return toLocalDateString(date);
			}
		}
	} catch {
		return String(val);
	}
};

// Format date for input based on type
export const formatForInput = (val: unknown, inputType: string): string => {
	if (!val) return '';

	if (inputType === 'time') {
		return normalizeTimeValue(val);
	}

	// Date-only input must reflect the literal calendar date, never a UTC shift.
	if (inputType === 'date') {
		const literal = extractDateOnly(val);
		if (literal) return literal;
		if (val instanceof Date) {
			return isNaN(val.getTime()) ? '' : toLocalDateString(val);
		}
		return '';
	}

	try {
		let date: Date;
		if (val instanceof Date) {
			date = val;
		} else if (typeof val === 'string') {
			date = new Date(val);
		} else {
			return '';
		}

		if (isNaN(date.getTime())) return '';

		switch (inputType) {
			case 'datetime-local':
				return date.toISOString().slice(0, 16);
			default:
				return '';
		}
	} catch {
		return '';
	}
};

// Convert a date input to a DateValue for the calendar.
// Date-only strings are parsed by their literal calendar date (no Date round-trip),
// so the calendar seeds on exactly the stored day in any timezone.
const dateToDateValue = (date: Date | string | null): DateValueType | null => {
	if (!date) return null;

	try {
		const literal = extractDateOnly(date);
		if (literal) {
			return parseAriaDate(literal);
		}

		const jsDate = date instanceof Date ? date : new Date(date);
		if (isNaN(jsDate.getTime())) return null;

		return parseAriaDate(toLocalDateString(jsDate));
	} catch {
		return null;
	}
};

// Convert DateValue to JavaScript Date
const dateValueToDate = (dateValue: DateValueType | null): Date | null => {
	if (!dateValue) return null;

	try {
		return new Date(dateValue.year, dateValue.month - 1, dateValue.day);
	} catch {
		return null;
	}
};

interface DateEditorProps {
	value: unknown;
	onFinishedEditing: (next?: unknown) => void;
	dateType?: DateEditorType;
}

export const DateEditor: React.FC<DateEditorProps> = ({ value, onFinishedEditing, dateType: forcedDateType }) => {
	// Extract current date data from the raw value
	const currentDateValue = typeof value === 'string' ? value : '';
	const dateType = resolveDateType(currentDateValue, forcedDateType);

	const [dateValue, setDateValue] = useState<string | Date | null>(currentDateValue);
	const [selectedDate, setSelectedDate] = useState<DateValueType | null>(
		dateToDateValue(currentDateValue || new Date()),
	);

	const keyContainerRef = useRef<HTMLDivElement>(null);

	const isTimeOnly = dateType === 'time';
	const isDateTimeType = dateType === 'datetime' || dateType === 'timestamptz';

	const handleDateSelect = useCallback(
		(dateValue: DateValueType | readonly DateValueType[] | null) => {
			// The shared Calendar also supports multi-select, so its public
			// callback includes arrays. This editor is intentionally single-date.
			if (Array.isArray(dateValue)) return;
			const selectedValue = dateValue as DateValueType | null;
			setSelectedDate(selectedValue);
			const jsDate = dateValueToDate(selectedValue);

			if (jsDate) {
				// For datetime types, preserve existing time if available
				if (isDateTimeType && currentDateValue) {
					const currentDate = new Date(currentDateValue);
					if (!isNaN(currentDate.getTime())) {
						jsDate.setHours(currentDate.getHours(), currentDate.getMinutes(), currentDate.getSeconds());
					}
				}
				setDateValue(jsDate);
			}
		},
		[isDateTimeType, currentDateValue],
	);

	const handleTimeChange = useCallback(
		(timeValue: string) => {
			if (!timeValue) return;

			if (isTimeOnly) {
				const normalizedTime = normalizeTimeValue(timeValue);
				setDateValue(normalizedTime);
				return;
			}

			const [hours, minutes, seconds = 0] = timeValue.split(':').map(Number);
			const targetDate: Date = selectedDate
				? dateValueToDate(selectedDate) || new Date()
				: currentDateValue
					? new Date(currentDateValue)
					: new Date();

			targetDate.setHours(hours || 0, minutes || 0, seconds || 0, 0);
			setDateValue(targetDate);
		},
		[isTimeOnly, selectedDate, currentDateValue],
	);

	const handleSave = useCallback(() => {
		let finalValue: string;

		if (!dateValue) {
			finalValue = '';
		} else {
			if (dateType === 'time') {
				finalValue = normalizeTimeValue(dateValue);
				if (!finalValue) {
					finalValue = String(dateValue).trim();
				}
				return onFinishedEditing(finalValue);
			}

			// Date-only path: serialize the literal calendar date with LOCAL getters.
			// A UTC conversion (toISOString) shifts the day backwards in any UTC+
			// zone — that is the write corruption this guards against.
			if (dateType === 'date') {
				const literal = extractDateOnly(dateValue);
				if (literal) {
					finalValue = literal;
				} else if (dateValue instanceof Date) {
					finalValue = isNaN(dateValue.getTime()) ? '' : toLocalDateString(dateValue);
				} else {
					finalValue = '';
				}
			} else {
				const date = dateValue instanceof Date ? dateValue : new Date(dateValue);

				if (isNaN(date.getTime())) {
					finalValue = '';
				} else {
					switch (dateType) {
						case 'datetime':
							finalValue = date.toISOString().slice(0, 19); // Remove Z
							break;
						case 'timestamptz':
							finalValue = date.toISOString();
							break;
						default: {
							// Default branch is treated as date-only semantics.
							const literal = extractDateOnly(dateValue);
							finalValue = literal ?? toLocalDateString(date);
						}
					}
				}
			}
		}

		// Emit the raw formatted date string
		onFinishedEditing(finalValue);
	}, [dateValue, dateType, onFinishedEditing]);

	const handleCancel = useCallback(() => {
		onFinishedEditing();
	}, [onFinishedEditing]);

	// Refs for native key handler
	const actionsRef = useRef({ handleSave, handleCancel });
	actionsRef.current = { handleSave, handleCancel };

	// Native DOM keydown listener — prevents Glide from intercepting keys in portal context
	useEffect(() => {
		const el = keyContainerRef.current;
		if (!el) return;
		const handler = (e: KeyboardEvent) => {
			const { handleSave, handleCancel } = actionsRef.current;

			if (e.key === 'Escape') {
				e.preventDefault();
				e.stopPropagation();
				handleCancel();
				return;
			}
			if ((e.key === 'Enter' && (e.metaKey || e.ctrlKey)) || (e.key === 's' && (e.metaKey || e.ctrlKey))) {
				e.preventDefault();
				e.stopPropagation();
				handleSave();
				return;
			}
			// Stop Tab from reaching Glide
			if (e.key === 'Tab') {
				e.stopPropagation();
			}
		};
		el.addEventListener('keydown', handler);
		return () => el.removeEventListener('keydown', handler);
	}, []);

	const displayValue = formatDate(dateValue, dateType);

	const isMac = typeof navigator !== 'undefined' && MAC_UA_RE.test(navigator.userAgent);
	const modKey = isMac ? '⌘' : 'Ctrl';

	return (
		<EditorFocusTrap
			onEscape={handleCancel}
			className={`bg-popover ${OVERLAY.sm} rounded-lg border p-2.5 shadow-lg`}
		>
			<div ref={keyContainerRef}>
				{isTimeOnly ? (
					// Time-only: compact input
					<div className='space-y-2'>
						<input
							type='time'
							step='1'
							value={formatForInput(dateValue, 'time')}
							onChange={(e) => handleTimeChange(e.target.value)}
							className='bg-muted/40 border-border/40 text-foreground w-full rounded-md border px-3 py-2 text-sm outline-none focus-visible:border-ring/60 focus-visible:ring-[3px] focus-visible:ring-ring/35'
							autoFocus
						/>
					</div>
				) : (
					// Date / DateTime: calendar + optional time
					<div>
						{/* Selected date display */}
						<div className='text-muted-foreground mb-1 px-1 text-xs font-medium tabular-nums'>
							{displayValue || 'No date selected'}
						</div>

						{/* Calendar */}
						<Calendar
							value={selectedDate}
							onChange={handleDateSelect}
							aria-label='Select date'
						/>

						{/* Time input for datetime types */}
						{isDateTimeType && (
							<div className='mt-2 px-1'>
								<input
									type='time'
									step='1'
									value={dateValue ? new Date(dateValue).toTimeString().split(' ')[0].slice(0, 8) : ''}
									onChange={(e) => handleTimeChange(e.target.value)}
									className='bg-muted/40 border-border/40 text-foreground w-full rounded-md border px-2.5 py-1.5 text-sm outline-none focus-visible:border-ring/60 focus-visible:ring-[3px] focus-visible:ring-ring/35'
								/>
							</div>
						)}
					</div>
				)}

				{/* Footer — hints + save */}
				<div className='mt-3 flex items-center justify-between gap-4 border-t px-1 pt-2.5'>
					<div className='text-muted-foreground flex items-center gap-3 text-xs'>
						<span className='inline-flex shrink-0 items-center gap-1'>
							<kbd className='bg-muted/60 border-border/40 inline-flex min-h-5 min-w-5 items-center justify-center rounded border font-sans text-[11px] leading-tight'>{modKey}</kbd>
							<kbd className='bg-muted/60 border-border/40 inline-flex min-h-5 min-w-5 items-center justify-center rounded border font-sans text-[11px] leading-tight'>↵</kbd>
							<span>save</span>
						</span>
						<span className='inline-flex shrink-0 items-center gap-1'>
							<kbd className='bg-muted/60 border-border/40 inline-flex min-h-5 items-center justify-center rounded border px-1.5 font-sans text-[11px] leading-tight'>Esc</kbd>
							<span>cancel</span>
						</span>
					</div>
					<Button onClick={handleSave} size='xs' variant='default' className='shrink-0'>
						Save
					</Button>
				</div>
			</div>
		</EditorFocusTrap>
	);
};

import React, { useCallback, useEffect, useLayoutEffect, useRef } from 'react';

interface EditorFocusTrapProps {
	children: React.ReactNode;
	onEscape?: () => void;
	onKeyDown?: (e: React.KeyboardEvent) => void;
	className?: string;
	style?: React.CSSProperties;
}

const FOCUSABLE_SELECTOR = [
	'button:not([disabled])',
	'input:not([disabled])',
	'textarea:not([disabled])',
	'select:not([disabled])',
	'a[href]',
	'[tabindex]:not([tabindex="-1"])',
].join(', ');

/** Filter to only truly visible focusable elements */
function getVisibleFocusable(container: HTMLElement): HTMLElement[] {
	return Array.from(container.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR)).filter(
		(el) => el.offsetParent !== null,
	);
}

export function EditorFocusTrap({ children, onEscape, onKeyDown, className, style }: EditorFocusTrapProps) {
	const containerRef = useRef<HTMLDivElement>(null);
	const previousActiveElement = useRef<Element | null>(null);

	// Focus the first visible focusable element synchronously before paint, so the
	// editor input is focused instantly on open (no setTimeout settle, no focus-jump
	// off an input the user already started typing in). Runs once on mount.
	useLayoutEffect(() => {
		previousActiveElement.current = document.activeElement;

		if (!containerRef.current) return;

		const visibleElements = getVisibleFocusable(containerRef.current);
		if (visibleElements.length > 0) {
			visibleElements[0].focus();
		} else {
			// If no visible focusable elements, focus the container itself
			containerRef.current.focus();
		}
	}, []);

	// Restore focus to the previously active element when unmounting (only if still
	// in DOM).
	useEffect(() => {
		return () => {
			if (previousActiveElement.current instanceof HTMLElement && previousActiveElement.current.isConnected) {
				previousActiveElement.current.focus();
			}
		};
	}, []);

	// Handle keyboard events — forward all keys to parent, then handle Escape/Tab
	const handleKeyDown = useCallback(
		(e: React.KeyboardEvent) => {
			// Forward all key events to parent before handling
			onKeyDown?.(e);

			if (e.key === 'Escape') {
				e.preventDefault();
				e.stopPropagation();
				onEscape?.();
				return;
			}

			if (e.key !== 'Tab') return;

			const container = containerRef.current;
			if (!container) return;

			const focusableElements = getVisibleFocusable(container);
			if (focusableElements.length === 0) return;

			const firstElement = focusableElements[0];
			const lastElement = focusableElements[focusableElements.length - 1];
			const activeElement = document.activeElement;

			if (e.shiftKey) {
				// Shift+Tab: going backwards
				if (activeElement === firstElement) {
					e.preventDefault();
					lastElement.focus();
				}
			} else {
				// Tab: going forwards
				if (activeElement === lastElement) {
					e.preventDefault();
					firstElement.focus();
				}
			}
		},
		[onEscape, onKeyDown],
	);

	return (
		<div
			ref={containerRef}
			className={className}
			style={style}
			onKeyDown={handleKeyDown}
			tabIndex={-1}
			role="dialog"
			aria-modal="true"
		>
			{children}
		</div>
	);
}

