'use client';

import { Component, type ErrorInfo, type ReactNode } from 'react';

import { sheetsLogger } from '../../utils/sheets-logger';
import { SheetsErrorState } from './sheets-error-state';

interface SheetsErrorBoundaryProps {
	children: ReactNode;
	/** Called when a render error is caught. Mirrors SheetsConfig.onError. */
	onError?: (error: unknown, ctx?: { source?: 'grid' | 'editor' | 'mutation' | 'upload'; tableName?: string }) => void;
	/** Custom fallback. Receives the error and a reset callback to retry rendering. */
	fallback?: (error: unknown, reset: () => void) => ReactNode;
}

interface SheetsErrorBoundaryState {
	error: unknown;
}

/**
 * Render-error boundary for the grid subtree. Catches exceptions thrown during
 * render of the DataEditor and editors, logs them through the injectable logger,
 * forwards them to the host via onError, and shows a recoverable error state.
 */
export class SheetsErrorBoundary extends Component<SheetsErrorBoundaryProps, SheetsErrorBoundaryState> {
	state: SheetsErrorBoundaryState = { error: null };

	static getDerivedStateFromError(error: unknown): SheetsErrorBoundaryState {
		return { error };
	}

	componentDidCatch(error: unknown, info: ErrorInfo): void {
		sheetsLogger().error('[sheets] render error', { error, componentStack: info.componentStack });
		this.props.onError?.(error, { source: 'grid' });
	}

	reset = (): void => {
		this.setState({ error: null });
	};

	render(): ReactNode {
		const { error } = this.state;
		if (error != null) {
			return this.props.fallback?.(error, this.reset) ?? <SheetsErrorState error={error} onRetry={this.reset} />;
		}
		return this.props.children;
	}
}

'use client';

import { RiAddLine, RiErrorWarningLine, RiInboxLine } from '@remixicon/react';

import { Button } from '@/components/ui/button';
import { cn } from '../../utils/cn';

function getErrorMessage(error: unknown): string {
	if (error instanceof Error) return error.message;
	if (typeof error === 'string') return error;
	return 'Something went wrong while loading this table.';
}

interface SheetsStateShellProps {
	className?: string;
	children: React.ReactNode;
}

/** Centered, full-size container shared by the error/empty/loading states. */
function SheetsStateShell({ className, children }: SheetsStateShellProps) {
	return (
		<div
			className={cn(
				'bg-background flex h-full min-h-0 flex-1 flex-col items-center justify-center gap-3 rounded-lg border p-8 text-center',
				className,
			)}
		>
			{children}
		</div>
	);
}

interface SheetsErrorStateProps {
	error: unknown;
	onRetry?: () => void;
}

/** Shown when the table data (or its metadata) fails to load. */
export function SheetsErrorState({ error, onRetry }: SheetsErrorStateProps) {
	return (
		<SheetsStateShell>
			<RiErrorWarningLine className='text-destructive h-8 w-8' />
			<div className='space-y-1'>
				<p className='text-foreground text-sm font-medium'>Failed to load data</p>
				<p className='text-muted-foreground max-w-md text-sm'>{getErrorMessage(error)}</p>
			</div>
			{onRetry && (
				<Button variant='outline' size='sm' onClick={onRetry}>
					Retry
				</Button>
			)}
		</SheetsStateShell>
	);
}

interface SheetsEmptyStateProps {
	tableName?: string;
	onAddRow?: () => void;
	readOnlyReason?: string | null;
}

/** Shown when the table loaded successfully but has no rows. */
export function SheetsEmptyState({ tableName, onAddRow, readOnlyReason }: SheetsEmptyStateProps) {
	return (
		<SheetsStateShell>
			<RiInboxLine className='text-muted-foreground h-8 w-8' />
			<div className='space-y-1'>
				<p className='text-foreground text-sm font-medium'>No rows yet</p>
				<p className='text-muted-foreground max-w-md text-sm'>
					{readOnlyReason ?? (tableName ? `The "${tableName}" table is empty.` : 'This table is empty.')}
				</p>
			</div>
			{onAddRow && (
				<Button variant='outline' size='sm' onClick={onAddRow}>
					<RiAddLine className='h-4 w-4' />
					<span className='ms-1'>Add row</span>
				</Button>
			)}
		</SheetsStateShell>
	);
}

/** Column-width hints (px) for the skeleton bars — varied so it reads as a real table. */
const SKELETON_COLS = [120, 88, 152, 64, 108, 132, 80];
const SKELETON_ROWS = 12;

/**
 * Shown during the initial data load. A STRUCTURAL skeleton of the grid (baseline-ui:
 * prefer skeletons over spinners) — mirrors the real grid's 40px header + 44px rows +
 * horizontal hairlines so the load→loaded swap doesn't jump. Pulse is motion-safe only.
 */
export function SheetsLoadingState() {
	return (
		<div
			className='bg-background flex h-full min-h-0 flex-1 flex-col overflow-hidden rounded-lg border'
			role='status'
			aria-busy='true'
			aria-label='Loading data'
		>
			<div className='flex shrink-0 items-center gap-6 border-b px-3' style={{ height: 40 }}>
				{SKELETON_COLS.map((w, i) => (
					<div key={i} className='bg-muted h-2.5 shrink-0 rounded-sm' style={{ width: Math.round(w * 0.7) }} />
				))}
			</div>
			{Array.from({ length: SKELETON_ROWS }).map((_, r) => (
				<div key={r} className='flex shrink-0 items-center gap-6 border-b px-3' style={{ height: 44 }}>
					{SKELETON_COLS.map((w, i) => (
						<div key={i} className='bg-muted/60 h-3 shrink-0 rounded-sm motion-safe:animate-pulse' style={{ width: w }} />
					))}
				</div>
			))}
		</div>
	);
}

export type OperatorValueType = 'string' | 'number' | 'date' | 'datetime' | 'interval' | 'key' | 'none';

export interface FilterOperator {
	operator: string;
	label: string;
	valueType: OperatorValueType;
}

const TEXT_OPERATORS: FilterOperator[] = [
	{ operator: 'includesInsensitive', label: 'contains', valueType: 'string' },
	{ operator: 'equalTo', label: 'equals', valueType: 'string' },
	{ operator: 'notEqualTo', label: 'not equals', valueType: 'string' },
	{ operator: 'startsWithInsensitive', label: 'starts with', valueType: 'string' },
	{ operator: 'endsWithInsensitive', label: 'ends with', valueType: 'string' },
	{ operator: 'isNull', label: 'is empty', valueType: 'none' },
];

const NUMERIC_OPERATORS: FilterOperator[] = [
	{ operator: 'equalTo', label: '=', valueType: 'number' },
	{ operator: 'notEqualTo', label: '\u2260', valueType: 'number' },
	{ operator: 'greaterThan', label: '>', valueType: 'number' },
	{ operator: 'greaterThanOrEqualTo', label: '\u2265', valueType: 'number' },
	{ operator: 'lessThan', label: '<', valueType: 'number' },
	{ operator: 'lessThanOrEqualTo', label: '\u2264', valueType: 'number' },
	{ operator: 'isNull', label: 'is empty', valueType: 'none' },
];

const BOOLEAN_OPERATORS: FilterOperator[] = [
	{ operator: 'equalTo:true', label: 'is true', valueType: 'none' },
	{ operator: 'equalTo:false', label: 'is false', valueType: 'none' },
	{ operator: 'isNull', label: 'is empty', valueType: 'none' },
];

function makeDateOperators(valueType: 'date' | 'datetime'): FilterOperator[] {
	return [
		{ operator: 'equalTo', label: 'equals', valueType },
		{ operator: 'lessThan', label: 'before', valueType },
		{ operator: 'lessThanOrEqualTo', label: 'on or before', valueType },
		{ operator: 'greaterThan', label: 'after', valueType },
		{ operator: 'greaterThanOrEqualTo', label: 'on or after', valueType },
		{ operator: 'isNull', label: 'is empty', valueType: 'none' },
	];
}

const DATE_OPERATORS = makeDateOperators('date');
const DATETIME_OPERATORS = makeDateOperators('datetime');

const UUID_OPERATORS: FilterOperator[] = [
	{ operator: 'equalTo', label: 'equals', valueType: 'string' },
	{ operator: 'notEqualTo', label: 'not equals', valueType: 'string' },
	{ operator: 'isNull', label: 'is empty', valueType: 'none' },
];

const INET_OPERATORS: FilterOperator[] = [
	{ operator: 'equalTo', label: 'equals', valueType: 'string' },
	{ operator: 'notEqualTo', label: 'not equals', valueType: 'string' },
	{ operator: 'contains', label: 'contains', valueType: 'string' },
	{ operator: 'containedBy', label: 'contained by', valueType: 'string' },
	{ operator: 'isNull', label: 'is empty', valueType: 'none' },
];

const JSON_OPERATORS: FilterOperator[] = [
	{ operator: 'containsKey', label: 'has key', valueType: 'key' },
	{ operator: 'isNull', label: 'is empty', valueType: 'none' },
];

const INTERVAL_OPERATORS: FilterOperator[] = [
	{ operator: 'equalTo', label: '=', valueType: 'interval' },
	{ operator: 'notEqualTo', label: '\u2260', valueType: 'interval' },
	{ operator: 'greaterThan', label: '>', valueType: 'interval' },
	{ operator: 'greaterThanOrEqualTo', label: '\u2265', valueType: 'interval' },
	{ operator: 'lessThan', label: '<', valueType: 'interval' },
	{ operator: 'lessThanOrEqualTo', label: '\u2264', valueType: 'interval' },
	{ operator: 'isNull', label: 'is empty', valueType: 'none' },
];

const ENUM_OPERATORS: FilterOperator[] = [
	{ operator: 'equalTo', label: 'equals', valueType: 'string' },
	{ operator: 'notEqualTo', label: 'not equals', valueType: 'string' },
	{ operator: 'isNull', label: 'is empty', valueType: 'none' },
];

const GQL_TYPE_OPERATORS: Record<string, FilterOperator[]> = {
	String: TEXT_OPERATORS,
	Int: NUMERIC_OPERATORS,
	Float: NUMERIC_OPERATORS,
	BigFloat: NUMERIC_OPERATORS,
	BigInt: NUMERIC_OPERATORS,
	Boolean: BOOLEAN_OPERATORS,
	Date: DATE_OPERATORS,
	Datetime: DATETIME_OPERATORS,
	UUID: UUID_OPERATORS,
	InternetAddress: INET_OPERATORS,
	JSON: JSON_OPERATORS,
	Interval: INTERVAL_OPERATORS,
	BitString: ENUM_OPERATORS,
};

const UNFILTERABLE_TYPES = new Set(['GeoJSON', 'FullText']);

/** Get available filter operators for a given gqlType. Returns empty array for unfilterable types. */
export function getOperatorsForGqlType(gqlType: string | null | undefined, isArray: boolean): FilterOperator[] {
	if (!gqlType || isArray || UNFILTERABLE_TYPES.has(gqlType)) return [];
	return GQL_TYPE_OPERATORS[gqlType] ?? [];
}

/** Whether a field type can be filtered at all. */
export function isFilterableType(gqlType: string | null | undefined, isArray: boolean): boolean {
	if (!gqlType || isArray || UNFILTERABLE_TYPES.has(gqlType)) return false;
	return gqlType in GQL_TYPE_OPERATORS;
}

/** Get the default (first) operator for a gqlType. */
export function getDefaultOperator(gqlType: string | null | undefined, isArray: boolean): string | undefined {
	const ops = getOperatorsForGqlType(gqlType, isArray);
	return ops[0]?.operator;
}

/** Whether an operator encodes its value and needs no user input. */
export function isValuelessOperator(operator: string): boolean {
	return operator === 'isNull' || operator === 'equalTo:true' || operator === 'equalTo:false';
}

import type { FieldMetadata } from '../cell-types/cell-type-resolver';
import type { RelationInfo } from '../store/relation-info-slice';

// Relation rendering options surfaced to cell factories alongside metadata
export interface RelationCellOptions {
	relationChipLimit?: number;
	relationLabelMaxLength?: number;
}

// Metadata used when creating cells from values
export interface CellCreationMetadata {
	cellType: string;
	fieldName: string;
	fieldMeta?: FieldMetadata;
	relationInfo?: RelationInfo;
	relationOptions?: RelationCellOptions;
	canEdit: boolean;
	isReadonly: boolean;
	activationBehavior: 'single-click' | 'double-click';
}

/**
 * useBatchCommit — the batched cell-value commit primitive behind paste / fill /
 * bulk-edit AND (routed through it) the single-cell edit, so EVERY server-row value
 * write is one undoable, coalesced operation.
 *
 * It owns NO coercion/readonly rules of its own: server-row writes go through the
 * shared {@link resolveServerPatch} (the same resolver `useCellEditing` uses), so the
 * UUID-id guard, relation normalization and readonly skips stay in ONE place.
 *
 * Coalescing contract (load-bearing for a 1000-cell paste):
 *   • prior values are captured from `combinedRows` BEFORE any optimistic patch, so
 *     undo restores the EXACT pre-edit value.
 *   • ONE optimistic cache patch is applied per affected ROW (merged col patches),
 *     not per cell — N rows -> N patches, never N×cols.
 *   • ONE server `update(rowId, {merged})` is issued per row.
 *   • when recording, the HistoryEntry's `undo`/`redo` re-enter `commitCells` with
 *     `{ record: false }` so replays never double-record.
 *
 * Draft-row writes are NOT batched here — they route to the existing per-cell draft
 * path (`editCell`) and are excluded from history (draft undo is out of P3 scope).
 */
import { useCallback, useRef } from 'react';

import { resolveServerPatch } from './use-cell-editing';
import type { CellEditingResult } from './use-cell-editing';
import { getDraftMeta, type SheetsRow } from '../row-model';
import type { SheetsRowIdentifier } from '../../row-identity';

/** A single cell write request. */
export interface CellWrite {
	rowIndex: number;
	colKey: string;
	value: unknown;
}

export interface CommitCellsOptions {
	/** When false, the commit is NOT pushed to history (used by undo/redo replays). Default true. */
	record?: boolean;
}

export interface CommitCellsResult {
	/** Number of server cells actually written (post readonly/null/no-op filtering). */
	applied: number;
}

interface UseBatchCommitParams {
	combinedRows: SheetsRow[];
	fieldMetaMap: Map<string, any>;
	relationInfoByField: Map<string, any>;
	update: (id: SheetsRowIdentifier, data: Record<string, unknown>) => Promise<{ updatedRow?: Record<string, unknown> | null }>;
	getRowIdentifier?: (row: Readonly<Record<string, unknown>>) => SheetsRowIdentifier | null;
	readOnlyFields?: ReadonlySet<string>;
	canUpdate?: boolean;
	/** Single-write optimistic cache patch (infinite mode) — returns a revert thunk. */
	applyOptimisticPatch?: (rowIndex: number, patch: Record<string, unknown>) => (() => void) | void;
	/** Re-sync a server row over the optimistic patch after the mutation resolves (infinite mode). */
	resyncRow?: (rowIndex: number, updatedRow: Record<string, unknown>) => void;
	/** Existing per-cell editor (draft routing + single-cell server coercion). */
	editCell: (rowIndex: number, colKey: string, rawValue: unknown) => Promise<CellEditingResult>;
	/** Observational per-server-write callback (mirrors useCellEditing's onCellEdit). */
	onCellEdit?: (id: SheetsRowIdentifier, field: string, value: unknown) => void;
	/** Push a reversible step to the history. */
	record: (entry: { label: string; undo: () => Promise<void> | void; redo: () => Promise<void> | void }) => void;
}

/** A resolved server write: its row, the patch field, the next + prior values. */
interface ResolvedWrite {
	rowIndex: number;
	rowId: SheetsRowIdentifier;
	field: string;
	value: unknown;
	prior: unknown;
}

function legacyRowIdentifier(row: Readonly<Record<string, unknown>>): SheetsRowIdentifier | null {
	return typeof row.id === 'string' || typeof row.id === 'number' ? row.id : null;
}

export function useBatchCommit({
	combinedRows,
	fieldMetaMap,
	relationInfoByField,
	update,
	getRowIdentifier = legacyRowIdentifier,
	readOnlyFields,
	canUpdate = true,
	applyOptimisticPatch,
	resyncRow,
	editCell,
	onCellEdit,
	record,
}: UseBatchCommitParams) {
	// Holds the latest commitCells so a recorded HistoryEntry (captured at record-time)
	// always re-enters the CURRENT closure — avoids a stale-row snapshot. Per-hook
	// instance, so multiple grids never share a commit fn.
	const commitRef = useRef<((writes: CellWrite[], opts?: CommitCellsOptions) => Promise<CommitCellsResult>) | null>(null);

	const commitCells = useCallback(
		async (writes: CellWrite[], opts?: CommitCellsOptions): Promise<CommitCellsResult> => {
			if (!writes.length) return { applied: 0 };

			const resolved: ResolvedWrite[] = [];
			const draftWrites: CellWrite[] = [];

			for (const w of writes) {
				const rowData = combinedRows[w.rowIndex] as Record<string, unknown> | null | undefined;
				// Null-guard unfetched proxy rows — skip writes whose row is not loaded.
				if (!rowData) continue;

				// Draft rows keep their existing per-cell path; excluded from coalescing + history.
				if (getDraftMeta(rowData)) {
					draftWrites.push(w);
					continue;
				}

				if (!canUpdate) continue;
				const resolution = resolveServerPatch(w.colKey, w.value, fieldMetaMap, relationInfoByField, readOnlyFields);
				if (resolution.kind === 'noop') continue;
				const rowIdentifier = getRowIdentifier(rowData);
				if (rowIdentifier === null) continue;

				resolved.push({
					rowIndex: w.rowIndex,
					rowId: rowIdentifier,
					field: resolution.field,
					value: resolution.value,
					// Capture the PRIOR value of the patched field BEFORE any optimistic patch.
					prior: rowData[resolution.field],
				});
			}

			// Fire draft writes through the existing path (not batched, not recorded).
			for (const dw of draftWrites) {
				// eslint-disable-next-line no-await-in-loop
				await editCell(dw.rowIndex, dw.colKey, dw.value);
			}

			if (!resolved.length) return { applied: 0 };

			// Group by row: one merged optimistic patch + one merged server PATCH per row.
			const byRow = new Map<number, ResolvedWrite[]>();
			for (const r of resolved) {
				const list = byRow.get(r.rowIndex);
				if (list) list.push(r);
				else byRow.set(r.rowIndex, [r]);
			}

			// Apply ONE optimistic patch per row (merged) and collect revert thunks.
			const reverts: Array<() => void> = [];
			for (const [rowIndex, group] of byRow) {
				const patch: Record<string, unknown> = {};
				for (const r of group) patch[r.field] = r.value;
				const revert = applyOptimisticPatch?.(rowIndex, patch);
				if (revert) reverts.push(revert);
			}

			// Issue ONE server mutation per row; revert ALL optimistic patches on first failure.
			try {
				for (const [rowIndex, group] of byRow) {
					const patch: Record<string, unknown> = {};
					for (const r of group) patch[r.field] = r.value;
					// eslint-disable-next-line no-await-in-loop
					const result = await update(group[0].rowId, patch);
					if (result?.updatedRow) resyncRow?.(rowIndex, result.updatedRow);
					for (const r of group) onCellEdit?.(r.rowId, r.field, r.value);
				}
			} catch (error) {
				for (const revert of reverts) revert();
				throw error;
			}

			// Record the inverse (prior values) so undo restores the exact pre-edit state.
			if (opts?.record !== false) {
				const priorWrites: CellWrite[] = resolved.map((r) => ({
					rowIndex: r.rowIndex,
					colKey: r.field,
					value: r.prior,
				}));
				const redoWrites: CellWrite[] = resolved.map((r) => ({
					rowIndex: r.rowIndex,
					colKey: r.field,
					value: r.value,
				}));
				// Capture the live commit fn via the closure below (commitRef).
				record({
					label: resolved.length > 1 ? `Edit ${resolved.length} cells` : 'Edit cell',
					undo: () => void commitRef.current?.(priorWrites, { record: false }),
					redo: () => void commitRef.current?.(redoWrites, { record: false }),
				});
			}

			return { applied: resolved.length };
		},
		[combinedRows, fieldMetaMap, relationInfoByField, update, getRowIdentifier, readOnlyFields, canUpdate, applyOptimisticPatch, resyncRow, editCell, onCellEdit, record],
	);

	commitRef.current = commitCells;
	return commitCells;
}

import { useCallback } from 'react';

import { DRAFT_ACTION_COLUMN_KEY } from '../sheets.constants';
import { prepareDraftRelationValue } from '../sheets.utils';
import type { DraftRowsState } from './use-draft-rows';
import { getDraftMeta } from '../row-model';
import type { SheetsRowIdentifier } from '../../row-identity';

/** Result from the useCellEditing hook */
export interface CellEditingResult {
	/** Type of edit: 'draft' for local draft row, 'server' for server mutation, 'noop' for no action */
	type: 'draft' | 'server' | 'noop';
	/** The updated row data from the server (only for 'server' type) */
	updatedRow?: Record<string, unknown> | null;
	/** The field that was patched (only for 'server' type) */
	patchField?: string;
	/** The value that was sent (only for 'server' type) */
	patchValue?: unknown;
}

interface UseCellEditingParams {
	combinedRows: any[];
	fieldMetaMap: Map<string, any>;
	relationInfoByField: Map<string, any>;
	updateDraftCell: DraftRowsState['updateDraftCell'];
	tableKey: string;
	update: (id: SheetsRowIdentifier, data: Record<string, unknown>) => Promise<{ updatedRow?: Record<string, unknown> | null }>;
	getRowIdentifier?: (row: Readonly<Record<string, unknown>>) => SheetsRowIdentifier | null;
	readOnlyFields?: ReadonlySet<string>;
	canUpdate?: boolean;
	onCellEdit?: (id: SheetsRowIdentifier, field: string, value: unknown) => void;
	/**
	 * Optimistic server-row cache patch. Applied to the local (infinite) cache BEFORE
	 * the `update` round-trip so the cell flips instantly; returns a revert thunk that
	 * the hook calls if `update` rejects. Omitted (e.g. paginated mode / unit tests) =>
	 * no pre-await patch and the consumer reconciles after the await as before.
	 */
	applyOptimisticPatch?: (rowIndex: number, patch: Record<string, unknown>) => (() => void) | void;
}

function legacyRowIdentifier(row: Readonly<Record<string, unknown>>): SheetsRowIdentifier | null {
	return typeof row.id === 'string' || typeof row.id === 'number' ? row.id : null;
}

/**
 * Normalize a relation value for a server PATCH: a JSON string is parsed, an array
 * is mapped to its ids (single id for belongsTo/hasOne, list otherwise), a single
 * object to its id. Mirrors the relation branch the canvas `handleCellEdit` ran,
 * but on the RAW native value instead of an extracted glide cell.
 */
export function normalizeRelationPatchValue(rawValue: unknown, relationKind: string | undefined): unknown {
	let value = rawValue;

	if (typeof value === 'string') {
		const trimmed = value.trim();
		if (trimmed === '') {
			value = null;
		} else {
			try {
				value = JSON.parse(trimmed);
			} catch {
				value = trimmed;
			}
		}
	}

	if (Array.isArray(value)) {
		const mapped = value
			.map((entry) => (entry && typeof entry === 'object' ? ((entry as any).id ?? entry) : entry))
			.filter((entry) => entry !== undefined && entry !== null);
		value = relationKind === 'belongsTo' || relationKind === 'hasOne' ? (mapped[0] ?? null) : mapped;
	} else if (value && typeof value === 'object') {
		value = (value as any).id ?? null;
	}

	if (value === '') value = null;
	return value;
}

/** The resolved server PATCH for one cell write, or a reason it is a no-op. */
export type ServerPatchResolution =
	| { kind: 'patch'; field: string; value: unknown }
	| { kind: 'noop' };

/**
 * Derive the single-field server PATCH for a server-row cell write — the ONE place
 * that owns server-row coercion + readonly guards (UUID id / relation-not-inline /
 * undefined). Shared by `useCellEditing` (single cell) and the batched `commitCells`
 * (paste/fill/bulk) so neither forks the rules. PURE; never touches the cache or
 * network. `rowData` is the target row (skip callers must null-guard before calling).
 */
export function resolveServerPatch(
	colKey: string,
	rawValue: unknown,
	fieldMetaMap: Map<string, any>,
	relationInfoByField: Map<string, any>,
	readOnlyFields?: ReadonlySet<string>,
): ServerPatchResolution {
	if (!colKey || colKey === DRAFT_ACTION_COLUMN_KEY) return { kind: 'noop' };
	if (readOnlyFields?.has(colKey)) return { kind: 'noop' };

	// Block edits to the UUID primary key id.
	const metaField = fieldMetaMap.get(colKey);
	if (colKey === 'id' && metaField?.type?.gqlType === 'UUID') return { kind: 'noop' };

	const relationInfo = relationInfoByField.get(colKey);
	let value: unknown = rawValue;

	if (relationInfo) {
		const patchFieldCandidate = relationInfo.foreignKeyField || colKey;
		const canEditRelationInline = relationInfo.kind === 'belongsTo' && fieldMetaMap.has(patchFieldCandidate);
		if (!canEditRelationInline) return { kind: 'noop' };
		value = normalizeRelationPatchValue(rawValue, relationInfo.kind);
	}

	if (value === undefined) return { kind: 'noop' };

	const field = relationInfo?.foreignKeyField || colKey;
	return { kind: 'patch', field, value };
}

export function useCellEditing({
	combinedRows,
	fieldMetaMap,
	relationInfoByField,
	updateDraftCell,
	tableKey,
	update,
	getRowIdentifier = legacyRowIdentifier,
	readOnlyFields,
	canUpdate = true,
	onCellEdit,
	applyOptimisticPatch,
}: UseCellEditingParams) {
	return useCallback(
		// NATIVE signature: the DOM editors / inline-toggle pass a raw value that flows
		// straight through — no glide cell round-trip. This is what fixes the boolean
		// toggle: a raw `false` persists as `false`, never stringified to "false".
		async (rowIndex: number, colKey: string, rawValue: unknown): Promise<CellEditingResult> => {
			const rowData = combinedRows[rowIndex];
			if (!colKey || !rowData) return { type: 'noop' };

			if (colKey === DRAFT_ACTION_COLUMN_KEY) {
				return { type: 'noop' };
			}

			const draftMeta = getDraftMeta(rowData);
			if (draftMeta?.isDraft && colKey === 'id') {
				return { type: 'noop' };
			}

			if (draftMeta?.isDraft) {
				const draftRowId: string | undefined = draftMeta.draftRowId;
				if (!draftRowId) return { type: 'noop' };

				const baseValue = rawValue;
				const relationInfo = relationInfoByField.get(colKey);

				let storedValue: unknown = baseValue;
				let extraValues: Record<string, unknown> | undefined;

				if (relationInfo) {
					const { relationData, foreignKeyUpdates, relationReferences } = prepareDraftRelationValue(
						baseValue,
						relationInfo,
					);
					const relationFieldKey = relationInfo.relationField;
					const foreignKeyFieldKey = relationInfo.foreignKeyField;
					const editingRelationField = relationFieldKey ? relationFieldKey === colKey : false;
					const editingForeignKeyField = foreignKeyFieldKey ? foreignKeyFieldKey === colKey : false;

					const processedRelationData = Array.isArray(relationData)
						? relationData.filter((entry) => entry !== undefined)
						: relationData;

					const relationExtra = relationFieldKey
						? processedRelationData === undefined
							? undefined
							: processedRelationData === null
								? { [relationFieldKey]: null }
								: typeof processedRelationData === 'object'
									? { [relationFieldKey]: processedRelationData }
									: undefined
						: undefined;

					const processedReferenceValue = Array.isArray(relationReferences)
						? relationReferences.filter((entry) => entry !== undefined)
						: relationReferences;

					const foreignKeyExtra = foreignKeyFieldKey
						? processedReferenceValue !== undefined
							? { [foreignKeyFieldKey]: processedReferenceValue }
							: undefined
						: undefined;

					if (editingRelationField) {
						storedValue = processedRelationData;
						extraValues = {
							...(foreignKeyUpdates ?? {}),
						};
					} else if (editingForeignKeyField) {
						storedValue = processedReferenceValue ?? processedRelationData;
						extraValues = {
							...(foreignKeyUpdates ?? {}),
							...(relationExtra ?? {}),
						};
					} else {
						storedValue = processedRelationData;
						extraValues = {
							...(foreignKeyUpdates ?? {}),
							...(relationExtra ?? {}),
							...(foreignKeyExtra ?? {}),
						};
					}
				}

				updateDraftCell({
					tableKey,
					draftRowId,
					columnKey: colKey,
					value: storedValue,
					extraValues: extraValues && Object.keys(extraValues).length > 0 ? extraValues : undefined,
				});
				return { type: 'draft' };
			}

			// Server row edit — derive the PATCH via the shared resolver (the single owner
			// of server-row coercion + readonly guards, also used by batched `commitCells`).
			if (!canUpdate) return { type: 'noop' };
			const resolution = resolveServerPatch(colKey, rawValue, fieldMetaMap, relationInfoByField, readOnlyFields);
			if (resolution.kind === 'noop') return { type: 'noop' };
			const { field: patchField, value } = resolution;
			const rowIdentifier = getRowIdentifier(rowData);
			if (rowIdentifier === null) return { type: 'noop' };

			// Optimistic: patch the local cache with the new value BEFORE awaiting the
			// server so the cell updates instantly. `applyOptimisticPatch` returns a revert
			// thunk (snapshot of the prior value) which we replay only if `update` rejects.
			const revertOptimisticPatch = applyOptimisticPatch?.(rowIndex, { [patchField]: value });

			let result: { updatedRow?: Record<string, unknown> | null };
			try {
				result = await update(rowIdentifier, { [patchField]: value });
			} catch (error) {
				if (typeof revertOptimisticPatch === 'function') revertOptimisticPatch();
				throw error;
			}
			onCellEdit?.(rowIdentifier, patchField, value);

			return {
				type: 'server',
				updatedRow: result?.updatedRow ?? null,
				patchField,
				patchValue: value,
			};
		},
		[combinedRows, fieldMetaMap, relationInfoByField, tableKey, update, getRowIdentifier, readOnlyFields, canUpdate, onCellEdit, updateDraftCell, applyOptimisticPatch],
	);
}

import { useMemo } from 'react';

import { useSheetsStore } from '../../store/sheets-store';
import type { DraftRow, DraftRowsSlice } from '../../store/draft-rows-slice';
import { attachDraftMeta, isDraftRow } from '../row-model';

interface DraftRowsTableState {
	order: string[];
	map: Record<string, DraftRow>;
	template: Record<string, unknown>;
	metaVersion: string;
	columnOrder: string[];
}

interface UseDraftRowsParams {
	tableKey: string;
	serverRows: any[];
	hasCompletedInitialLoad: boolean;
}

export interface DraftRowsState {
	draftRowsTable?: DraftRowsTableState;
	draftRows: DraftRow[];
	hasDraftRows: boolean;
	combinedRows: any[];
	draftRowIndices: number[];
	createDraftRow: DraftRowsSlice['createDraftRow'];
	updateDraftCell: DraftRowsSlice['updateDraftCell'];
	removeDraftRow: DraftRowsSlice['removeDraftRow'];
	syncDraftRowsWithMeta: DraftRowsSlice['syncDraftRowsWithMeta'];
	setDraftRowStatus: DraftRowsSlice['setDraftRowStatus'];
}

export function useDraftRows({
	tableKey,
	serverRows,
	hasCompletedInitialLoad,
}: UseDraftRowsParams): DraftRowsState {
	const draftRowsTable = useSheetsStore(
		(state) => state.draftRowsByTable[tableKey] as DraftRowsTableState | undefined,
	);
	const createDraftRow = useSheetsStore((state) => state.createDraftRow);
	const updateDraftCell = useSheetsStore((state) => state.updateDraftCell);
	const removeDraftRow = useSheetsStore((state) => state.removeDraftRow);
	const syncDraftRowsWithMeta = useSheetsStore((state) => state.syncDraftRowsWithMeta);
	const setDraftRowStatus = useSheetsStore((state) => state.setDraftRowStatus);

	const draftRows = useMemo(() => {
		if (!draftRowsTable) return [] as DraftRow[];
		return draftRowsTable.order.map((id) => draftRowsTable.map[id]).filter((row): row is DraftRow => Boolean(row));
	}, [draftRowsTable]);

	const mayShowDrafts = hasCompletedInitialLoad || serverRows.length > 0 || draftRows.length > 0;

	const combinedRows = useMemo(() => {
		if (!draftRows.length || !mayShowDrafts) return serverRows as any[];

		const draftDataRows = draftRows.map((draft) => {
			const row = { ...draft.values } as Record<string, unknown>;
			return attachDraftMeta(row, {
				isDraft: true,
				draftRowId: draft.id,
				status: draft.status,
				errors: draft.errors,
			});
		});

		return [...(serverRows as any[]), ...draftDataRows];
	}, [serverRows, draftRows, mayShowDrafts]);

	const draftRowIndices = useMemo(() => {
		const indices: number[] = [];
		combinedRows.forEach((row, index) => {
			if (isDraftRow(row)) {
				indices.push(index);
			}
		});
		return indices;
	}, [combinedRows]);

	const hasDraftRows = draftRows.length > 0 && mayShowDrafts;

	return {
		draftRowsTable,
		draftRows,
		hasDraftRows,
		combinedRows,
		draftRowIndices,
		createDraftRow,
		updateDraftCell,
		removeDraftRow,
		syncDraftRowsWithMeta,
		setDraftRowStatus,
	};
}

import { useCallback, useMemo, useState } from 'react';

import type { RelationInfo } from '../../store/relation-info-slice';
import type { DraftRow } from '../../store/draft-rows-slice';
import { SHEETS_CONCURRENCY } from '../../config/sheets-concurrency';

import { prepareDraftSubmissionPayload, validateDraftRowRequiredFields, type DraftValidationFieldMeta } from '../sheets.utils';
import type { DraftSubmitResult } from '../draft-types';
import type { DraftRowEntry } from './use-grid-selection';
import { sheetsLogger } from '../../utils/sheets-logger';

interface DraftRowsTableState {
	order: string[];
	map: Record<string, DraftRow>;
	template: Record<string, unknown>;
	metaVersion: string;
	columnOrder: string[];
}

interface OperationFeedbackCallbacks {
	onStart?: (type: 'submit', total: number) => string;
	onProgress?: (id: string, completed: number, failed: number) => void;
	onComplete?: (id: string, status: 'success' | 'partial' | 'error', message: string) => void;
}

interface UseDraftSubmissionParams {
	tableKey: string;
	draftRowsTable?: DraftRowsTableState;
	selectedDraftRowEntries: DraftRowEntry[];
	hasDraftSelection: boolean;
	create: (data: Record<string, unknown>) => Promise<{ createdRow?: Record<string, unknown> | null }>;
	removeDraftRow: (tableKey: string, draftRowId: string) => void;
	setDraftRowStatus: (args: {
		tableKey: string;
		draftRowId: string;
		status: DraftRow['status'];
		errors?: Record<string, string> | null;
	}) => void;
	clearSelection: () => void;
	allowedColumns?: ReadonlySet<string>;
	relationInfoByKey?: Record<string, RelationInfo | undefined>;
	fieldMetaByKey?: Record<string, DraftValidationFieldMeta | undefined>;
	onSubmittedSuccessfully?: (result: { success: number; failed: number }) => void;
	/** Feedback callbacks for inline status indicators */
	feedback?: OperationFeedbackCallbacks;
}

export function useDraftSubmission({
	tableKey,
	draftRowsTable,
	selectedDraftRowEntries,
	hasDraftSelection,
	create,
	removeDraftRow,
	setDraftRowStatus,
	clearSelection,
	allowedColumns,
	relationInfoByKey,
	fieldMetaByKey,
	onSubmittedSuccessfully,
	feedback,
}: UseDraftSubmissionParams) {
	const [isSubmittingDrafts, setIsSubmittingDrafts] = useState(false);

	const submitDraftEntries = useCallback(
		async (entries: DraftRowEntry[], operationId?: string): Promise<{ success: number; failed: number }> => {
			if (!entries.length) {
				return { success: 0, failed: 0 };
			}

			setIsSubmittingDrafts(true);

			const submissionResults = {
				success: 0,
				failed: 0,
			};

			try {
				let nextEntryIndex = 0;
				const workerCount = Math.min(SHEETS_CONCURRENCY.draftSubmit, entries.length);

				const runSubmitWorker = async () => {
					while (nextEntryIndex < entries.length) {
						const currentIndex = nextEntryIndex;
						nextEntryIndex += 1;
						const { draftRowId, draftRow } = entries[currentIndex];

						// Pre-validate required fields before sending to server
						if (fieldMetaByKey) {
							const validationErrors = validateDraftRowRequiredFields(
								draftRow.values,
								fieldMetaByKey,
								{ allowedColumns, relationInfoByKey },
							);
							if (Object.keys(validationErrors).length > 0) {
								submissionResults.failed += 1;
								setDraftRowStatus({ tableKey, draftRowId, status: 'error', errors: validationErrors });
								if (operationId) {
									feedback?.onProgress?.(operationId, submissionResults.success, submissionResults.failed);
								}
								continue;
							}
						}

						setDraftRowStatus({ tableKey, draftRowId, status: 'saving', errors: null });
						const payload = prepareDraftSubmissionPayload(draftRow.values, {
							allowedColumns,
							relationInfoByKey,
						});

						try {
							await create(payload);
							removeDraftRow(tableKey, draftRowId);
							submissionResults.success += 1;
						} catch (error) {
							submissionResults.failed += 1;
							const message = error instanceof Error ? error.message : 'Failed to submit draft row';
							sheetsLogger().error('submitDraftRow failed', error);
							setDraftRowStatus({ tableKey, draftRowId, status: 'error', errors: { submit: message } });
						}

						if (operationId) {
							feedback?.onProgress?.(
								operationId,
								submissionResults.success,
								submissionResults.failed,
							);
						}
					}
				};

				await Promise.all(Array.from({ length: workerCount }, () => runSubmitWorker()));
			} finally {
				setIsSubmittingDrafts(false);
			}

			if (submissionResults.success > 0) {
				onSubmittedSuccessfully?.(submissionResults);
			}

			return submissionResults;
		},
		[
			allowedColumns,
			relationInfoByKey,
			fieldMetaByKey,
			create,
			removeDraftRow,
			setDraftRowStatus,
			tableKey,
			feedback,
			onSubmittedSuccessfully,
		],
	);

	const handleSubmitDraftRows = useCallback(async () => {
		if (!draftRowsTable || !hasDraftSelection) {
			return;
		}

		const total = selectedDraftRowEntries.length;
		const operationId = feedback?.onStart?.('submit', total);

		const submissionResults = await submitDraftEntries(selectedDraftRowEntries, operationId);

		if (operationId) {
			const { success, failed } = submissionResults;
			if (failed === 0 && success > 0) {
				feedback?.onComplete?.(
					operationId,
					'success',
					`Submitted ${success} ${success === 1 ? 'row' : 'rows'}`,
				);
			} else if (success > 0 && failed > 0) {
				feedback?.onComplete?.(
					operationId,
					'partial',
					`Submitted ${success}, ${failed} failed`,
				);
			} else if (failed > 0) {
				feedback?.onComplete?.(
					operationId,
					'error',
					`Failed to submit ${failed} ${failed === 1 ? 'row' : 'rows'}`,
				);
			}
		}

		if (submissionResults.success > 0) {
			clearSelection();
		}
	}, [draftRowsTable, hasDraftSelection, selectedDraftRowEntries, submitDraftEntries, clearSelection, feedback]);

	const handleSubmitSingleDraftRow = useCallback(
		async (draftRowId: string) => {
			if (!draftRowsTable) {
				return;
			}

			const draftRow = draftRowsTable.map[draftRowId];
			if (!draftRow) {
				return;
			}

			// Single row submission - no operation feedback, rely on row status indicator
			await submitDraftEntries([{ draftRowId, draftRow }]);
		},
		[draftRowsTable, submitDraftEntries],
	);

	const submitDraftLabel = useMemo(() => {
		if (!hasDraftSelection) {
			return 'Submit draft rows';
		}
		const count = selectedDraftRowEntries.length;
		return `Submit ${count} draft ${count === 1 ? 'row' : 'rows'}`;
	}, [hasDraftSelection, selectedDraftRowEntries.length]);

	const submitDraftButtonDisabled = isSubmittingDrafts || !hasDraftSelection;

	/**
	 * Submit a single draft row for editor workflows (e.g., ImageEditor upload).
	 * Returns the created row with real database ID for subsequent operations.
	 *
	 * NOTE: This does NOT call onSingleRowSubmitted - the editor is responsible
	 * for triggering data refresh after any follow-up operations (like upload)
	 * are complete. This prevents premature cache invalidation.
	 */
	const submitDraftRowForEditor = useCallback(
		async (draftRowId: string): Promise<DraftSubmitResult> => {
			if (!draftRowsTable) {
				return { createdRow: null };
			}

			const draftRow = draftRowsTable.map[draftRowId];
			if (!draftRow) {
				return { createdRow: null };
			}

			try {
				setDraftRowStatus({ tableKey, draftRowId, status: 'saving', errors: null });

				const payload = prepareDraftSubmissionPayload(draftRow.values, {
					allowedColumns,
					relationInfoByKey,
				});

				const result = await create(payload);
				const createdRow = result?.createdRow ?? null;

				if (createdRow) {
					removeDraftRow(tableKey, draftRowId);
					// NOTE: Don't call onSingleRowSubmitted here - let the editor
					// trigger refresh after follow-up operations complete
				}

				return { createdRow };
			} catch (error) {
				const message = error instanceof Error ? error.message : 'Failed to create row';
				setDraftRowStatus({ tableKey, draftRowId, status: 'error', errors: { submit: message } });
				throw error;
			}
		},
		[draftRowsTable, setDraftRowStatus, tableKey, allowedColumns, relationInfoByKey, create, removeDraftRow],
	);

	return {
		isSubmittingDrafts,
		submitDraftButtonDisabled,
		submitDraftLabel,
		handleSubmitDraftRows,
		handleSubmitSingleDraftRow,
		submitDraftRowForEditor,
	};
}

import { useCallback, useMemo, useState } from 'react';
import type { ReactNode } from 'react';

import { isValuelessOperator } from '../filter-operators';
import {
	createEmptyGroup,
	type FilterGroup,
	type FilterNode,
} from '../sheets.controls';
import { buildWhereFromFilters } from '../sheets.utils';

// Data filtering context type
export interface DataFilteringContextValue {
	filterTree: FilterGroup;
	filtersOpen: boolean;
	effectiveWhere: any;
	hasActiveFilters: boolean;
	setFilterTree: (tree: FilterGroup) => void;
	setFiltersOpen: (open: boolean) => void;
	clearAllFilters: () => void;
	applyFilters: () => void;
}

// Data filtering hook configuration
export interface UseDataFilteringConfig {
	columnKeys: string[];
	tableMeta?: {
		fields?: Array<{
			name?: string | null;
			type?: {
				gqlType?: string | null;
			} | null;
		} | null> | null;
	} | null;
	initialFilterTree?: FilterGroup;
}

function hasActiveNode(node: FilterNode): boolean {
	if (node.type === 'condition') {
		return isValuelessOperator(node.operator) ||
			(node.value !== '' && node.value !== null && node.value !== undefined);
	}
	return node.children.some(hasActiveNode);
}

// Main data filtering hook — uses local state instead of global Zustand store
export function useDataFiltering({
	columnKeys,
	tableMeta,
	initialFilterTree,
}: UseDataFilteringConfig) {
	const [filterTree, setFilterTree] = useState<FilterGroup>(initialFilterTree ?? createEmptyGroup());
	const [filtersOpen, setFiltersOpen] = useState(false);

	const clearAllFilters = useCallback(() => {
		setFilterTree(createEmptyGroup());
	}, []);

	// applyFilters is a no-op since state is already reactive
	const applyFilters = useCallback(() => {}, []);

	// Compute effective where clause from current filters
	const effectiveWhere = useMemo(
		() => buildWhereFromFilters(filterTree, tableMeta),
		[filterTree, tableMeta],
	);

	// Check if there are active filters
	const hasActiveFilters = useMemo(
		() => hasActiveNode(filterTree),
		[filterTree],
	);

	const contextValue: DataFilteringContextValue = useMemo(
		() => ({
			filterTree,
			filtersOpen,
			effectiveWhere,
			hasActiveFilters,
			setFilterTree,
			setFiltersOpen,
			clearAllFilters,
			applyFilters,
		}),
		[filterTree, filtersOpen, effectiveWhere, hasActiveFilters, clearAllFilters, applyFilters],
	);

	return {
		contextValue,
		Provider: ({ children }: { children: ReactNode }) => children,
	};
}

import { useCallback } from 'react';

import type { SheetsSelection } from '../../selection/selection-model';
import { SHEETS_CONCURRENCY } from '../../config/sheets-concurrency';
import { sheetsLogger } from '../../utils/sheets-logger';
import { getDraftMeta } from '../row-model';
import type { SheetsRowIdentifier } from '../../row-identity';

interface OperationFeedbackCallbacks {
	onStart?: (type: 'delete', total: number) => string;
	onProgress?: (id: string, completed: number, failed: number) => void;
	onComplete?: (id: string, status: 'success' | 'partial' | 'error', message: string) => void;
}

type DeleteOutcome = { status: 'success' | 'partial' | 'error'; message: string } | null;

/**
 * Build the completion toast for a bulk delete, distinguishing UNSAVED draft rows
 * (discarded client-side, nothing hit the server) from real server-row deletes.
 *
 * `drafts` = draft rows discarded, `deleted` = server rows deleted, `failed` =
 * server deletes that errored. All-success wording reflects reality:
 *   - only drafts  -> "Discarded N draft(s)"
 *   - only server  -> "Deleted N row(s)"  (unchanged)
 *   - mixed        -> "Deleted N rows, discarded M drafts"
 * The partial/error (failure) wording is unchanged from prior behavior.
 */
export function summarizeDeleteResult(drafts: number, deleted: number, failed: number): DeleteOutcome {
	const successes = drafts + deleted;

	if (failed === 0 && successes > 0) {
		let message: string;
		if (deleted === 0) {
			message = `Discarded ${drafts} draft${drafts === 1 ? '' : 's'}`;
		} else if (drafts === 0) {
			message = `Deleted ${deleted} ${deleted === 1 ? 'row' : 'rows'}`;
		} else {
			message = `Deleted ${deleted} ${deleted === 1 ? 'row' : 'rows'}, discarded ${drafts} draft${drafts === 1 ? '' : 's'}`;
		}
		return { status: 'success', message };
	}

	if (successes > 0 && failed > 0) {
		return { status: 'partial', message: `Deleted ${successes}, ${failed} failed` };
	}

	if (failed > 0) {
		return { status: 'error', message: `Failed to delete ${failed} ${failed === 1 ? 'row' : 'rows'}` };
	}

	return null;
}

export function useGridOperations(
	data: any[],
	deleteRow: (id: SheetsRowIdentifier) => Promise<any>,
	gridSelection: SheetsSelection | undefined,
	clearSelection: () => void,
	options?: {
		onRemoveDraftRow?: (draftRowId: string) => void;
		onAfterServerDeletes?: () => void;
		getRowIdentifier?: (row: Readonly<Record<string, unknown>>) => SheetsRowIdentifier | null;
		canDeleteServerRows?: boolean;
		feedback?: OperationFeedbackCallbacks;
	},
) {
	const deleteSelected = useCallback(async () => {
		if (!gridSelection) return;

		const rows = gridSelection.rows.toArray();
		if (rows.length === 0) return;

			// Start operation feedback
			const operationId = options?.feedback?.onStart?.('delete', rows.length);

			let successes = 0;
			let failures = 0;
			let serverSuccesses = 0;
			let draftDiscards = 0;
			const records = rows.map((idx) => data[idx]);
			let nextRecordIndex = 0;
			const workerCount = Math.min(SHEETS_CONCURRENCY.bulkDelete, records.length);

			const runDeleteWorker = async () => {
				while (nextRecordIndex < records.length) {
					const currentIndex = nextRecordIndex;
					nextRecordIndex += 1;
					const record = records[currentIndex];

					const draftMeta = getDraftMeta(record);
					if (draftMeta?.isDraft && options?.onRemoveDraftRow) {
						const draftRowId = draftMeta.draftRowId;
						if (draftRowId) {
							options.onRemoveDraftRow(draftRowId);
							successes += 1;
							draftDiscards += 1;
						} else {
							failures += 1;
						}
					} else if (options?.canDeleteServerRows !== false) {
						const identifier = options?.getRowIdentifier
							? options.getRowIdentifier(record)
							: typeof record?.id === 'string' || typeof record?.id === 'number'
								? record.id
								: null;
						if (identifier === null) {
							failures += 1;
							continue;
						}
						try {
							await deleteRow(identifier);
							successes += 1;
							serverSuccesses += 1;
						} catch (error) {
							sheetsLogger().error('Failed to delete record', { identifier, error });
							failures += 1;
						}
					} else {
						failures += 1;
					}

					if (operationId) {
						options?.feedback?.onProgress?.(operationId, successes, failures);
					}
				}
			};

			await Promise.all(Array.from({ length: workerCount }, () => runDeleteWorker()));

			// Complete operation feedback — distinguish discarded drafts from server deletes.
			if (operationId) {
				const outcome = summarizeDeleteResult(draftDiscards, serverSuccesses, failures);
				if (outcome) {
					options?.feedback?.onComplete?.(operationId, outcome.status, outcome.message);
				}
			}

		if (serverSuccesses > 0) {
			options?.onAfterServerDeletes?.();
		}

		// Always clear selection so indices don't point to new rows after deletion
		clearSelection();
	}, [gridSelection, data, deleteRow, clearSelection, options]);

	return {
		deleteSelected,
	};
}

import { useMemo } from 'react';

import type { SheetsSelection } from '../../selection/selection-model';
import type { DraftRow } from '../../store/draft-rows-slice';
import { getDraftMeta, type DraftMeta } from '../row-model';

interface DraftRowsTableState {
	order: string[];
	map: Record<string, DraftRow>;
	template: Record<string, unknown>;
	metaVersion: string;
	columnOrder: string[];
}

export interface DraftRowEntry {
	draftRowId: string;
	draftRow: DraftRow;
}

interface UseGridSelectionStateParams {
	gridSelection: SheetsSelection | undefined;
	combinedRows: any[];
	draftRowsTable?: DraftRowsTableState;
}

export function useGridSelectionState({ gridSelection, combinedRows, draftRowsTable }: UseGridSelectionStateParams) {
	const selectedRowIndices = useMemo(() => {
		if (!gridSelection) return [] as number[];
		return gridSelection.rows.toArray();
	}, [gridSelection]);

	const selectedRowCount = selectedRowIndices.length;

	const selectedDraftRowEntries = useMemo(() => {
		if (!draftRowsTable || selectedRowIndices.length === 0) return [] as DraftRowEntry[];

		return selectedRowIndices
			.map((rowIndex) => getDraftMeta(combinedRows[rowIndex]))
			.filter((meta): meta is DraftMeta => Boolean(meta?.draftRowId))
			.map((meta) => {
				const draftRow = draftRowsTable.map[meta.draftRowId];
				return draftRow ? { draftRowId: meta.draftRowId, draftRow } : null;
			})
			.filter((entry): entry is DraftRowEntry => entry !== null);
	}, [draftRowsTable, selectedRowIndices, combinedRows]);

	const hasDraftSelection = selectedDraftRowEntries.length > 0;

	return {
		selectedRowIndices,
		selectedRowCount,
		selectedDraftRowEntries,
		hasDraftSelection,
	};
}

import { useCallback, useMemo, useReducer } from 'react';

import { emptySheetsSelection, moveActive, selectCell } from '../../selection/selection-model';
import type { SheetsSelection } from '../../selection/selection-model';
import type { FilterGroup } from '../sheets.controls';

// Centralized grid state interface
export interface GridState {
	// Sorting state
	sorting: {
		id: string | null;
		desc: boolean;
	};

	// Pagination state
	pageIndex: number;

	// Filter states
	filterTree: FilterGroup;
	filtersOpen: boolean;

	// Column state
	columnWidths: Map<string, number>;

	// Selection state (native SheetsSelection — glide is only a derived projection now).
	// Field name kept as `gridSelection` to minimize consumer churn during the port.
	gridSelection: SheetsSelection | undefined;
}

const EMPTY_FILTER_TREE: FilterGroup = { type: 'group', id: 'root', conjunction: 'and', children: [] };

// Action types for state updates
export type GridAction =
	| { type: 'SET_SORTING'; payload: GridState['sorting'] }
	| { type: 'TOGGLE_SORTING'; payload: string }
	| { type: 'SET_PAGE_INDEX'; payload: number }
	| { type: 'SET_FILTER_TREE'; payload: FilterGroup }
	| { type: 'CLEAR_ALL_FILTERS' }
	| { type: 'TOGGLE_FILTERS_PANEL' }
	| { type: 'SET_FILTERS_OPEN'; payload: boolean }
	| { type: 'RESIZE_COLUMN'; payload: { id: string; width: number } }
	| { type: 'SET_GRID_SELECTION'; payload: SheetsSelection | undefined }
	| { type: 'SET_ACTIVE_CELL'; payload: { col: number; row: number } }
	| { type: 'MOVE_ACTIVE'; payload: { dCol: number; dRow: number; colCount: number; rowCount: number } }
	| { type: 'RESET_PAGE_IF_NEEDED'; payload: { totalPages: number } };

// Initial state factory
function createInitialGridState(): GridState {
	return {
		sorting: { id: null, desc: false },
		pageIndex: 0,
		filterTree: { ...EMPTY_FILTER_TREE },
		filtersOpen: false,
		columnWidths: new Map(),
		gridSelection: undefined,
	};
}

// State reducer with type-safe action handling
function gridStateReducer(state: GridState, action: GridAction): GridState {
	switch (action.type) {
		case 'SET_SORTING':
			return {
				...state,
				sorting: action.payload,
			};

		case 'TOGGLE_SORTING': {
			const colId = action.payload;
			let newSorting: GridState['sorting'];

			if (state.sorting.id !== colId) {
				// Different column clicked: start with ASC
				newSorting = { id: colId, desc: false };
			} else if (!state.sorting.desc) {
				// Same column, currently ASC: switch to DESC
				newSorting = { id: colId, desc: true };
			} else {
				// Same column, currently DESC: reset to neutral (no sorting)
				newSorting = { id: null, desc: false };
			}

			return {
				...state,
				sorting: newSorting,
			};
		}

		case 'SET_PAGE_INDEX':
			return {
				...state,
				pageIndex: action.payload,
			};

		case 'SET_FILTER_TREE':
			return {
				...state,
				filterTree: action.payload,
			};

		case 'CLEAR_ALL_FILTERS':
			return {
				...state,
				filterTree: { ...EMPTY_FILTER_TREE },
			};

		case 'TOGGLE_FILTERS_PANEL':
			return {
				...state,
				filtersOpen: !state.filtersOpen,
			};

		case 'SET_FILTERS_OPEN':
			return {
				...state,
				filtersOpen: action.payload,
			};

		case 'RESIZE_COLUMN': {
			const newColumnWidths = new Map(state.columnWidths);
			newColumnWidths.set(action.payload.id, action.payload.width);
			return {
				...state,
				columnWidths: newColumnWidths,
			};
		}

		case 'SET_GRID_SELECTION':
			return {
				...state,
				gridSelection: action.payload,
			};

		case 'SET_ACTIVE_CELL': {
			const { col, row } = action.payload;
			return {
				...state,
				gridSelection: selectCell(state.gridSelection ?? emptySheetsSelection, col, row),
			};
		}

		case 'MOVE_ACTIVE': {
			const { dCol, dRow, colCount, rowCount } = action.payload;
			return {
				...state,
				gridSelection: moveActive(state.gridSelection ?? emptySheetsSelection, dCol, dRow, colCount, rowCount),
			};
		}

		case 'RESET_PAGE_IF_NEEDED': {
			const { totalPages } = action.payload;
			if (state.pageIndex >= totalPages) {
				return {
					...state,
					pageIndex: Math.max(0, totalPages - 1),
				};
			}
			return state;
		}

		default:
			return state;
	}
}

// Custom hook for grid state management
export function useGridState() {
	const [state, dispatch] = useReducer(gridStateReducer, undefined, createInitialGridState);

	const setSorting = useCallback((sorting: GridState['sorting']) => {
		dispatch({ type: 'SET_SORTING', payload: sorting });
	}, []);

	const toggleSorting = useCallback((colId: string) => {
		dispatch({ type: 'TOGGLE_SORTING', payload: colId });
	}, []);

	const setPageIndex = useCallback((pageIndex: number) => {
		dispatch({ type: 'SET_PAGE_INDEX', payload: pageIndex });
	}, []);

	const setFilterTree = useCallback((tree: FilterGroup) => {
		dispatch({ type: 'SET_FILTER_TREE', payload: tree });
	}, []);

	const clearAllFilters = useCallback(() => {
		dispatch({ type: 'CLEAR_ALL_FILTERS' });
	}, []);

	const toggleFiltersPanel = useCallback(() => {
		dispatch({ type: 'TOGGLE_FILTERS_PANEL' });
	}, []);

	const setFiltersOpen = useCallback((open: boolean) => {
		dispatch({ type: 'SET_FILTERS_OPEN', payload: open });
	}, []);

	const resizeColumn = useCallback((id: string, width: number) => {
		dispatch({ type: 'RESIZE_COLUMN', payload: { id, width } });
	}, []);

	const setGridSelection = useCallback((selection: SheetsSelection | undefined) => {
		dispatch({ type: 'SET_GRID_SELECTION', payload: selection });
	}, []);

	const setActiveCell = useCallback((col: number, row: number) => {
		dispatch({ type: 'SET_ACTIVE_CELL', payload: { col, row } });
	}, []);

	const moveActiveCell = useCallback((dCol: number, dRow: number, colCount: number, rowCount: number) => {
		dispatch({ type: 'MOVE_ACTIVE', payload: { dCol, dRow, colCount, rowCount } });
	}, []);

	const resetPageIfNeeded = useCallback((totalPages: number) => {
		dispatch({ type: 'RESET_PAGE_IF_NEEDED', payload: { totalPages } });
	}, []);

	// Stable object identity (avoid prop/effect churn in consumers)
	const actions = useMemo(
		() => ({
			setSorting,
			toggleSorting,
			setPageIndex,
			setFilterTree,
			clearAllFilters,
			toggleFiltersPanel,
			setFiltersOpen,
			resizeColumn,
			setGridSelection,
			setActiveCell,
			moveActiveCell,
			resetPageIfNeeded,
		}),
		[
			setSorting,
			toggleSorting,
			setPageIndex,
			setFilterTree,
			clearAllFilters,
			toggleFiltersPanel,
			setFiltersOpen,
			resizeColumn,
			setGridSelection,
			setActiveCell,
			moveActiveCell,
			resetPageIfNeeded,
		],
	);

	return {
		state,
		actions,
	};
}

/**
 * Hook for integrating infinite scroll with the data grid
 * Wraps useSheetsInfiniteTable and provides grid-specific utilities
 */
import { useCallback, useMemo } from 'react';

import type { MetaField, MetaQuery } from '@constructive-io/data';

import { useSheetsContext } from '../../context/sheets-context';
import { useSheetsMeta } from '../../hooks/use-sheets-meta';
import { useSheetsInfiniteTable, type UseInfiniteTableOptions } from '../../hooks/use-sheets-infinite-table';

import { getAllRelationFields } from '../../utils/relation-utils';
import { normalizeServerRow } from '../sheets.utils';

type RowRecord = Record<string, unknown>;

/** Native inclusive row window — the DOM grid's visible-range shape (no glide Rectangle). */
export interface VisibleRowRange {
	startIndex: number;
	endIndex: number;
}

type MetaTable = NonNullable<NonNullable<NonNullable<MetaQuery['_meta']>['tables']>[number]>;

/**
 * Apply field type overrides from SheetsConfig to field metadata.
 * Mirrors the logic in use-load-grid.ts for consistent behavior.
 */
function buildFieldMetaMap(
	fields: MetaField[],
	tableName: string,
	fieldTypeOverrides?: Record<string, string>,
): Map<string, MetaField> {
	const map = new Map<string, MetaField>();

	if (!fields || fields.length === 0) return map;

	for (const field of fields) {
		if (!field?.name) continue;

		const overrideKey = `${tableName}.${field.name}`;
		const overridePgAlias = fieldTypeOverrides?.[overrideKey];

		if (overridePgAlias && field.type?.pgAlias !== overridePgAlias) {
			map.set(field.name, {
				...field,
				type: {
					...field.type,
					pgAlias: overridePgAlias,
				},
			} as MetaField);
		} else {
			map.set(field.name, field);
		}
	}

	return map;
}

export interface UseInfiniteGridDataOptions extends Omit<UseInfiniteTableOptions, 'select'> {
	tableName: string;
}

export interface UseInfiniteGridDataResult {
	/** Get row at index, returns null if not loaded */
	getRowAtIndex: (index: number) => RowRecord | null;
	/** Total count of rows */
	totalCount: number;
	/** Check if row is loaded */
	isRowLoaded: (rowIndex: number) => boolean;
	/** Prefetch the rows in an inclusive visible window (native range, not a glide Rectangle). */
	onVisibleRegionChanged: (range: VisibleRowRange) => void;
	/** Whether data is loading */
	isLoading: boolean;
	/** Whether initial data has been fetched */
	hasInitialData: boolean;
	/** Error if any */
	error: Error | null;
	/** Invalidate and refetch all data */
	invalidate: () => void;
	/**
	 * Optimistically update a single row in the cache without refetching.
	 * Used after successful cell edits to avoid full grid refresh.
	 * @param rowIndex The index of the row to update
	 * @param patch Partial row data to merge with existing row
	 * @returns true if the row was found and updated, false on a cache miss
	 */
	updateRowAtIndex: (rowIndex: number, patch: Partial<RowRecord>) => boolean;
	/** Table metadata */
	tableMeta: MetaTable | null;
	/** Field metadata map */
	fieldMetaMap: Map<string, MetaField>;
	/** All relation field names */
	allRelationFields: string[];
	/** Page size */
	pageSize: number;
}

/**
 * Hook that provides infinite scroll data loading for the grid
 */
export function useInfiniteGridData({
	tableName,
	pageSize = 100,
	orderBy,
	where,
	enabled = true,
}: UseInfiniteGridDataOptions): UseInfiniteGridDataResult {
	// Get metadata
	const { data: meta, error: metaError } = useSheetsMeta({ enabled });
	const { config } = useSheetsContext();

	const tableMeta = useMemo<MetaTable | null>(() => {
		const candidate = meta?._meta?.tables?.find((t) => t?.name === tableName) as MetaTable | undefined;
		return candidate ?? null;
	}, [meta, tableName]);

	// Field metadata map for quick lookup, enhanced with field type overrides
	const fieldMetaMap = useMemo(() => {
		const candidate = meta?._meta?.tables?.find((t) => t?.name === tableName) as MetaTable | undefined;
		const fields = (candidate?.fields as MetaField[]) || [];
		return buildFieldMetaMap(fields, tableName, config.fieldTypeOverrides);
	}, [meta, tableName, config.fieldTypeOverrides]);

	const metaTables = meta?._meta?.tables;
	const allRelationFields = useMemo<string[]>(
		() => {
			const rawTables = metaTables?.filter((t): t is NonNullable<typeof t> => t != null);
			return getAllRelationFields(tableMeta?.relations, rawTables);
		},
		[tableMeta, metaTables],
	);

	const relationFieldNames = useMemo(() => new Set(allRelationFields), [allRelationFields]);

	const fieldSelection = useMemo(() => {
		if (allRelationFields.length === 0) return 'all' as const;
		return { includeRelations: allRelationFields };
	}, [allRelationFields]);

	// Use the infinite table hook
	const infiniteTable = useSheetsInfiniteTable<RowRecord>(tableName, {
		pageSize,
		orderBy,
		where,
		select: fieldSelection,
		enabled,
	});

	// Get row at index with normalization
	// Note: We don't cache normalized rows because optimistic updates change the underlying
	// data without changing the row id. Caching by id causes stale data to be returned.
	// Normalization is cheap enough to do on every access.
	const getRowAtIndex = useCallback(
		(rowIndex: number): RowRecord | null => {
			const rawRow = infiniteTable.getRowAtIndex(rowIndex);
			if (rawRow === null) return null;

			// Always normalize - caching caused stale data issues with optimistic updates
			// because the cache key (id) doesn't change when other fields are updated
			return normalizeServerRow(rawRow, relationFieldNames);
		},
		[infiniteTable, relationFieldNames],
	);

	// Prefetch rows for an inclusive visible window (native range).
	const onVisibleRegionChanged = useCallback(
		(range: VisibleRowRange) => {
			const startRow = range.startIndex;
			const endRow = range.endIndex;

			// Add buffer for smoother scrolling
			const buffer = Math.ceil(pageSize / 2);
			infiniteTable.ensureRowsLoaded(Math.max(0, startRow - buffer), endRow + buffer);
		},
		[infiniteTable, pageSize],
	);

	// Invalidate and refetch
	const invalidate = useCallback(() => {
		infiniteTable.invalidate();
	}, [infiniteTable]);

	// Optimistically update a single row without refetching
	const updateRowAtIndex = useCallback(
		(rowIndex: number, patch: Partial<RowRecord>): boolean => {
			// Update the underlying React Query page cache
			// getRowAtIndex will return the updated data on next access.
			// Propagate the inner boolean so callers can self-heal (refetch) on a cache miss.
			return infiniteTable.updateRowAtIndex(rowIndex, patch);
		},
		[infiniteTable],
	);

	return {
		getRowAtIndex,
		totalCount: infiniteTable.totalCount,
		isRowLoaded: infiniteTable.isRowLoaded,
		onVisibleRegionChanged,
		isLoading: infiniteTable.isLoading,
		hasInitialData: infiniteTable.hasInitialData,
		error: metaError ?? infiniteTable.error,
		invalidate,
		updateRowAtIndex,
		tableMeta,
		fieldMetaMap,
		allRelationFields,
		pageSize,
	};
}

import { useMemo } from 'react';
import type { ReactNode } from 'react';

import { assessTableWriteCapability, getRowIdentityDefinition } from '@constructive-io/data';
import type { FieldSelection, MetaField, MetaQuery, QueryOptions, TableWriteCapability } from '@constructive-io/data';

import { useSheetsContext } from '../../context/sheets-context';
import { useSheetsMeta } from '../../hooks/use-sheets-meta';
import { useSheetsTable, type UseTableResult } from '../../hooks/use-sheets-table';
import { getAllRelationFields } from '../../utils/relation-utils';
import { createColumnSchemaFromMeta } from '../../cell-types/type-mapping';
import type { TableSchema, ColumnSchema } from '../../cell-types/types';
import { resolveSheetsRowIdentity } from '../../row-identity';

type MetaTable = NonNullable<NonNullable<NonNullable<MetaQuery['_meta']>['tables']>[number]>;
type RowRecord = Record<string, unknown>;
type TableOperations = Pick<UseTableResult<RowRecord>, 'update' | 'delete'>;
type CreatedRow = Record<string, unknown>;

// Data loading context type
export interface DataLoadingContextValue {
	// Table data
	data: RowRecord[];
	totalCount: number;
	// Loading states
	isLoading: boolean;
	isError: boolean;
	error: Error | null;
	// CRUD operations
	update: TableOperations['update'];
	create: (data: Record<string, unknown>) => Promise<{ createdRow?: CreatedRow | null }>;
	delete: TableOperations['delete'];
	// Refetch the table query (used by the error-state retry)
	refetch: () => Promise<unknown>;
	// Meta information
	meta: MetaQuery | undefined;
	tableMeta: MetaTable | null;
	writeCapability: TableWriteCapability | null;
	tableSchema: TableSchema | null;
	fieldMetaMap: Map<string, MetaField>;
	allRelationFields: string[];
}

// Data loading hook configuration
export interface UseDataLoadingConfig {
	tableName: string;
	enabled?: boolean;
	queryOptions: {
		limit?: number;
		offset?: number;
		orderBy?: Array<{ field: string; direction: 'asc' | 'desc' }>;
		where?: QueryOptions['where'];
	};
}

/**
 * Apply field type overrides from SheetsConfig to field metadata.
 *
 * In the admin app, this was handled by `buildEnhancedFieldMetaMap` which
 * merged smartTags.pgAlias from schema-builder. In sheets, the consumer
 * passes `config.fieldTypeOverrides` as a Record<string, string> where
 * key is "tableName.fieldName" and value is the cell type override (pgAlias).
 */
function buildFieldMetaMap(
	fields: MetaField[],
	tableName: string,
	fieldTypeOverrides?: Record<string, string>,
): Map<string, MetaField> {
	const map = new Map<string, MetaField>();

	if (!fields || fields.length === 0) return map;

	for (const field of fields) {
		if (!field?.name) continue;

		// Check for field type override
		const overrideKey = `${tableName}.${field.name}`;
		const overridePgAlias = fieldTypeOverrides?.[overrideKey];

		if (overridePgAlias && field.type?.pgAlias !== overridePgAlias) {
			// Apply override
			map.set(field.name, {
				...field,
				type: {
					...field.type,
					pgAlias: overridePgAlias,
				},
			} as MetaField);
		} else {
			map.set(field.name, field);
		}
	}

	return map;
}

// Main data loading hook
export function useDataLoading({
	tableName,
	enabled = true,
	queryOptions,
}: UseDataLoadingConfig) {
	// Meta data for table information
	const { data: meta, isLoading: isMetaLoading, error: metaError } = useSheetsMeta({ enabled });
	const { config } = useSheetsContext();

	const tableMeta = useMemo<MetaTable | null>(() => {
		const candidate = meta?._meta?.tables?.find((t) => t?.name === tableName) as MetaTable | undefined;
		return candidate ?? null;
	}, [meta, tableName]);

	// Table schema for form integration
	const tableSchema = useMemo<TableSchema | null>(() => buildTableSchema(tableMeta), [tableMeta]);
	const writeCapability = useMemo<TableWriteCapability | null>(
		() => tableMeta ? assessTableWriteCapability(tableMeta) : null,
		[tableMeta],
	);

	// Field metadata map for quick lookup, enhanced with field type overrides
	const fieldMetaMap = useMemo(() => {
		const candidate = meta?._meta?.tables?.find((t) => t?.name === tableName) as MetaTable | undefined;
		const fields = (candidate?.fields as MetaField[]) || [];
		return buildFieldMetaMap(fields, tableName, config.fieldTypeOverrides);
	}, [meta, tableName, config.fieldTypeOverrides]);

	const metaTables = meta?._meta?.tables;
	const allRelationFields = useMemo(
		() => {
			const rawTables = metaTables?.filter((t): t is NonNullable<typeof t> => t != null);
			return getAllRelationFields(tableMeta?.relations, rawTables);
		},
		[tableMeta, metaTables],
	);

	const relationSelection = useMemo<FieldSelection>(() => {
		return allRelationFields.length > 0 ? { includeRelations: allRelationFields } : 'all';
	}, [allRelationFields]);

	const tableData = useSheetsTable<RowRecord>(tableName, {
		...queryOptions,
		// Leverage field selection to include relation fields when requested
		select: relationSelection,
		enabled,
	});
	const {
		data = [],
		totalCount,
		update: updateRow,
		create: createRow,
		delete: deleteRow,
		isLoading: isTableLoading,
		error: tableError,
		refetch,
	} = tableData;

	const create: DataLoadingContextValue['create'] = async (payload) => {
		const result = await createRow(payload);
		const createdRow = result?.createdRow;
		if (!createdRow || typeof createdRow !== 'object' || !tableMeta) {
			throw new Error(`Create mutation for '${tableName}' did not return a row identity.`);
		}
		const identity = resolveSheetsRowIdentity(tableMeta, createdRow);
		if (identity.status !== 'identified') {
			throw new Error(`Create mutation for '${tableName}' returned an incomplete primary-key identity.`);
		}

		return { createdRow: createdRow as CreatedRow };
	};

	// Combined loading and error states
	const isLoading = isMetaLoading || isTableLoading;
	const isError = !!metaError || !!tableError;
	const error = (metaError as Error | null) || (tableError as Error | null) || null;

	const contextValue: DataLoadingContextValue = useMemo(
		() => ({
			data,
			totalCount,
			isLoading,
			isError,
			error,
			update: updateRow,
			create,
			delete: deleteRow,
			refetch,
			meta,
			tableMeta,
			writeCapability,
			tableSchema,
			fieldMetaMap,
			allRelationFields,
		}),
		[
			data,
			totalCount,
			isLoading,
			isError,
			error,
			updateRow,
			create,
			deleteRow,
			refetch,
			meta,
			tableMeta,
			writeCapability,
			tableSchema,
			fieldMetaMap,
			allRelationFields,
		],
	);

	return {
		contextValue,
		Provider: ({ children }: { children: ReactNode }) => children,
	};
}

function buildTableSchema(metaTable: MetaTable | null): TableSchema | null {
	if (!metaTable) return null;

	const columns: ColumnSchema[] = [];
	for (const field of metaTable.fields ?? []) {
		if (!field) continue;
		columns.push(createColumnSchemaFromMeta(field));
	}

	const identity = getRowIdentityDefinition(metaTable);
	const primaryKeyFields = identity.status === 'keyed'
		? identity.fields.map((field) => field.fieldName)
		: [];

	const inflection = metaTable.inflection;

	const metadata: TableSchema['metadata'] = {
		label: metaTable.name ?? undefined,
		description: inflection?.tableType ?? inflection?.allRows ?? undefined,
		primaryKey: primaryKeyFields.length > 0 ? primaryKeyFields : undefined,
	};

	return {
		id: metaTable.name ?? 'unknown-table',
		name: metaTable.name ?? 'unknown-table',
		columns,
		metadata,
	};
}

// Convenience hooks for accessing specific parts of the context
export function useTableData(): null {
	return null;
}
export function useTableOperations(): null {
	return null;
}
export function useTableMeta(): null {
	return null;
}

import { useCallback, useEffect, useMemo, useState } from 'react';

// Data pagination context type
export interface DataPaginationContextValue {
	// Pagination state
	pageIndex: number;
	pageSize: number;
	totalCount: number;
	totalPages: number;

	// Computed values
	hasNextPage: boolean;
	hasPreviousPage: boolean;
	startIndex: number;
	endIndex: number;

	// Actions
	setPageIndex: (index: number) => void;
	setPageSize: (size: number) => void;
	goToNextPage: () => void;
	goToPreviousPage: () => void;
	goToFirstPage: () => void;
	goToLastPage: () => void;
}

// Data pagination hook configuration
export interface UseDataPaginationConfig {
	initialPageSize?: number;
	initialPageIndex?: number;
	totalCount?: number;
	onPageChange?: (pageIndex: number, pageSize: number) => void;
}

// Main data pagination hook — uses local state instead of global Zustand store
export function useDataPagination({
	initialPageSize = 100,
	initialPageIndex = 0,
	totalCount = 0,
	onPageChange,
}: UseDataPaginationConfig) {
	const [pageIndex, setPageIndexState] = useState(initialPageIndex);
	const [pageSize, setPageSizeState] = useState(initialPageSize);

	// Compute pagination values
	const totalPages = useMemo(() => Math.max(1, Math.ceil(totalCount / pageSize)), [totalCount, pageSize]);
	const hasNextPage = useMemo(() => pageIndex < totalPages - 1, [pageIndex, totalPages]);
	const hasPreviousPage = useMemo(() => pageIndex > 0, [pageIndex]);
	const startIndex = useMemo(() => pageIndex * pageSize + 1, [pageIndex, pageSize]);
	const endIndex = useMemo(() => Math.min((pageIndex + 1) * pageSize, totalCount), [pageIndex, pageSize, totalCount]);

	useEffect(() => {
		if (pageSize !== initialPageSize) {
			setPageSizeState(initialPageSize);
		}
	}, [initialPageSize]); // eslint-disable-line react-hooks/exhaustive-deps

	useEffect(() => {
		if (pageIndex !== initialPageIndex) {
			setPageIndexState(initialPageIndex);
		}
	}, [initialPageIndex]); // eslint-disable-line react-hooks/exhaustive-deps

	// Auto-adjust page index when total pages changes
	useEffect(() => {
		if (pageIndex >= totalPages && totalPages > 0) {
			setPageIndexState(Math.max(0, totalPages - 1));
		}
	}, [pageIndex, totalPages]);

	// Page index setter with callback
	const setPageIndex = useCallback(
		(index: number) => {
			const clampedIndex = Math.max(0, Math.min(index, totalPages - 1));
			setPageIndexState(clampedIndex);
			onPageChange?.(clampedIndex, pageSize);
		},
		[totalPages, pageSize, onPageChange],
	);

	// Page size setter with callback and reset to first page
	const setPageSize = useCallback(
		(size: number) => {
			setPageSizeState(size);
			setPageIndexState(0);
			onPageChange?.(0, size);
		},
		[onPageChange],
	);

	// Navigation actions
	const goToNextPage = useCallback(() => {
		if (hasNextPage) {
			setPageIndex(pageIndex + 1);
		}
	}, [hasNextPage, pageIndex, setPageIndex]);

	const goToPreviousPage = useCallback(() => {
		if (hasPreviousPage) {
			setPageIndex(pageIndex - 1);
		}
	}, [hasPreviousPage, pageIndex, setPageIndex]);

	const goToFirstPage = useCallback(() => {
		setPageIndex(0);
	}, [setPageIndex]);

	const goToLastPage = useCallback(() => {
		setPageIndex(totalPages - 1);
	}, [totalPages, setPageIndex]);

	const contextValue: DataPaginationContextValue = useMemo(
		() => ({
			pageIndex,
			pageSize,
			totalCount,
			totalPages,
			hasNextPage,
			hasPreviousPage,
			startIndex,
			endIndex,
			setPageIndex,
			setPageSize,
			goToNextPage,
			goToPreviousPage,
			goToFirstPage,
			goToLastPage,
		}),
		[
			pageIndex,
			pageSize,
			totalCount,
			totalPages,
			hasNextPage,
			hasPreviousPage,
			startIndex,
			endIndex,
			setPageIndex,
			setPageSize,
			goToNextPage,
			goToPreviousPage,
			goToFirstPage,
			goToLastPage,
		],
	);

	return {
		contextValue,
		Provider: ({ children }: { children: any }) => children,
	};
}

// Convenience hooks for accessing specific parts of the context
export function usePaginationState() {
	// Placeholder — real values come from the contextValue returned by useDataPagination
	return { pageIndex: 0, pageSize: 100 };
}

export function usePaginationActions() {
	// Placeholder — real actions come from the contextValue
	return {
		setPageIndex: (_index: number) => {},
		setPageSize: (_size: number) => {},
		goToNextPage: () => {},
		goToPreviousPage: () => {},
		goToFirstPage: () => {},
		goToLastPage: () => {},
	};
}

/**
 * useUndoRedo — a tiny two-stack history for grid mutations.
 *
 * Each {@link HistoryEntry} carries its own inverse: `undo` reverts the change,
 * `redo` re-applies it (both may be async — a server mutation). `record` pushes a
 * new entry onto the undo stack and CLEARS the redo stack (a fresh edit forks the
 * timeline). `undo`/`redo` move the top entry across the two stacks, running the
 * matching thunk.
 *
 * The stacks live in refs so the handler identities (`undo`/`redo`/`record`) stay
 * STABLE across renders — keydown wiring binds them once. `canUndo`/`canRedo` are
 * reactive (state) so chrome can disable buttons. Depth is capped to bound memory.
 */
import { useCallback, useRef, useState } from 'react';

/** One reversible step: a label plus its undo / redo thunks. */
export interface HistoryEntry {
	label: string;
	undo: () => Promise<void> | void;
	redo: () => Promise<void> | void;
}

export interface UseUndoRedoResult {
	/** Push a new entry; clears the redo stack. */
	record: (entry: HistoryEntry) => void;
	/** Pop the top undo entry, run its `undo`, push it to the redo stack. No-op when empty. */
	undo: () => Promise<void>;
	/** Pop the top redo entry, run its `redo`, push it to the undo stack. No-op when empty. */
	redo: () => Promise<void>;
	/** True when the undo stack is non-empty. */
	canUndo: boolean;
	/** True when the redo stack is non-empty. */
	canRedo: boolean;
	/** Drop all history. */
	clear: () => void;
}

const DEFAULT_MAX_DEPTH = 100;

export function useUndoRedo(maxDepth: number = DEFAULT_MAX_DEPTH): UseUndoRedoResult {
	const undoStack = useRef<HistoryEntry[]>([]);
	const redoStack = useRef<HistoryEntry[]>([]);
	const [canUndo, setCanUndo] = useState(false);
	const [canRedo, setCanRedo] = useState(false);

	const sync = useCallback(() => {
		setCanUndo(undoStack.current.length > 0);
		setCanRedo(redoStack.current.length > 0);
	}, []);

	const record = useCallback(
		(entry: HistoryEntry) => {
			undoStack.current.push(entry);
			if (undoStack.current.length > maxDepth) undoStack.current.shift();
			redoStack.current = [];
			sync();
		},
		[maxDepth, sync],
	);

	const undo = useCallback(async () => {
		const entry = undoStack.current.pop();
		if (!entry) return;
		redoStack.current.push(entry);
		sync();
		await entry.undo();
	}, [sync]);

	const redo = useCallback(async () => {
		const entry = redoStack.current.pop();
		if (!entry) return;
		undoStack.current.push(entry);
		sync();
		await entry.redo();
	}, [sync]);

	const clear = useCallback(() => {
		undoStack.current = [];
		redoStack.current = [];
		sync();
	}, [sync]);

	return { record, undo, redo, canUndo, canRedo, clear };
}

// Typed row + draft-metadata model for the sheets grid.
//
// Draft metadata is attached to a row under a non-enumerable Symbol key so it
// never collides with real column data and stays invisible to JSON.stringify
// and key enumeration. NOTE: exactly like the previous non-enumerable string
// markers (`__isDraft` etc.), this metadata does NOT survive an object spread
// (`{ ...row }`) — callers must thread the row reference through rather than a
// shallow copy.
import type { DraftRow } from '../store/draft-rows-slice';

/** A grid row: arbitrary column values keyed by field name, plus an optional id. */
export type SheetsRow = Record<string, unknown> & { id?: string | number };

/** Client-side draft metadata carried by a not-yet-persisted row. */
export interface DraftMeta {
	readonly isDraft: true;
	readonly draftRowId: string;
	readonly status: DraftRow['status'];
	readonly errors: Record<string, string> | null;
}

const DRAFT_META: unique symbol = Symbol('sheets.draftMeta');

/** A row that may carry draft metadata under the (non-enumerable) Symbol key. */
export type RowWithDraft<TRow extends SheetsRow = SheetsRow> = TRow & { readonly [DRAFT_META]?: DraftMeta };

/** Attach draft metadata to a row in place (non-enumerable). Returns the same row, typed. */
export function attachDraftMeta<TRow extends SheetsRow>(row: TRow, meta: DraftMeta): RowWithDraft<TRow> {
	Object.defineProperty(row, DRAFT_META, { value: meta, enumerable: false, configurable: true });
	return row as RowWithDraft<TRow>;
}

/** Read draft metadata, or undefined for a normal (server) row. */
export function getDraftMeta(row: SheetsRow | null | undefined): DraftMeta | undefined {
	return row ? (row as RowWithDraft)[DRAFT_META] : undefined;
}

/** True when the row is a client-side draft. */
export function isDraftRow(row: SheetsRow | null | undefined): boolean {
	return getDraftMeta(row)?.isDraft === true;
}

/**
 * The right-click CONTEXT MENU (Stage B) — the showcase of the command layer: a menu is just
 * another EVENT SOURCE that resolves to named commands and runs through the SAME `dispatch`
 * pipeline as keys / clicks. Rendered ONCE at the grid level (never per-cell, so the per-cell
 * memo is untouched); the cell host calls `open(col, row, clientX, clientY)` on `onContextMenu`.
 *
 * Anchoring: Base UI's Menu anchors to its Trigger. We render a 0×0 FIXED trigger at the pointer
 * coordinates and toggle the controlled `open`, so the popup floats at the right-clicked cell.
 *
 * The ITEM MODEL is a pure builder (`buildContextMenuItems`) so the action→command mapping +
 * disabled gating is unit-testable WITHOUT the Base-UI popup (which needs a real layout env). The
 * component maps the model to <DropdownMenuItem>s. "Delete row(s)" is the one destructive action —
 * its `run` requests the SAME AlertDialog confirm the toolbar Delete uses.
 */
import { useState, type ReactNode } from 'react';
import { RiAddLine, RiClipboardLine, RiDeleteBin6Line, RiEraserLine, RiScissorsLine, RiFileCopyLine } from '@remixicon/react';

import {
	AlertDialog,
	AlertDialogAction,
	AlertDialogCancel,
	AlertDialogContent,
	AlertDialogDescription,
	AlertDialogFooter,
	AlertDialogHeader,
	AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import {
	DropdownMenu,
	DropdownMenuContent,
	DropdownMenuItem,
	DropdownMenuSeparator,
	DropdownMenuShortcut,
	DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';

/** Where the menu is anchored + the cell it acts on. `null` = closed. */
export interface ContextMenuState {
	clientX: number;
	clientY: number;
}

/** One row of the menu (or a separator). `run` fires on click; `disabled` greys it out. */
export interface ContextMenuItem {
	key: string;
	separator?: boolean;
	label?: string;
	icon?: ReactNode;
	shortcut?: string;
	destructive?: boolean;
	disabled?: boolean;
	run?: () => void;
}

export interface BuildContextMenuItemsArgs {
	/** Dispatch a command id through the grid's stable dispatch pipeline. */
	onAction: (commandId: string) => void;
	/** True when the command's `canRun` passes against the latched context. */
	isEnabled: (commandId: string) => boolean;
	/** Append a draft row (the toolbar Add-row path). */
	onAddRow: () => void;
	/** Open the destructive delete confirm (the AlertDialog). */
	requestDelete: () => void;
	/** Count of currently selected rows — gates Delete + drives its label. */
	selectedRowCount: number;
	canAddRows?: boolean;
	canDeleteRows?: boolean;
}

/**
 * Pure menu model — the single source of truth for the items, their command mapping, and their
 * disabled state. Tested directly (no DOM). Clipboard / clear items dispatch their command id via
 * `onAction` and are disabled when `isEnabled(id)` is false; Add row / Delete use dedicated paths.
 */
export function buildContextMenuItems({
	onAction,
	isEnabled,
	onAddRow,
	requestDelete,
	selectedRowCount,
	canAddRows = true,
	canDeleteRows = true,
}: BuildContextMenuItemsArgs): ContextMenuItem[] {
	const cmd = (key: string, commandId: string, label: string, icon: ReactNode, shortcut?: string): ContextMenuItem => ({
		key,
		label,
		icon,
		shortcut,
		disabled: !isEnabled(commandId),
		run: () => onAction(commandId),
	});
	return [
		cmd('copy', 'clipboard.copy', 'Copy', <RiFileCopyLine className='size-4' aria-hidden='true' />, '⌘C'),
		cmd('cut', 'clipboard.cut', 'Cut', <RiScissorsLine className='size-4' aria-hidden='true' />, '⌘X'),
		cmd('paste', 'clipboard.paste', 'Paste', <RiClipboardLine className='size-4' aria-hidden='true' />, '⌘V'),
		cmd('clear', 'cell.clear', 'Clear', <RiEraserLine className='size-4' aria-hidden='true' />),
		{ key: 'sep', separator: true },
		{
			key: 'add-row',
			label: 'Add row',
			icon: <RiAddLine className='size-4' aria-hidden='true' />,
			disabled: !canAddRows,
			run: onAddRow,
		},
		{
			key: 'delete-rows',
			label: selectedRowCount > 1 ? `Delete ${selectedRowCount} rows` : 'Delete row',
			icon: <RiDeleteBin6Line className='size-4' aria-hidden='true' />,
			destructive: true,
			disabled: !canDeleteRows || selectedRowCount === 0,
			run: requestDelete,
		},
	];
}

export interface SheetsContextMenuProps {
	/** Open anchor + position; `null` keeps the menu closed. */
	state: ContextMenuState | null;
	/** Close the menu (clears `state`). */
	onClose: () => void;
	/** Dispatch a command id through the grid's stable dispatch pipeline. */
	onAction: (commandId: string) => void;
	/** True when the command's `canRun` passes against the latched context. */
	isEnabled: (commandId: string) => boolean;
	/** Append a draft row (the toolbar Add-row path). */
	onAddRow: () => void;
	/** Delete the selected row(s) (the toolbar deleteSelected path) — guarded by the AlertDialog. */
	onDeleteRows: () => void;
	/** Count of currently selected rows — drives the destructive dialog copy. */
	selectedRowCount: number;
	canAddRows?: boolean;
	canDeleteRows?: boolean;
}

export function SheetsContextMenu({
	state,
	onClose,
	onAction,
	isEnabled,
	onAddRow,
	onDeleteRows,
	selectedRowCount,
	canAddRows = true,
	canDeleteRows = true,
}: SheetsContextMenuProps) {
	const [confirmDelete, setConfirmDelete] = useState(false);
	const open = state !== null;

	const items = buildContextMenuItems({
		onAction,
		isEnabled,
		onAddRow,
		requestDelete: () => setConfirmDelete(true),
		selectedRowCount,
		canAddRows,
		canDeleteRows,
	});

	return (
		<>
			<DropdownMenu open={open} onOpenChange={(next) => !next && onClose()}>
				{/* 0×0 fixed anchor at the pointer — the menu floats from here. */}
				<DropdownMenuTrigger
					aria-hidden
					tabIndex={-1}
					style={{
						position: 'fixed',
						left: state?.clientX ?? 0,
						top: state?.clientY ?? 0,
						width: 0,
						height: 0,
					}}
				/>
				<DropdownMenuContent align='start'>
					{items.map((item) =>
						item.separator ? (
							<DropdownMenuSeparator key={item.key} />
						) : (
							<DropdownMenuItem
								key={item.key}
								variant={item.destructive ? 'destructive' : 'default'}
								disabled={item.disabled}
								onClick={() => {
									// Run then close — a menu pick is a one-shot (the popup dismisses).
									item.run?.();
									onClose();
								}}
							>
								{item.icon}
								{item.label}
								{item.shortcut && <DropdownMenuShortcut>{item.shortcut}</DropdownMenuShortcut>}
							</DropdownMenuItem>
						),
					)}
				</DropdownMenuContent>
			</DropdownMenu>

			{/* Destructive confirm — mirrors the toolbar Delete AlertDialog. Driven open after the
			    menu closes so the two overlays never fight for focus. */}
			<AlertDialog open={confirmDelete} onOpenChange={setConfirmDelete}>
				<AlertDialogContent>
					<AlertDialogHeader>
						<AlertDialogTitle>Delete rows?</AlertDialogTitle>
						<AlertDialogDescription>
							This will permanently delete {selectedRowCount} {selectedRowCount === 1 ? 'row' : 'rows'}. This action cannot be
							undone.
						</AlertDialogDescription>
					</AlertDialogHeader>
					<AlertDialogFooter>
						<AlertDialogCancel>Cancel</AlertDialogCancel>
						<AlertDialogAction
							className='bg-destructive text-white hover:bg-destructive/90'
							onClick={() => {
								onDeleteRows();
								setConfirmDelete(false);
							}}
						>
							Delete
						</AlertDialogAction>
					</AlertDialogFooter>
				</AlertDialogContent>
			</AlertDialog>
		</>
	);
}

import { memo, useCallback, useEffect, useMemo, useState } from "react";
import {
  RiAddLine,
  RiCloseCircleLine,
  RiDeleteBin6Line,
  RiDownloadLine,
  RiFilter3Line,
  RiSearch2Line,
} from "@remixicon/react";

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

import {
  getDefaultOperator,
  getOperatorsForGqlType,
  isFilterableType,
  type FilterOperator,
  type OperatorValueType,
} from "./filter-operators";
import type { SheetsSelection } from "../selection/selection-model";

// Filter value can be string, number, boolean, null, or undefined
// This matches the usage in buildWhereFromFilters and GraphQL filter operations
export type FilterValue = string | number | boolean | null | undefined;

// ── Filter tree types ──

export type FilterNode = FilterCondition | FilterGroup;

export interface FilterCondition {
  type: "condition";
  id: string;
  field: string;
  operator: string;
  value: FilterValue;
}

export interface FilterGroup {
  type: "group";
  id: string;
  conjunction: "and" | "or";
  children: FilterNode[];
}

export const MAX_FILTER_DEPTH = 3;

export type FieldTypeMap = Record<string, { gqlType: string; isArray: boolean }>;

// ── Tree helpers ──

function uid(): string {
  return Math.random().toString(36).slice(2, 9);
}

export function createEmptyGroup(conjunction: "and" | "or" = "and"): FilterGroup {
  return { type: "group", id: uid(), conjunction, children: [] };
}

function createCondition(field: string, operator: string): FilterCondition {
  return { type: "condition", id: uid(), field, operator, value: "" };
}

export function countConditions(node: FilterNode): number {
  if (node.type === "condition") return 1;
  return node.children.reduce((sum, child) => sum + countConditions(child), 0);
}

export interface SheetsControlsProps {
  openSearch?: () => void;
  filterTree: FilterGroup;
  setFilterTree: (tree: FilterGroup) => void;
  filtersOpen: boolean;
  setFiltersOpen: (open: boolean) => void;
  clearAllFilters: () => void;
  applyFilters: () => void;
  columnKeys: string[];
  fieldTypeMap: FieldTypeMap;
  showSelection: boolean;
  gridSelection: SheetsSelection | null;
  setGridSelection: (selection: SheetsSelection | null) => void;
  deleteSelected: () => void;
  onAddRow?: () => void;
  onExport?: () => void;
  canDelete?: boolean;
  readOnlyReason?: string | null;
}

function getInputType(valueType: OperatorValueType): string {
  switch (valueType) {
    case "number":
      return "number";
    case "date":
      return "date";
    case "datetime":
      return "datetime-local";
    default:
      return "text";
  }
}

function getPlaceholder(valueType: OperatorValueType): string {
  if (valueType === "key") return "key name";
  return "Value...";
}

/** Parse a JSON-encoded IntervalInput string into individual fields. */
function parseIntervalValue(raw: FilterValue): {
  days: string;
  hours: string;
  minutes: string;
  seconds: string;
} {
  const empty = { days: "", hours: "", minutes: "", seconds: "" };
  if (!raw || typeof raw !== "string") return empty;
  try {
    const obj = JSON.parse(raw);
    return {
      days: obj.days ? String(obj.days) : "",
      hours: obj.hours ? String(obj.hours) : "",
      minutes: obj.minutes ? String(obj.minutes) : "",
      seconds: obj.seconds ? String(obj.seconds) : "",
    };
  } catch {
    return empty;
  }
}

/** Compose individual interval fields into a JSON-encoded IntervalInput string. */
function composeIntervalValue(fields: {
  days: string;
  hours: string;
  minutes: string;
  seconds: string;
}): string {
  const obj: Record<string, number> = {};
  const d = parseInt(fields.days, 10);
  const h = parseInt(fields.hours, 10);
  const m = parseInt(fields.minutes, 10);
  const s = parseInt(fields.seconds, 10);
  if (!isNaN(d) && d !== 0) obj.days = d;
  if (!isNaN(h) && h !== 0) obj.hours = h;
  if (!isNaN(m) && m !== 0) obj.minutes = m;
  if (!isNaN(s) && s !== 0) obj.seconds = s;
  return Object.keys(obj).length > 0 ? JSON.stringify(obj) : "";
}

/** Structured interval input — renders d/h/m/s number fields that map to IntervalInput. */
function IntervalFilterInput({
  value,
  onChange,
}: {
  value: FilterValue;
  onChange: (v: string) => void;
}) {
  const fields = useMemo(() => parseIntervalValue(value), [value]);

  const handleChange = useCallback(
    (unit: "days" | "hours" | "minutes" | "seconds", v: string) => {
      onChange(composeIntervalValue({ ...fields, [unit]: v }));
    },
    [fields, onChange],
  );

  return (
    <div className="flex items-center gap-1">
      <Input
        className="w-[52px] px-1.5 text-center"
        type="number"
        placeholder="d"
        min={0}
        value={fields.days}
        onChange={(e) => handleChange("days", e.target.value)}
      />
      <Input
        className="w-[52px] px-1.5 text-center"
        type="number"
        placeholder="h"
        min={0}
        max={23}
        value={fields.hours}
        onChange={(e) => handleChange("hours", e.target.value)}
      />
      <Input
        className="w-[52px] px-1.5 text-center"
        type="number"
        placeholder="m"
        min={0}
        max={59}
        value={fields.minutes}
        onChange={(e) => handleChange("minutes", e.target.value)}
      />
      <Input
        className="w-[52px] px-1.5 text-center"
        type="number"
        placeholder="s"
        min={0}
        max={59}
        value={fields.seconds}
        onChange={(e) => handleChange("seconds", e.target.value)}
      />
    </div>
  );
}

const FilterConditionRow = memo(function FilterConditionRow({
  condition,
  columns,
  fieldTypeMap,
  onChange,
  onRemove,
}: {
  condition: FilterCondition;
  columns: readonly string[];
  fieldTypeMap: FieldTypeMap;
  onChange: (updates: Partial<FilterCondition>) => void;
  onRemove: () => void;
}) {
  const typeInfo = fieldTypeMap[condition.field];
  const operators = useMemo<FilterOperator[]>(
    () => getOperatorsForGqlType(typeInfo?.gqlType, typeInfo?.isArray ?? false),
    [typeInfo?.gqlType, typeInfo?.isArray],
  );
  const currentOp = operators.find((o) => o.operator === condition.operator) ?? operators[0];

  const handleColumnChange = useCallback(
    (newField: string) => {
      const info = fieldTypeMap[newField];
      const defaultOp = getDefaultOperator(info?.gqlType, info?.isArray ?? false) ?? "equalTo";
      onChange({ field: newField, operator: defaultOp, value: "" });
    },
    [fieldTypeMap, onChange],
  );

  const handleOperatorChange = useCallback(
    (newOp: string) => {
      const opEntry = operators.find((o) => o.operator === newOp);
      if (opEntry?.valueType === "none") {
        onChange({ operator: newOp, value: "" });
      } else {
        onChange({ operator: newOp });
      }
    },
    [operators, onChange],
  );

  return (
    <div className="flex items-center gap-2">
      <Select value={condition.field} onValueChange={handleColumnChange}>
        <SelectTrigger className="w-[140px]">
          <SelectValue placeholder="Column" />
        </SelectTrigger>
        <SelectContent>
          {columns.map((k) => (
            <SelectItem key={k} value={k}>
              {k}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>

      {operators.length > 0 && (
        <Select value={currentOp?.operator ?? ""} onValueChange={handleOperatorChange}>
          <SelectTrigger className="w-[130px]">
            <SelectValue placeholder="Operator" />
          </SelectTrigger>
          <SelectContent>
            {operators.map((op) => (
              <SelectItem key={op.operator} value={op.operator}>
                {op.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      )}

      {currentOp && currentOp.valueType === "interval" && (
        <IntervalFilterInput value={condition.value} onChange={(v) => onChange({ value: v })} />
      )}

      {currentOp && currentOp.valueType !== "none" && currentOp.valueType !== "interval" && (
        <Input
          className="w-[150px]"
          type={getInputType(currentOp.valueType)}
          placeholder={getPlaceholder(currentOp.valueType)}
          value={
            typeof condition.value === "string" || typeof condition.value === "number"
              ? String(condition.value)
              : ""
          }
          onChange={(e) => onChange({ value: e.target.value })}
        />
      )}

      <Button variant="ghost" size="icon" onClick={onRemove} aria-label="Remove filter">
        <RiCloseCircleLine className="h-4 w-4" />
      </Button>
    </div>
  );
});

/** Recursive filter group UI — renders AND/OR toggle + conditions + nested groups. */
const FilterGroupUI = memo(function FilterGroupUI({
  group,
  depth,
  fieldTypeMap,
  filterableColumns,
  onChange,
  onRemove,
}: {
  group: FilterGroup;
  depth: number;
  fieldTypeMap: FieldTypeMap;
  filterableColumns: readonly string[];
  onChange: (updated: FilterGroup) => void;
  onRemove?: () => void;
}) {
  const toggleConjunction = useCallback(() => {
    onChange({ ...group, conjunction: group.conjunction === "and" ? "or" : "and" });
  }, [group, onChange]);

  const addCondition = useCallback(() => {
    const firstCol = filterableColumns[0];
    if (!firstCol) return;
    const info = fieldTypeMap[firstCol];
    const defaultOp = getDefaultOperator(info?.gqlType, info?.isArray ?? false) ?? "equalTo";
    onChange({ ...group, children: [...group.children, createCondition(firstCol, defaultOp)] });
  }, [group, filterableColumns, fieldTypeMap, onChange]);

  const addGroup = useCallback(() => {
    const childConj = group.conjunction === "and" ? "or" : "and";
    onChange({ ...group, children: [...group.children, createEmptyGroup(childConj)] });
  }, [group, onChange]);

  const updateChild = useCallback(
    (childId: string, updated: FilterNode) => {
      onChange({ ...group, children: group.children.map((c) => (c.id === childId ? updated : c)) });
    },
    [group, onChange],
  );

  const removeChild = useCallback(
    (childId: string) => {
      onChange({ ...group, children: group.children.filter((c) => c.id !== childId) });
    },
    [group, onChange],
  );

  return (
    <div className={depth > 0 ? "border-muted-foreground/20 ml-1 border-l-2 pl-3" : undefined}>
      <div className="mb-2 flex items-center gap-1.5">
        <span className="text-muted-foreground text-xs">Match</span>
        <Button
          variant="outline"
          size="sm"
          className="h-6 px-2 text-xs font-medium"
          onClick={toggleConjunction}
        >
          {group.conjunction === "and" ? "all" : "any"}
        </Button>
        <span className="text-muted-foreground text-xs">of:</span>
        {onRemove && (
          <Button
            variant="ghost"
            size="icon"
            className="ml-auto h-6 w-6"
            onClick={onRemove}
            aria-label="Remove group"
          >
            <RiCloseCircleLine className="h-3.5 w-3.5" />
          </Button>
        )}
      </div>

      <div className="grid gap-2">
        {group.children.map((child) => {
          if (child.type === "condition") {
            return (
              <FilterConditionRow
                key={child.id}
                condition={child}
                columns={filterableColumns}
                fieldTypeMap={fieldTypeMap}
                onChange={(updates) => updateChild(child.id, { ...child, ...updates })}
                onRemove={() => removeChild(child.id)}
              />
            );
          }
          return (
            <FilterGroupUI
              key={child.id}
              group={child}
              depth={depth + 1}
              fieldTypeMap={fieldTypeMap}
              filterableColumns={filterableColumns}
              onChange={(updated) => updateChild(child.id, updated)}
              onRemove={() => removeChild(child.id)}
            />
          );
        })}
      </div>

      <div className="mt-2 flex items-center gap-2">
        <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={addCondition}>
          <RiAddLine className="mr-1 h-3.5 w-3.5" /> Condition
        </Button>
        {depth < MAX_FILTER_DEPTH - 1 && (
          <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={addGroup}>
            <RiAddLine className="mr-1 h-3.5 w-3.5" /> Group
          </Button>
        )}
      </div>
    </div>
  );
});

export function SheetsControls(props: SheetsControlsProps) {
  const {
    openSearch,
    filterTree,
    setFilterTree,
    filtersOpen,
    setFiltersOpen,
    clearAllFilters,
    applyFilters,
    columnKeys,
    fieldTypeMap,
    showSelection,
    gridSelection,
    deleteSelected,
    onAddRow,
    onExport,
    canDelete = true,
    readOnlyReason,
  } = props;

  const filterableColumns = useMemo(() => {
    if (Object.keys(fieldTypeMap).length === 0) return columnKeys;
    return columnKeys.filter((k) => {
      const info = fieldTypeMap[k];
      if (!info) return false;
      return isFilterableType(info.gqlType, info.isArray);
    });
  }, [columnKeys, fieldTypeMap]);

  // ── Local filter tree (only committed on Apply) ──
  const [localTree, setLocalTree] = useState<FilterGroup>(filterTree);

  // Sync local state when popover opens
  useEffect(() => {
    if (filtersOpen) {
      setLocalTree(filterTree);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- only trigger on popover open/close
  }, [filtersOpen]);

  const handleApplyFilters = useCallback(() => {
    setFilterTree(localTree);
    applyFilters();
  }, [localTree, setFilterTree, applyFilters]);

  const handleClearAllFilters = useCallback(() => {
    setLocalTree(createEmptyGroup());
    clearAllFilters();
  }, [clearAllFilters]);

  const conditionCount = useMemo(() => countConditions(localTree), [localTree]);

  const selectedRowCount = useMemo(() => {
    if (!gridSelection) return 0;
    return gridSelection.rows.length;
  }, [gridSelection]);

  return (
    <>
      <div
        data-part-id="sheets-controls"
        className="flex shrink-0 flex-wrap items-center justify-between gap-4 py-4"
      >
        <div className="flex min-w-0 flex-wrap items-center gap-2">
		  {readOnlyReason && (
			<span
				className="border-border bg-muted text-muted-foreground inline-flex h-8 items-center rounded-md border px-2.5 text-xs"
				role="status"
				title={readOnlyReason}
			>
				Read-only
			</span>
		  )}
          <Button variant="outline" size="sm" onClick={() => openSearch?.()}>
            <RiSearch2Line className="text-muted-foreground/60 -ms-1.5 size-5" aria-hidden="true" />
            Search
          </Button>
          {onAddRow && (
            <Button variant="outline" size="sm" aria-label="Add row" onClick={() => onAddRow()}>
              <RiAddLine className="text-muted-foreground/60 -ms-1.5 size-5" aria-hidden="true" />
              Add row
            </Button>
          )}
          {onExport && (
            <Button variant="outline" size="sm" aria-label="Export CSV" onClick={() => onExport()}>
              <RiDownloadLine
                className="text-muted-foreground/60 -ms-1.5 size-5"
                aria-hidden="true"
              />
              Export
            </Button>
          )}
        </div>

        <div className="flex items-center gap-2">
          {showSelection && (
            <AlertDialog>
              <AlertDialogTrigger asChild>
                <Button
				  variant="destructive-outline"
				  size="sm"
				  disabled={!canDelete || selectedRowCount === 0}
				  title={!canDelete ? readOnlyReason ?? 'Delete is unavailable for this table.' : undefined}
				>
                  <RiDeleteBin6Line className="-ms-1.5 size-5" aria-hidden="true" />
                  Delete
                  {selectedRowCount > 0 ? ` (${selectedRowCount})` : ""}
                </Button>
              </AlertDialogTrigger>
              <AlertDialogContent>
                <AlertDialogHeader>
                  <AlertDialogTitle>Delete rows?</AlertDialogTitle>
                  <AlertDialogDescription>
                    This will permanently delete {selectedRowCount}{" "}
                    {selectedRowCount === 1 ? "row" : "rows"}. This action cannot be undone.
                  </AlertDialogDescription>
                </AlertDialogHeader>
                <AlertDialogFooter>
                  <AlertDialogCancel>Cancel</AlertDialogCancel>
                  <AlertDialogAction
                    className="bg-destructive text-white hover:bg-destructive/90"
                    onClick={() => deleteSelected()}
                  >
                    Delete
                  </AlertDialogAction>
                </AlertDialogFooter>
              </AlertDialogContent>
            </AlertDialog>
          )}
          <Popover open={filtersOpen} onOpenChange={setFiltersOpen}>
            <PopoverTrigger asChild>
              <Button variant="outline" size="sm" className="relative">
                <RiFilter3Line
                  className="text-muted-foreground/60 -ms-1.5 size-5"
                  aria-hidden="true"
                />
                Filters
                {countConditions(filterTree) > 0 && (
                  <span
                    className="border-border/60 bg-background text-muted-foreground/70 ms-2 -me-1 inline-flex h-5
											max-h-full items-center rounded border px-1 font-[inherit] text-[0.625rem] font-medium"
                  >
                    {countConditions(filterTree)}
                  </span>
                )}
              </Button>
            </PopoverTrigger>
            <PopoverContent
              className="w-auto min-w-[28rem] max-h-[32rem] overflow-auto p-4"
              align="end"
            >
              <div className="grid gap-4">
                <div className="space-y-2">
                  <h4 className="leading-none font-medium">Filters</h4>
                </div>
                <FilterGroupUI
                  group={localTree}
                  depth={0}
                  fieldTypeMap={fieldTypeMap}
                  filterableColumns={filterableColumns}
                  onChange={setLocalTree}
                />
                <div className="flex items-center justify-end gap-2 border-t pt-2">
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={handleClearAllFilters}
                    disabled={conditionCount === 0}
                  >
                    Clear all
                  </Button>
                  <Button size="sm" onClick={handleApplyFilters}>
                    Apply
                  </Button>
                </div>
              </div>
            </PopoverContent>
          </Popover>
        </div>
      </div>
    </>
  );
}

/**
 * Formatter utilities for grid cell previews
 * - Keep these pure so they are easy to test
 */

export function compactJsonPreview(value: unknown, maxLen = 80): string {
	try {
		const s = typeof value === 'string' ? value : JSON.stringify(value);
		if (s.length <= maxLen) return s;
		return s.slice(0, maxLen - 1) + '\u2026';
	} catch {
		const s = String(value);
		return s.length > maxLen ? s.slice(0, maxLen - 1) + '\u2026' : s;
	}
}

export function formatArrayPreview(arr: unknown[], max = 3): string {
	const items = arr
		.slice(0, max)
		.map((v) => (typeof v === 'object' && v !== null ? compactJsonPreview(v, 20) : String(v)));
	const more = arr.length > max ? ` +${arr.length - max}` : '';
	return items.join(', ') + more;
}

export function formatImagePreview(val: unknown): string {
	if (!val) return '';
	if (typeof val === 'string') return val.split('/').pop() || val;
	if (typeof val === 'object' && val !== null) {
		const rec = val as Record<string, unknown>;
		const url = (rec.url as string) || '';
		const filename = (rec.filename as string) || url.split('/').pop() || 'image';
		return filename;
	}
	return String(val);
}

