// Rows moved per PageUp/PageDown when the scroll element's clientHeight can't be read
// (jsdom / detached). A sensible spreadsheet page span.
const FALLBACK_PAGE_ROWS = 10;
/** Estimated body row height — MUST match grid-viewport's ESTIMATED_ROW_HEIGHT (page-span math). */
const ESTIMATED_ROW_HEIGHT = 34;

/** Escape a single CSV field: wrap in quotes when it contains comma/quote/newline. */
function escapeCsvField(value: unknown): string {
	const str = value == null ? '' : String(value);
	if (/[",\n\r]/.test(str)) {
		return `"${str.replace(/"/g, '""')}"`;
	}
	return str;
}

/**
 * Build a CSV string from rows + columns and trigger a browser download.
 * Dependency-free: values are stringified via String() (objects become
 * "[object Object]" — callers wanting rich serialization should pre-flatten).
 */
function downloadCsv(rows: Record<string, unknown>[], columns: string[], filename?: string): void {
	if (typeof document === 'undefined') return;
	const header = columns.map(escapeCsvField).join(',');
	const body = rows.map((row) => columns.map((col) => escapeCsvField(row?.[col])).join(',')).join('\n');
	const csv = body ? `${header}\n${body}` : header;

	const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
	const url = URL.createObjectURL(blob);
	const link = document.createElement('a');
	link.href = url;
	link.download = filename ?? 'export.csv';
	document.body.appendChild(link);
	link.click();
	document.body.removeChild(link);
	URL.revokeObjectURL(url);
}

/**
 * Coerce a cell's raw row value to a boolean for the inline-toggle commit — MUST
 * match the boolean SheetsCell factory (cell-model/factories/boolean.ts) so the
 * toggle flips against the SAME boolean the cell renders: null/undefined -> false,
 * a boolean passes through, anything else via Boolean(). The host commits the
 * negation, so an unset boolean toggles on first.
 */
function coerceCellBoolean(value: unknown): boolean {
	if (value === null || value === undefined) return false;
	return typeof value === 'boolean' ? value : Boolean(value);
}

/** The absolute-nav keys whose command (`cell.navAbsolute`) needs the payload below. */
const ABSOLUTE_NAV_KEYS = new Set(['Tab', 'Home', 'End', 'PageUp', 'PageDown']);

/**
 * Build the dispatch payload for a key event. Only `cell.navAbsolute` (Tab/Home/End/Page*)
 * needs one — the funnel's old inline branch derived the page span from the scroll element's
 * clientHeight (e.currentTarget IS the scroll root), falling back to a constant under jsdom.
 * Arrows / extends / undo / redo / select-all / open read everything from the command context,
 * so they get `undefined`.
 */
function buildKeyPayload(e: React.KeyboardEvent): NavAbsolutePayload | undefined {
	if (!ABSOLUTE_NAV_KEYS.has(e.key)) return undefined;
	const clientHeight = (e.currentTarget as HTMLElement).clientHeight;
	const pageRows = clientHeight > 0 ? Math.max(1, Math.floor(clientHeight / ESTIMATED_ROW_HEIGHT)) : FALLBACK_PAGE_ROWS;
	return { key: e.key, ctrlOrMeta: e.ctrlKey || e.metaKey, shift: e.shiftKey, pageRows };
}

function SheetsInnerComponent<TRow extends SheetsRow = SheetsRow>(
	props: DataGridProps<TRow>,
	ref: React.ForwardedRef<SheetsHandle>,
) {
	// The native TanStack DOM grid is the only render path (the canvas <DataEditor>
	// branch was removed at the glide cutover).
	return (
		<FeedbackProvider>
			<SheetsDomInner {...props} forwardedRef={ref} />
		</FeedbackProvider>
	);
}

// forwardRef erases the component's own generic parameter; the cast restores a
// generic call signature so `Sheets<MyRow>` keeps inferring TRow. This is the
// single allowed `as` cast for Unit A (well-known generic-forwardRef pattern).
export const Sheets = forwardRef(SheetsInnerComponent) as <TRow extends SheetsRow = SheetsRow>(
	props: DataGridProps<TRow> & { ref?: React.Ref<SheetsHandle> },
) => React.ReactElement;

// ============================================================================
// The (only) render path. Reuses the useSheets hook for data/state, feeds its
// bindings into the v9 table instance + GridViewport, and renders native DOM
// cells via SheetsCellHost. Surfaces the same load states (error / loading /
// empty + consumer slots) the removed canvas branch owned.
// ============================================================================

// Row selection (Phase 6), column sizing + pinning (Stage 2) are all wired to the shell now.
// Pinning is shell-DERIVED (frozenCount), never edited from the grid, so its onChange is a no-op.
// Stable empty row-selection map returned when nothing is selected.
const EMPTY_ROW_SELECTION: RowSelectionState = {};
const noop = () => {};

// Overlay flip-geometry knobs — MUST match the OverlayManager's private constants so
// the geometry we hand the editor via EditorProps.overlay matches where it's placed.
const OVERLAY_MARGIN_PX = 12;
const OVERLAY_MIN_BELOW_PX = 320;

function SheetsDomInner<TRow extends SheetsRow = SheetsRow>({
	forwardedRef,
	...props
}: DataGridProps<TRow> & { forwardedRef?: React.ForwardedRef<SheetsHandle> }) {
	const {
		tableName,
		className,
		pageSize = 100,
		showSelection = true,
		showPagination = true,
		infiniteScroll = false,
		slots,
	} = props;
	const s = useSheets<TRow>(props);
	const shell = s._shell;

	const { config } = useSheetsContext();

	const viewportRef = useRef<GridViewportHandle>(null);

	// ============== EVENT->COMMAND DISPATCH (P4 Phase 1) ==============
	// ONE interceptable pipeline: every grid event resolves to a named command and runs
	// through `dispatch`. The registry + keymap are latched (so a Phase 2 consumer override
	// is a ref swap, not a new dispatch identity); `ctxRef.current` is the assembled
	// GridCommandContext, repointed each render below (mirrors the openEditor ref-latch).
	// `dispatch` is useCallback([]) reading the refs, so it stays referentially STABLE — the
	// per-cell memo gates on the pointer callbacks that close over it, so it must never churn.
	// PUBLIC CUSTOMIZATION SEAM (P4 Phase 2): registry / keymap / interceptors derive from the
	// consumer props but rebuild ONLY when the prop IDENTITY changes (useMemo), so omitting them
	// is identical to the defaults. Each is latched into a ref so the keydown handler + dispatch
	// read the latest without re-creating. The PUBLIC `dispatch` callback stays referentially
	// STABLE (reads dispatchRef.current), so the per-cell memo never churns; dispatchRef itself is
	// rebuilt when the registry or interceptor list identity changes (additive, no identity leak).
	const { commands, keymap, interceptors, onCommand } = props;
	const registry = useMemo<GridCommandRegistry>(() => createGridCommandRegistry(commands), [commands]);
	// Consumer bindings scan FIRST (resolveKeyCommand is first-match-wins) so a rebind of a
	// built-in chord wins over the default; the defaults follow as the fallback set.
	const fullKeymap = useMemo<Binding[]>(() => [...(keymap ?? []), ...DEFAULT_KEYMAP], [keymap]);
	const keymapRef = useRef<Binding[]>(fullKeymap);
	keymapRef.current = fullKeymap;
	// Consumer interceptors are OUTERMOST (first-listed); the onCommand tail observer is appended
	// LAST so it sits innermost (after every consumer interceptor) and observes the real result.
	const chain = useMemo<Interceptor[]>(
		() => [...(interceptors ?? []), ...(onCommand ? [tailObserver(onCommand)] : [])],
		[interceptors, onCommand],
	);
	const ctxRef = useRef<GridCommandContext>(undefined as unknown as GridCommandContext);
	const dispatchRef = useRef<Dispatch>(undefined as unknown as Dispatch);
	dispatchRef.current = useMemo<Dispatch>(() => makeDispatch(registry, () => ctxRef.current, chain), [registry, chain]);
	const dispatch = useCallback<Dispatch>((command, native, payload) => dispatchRef.current(command, native, payload), []);

	const columns = useMemo<SheetsColumnDescriptor[]>(
		() => s.columns.map((col) => ({ key: col.id, name: col.title, size: col.width })),
		[s.columns],
	);

	// ============== COLUMN SIZING + PINNING STATE MIRROR (Stage 2) ==============
	// Sizing: project the shell's columnWidths Map → v9 ColumnSizingState; a width committed
	// by the header drag-resize handle goes STRAIGHT to resizeColumn (the same setter the canvas
	// onColumnResize uses), so the Map stays the single source of truth and the table just mirrors.
	// Pinning: pin col0 ('id') exactly when the canvas freezes it (frozenCount), else nothing —
	// GridViewport's findStickyColumnIndex falls back to col0 anyway, so the sticky column is identical.
	const columnWidths = shell.columnWidths;
	const resizeColumn = shell.resizeColumn;
	const frozenCount = shell.frozenCount;
	const firstColumnKey = shell.columnKeys[0];

	const columnSizing = useMemo<Record<string, number>>(() => {
		const sizing: Record<string, number> = {};
		columnWidths.forEach((width, key) => {
			sizing[key] = width;
		});
		return sizing;
	}, [columnWidths]);

	const columnPinning = useMemo<ColumnPinningState>(
		() => ({ start: frozenCount > 0 && firstColumnKey ? [firstColumnKey] : [], end: [] }),
		[frozenCount, firstColumnKey],
	);

	const onColumnSizingChange = useCallback<OnChangeFn<ColumnSizingState>>(
		(updater) => {
			const next = functionalUpdate(updater, columnSizing);
			for (const key of Object.keys(next)) {
				if (next[key] !== columnSizing[key]) resizeColumn(key, next[key]);
			}
		},
		[columnSizing, resizeColumn],
	);

	// ============== ROW-SELECTION STATE MIRROR (Phase 6, both directions) ==============
	// The native SheetsSelection (RangeSet of ROW indices) stays canonical; the v9
	// table only needs a derived `Record<rowId, true>` view. Both directions use the
	// same metadata-defined row key, so renamed/composite PK selections round-trip.
	const combinedRows = shell.combinedRows;
	const getRowId = shell.getRowId;
	const selection = s.selection.gridSelection;
	const setSelection = s.selection.setGridSelection;
	// Active (keyboard cursor) cell `[col, row]`, threaded to the viewport for the focus ring +
	// aria-activedescendant. Derived in render (a plain read, no setState) per the no-setState-in-render rule.
	const activeCell = selection?.current?.cell;

	const rowSelection = useMemo<RowSelectionState>(() => {
		if (!selection) return EMPTY_ROW_SELECTION;
		const map: RowSelectionState = {};
		for (const index of selection.rows.toArray()) {
			map[getRowId(combinedRows[index], index)] = true;
		}
		return map;
	}, [selection, combinedRows, getRowId]);

	const onRowSelectionChange = useCallback<OnChangeFn<RowSelectionState>>(
		(updater) => {
			const next = functionalUpdate(updater, rowSelection);
			// Map the selected row IDS back to row INDICES via combinedRows, then fold
			// into a fresh RangeSet. Active cell follows the lowest selected index (or
			// clears to the empty selection when nothing is selected).
			const indexById = new Map<string, number>();
			for (let i = 0; i < combinedRows.length; i++) indexById.set(getRowId(combinedRows[i], i), i);

			let rows = RangeSet.empty();
			let lowest: number | undefined;
			for (const id of Object.keys(next)) {
				if (!next[id]) continue;
				const index = indexById.get(id);
				if (index === undefined) continue;
				rows = rows.add(index);
				if (lowest === undefined || index < lowest) lowest = index;
			}

			if (lowest === undefined) {
				setSelection(emptySheetsSelection);
				return;
			}
			setSelection({ current: { cell: [0, lowest] }, rows, columns: RangeSet.empty() });
		},
		[rowSelection, combinedRows, getRowId, setSelection],
	);

	const table = useSheetsTableInstance({
		columns,
		data: combinedRows,
		columnSizing,
		columnPinning,
		rowSelection,
		onColumnSizingChange,
		// Pinning is shell-derived (frozenCount), never edited from the grid → no writer needed.
		onColumnPinningChange: noop,
		onRowSelectionChange,
		getRowId,
	});

	// ============== LEADING CHECKBOX / SELECT-ALL COLUMN (drives the canonical RangeSet) ==============
	// The DOM grid has no canvas rowMarkers, so the GridViewport paints a sticky checkbox column whose
	// toggles write the canonical SheetsSelection directly (the rowSelection mirror above derives FROM
	// it). selectRange/toggleRow/clear are the same pure helpers the canvas projection round-trips, so
	// shift-range and ctrl-toggle behave identically. `shiftAnchorRef` records the last-toggled index so
	// a subsequent shift-click selects the contiguous block — caller-owned, matching selectRange's contract.
	const rowCount = combinedRows.length;
	const shiftAnchorRef = useRef<number | null>(null);
	// Latch selection + rowCount so the STABLE toggle impls (ctx methods) read the latest values
	// without re-creating, while rowMarker's handlers dispatch the named commands through `dispatch`.
	const rowMarkerSelectionRef = useRef(selection);
	rowMarkerSelectionRef.current = selection;
	const rowCountRef = useRef(rowCount);
	rowCountRef.current = rowCount;
	// Verbatim toggle bodies, lifted from the previous inline rowMarker handlers — the rowMarker
	// dispatches `rowmarker.toggleRow` / `rowmarker.toggleAll`, whose commands call these.
	const toggleRowImpl = useCallback((index: number, shiftKey: boolean) => {
		const sel = rowMarkerSelectionRef.current ?? emptySheetsSelection;
		const anchor = shiftAnchorRef.current;
		const next = shiftKey && anchor !== null ? selectRange(sel, anchor, index) : toggleRow(sel, index);
		shiftAnchorRef.current = index;
		setSelection(next);
	}, [setSelection]);
	const toggleAllImpl = useCallback(() => {
		const sel = rowMarkerSelectionRef.current ?? emptySheetsSelection;
		const rc = rowCountRef.current;
		const allSelected = rc > 0 && sel.rows.length === rc;
		shiftAnchorRef.current = null;
		setSelection(
			allSelected || rc === 0
				? clear(sel)
				: { current: { cell: [0, 0] }, rows: RangeSet.fromSingleSelection([0, rc]), columns: RangeSet.empty() },
		);
	}, [setSelection]);
	const rowMarker = useMemo<RowMarker>(() => {
		const sel = selection ?? emptySheetsSelection;
		const selectedCount = sel.rows.length;
		const allSelected = rowCount > 0 && selectedCount === rowCount;
		return {
			isSelected: (index) => sel.rows.hasIndex(index),
			// Toggle handlers route through the ONE dispatch pipeline (rowmarker.toggleRow /
			// rowmarker.toggleAll); the command bodies call toggleRowImpl / toggleAllImpl (the
			// verbatim selectRange/toggleRow/clear logic lifted above).
			onToggleRow: (index, shiftKey) => dispatch('rowmarker.toggleRow', undefined, { rowIndex: index, shift: shiftKey }),
			allSelected,
			someSelected: selectedCount > 0 && !allSelected,
			onToggleAll: () => dispatch('rowmarker.toggleAll'),
		};
	}, [selection, rowCount, dispatch]);

	// Imperative getSelectedRows reads the SAME canonical RangeSet the canvas handle uses.
	const getSelectedRows = useCallback(
		(): Record<string, unknown>[] =>
			(selection?.rows.toArray() ?? []).map((i) => combinedRows[i]).filter(Boolean) as Record<string, unknown>[],
		[selection, combinedRows],
	);

	// Shared CSV export body — selected rows if any, else the loaded/filtered set. Reused by
	// the imperative SheetsHandle.exportCsv() and the toolbar Export button (handleExport).
	const runCsvExport = useCallback(
		(opts?: { columns?: string[]; filename?: string }) => {
			const selected = getSelectedRows();
			const rows = selected.length ? selected : (shell.combinedRows as Record<string, unknown>[]);
			downloadCsv(rows, opts?.columns ?? shell.columnKeys, opts?.filename);
		},
		[getSelectedRows, shell.combinedRows, shell.columnKeys],
	);

	useImperativeHandle(
		forwardedRef,
		(): SheetsHandle => ({
			scrollToRow: (index) => viewportRef.current?.scrollToIndex(index),
			submitDrafts: () => s.draft.submitDrafts(),
			refetch: () => s.refetch(),
			getSelectedRows,
			exportCsv: (opts) => runCsvExport(opts),
		}),
		[s.draft.submitDrafts, s.refetch, getSelectedRows, runCsvExport],
	);

	// ============== ADD ROW (toolbar) ==============
	// Append a draft via the shell API, then scroll it into view. appendRow resolves to the
	// new draft's index (or undefined when metadata isn't ready yet — then there's nothing to
	// scroll to). Threaded into <SheetsControls onAddRow=…> so the toolbar renders an Add-row button.
	const appendRow = s.draft.appendRow;
	const handleAddRow = useCallback(() => {
		void appendRow().then((index) => {
			if (index !== undefined) viewportRef.current?.scrollToIndex(index);
		});
	}, [appendRow]);

	// Toolbar Export button — same path as the imperative SheetsHandle.exportCsv().
	const handleExport = useCallback(() => runCsvExport({ filename: `${tableName}.csv` }), [runCsvExport, tableName]);

	// ============== SCROLL + SELECTION RESET ON SORT/FILTER CHANGE ==============
	// When sort or filter changes the infinite query re-keys and the row set is a different,
	// index-based window — so any held selection/active-cell now points at the wrong rows.
	// Per the locked decision we CLEAR selection + active cell and scroll back to the top.
	// Keyed precisely on the same sort+filter inputs the query derives its where/orderBy from,
	// so it fires only on a real sort/filter transition (not on data refetch or draft edits).
	const optionsKey = useMemo(
		() => JSON.stringify({ id: shell.sorting.id, desc: shell.sorting.desc, filter: shell.filterTree }),
		[shell.sorting.id, shell.sorting.desc, shell.filterTree],
	);
	const didMountResetRef = useRef(false);
	useEffect(() => {
		if (!didMountResetRef.current) {
			didMountResetRef.current = true;
			return;
		}
		setSelection(emptySheetsSelection);
		viewportRef.current?.scrollToIndex(0);
	}, [optionsKey, setSelection]);

	// ============== NATIVE OVERLAY EDITING (Phase 4, additive) ==============
	// Open/close state for the native React-portal overlay editor. The host measures
	// the activated cell's rect (only it knows the cell DOM node) and calls openEditor.
	const overlay = useOverlayController();
	const overlayOpen = overlay.open;
	const overlayClose = overlay.close;
	const overlayReanchor = overlay.reanchor;

	// Inject the shell's native content resolver into the cell host (Phase 3): the
	// host renders the consumer component when registered, else the kind→view map.
	// openEditor is threaded so the cell wrapper can activate the overlay editor;
	// submitDraftRow is threaded so the draft-action cell's Button can submit (Stage 4).
	const getSheetsCellContent = shell.getSheetsCellContent;
	const submitDraftRow = shell.submitDraftRow;
	const commitCellValue = shell.commitCellValue;
	const getEditorComponent = shell.cellRegistry.getEditorComponent;
	// Undo/redo handlers (stable from useUndoRedo) — wired into the edit.undo / edit.redo commands.
	const undo = shell.undo;
	const redo = shell.redo;
	// Batched commit + observational emit — threaded into the command context (commitCells/emit).
	const commitCells = shell.commitCells;
	const emit = shell.emit;

	// REF-LATCH (perf): `openEditor` is a dep of `renderCell`, which the cell host
	// memo-gates on (prev.openEditor === next.openEditor). Closing over `combinedRows` /
	// `commitCellValue` / the resolver directly would give `openEditor` a NEW identity on
	// every data/draft change, busting the per-cell memo for the ENTIRE visible window.
	// Instead we latch each churning value into a ref kept current every render and read
	// `*Ref.current` inside the callback, so `openEditor` stays referentially STABLE while
	// still seeing the latest values. (`overlayOpen` is already stable — useCallback([]) —
	// so it stays a direct, guaranteed-stable dep.)
	const getSheetsCellContentRef = useRef(getSheetsCellContent);
	getSheetsCellContentRef.current = getSheetsCellContent;
	const getEditorComponentRef = useRef(getEditorComponent);
	getEditorComponentRef.current = getEditorComponent;
	const combinedRowsRef = useRef(combinedRows);
	combinedRowsRef.current = combinedRows;
	const commitCellValueRef = useRef(commitCellValue);
	commitCellValueRef.current = commitCellValue;
	const commitCellsRef = useRef(commitCells);
	commitCellsRef.current = commitCells;
	// Read the LATEST selection inside the keydown handler so a queued move can't resurrect a
	// stale active cell right after a sort/filter clear (the optionsKey effect resets selection).
	const selectionRef = useRef(selection);
	selectionRef.current = selection;

	// EDIT-INTENT BRANCH (Stage 2): activation routes through the SINGLE edit-intent
	// resolver off the resolved `typeKey` — NOT the broken `cell.meta?.cellType ?? 'text'`
	// lookup that mis-routed every non-text cell to TextEditor. The cell-host fires this
	// on double-click / Enter / F2 (it already no-ops readonly cells); here we branch
	// BEFORE opening any overlay:
	//   • inline-toggle (booleans): commit `!currentBool` in place, no overlay.
	//   • overlay: open the portal (the editorNode block resolves intent.editor).
	//   • none (readonly / non-editable): do nothing.
	const openEditorImpl = useCallback<OpenEditor>(
		(rowIndex, colKey, anchorRect, initialText) => {
			const resolution = getSheetsCellContentRef.current(rowIndex, colKey);
			const intent = resolveEditIntent(
				resolution.typeKey,
				{ readonly: resolution.cell.readonly },
				getEditorComponentRef.current,
			);
			if (intent.mode === 'none') return;
			if (intent.mode === 'inline-toggle') {
				const current = (combinedRowsRef.current[rowIndex] as Record<string, unknown> | undefined)?.[colKey];
				commitCellValueRef.current(rowIndex, colKey, !coerceCellBoolean(current));
				return;
			}
			// inline-edit (simple text/number): edit IN PLACE — same active-cell controller (so nav/
			// clipboard suppression + scroll commit-on-unmount are shared) but the cell host renders
			// the input and the portal is skipped (editorNode is null for a non-overlay intent).
			if (intent.mode === 'inline-edit') {
				overlayOpen({ rowIndex, colKey, anchorRect, initialText, mode: 'inline' });
				return;
			}
			overlayOpen({ rowIndex, colKey, anchorRect, initialText, mode: 'overlay' });
		},
		[overlayOpen],
	);
	// The dblclick entrypoint threaded into the cell host: route through the ONE pipeline as
	// `editor.open`; the command body calls ctx.openEditorAt → openEditorImpl. STABLE (closes
	// over the stable `dispatch`), so it never busts the per-cell memo.
	const openEditor = useCallback<OpenEditor>(
		(rowIndex, colKey, anchorRect, initialText) =>
			dispatch('editor.open', undefined, { rowIndex, colKey, anchorRect, initialText }),
		[dispatch],
	);
	// ============== RANGE-AWARE BULK EDIT (Stage B) ==============
	// The editor's onCommit routes through here. When a MULTI-CELL range is selected AND the
	// active (edited) cell sits inside it, the committed value FANS OUT across the whole range
	// as ONE undo-aware batch (single optimistic patch + coalesced per-row mutations + one undo
	// entry — commitCells skips readonly/UUID internally and resolveServerPatch coerces the
	// string value PER target column). A single-cell selection (or none, or an active cell
	// outside the range) keeps the existing single-cell commit byte-for-byte. The LATEST range
	// is read off `selectionRef` so a queued sort/filter clear wins (same latch the keymap uses).
	const columnKeysRef = useRef(shell.columnKeys);
	columnKeysRef.current = shell.columnKeys;
	const commitBulkOrSingle = useCallback(
		(rowIndex: number, colKey: string, value: unknown) => {
			const range = selectionRef.current?.current?.range;
			const keys = columnKeysRef.current;
			const activeCol = keys.indexOf(colKey);
			const multiCell = !!range && range.width * range.height > 1;
			const inside =
				!!range &&
				activeCol >= 0 &&
				activeCol >= range.x &&
				activeCol < range.x + range.width &&
				rowIndex >= range.y &&
				rowIndex < range.y + range.height;
			if (multiCell && inside && range) {
				const writes = bulkEditWrites(range, value, keys);
				if (writes.length) void commitCellsRef.current(writes);
				return;
			}
			commitCellValueRef.current(rowIndex, colKey, value);
		},
		[],
	);
	// ============== CELL-RANGE SELECTION (Stage B) ==============
	// `anchorRef` holds the FIXED corner a contiguous range extends FROM. A plain activate
	// (click / non-shift Arrow) resets it to the new active cell; a shift extend keeps it put.
	// It is the caller-owned anchor `extendRangeToCell` expects (the model stays a pure value).
	const anchorRef = useRef<[number, number] | null>(null);
	const setSelectionRange = s.selection.setGridSelection;
	// Extend the contiguous range from the latched anchor to `[col, row]`. Reads the LATEST
	// selection (post-sort-clear safe) and falls back to the target as anchor when none latched.
	const extendToCell = useCallback(
		(col: number, row: number) => {
			const sel = selectionRef.current ?? emptySheetsSelection;
			const anchor = anchorRef.current ?? sel.current?.cell ?? [col, row];
			anchorRef.current = anchor;
			setSelectionRange(extendRangeToCell(sel, col, row, anchor[0], anchor[1]));
		},
		[setSelectionRange],
	);
	// Click-to-activate: park the active cell on the clicked cell. Stable (the shell's
	// setActiveCell is a stable useCallback), so it never busts the per-cell memo. Shift-click
	// EXTENDS the range from the latched anchor; a plain click activates AND resets the anchor.
	const setActiveCell = s.selection.setActiveCell;
	const handleActivateCell = useCallback(
		(col: number, row: number, shiftKey?: boolean) =>
			dispatch(shiftKey ? 'cell.extendToClicked' : 'cell.activate', undefined, { col, row }),
		[dispatch],
	);

	// ============== RIGHT-CLICK CONTEXT MENU (Stage B) ==============
	// A menu is just another EVENT SOURCE → dispatch. State is the pointer anchor (null = closed),
	// rendered ONCE at the grid level. `handleContextMenu` is STABLE (reads selectionRef + the stable
	// dispatch), so it never busts the per-cell memo. When the right-clicked cell sits OUTSIDE the
	// current active cell / selection range, we activate it first so the menu acts on the clicked cell.
	const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
	const handleContextMenu = useCallback(
		(col: number, row: number, clientX: number, clientY: number) => {
			const sel = selectionRef.current;
			const active = sel?.current?.cell;
			const range = sel?.current?.range;
			const inRange =
				!!range && col >= range.x && col < range.x + range.width && row >= range.y && row < range.y + range.height;
			const isActive = !!active && active[0] === col && active[1] === row;
			if (!isActive && !inRange) dispatch('cell.activate', undefined, { col, row });
			setContextMenu({ clientX, clientY });
		},
		[dispatch],
	);
	const closeContextMenu = useCallback(() => setContextMenu(null), []);
	// Enabled-state probe for the menu items: run the resolved command's `canRun` against the latched
	// context (same gate the dispatch core applies). A missing canRun means "always runnable".
	const isCommandEnabled = useCallback(
		(commandId: string) => {
			const cmd = registry.get(commandId);
			return cmd ? (cmd.canRun ? cmd.canRun(ctxRef.current, undefined) : true) : false;
		},
		[registry],
	);

	// ============== INLINE (IN-CELL) EDIT WIRING ==============
	// Simple text/number types edit in place via the cell host's <input> instead of the portal.
	// They ride the SAME active-editor controller (`overlay`) tagged `mode: 'inline'`, so the only
	// extra wiring here is (a) telling the editing cell to render the input and (b) commit/cancel
	// routed through the existing value-commit pipeline. The inline KEY is the editing cell identity,
	// NULL during overlay editing — so `renderCell` stays referentially stable across overlay
	// scroll-reanchors (which mutate `overlay.active.anchorRect` but never this key).
	const inlineActive = overlay.active?.mode === 'inline' ? overlay.active : null;
	const inlineKey = inlineActive ? `${inlineActive.rowIndex}:${inlineActive.colKey}` : null;
	const inlineInitialText = inlineActive?.initialText;
	const onInlineCommit = useCallback(
		(rowIndex: number, colKey: string, value: unknown) => {
			commitBulkOrSingle(rowIndex, colKey, value);
			overlayClose();
		},
		[commitBulkOrSingle, overlayClose],
	);

	const renderCell = useCallback<RenderCell>(
		(c, ctx) => {
			const editingThisCell = inlineKey != null && inlineKey === `${c.row.index}:${c.column.id}`;
			return (
				<SheetsCellHost
					cell={c}
					ctx={ctx}
					getSheetsCellContent={getSheetsCellContent}
					openEditor={openEditor}
					isEditing={editingThisCell}
					inlineInitialText={editingThisCell ? inlineInitialText : undefined}
					onInlineCommit={onInlineCommit}
					onInlineCancel={overlayClose}
					onActivateCell={handleActivateCell}
					onContextMenu={handleContextMenu}
					onSubmitDraftRow={submitDraftRow}
				/>
			);
		},
		[inlineKey, inlineInitialText, onInlineCommit, overlayClose, getSheetsCellContent, openEditor, handleActivateCell, handleContextMenu, submitDraftRow],
	);

	// ============== SPREADSHEET KEYBOARD NAV (grid root owns keys) ==============
	// The grid root (role=grid, tabIndex=0, aria-activedescendant) owns spreadsheet keys.
	// Arrows move the active cell (clamped); Enter/F2 open the overlay at the active cell.
	// IGNORE keydowns while an overlay editor is open so nav doesn't fight editing. The
	// active cell + col/row counts are read LATEST (refs) so a post-sort/filter clear wins.
	const moveActiveCell = s.selection.moveActive;
	const isOverlayOpen = overlay.isOpen;

	// Shared open-at-active-cell path (Enter / F2 / type-to-edit): resolve the active cell's
	// DOM node by its stable id, null-guarding the row (infinite-mode proxy rows can be null at
	// unloaded indices) + the colKey, then open the overlay. `initialText` seeds type-to-edit
	// (OVERWRITE). Returns true when an overlay was opened.
	const openEditorAtActiveCell = useCallback(
		(initialText?: string): boolean => {
			const cell = selectionRef.current?.current?.cell;
			if (!cell) return false;
			const [col, row] = cell;
			const rowData = combinedRowsRef.current[row];
			if (!rowData) return false;
			const colKey = columns[col]?.key;
			if (!colKey) return false;
			const node = document.getElementById(`sheets-cell-${row}-${col}`);
			if (!node) return false;
			// Open directly via the impl (NOT the dispatching `openEditor`) — this fn is itself the
			// body of the editor.openActive / editor.typeToEdit commands' canRun, so going through
			// dispatch again would double-route. Matches the original (which called openEditor directly).
			openEditorImpl(row, colKey, node.getBoundingClientRect(), initialText);
			return true;
		},
		[columns, openEditorImpl],
	);

	// Every grid key now resolves to a NAMED command through the ONE dispatch pipeline. The
	// keymap (first-match-wins) covers undo/redo/select-all/arrows/extend/abs-nav/open; an
	// UNRESOLVED key that is a single printable char (no ctrl/meta/alt) falls to the
	// `editor.typeToEdit` sentinel (also through dispatch, so it is interceptable). Any other
	// unresolved key is left untouched — NO dispatch, NO preventDefault — so it reaches the
	// browser. preventDefault lives in the dispatch CORE, gated on a resolved+runnable command.
	const handleGridKeyDown = useCallback(
		(e: React.KeyboardEvent) => {
			// Don't intercept while editing — the overlay editor owns its own keys.
			if (isOverlayOpen) return;
			const cmd = resolveKeyCommand(e.nativeEvent, keymapRef.current);
			if (cmd) {
				dispatch(cmd, e.nativeEvent, buildKeyPayload(e));
				return;
			}
			// Unresolved: only the printable-key sentinel routes through dispatch; everything
			// else falls through to the browser with no preventDefault.
			if (e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
				dispatch('editor.typeToEdit', e.nativeEvent, { char: e.key });
			}
		},
		[isOverlayOpen, dispatch],
	);

	// ============== NATIVE CLIPBOARD (Stage B) ==============
	// The grid root (role=grid, tabIndex=0) receives the browser's native copy/cut/paste events
	// when focused. We do NOT bind Ctrl/Cmd+C/X/V in the keymap — pressing them fires these native
	// events directly, so binding the keys too would double-handle. Each handler is SKIPPED while an
	// overlay editor is open (the editor owns its own clipboard) and routes through the ONE dispatch
	// pipeline as `clipboard.copy`/`cut`/`paste`, threading the native ClipboardData as the payload.
	// preventDefault happens in the dispatch core (so the browser does not also copy/paste).
	const handleCopy = useCallback(
		(e: React.ClipboardEvent) => {
			if (isOverlayOpen) return;
			dispatch('clipboard.copy', e.nativeEvent, { clipboard: (e.nativeEvent as ClipboardEvent).clipboardData });
		},
		[isOverlayOpen, dispatch],
	);
	const handleCut = useCallback(
		(e: React.ClipboardEvent) => {
			if (isOverlayOpen) return;
			dispatch('clipboard.cut', e.nativeEvent, { clipboard: (e.nativeEvent as ClipboardEvent).clipboardData });
		},
		[isOverlayOpen, dispatch],
	);
	const handlePaste = useCallback(
		(e: React.ClipboardEvent) => {
			if (isOverlayOpen) return;
			dispatch('clipboard.paste', e.nativeEvent, { clipboard: (e.nativeEvent as ClipboardEvent).clipboardData });
		},
		[isOverlayOpen, dispatch],
	);

	// FOLLOW-CELL-ON-SCROLL (Stage B): on viewport scroll, re-measure the active cell's DOM
	// node and re-anchor the overlay to it (cheap, passive — DOM read + a position state set)
	// instead of closing. If the node is GONE (the cell scrolled out of the virtual window and
	// unmounted), we COMMIT-AND-CLOSE rather than silently discard: blur the focused editor
	// element so a commit-on-blur editor (text/number) commits its in-progress value, then
	// close. (Backgrounded-tab rAF throttling is irrelevant — this runs straight off scroll.)
	const activeRef = useRef(overlay.active);
	activeRef.current = overlay.active;
	const columnsRef = useRef(columns);
	columnsRef.current = columns;
	const handleOverlayScroll = useCallback(() => {
		const a = activeRef.current;
		if (!a) return;
		// The cell DOM id is `sheets-cell-${rowIndex}-${columnIndex}` — map the stored colKey
		// back to its rendered column index (same ordering the cell host + activedescendant use).
		const colIndex = columnsRef.current.findIndex((c) => c.key === a.colKey);
		const node = colIndex >= 0 ? document.getElementById(`sheets-cell-${a.rowIndex}-${colIndex}`) : null;
		if (node) {
			// Inline edits live INSIDE the cell, so they ride the virtualized row natively — no
			// reposition needed (and reanchoring would churn state every scroll frame). Only the
			// portal overlay re-anchors to the cell on scroll.
			if (a.mode !== 'inline') overlayReanchor(node.getBoundingClientRect());
			return;
		}
		// Cell unmounted (scrolled out of the virtual window) — commit any in-progress value
		// (commit-on-blur editors, incl. the inline input) then close.
		const focused = document.activeElement;
		if (focused instanceof HTMLElement) focused.blur();
		overlayClose();
	}, [overlayReanchor, overlayClose]);

	// Resolve the active editor + its EditorProps. Computed in render (cheap, only when
	// an overlay is open) — the cell resolution, value, native editor and flip geometry
	// all derive from overlay.active, so no effect/state mirror is needed.
	const active = overlay.active;
	const editorNode = (() => {
		if (!active) return null;
		const resolution = getSheetsCellContent(active.rowIndex, active.colKey);
		// Resolve the editor through the SAME edit-intent resolver the activation branch
		// used (typeKey-driven, consumer-override aware). Only `overlay` intents ever open
		// here (openEditor short-circuits inline-toggle/none), but resolving again keeps a
		// single source of truth — and guards against a non-overlay intent slipping through.
		const intent = resolveEditIntent(resolution.typeKey, { readonly: resolution.cell.readonly }, getEditorComponent);
		if (intent.mode !== 'overlay') return null;
		const Editor = intent.editor;
		const rowValue = (combinedRows[active.rowIndex] as Record<string, unknown> | undefined)?.[active.colKey];
		const geom = computeOverlayGeometry(
			typeof window !== 'undefined' ? window.innerHeight : 800,
			active.anchorRect.top,
			active.anchorRect.height,
			OVERLAY_MARGIN_PX,
			OVERLAY_MIN_BELOW_PX,
		);
		return {
			presetClass: Editor.overlayPresetClass,
			// Commit-on-click-away (Stage B): editors that own an onBlur→onCommit advertise it
			// so the OverlayManager dismisses by blurring (commit) instead of cancelling.
			dismissMode: Editor.commitsOnBlur ? ('commit' as const) : ('cancel' as const),
			element: (
				<Editor
					value={rowValue}
					cell={resolution.cell}
					colKey={active.colKey}
					rowId={getRowId(combinedRows[active.rowIndex], active.rowIndex)}
					rowIndex={active.rowIndex}
					tableName={props.tableName}
					fieldMeta={resolution.fieldMeta}
					relationInfo={resolution.relationInfo}
					initialText={active.initialText}
					onCommit={(next) => {
						commitBulkOrSingle(active.rowIndex, active.colKey, next);
						overlayClose();
					}}
					onCommitPatch={(patch) => {
						shell.commitCellPatch(active.rowIndex, patch);
						overlayClose();
					}}
					onSubmitDraftRow={shell.submitDraftRow}
					onInvalidateData={shell.invalidateData}
					onCancel={overlayClose}
					overlay={{ maxHeight: geom.maxHeight, flipped: geom.shouldFlip }}
				/>
			),
		};
	})();

	// INFINITE SCROLL: the virtualizer COUNT is left to its default (`rows.length`) — in
	// infinite mode `combinedRows` IS the full-length proxy (`serverRowCount + drafts`, null-backing
	// unloaded indices), so `rows.length` already spans every lazy row AND includes drafts; forcing
	// `count = totalCount` would drop the appended draft rows. We only wire the prefetch handler:
	// the viewport's overscan-inclusive {startIndex,endIndex} window IS the native range the shell
	// prefetches against (handleVisibleRegionChanged no-ops when paginated + clamps to the server
	// row count, but we still attach only in infinite mode, matching the prior paginated omission).
	const onVisibleRegionChanged = shell.onVisibleRegionChanged;
	const onVisibleRangeChange = useCallback(
		(range: VisibleRange) => {
			onVisibleRegionChanged(range);
		},
		[onVisibleRegionChanged],
	);

	// Sort caret state mirror (the shell owns it via useGridState). The shell's onHeaderClicked is
	// the sort toggle keyed by colIndex (the draft-action column is excluded as non-sortable); the
	// DOM header speaks colKey, so map back to the colIndex it expects via columnKeys.
	const sorting = shell.sorting;
	const onHeaderClicked = shell.onHeaderClicked;
	const columnKeys = shell.columnKeys;
	// Header click routes through the ONE pipeline as `header.sortToggle`; the command body calls
	// ctx.sortToggle(colKey), which maps the colKey back to the colIndex onHeaderClicked expects.
	const onHeaderClick = useCallback((colKey: string) => dispatch('header.sortToggle', undefined, { colKey }), [dispatch]);

	// Fill-handle drag release routes through the ONE pipeline as `fill.drag`; the command extends
	// the source band toward `target`, replicates the source values, and widens the selection.
	const handleFillDrag = useCallback(
		(sourceRange: SelectionRect, target: [number, number]) => dispatch('fill.drag', undefined, { from: sourceRange, to: target }),
		[dispatch],
	);

	// ============== ASSEMBLE + LATCH THE GRID COMMAND CONTEXT ==============
	// ONE object the commands run against: live GETTERS read the existing refs/derived render
	// values; methods are the EXISTING stable callbacks wrapped VERBATIM (no dispatcher is
	// reinvented). Rebuilt each render (cheap) and REPOINTED into `ctxRef` so `dispatch`
	// (stable, reads ctxRef.current) always sees the latest values — mirrors the openEditor
	// ref-latch. The pointer callbacks threaded into renderCell close over `dispatch`, not this,
	// so the per-cell memo is unaffected.
	ctxRef.current = {
		get rowCount() {
			return combinedRowsRef.current.length;
		},
		get colCount() {
			return columnsRef.current.length;
		},
		get activeCell() {
			return selectionRef.current?.current?.cell;
		},
		get selection() {
			return selectionRef.current;
		},
		get combinedRows() {
			return combinedRowsRef.current;
		},
		get columnKeys() {
			return columnsRef.current.map((c) => c.key);
		},
		getAnchor: () => anchorRef.current,
		setAnchor: (anchor) => {
			anchorRef.current = anchor;
		},
		setActiveCell,
		moveActiveCell,
		extendToCell,
		setSelection: setSelectionRange,
		commitCells,
		openEditorAtActive: openEditorAtActiveCell,
		openEditorAt: openEditorImpl,
		undo,
		redo,
		scrollToCell: (col, row) => viewportRef.current?.scrollToCell(col, row),
		sortToggle: (colKey) => onHeaderClicked(columnKeys.indexOf(colKey)),
		toggleRow: toggleRowImpl,
		toggleAll: toggleAllImpl,
		getCellsInRange: (rect: SelectionRect): CellMatrix => {
			const r = extractCellsInRange(rect, combinedRowsRef.current, columnsRef.current.map((c) => c.key));
			return { cols: r.cols, rows: r.rows, values: r.values };
		},
		toTSV: (values) => serializeTSV(values),
		emit,
	} satisfies GridCommandContext;

	// ============== LOAD STATES ==============
	// Surface real error/empty/loading states instead of a blank grid (moved here from
	// the removed canvas branch). The full-screen error is for INITIAL-load failure only
	// (no server rows AND no drafts); background-refetch errors keep the populated grid
	// mounted and surface via the `load:error` onEvent emission instead.
	if (s.dataError && shell.combinedRows.length === 0) {
		const retry = () => s.refetch();
		if (slots?.error) {
			return <>{slots.error({ error: s.dataError, retry })}</>;
		}
		return <SheetsErrorState error={s.dataError} onRetry={retry} />;
	}

	// Initial load only; same-scope refetches retain their current query data.
	if (s.isInitialLoading) {
		if (slots?.loading) return <>{slots.loading}</>;
		return <SheetsLoadingState />;
	}

	// Loaded successfully but no server rows and nothing drafted yet (and no active filter).
	if (s.isEmpty) {
		if (slots?.empty) {
			return <>{typeof slots.empty === 'function' ? slots.empty({ tableName }) : slots.empty}</>;
		}
		return (
			<SheetsEmptyState
				tableName={tableName}
				readOnlyReason={shell.readOnlyReason}
				onAddRow={shell.canCreate ? () => {
					void s.draft.appendRow();
				} : undefined}
			/>
		);
	}

	// Filtered-empty: the server returned 0 rows while a filter is active (so `isEmpty` above is
	// false — it requires no filter). Without this the body renders blank under the header and looks
	// broken; instead we keep the toolbar/filter bar mounted and overlay a "No matching rows" panel
	// with a one-click clear back to the unfiltered set.
	const activeFilterCount = shell.filterTree ? countConditions(shell.filterTree) : 0;
	const isFilteredEmpty = shell.serverRowCount === 0 && shell.draftRowCount === 0 && activeFilterCount > 0;

	return (
		<SheetsErrorBoundary onError={config.onError}>
			{/* Controls — consumer toolbar slot replaces the default <SheetsControls> block. */}
			<div data-part-id='sheets-controls-container'>
				{slots?.toolbar ? (
					<>{typeof slots.toolbar === 'function' ? slots.toolbar({ tableName }) : slots.toolbar}</>
				) : (
					<SheetsControls
						filterTree={shell.filterTree}
						setFilterTree={shell.setFilterTree}
						filtersOpen={shell.filtersOpen}
						setFiltersOpen={shell.setFiltersOpen}
						clearAllFilters={shell.clearAllFilters}
						applyFilters={shell.applyFilters}
						columnKeys={shell.columnKeys}
						fieldTypeMap={shell.fieldTypeMap}
						showSelection={showSelection}
						gridSelection={s.selection.gridSelection ?? null}
						setGridSelection={shell.setGridSelectionForControls}
						deleteSelected={s.draft.deleteSelected}
						onAddRow={shell.canCreate ? handleAddRow : undefined}
						canDelete={shell.canDelete}
						readOnlyReason={shell.readOnlyReason}
						onExport={handleExport}
					/>
				)}
			</div>

			<div
				data-part-id='sheets-container'
				role='region'
				aria-label={`${tableName} table`}
				className={cn('bg-background relative isolate h-full min-h-0 flex-1 overflow-hidden rounded-lg border', className)}
			>
				<GridViewport
					table={table}
					renderCell={renderCell}
					handleRef={viewportRef}
					onScroll={handleOverlayScroll}
					sorting={sorting}
					onHeaderClick={onHeaderClick}
					onResize={resizeColumn}
					onVisibleRangeChange={infiniteScroll ? onVisibleRangeChange : undefined}
					rowMarker={showSelection ? rowMarker : undefined}
					activeCell={activeCell}
					activeRange={s.selection.gridSelection?.current?.range}
					onGridKeyDown={handleGridKeyDown}
					onCopy={handleCopy}
					onCut={handleCut}
					onPaste={handlePaste}
					onFillDrag={handleFillDrag}
					activeDescendantId={activeCell ? `sheets-cell-${activeCell[1]}-${activeCell[0]}` : undefined}
				/>

				{/* Filtered-empty panel — overlays the empty body while the filter bar stays visible above. */}
				{isFilteredEmpty && (
					<div className='bg-background/80 absolute inset-0 flex flex-col items-center justify-center gap-3 p-6 text-center'>
						<RiSearchEyeLine className='text-muted-foreground h-8 w-8' />
						<div className='space-y-1'>
							<p className='text-foreground text-sm font-medium'>No matching rows</p>
							<p className='text-muted-foreground max-w-md text-sm'>
								No rows match the active {activeFilterCount === 1 ? 'filter' : 'filters'}.
							</p>
						</div>
						<Button variant='outline' size='sm' onClick={shell.clearAllFilters}>
							<RiFilterOffLine className='h-4 w-4' />
							<span className='ms-1'>Clear filters</span>
						</Button>
					</div>
				)}

				{/* Floating status indicator — surfaces save/delete/submit feedback from the FeedbackProvider. */}
				<div className='pointer-events-none absolute bottom-4 left-1/2 z-10 -translate-x-1/2'>
					<FloatingStatus />
				</div>
			</div>

			{/* Pagination — hidden in infinite scroll mode (canvas parity). */}
			{showPagination && !infiniteScroll && s.pagination.pageCount > 1 && (
				<SheetsPagination
					pageIndex={s.pagination.pageIndex}
					pageSize={pageSize}
					totalCount={shell.totalCount}
					totalPages={s.pagination.pageCount}
					setPageIndex={s.pagination.setPageIndex}
				/>
			)}

			<OverlayManager
				open={overlay.isOpen && editorNode != null}
				anchorRect={active?.anchorRect ?? null}
				presetClass={editorNode?.presetClass}
				dismissMode={editorNode?.dismissMode}
				onCancel={overlayClose}
			>
				{editorNode?.element}
			</OverlayManager>

			{/* Right-click context menu — items dispatch through the SAME pipeline as keys/clicks
			    (clipboard.* with no native event take the navigator.clipboard fallback). Rendered once. */}
			<SheetsContextMenu
				state={contextMenu}
				onClose={closeContextMenu}
				onAction={(commandId) => dispatch(commandId)}
				isEnabled={isCommandEnabled}
				onAddRow={handleAddRow}
				onDeleteRows={s.draft.deleteSelected}
				selectedRowCount={selection?.rows.length ?? 0}
				canAddRows={shell.canCreate}
				canDeleteRows={shell.canDelete}
			/>
		</SheetsErrorBoundary>
	);
}

// Public props alias — generic over the consumer's row type (default SheetsRow keeps
// existing untyped callers compiling). Carries DataGridProps' TRow through.
export type SheetsProps<TRow extends SheetsRow = SheetsRow> = DataGridProps<TRow>;

import type { SheetsRow } from './row-model';
import type { CellTypeDefinition } from '../cell-types/define-cell-type';
import type { CellSlots } from '../cell-model/cell-slots';
// SheetsThemeInput is owned + exported by Unit B (./sheets.theme). Imported as a type
// only; if Unit B's change has not landed yet this import is the single expected
// cross-unit transient error — both units typecheck once they land together.
import type { SheetsThemeInput } from './sheets.theme';
import type { GridCommand, Binding, Interceptor, DispatchEvent, CommandResult } from '../commands';
import type { SheetsRowIdentifier } from '../row-identity';

export interface DataGridRow {
	id: string;
	[key: string]: any;
}

// =============================================================================
// Public component API — events, render slots, imperative handle
// =============================================================================

/**
 * Lifecycle/interaction event emitted by {@link Sheets} via the optional
 * `onEvent` prop. Purely observational: firing an event never changes grid
 * behavior, so consumers can wire analytics/telemetry without side effects.
 */
export interface SheetsEvent {
	type:
		| 'load:success'
		| 'load:error'
		| 'cell:edit'
		| 'row:create'
		| 'row:delete'
		| 'filter:apply'
		| 'sort:change'
		| 'page:change';
	/** The table the event originated from. */
	tableName: string;
	/** Epoch ms (`Date.now()`) when the event fired. */
	at: number;
	/** Event-specific extra context (ids, values, error, page index, …). */
	meta?: Record<string, unknown>;
}

/** Context passed to the `toolbar` slot when supplied as a render function. */
export interface SheetsToolbarSlotContext {
	tableName: string;
}

/**
 * Render-slot overrides. Each provided slot replaces the corresponding default
 * (the Phase-0 SheetsErrorState / SheetsEmptyState / SheetsLoadingState stay as
 * fallbacks when a slot is omitted). All slots are optional and additive.
 */
export interface SheetsSlots {
	/** Replaces (precedes) the default <SheetsControls> toolbar block. */
	toolbar?: React.ReactNode | ((ctx: SheetsToolbarSlotContext) => React.ReactNode);
	/** Replaces the default full-screen empty state. */
	empty?: React.ReactNode | ((ctx: { tableName: string }) => React.ReactNode);
	/** Replaces the default full-screen error state. */
	error?: (ctx: { error: unknown; retry: () => void }) => React.ReactNode;
	/** Replaces the default full-screen loading state. */
	loading?: React.ReactNode;
}

/**
 * Alias kept in sync with {@link SheetsSlots}. The `slots` prop is typed with
 * this name to match the shared Phase-4 contract; `SheetsSlots` is the exported
 * public name.
 */
export type SheetsSlotsInput = SheetsSlots;

/**
 * Imperative handle exposed through a `ref` on {@link Sheets}. Lets host apps
 * drive the grid (scroll, submit drafts, refetch, read selection, export CSV)
 * without reaching into internals.
 */
export interface SheetsHandle {
	/** Scroll the viewport so the row at `index` is visible. */
	scrollToRow(index: number): void;
	/** Submit all pending draft rows (awaits the in-flight submission). */
	submitDrafts(): Promise<void>;
	/** Refetch the underlying table data (mode-aware: infinite vs paginated). */
	refetch(): void;
	/** Return the currently selected rows (empty array when nothing selected). */
	getSelectedRows(): Record<string, unknown>[];
	/** Download the selected rows (or all rows when none selected) as CSV. */
	exportCsv(opts?: { columns?: string[]; filename?: string }): void;
}

export interface DataGridColumnMeta {
	fieldName: string;
	fieldType: {
		gqlType: string;
		pgType?: string | null;
		pgAlias?: string | null;
	};
}

export interface DataGridProps<TRow extends SheetsRow = SheetsRow> {
	tableName: string;
	className?: string;
	pageSize?: number;
	showSelection?: boolean;
	showPagination?: boolean;
	onRowSelect?: (selectedRows: TRow[]) => void;
	onCellEdit?: (id: SheetsRowIdentifier, field: string, value: unknown) => void;
	// Relation rendering options
	relationChipLimit?: number;
	relationLabelMaxLength?: number;
	/**
	 * Enable infinite scroll mode with cursor-based pagination.
	 * When enabled:
	 * - Rows are loaded on-demand as user scrolls
	 * - Traditional pagination UI is hidden
	 * - Uses hybrid cursor/offset pagination for optimal performance
	 * @default false
	 */
	infiniteScroll?: boolean;
	/** Per-instance cell types merged over provider plugins. */
	cellTypes?: CellTypeDefinition<any>[];
	/** Consumer cell-component overrides keyed by cell typeKey. */
	cellSlots?: CellSlots;
	/**
	 * Optional observational event callback. Fired on load success/error, cell
	 * edits, row create/delete, filter apply, sort change, and page change.
	 * Omitting it leaves behavior unchanged.
	 */
	onEvent?: (e: SheetsEvent) => void;
	/**
	 * Optional render-slot overrides for the toolbar / empty / error / loading
	 * regions. Any omitted slot falls back to the built-in default.
	 */
	slots?: SheetsSlotsInput;
	/**
	 * Override or extend the grid command set: a command with a matching id REPLACES
	 * the built-in body, a new id ADDS a command. Omitting it = the default set.
	 */
	commands?: GridCommand[];
	/**
	 * Extra / override key bindings, scanned BEFORE the defaults (first-match-wins),
	 * so a rebind of a built-in chord wins. Omitting it = the default keymap.
	 */
	keymap?: Binding[];
	/**
	 * Interceptors wrapping every dispatch (observe / veto / transform). Listed FIRST
	 * = OUTERMOST; the consumer list runs outside the `onCommand` tail observer.
	 */
	interceptors?: Interceptor[];
	/**
	 * Observe every dispatch and its result (sugar for an innermost tail-observer
	 * interceptor — runs after all consumer interceptors, never alters behavior).
	 */
	onCommand?: (ev: DispatchEvent, result: CommandResult) => void;
	/** Optional theme token overrides (per light/dark mode) or a Glide-theme function. */
	theme?: SheetsThemeInput;
	/** Optional explicit theme mode; defaults to following the document `dark` class. */
	themeMode?: 'light' | 'dark' | 'system';
	/**
	 * @internal Render-path switch for the TanStack DOM port spike. `'dom'`
	 * renders the native DOM grid; anything else (default) renders the canvas
	 * `<DataEditor>`. Double-underscore = internal/undocumented; NOT a public API.
	 */
	__impl?: 'canvas' | 'dom';
}

import { CellRegistry } from '../cell-types/cell-registry';
import { prepareCreateInput, type MetaField, type Filter } from '@constructive-io/data';
import { mapToFrontendCellType } from '../cell-types/type-mapping';
import type { RelationInfo } from '../store/relation-info-slice';

import type { FieldMetadata } from '../cell-types/cell-type-resolver';
import type { FilterCondition, FilterGroup, FilterNode, FilterValue } from './sheets.controls';
import { isFilterableType, isValuelessOperator } from './filter-operators';
import { compactJsonPreview } from './sheets.formatters';

export function formatColumnHeader(fieldName: string): string {
	return fieldName
		.replace(/([A-Z])/g, ' $1')
		.replace(/^./, (str) => str.toUpperCase())
		.replace(/_/g, ' ')
		.trim();
}

export function getColumnWidthByMeta(field: FieldMetadata): number {
	const t = field.type;
	if (!t) return 150;
	const cellType = mapToFrontendCellType({
		gqlType: t.gqlType,
		isArray: !!t.isArray,
		pgAlias: t.pgAlias,
		pgType: t.pgType,
		subtype: t.subtype ?? null,
	});
	const entry = CellRegistry.get(cellType);
	return entry?.metadata?.width ?? 150;
}

type FilterableFieldMeta = {
	name?: string | null;
	type?: {
		gqlType?: string | null;
		isArray?: boolean | null;
		pgType?: string | null;
	} | null;
};

type FilterableTableMeta = {
	fields?: Array<FilterableFieldMeta | null> | null;
} | null | undefined;

/** Coerce a raw string value to the appropriate JS type based on gqlType. */
function coerceFilterValue(gqlType: string | null | undefined, strVal: string): unknown {
	switch (gqlType) {
		case 'Int': {
			const n = parseInt(strVal, 10);
			return Number.isNaN(n) ? null : n;
		}
		case 'Float': {
			const n = parseFloat(strVal);
			return Number.isNaN(n) ? null : n;
		}
		case 'Interval': {
			// Value is a JSON-encoded IntervalInput object from the structured UI
			try {
				const obj = JSON.parse(strVal);
				if (obj && typeof obj === 'object' && !Array.isArray(obj)) return obj;
				return null;
			} catch {
				return null;
			}
		}
		// Everything else passes through as string
		default:
			return strVal;
	}
}

/**
 * Build the filter expression for a single field using an explicit operator.
 * Returns null for types that cannot be filtered (arrays, GeoJSON, FullText, unknown types).
 */
function buildFieldFilter(
	fieldMeta: FilterableFieldMeta | null | undefined,
	operator: string,
	rawValue: FilterValue,
): Record<string, unknown> | null {
	// Value-less operators encode their value in the operator name
	if (isValuelessOperator(operator)) {
		if (operator === 'isNull') return { isNull: true };
		if (operator === 'equalTo:true') return { equalTo: true };
		if (operator === 'equalTo:false') return { equalTo: false };
	}

	const gqlType = fieldMeta?.type?.gqlType;
	const isArray = !!fieldMeta?.type?.isArray;

	// Skip unfilterable types (arrays, GeoJSON, FullText, unknown)
	if (!isFilterableType(gqlType, isArray)) return null;

	const strVal = String(rawValue);
	const coerced = coerceFilterValue(gqlType, strVal);
	if (coerced === null) return null;

	return { [operator]: coerced };
}

/** Convert a single condition node to a PostGraphile filter expression. */
function conditionToWhere(
	condition: FilterCondition,
	fieldsByName: Map<string, FilterableFieldMeta>,
): Filter | null {
	// Skip empty-value conditions (unless valueless operator)
	if (
		!isValuelessOperator(condition.operator) &&
		(condition.value === '' || condition.value === null || condition.value === undefined)
	) {
		return null;
	}
	const fieldMeta = fieldsByName.get(condition.field);
	const filterExpr = buildFieldFilter(fieldMeta, condition.operator, condition.value);
	return filterExpr ? ({ [condition.field]: filterExpr } as Filter) : null;
}

/** Recursively convert a filter tree node to a PostGraphile Filter object. */
function filterNodeToWhere(
	node: FilterNode,
	fieldsByName: Map<string, FilterableFieldMeta>,
): Filter | null {
	if (node.type === 'condition') {
		return conditionToWhere(node, fieldsByName);
	}

	const childFilters = node.children
		.map((child) => filterNodeToWhere(child, fieldsByName))
		.filter((f): f is Filter => f !== null);

	if (childFilters.length === 0) return null;
	if (childFilters.length === 1) return childFilters[0];
	return { [node.conjunction]: childFilters };
}

export function buildWhereFromFilters(
	filterTree: FilterGroup,
	tableMeta: FilterableTableMeta,
): Filter | undefined {
	if (!filterTree.children.length) return undefined;

	// Pre-build field lookup map
	const fieldsByName = new Map<string, FilterableFieldMeta>();
	for (const field of tableMeta?.fields ?? []) {
		if (field?.name) fieldsByName.set(field.name, field);
	}

	const treeWhere = filterNodeToWhere(filterTree, fieldsByName);
	return treeWhere ?? undefined;
}

export function mapFromFieldMetaMap(fieldMetaMap: Map<string, MetaField>): Record<string, MetaField | undefined> {
	const record: Record<string, MetaField | undefined> = {};
	fieldMetaMap.forEach((value, key) => {
		record[key] = value;
	});
	return record;
}

export function mapFromRelationInfoMap(
	relationInfoMap: Map<string, RelationInfo | undefined>,
): Record<string, RelationInfo | undefined> {
	const record: Record<string, RelationInfo | undefined> = {};
	relationInfoMap.forEach((value, key) => {
		record[key] = value;
	});
	return record;
}

function unwrapConnectionNode(entry: unknown): unknown {
	if (!entry || typeof entry !== 'object') return entry;

	const record = entry as Record<string, unknown>;
	if ('node' in record && record.node !== undefined) {
		return unwrapConnectionNode(record.node);
	}
	return entry;
}

export function unwrapRelationValue<T = unknown>(value: T): T {
	if (Array.isArray(value)) {
		return value.map((entry) => unwrapRelationValue(entry)) as unknown as T;
	}

	if (value && typeof value === 'object') {
		const record = value as Record<string, unknown>;

		if (Array.isArray(record.nodes)) {
			return record.nodes.map((entry) => unwrapRelationValue(entry)) as unknown as T;
		}

		if (Array.isArray(record.edges)) {
			return record.edges.map((edge) => unwrapRelationValue(unwrapConnectionNode(edge))) as unknown as T;
		}

		if ('node' in record && record.node !== undefined) {
			return unwrapRelationValue(record.node) as unknown as T;
		}
	}

	return value;
}

export function normalizeServerRow(row: Record<string, unknown>, relationFields: Set<string>): Record<string, unknown> {
	if (!row || typeof row !== 'object') {
		return row;
	}

	const next: Record<string, unknown> = { ...row };
	relationFields.forEach((fieldName) => {
		next[fieldName] = unwrapRelationValue(next[fieldName]);
	});
	return next;
}

interface DraftSubmissionOptions {
	allowedColumns?: ReadonlySet<string>;
	relationInfoByKey?: Record<string, RelationInfo | undefined>;
}

export interface DraftValidationFieldMeta {
	name?: string | null;
	isNotNull?: boolean | null;
	hasDefault?: boolean | null;
	type?: { gqlType?: string | null; isArray?: boolean | null } | null;
}

export function validateDraftRowRequiredFields(
	values: Record<string, unknown>,
	fieldMetaByKey: Record<string, DraftValidationFieldMeta | undefined>,
	options?: {
		allowedColumns?: ReadonlySet<string>;
		relationInfoByKey?: Record<string, RelationInfo | undefined>;
	},
): Record<string, string> {
	const errors: Record<string, string> = {};
	const { allowedColumns, relationInfoByKey } = options ?? {};
	const allowsAll = !allowedColumns || allowedColumns.size === 0;

	for (const [key, meta] of Object.entries(fieldMetaByKey)) {
		if (!meta) continue;
		if (!meta.isNotNull) continue;
		if (meta.hasDefault) continue;
		if (key === 'id') continue;
		if (!allowsAll && !allowedColumns?.has(key)) continue;

		const relInfo = relationInfoByKey?.[key];
		if (relInfo && relInfo.relationField === key) continue;

		const value = values[key];
		if (value == null || value === '') {
			errors[key] = `${formatColumnHeader(key)} is required`;
		}
	}

	return errors;
}

export function prepareDraftSubmissionPayload(
	values: Record<string, unknown>,
	options: DraftSubmissionOptions = {},
): Record<string, unknown> {
	const { allowedColumns, relationInfoByKey } = options;
	const allowsAll = !allowedColumns || allowedColumns.size === 0;

	// Step 1: Filter nullish values using centralized utility
	// Draft submission is a CREATE operation, so null/undefined are filtered
	const { id: _id, ...valuesWithoutId } = values;
	const filtered = prepareCreateInput(valuesWithoutId);

	// Step 2: Apply relation-specific transformations
	const payload: Record<string, unknown> = {};

	const normalizeForeignKeyValue = (input: unknown): unknown => {
		if (input === undefined || input === null) return undefined;

		const extractId = (candidate: unknown): string | number | null => {
			if (candidate === null || candidate === undefined) return null;
			if (typeof candidate === 'object') {
				const record = candidate as Record<string, unknown>;
				const id = record.id;
				if (typeof id === 'string' || typeof id === 'number') {
					return id;
				}
				return null;
			}
			if (typeof candidate === 'string' || typeof candidate === 'number') {
				return candidate;
			}
			return null;
		};

		if (Array.isArray(input)) {
			return input
				.map((entry) => extractId(entry))
				.filter((entry): entry is string | number => entry !== undefined && entry !== null);
		}

		return extractId(input);
	};

	for (const [key, value] of Object.entries(filtered)) {
		const isAllowed = allowsAll || allowedColumns?.has(key);
		if (!isAllowed) continue;

		const relInfo = relationInfoByKey?.[key];

		if (relInfo?.relationField === key) {
			// Skip relation display fields; rely on the corresponding foreign key entry
			continue;
		}

		if (relInfo?.foreignKeyField === key) {
			const normalized = normalizeForeignKeyValue(value);
			if (normalized === undefined) continue;
			payload[key] = normalized;
			continue;
		}

		payload[key] = value;
	}

	return payload;
}

export function prepareDraftRelationValue(
	rawValue: unknown,
	relationInfo: RelationInfo,
): {
	relationData: unknown;
	foreignKeyUpdates?: Record<string, unknown>;
	relationReferences?: unknown;
} {
	let value = rawValue;

	if (typeof value === 'string') {
		const trimmed = value.trim();
		if (!trimmed) {
			value = null;
		} else {
			try {
				value = JSON.parse(trimmed);
			} catch {
				value = trimmed;
			}
		}
	}

	const isListRelation = relationInfo.kind === 'hasMany' || relationInfo.kind === 'manyToMany';

	if (isListRelation) {
		const entries = Array.isArray(value) ? value : value == null ? [] : [value];
		const normalized = entries
			.map(normalizeRelationEntry)
			.filter((entry): entry is RelationNormalization => entry !== null);

		const relationData = normalized.map((entry) => entry.value);
		const relationReferences = normalized.map((entry) => entry.reference ?? null);

		const fkField = relationInfo.foreignKeyField;
		const foreignKeyUpdates = fkField
			? {
					[fkField]: normalized.map((entry) => (entry.reference === undefined ? null : entry.reference)),
				}
			: undefined;

		return {
			relationData,
			foreignKeyUpdates,
			relationReferences,
		};
	}

	const normalizedEntry = normalizeRelationEntry(Array.isArray(value) ? (value[0] ?? null) : value);

	const relationData = normalizedEntry?.value ?? null;
	const relationReference = normalizedEntry?.reference ?? null;

	const fkField = relationInfo.foreignKeyField;
	const foreignKeyUpdates = fkField
		? {
				[fkField]: normalizedEntry?.reference ?? null,
			}
		: undefined;

	return {
		relationData,
		foreignKeyUpdates,
		relationReferences: relationReference,
	};
}

type RelationNormalization = {
	value: unknown;
	reference: string | number | null | undefined;
};

function normalizeRelationEntry(entry: unknown): RelationNormalization | null {
	if (entry === null || entry === undefined || entry === '') {
		return null;
	}

	if (Array.isArray(entry)) {
		return normalizeRelationEntry(entry[0]);
	}

	if (typeof entry === 'object') {
		const record = entry as Record<string, unknown>;
		const id = record.id;
		return {
			value: record,
			reference: typeof id === 'string' || typeof id === 'number' ? (id as string | number) : null,
		};
	}

	if (typeof entry === 'string' || typeof entry === 'number') {
		return {
			value: entry,
			reference: entry,
		};
	}

	return null;
}

// Infer cell type from data content when location/metadata is not available
export function inferCellTypeFromData(data: string): string | undefined {
	if (!data || typeof data !== 'string') return undefined;

	try {
		const parsed = JSON.parse(data);

		// Check for geometry data patterns (wrapped format with geojson property)
		if (parsed && typeof parsed === 'object' && parsed.geojson) {
			// This is the wrapped geometry format: {"geojson": {...}, "srid": ..., "x": ..., "y": ...}
			// But sometimes it might only have the geojson property
			if (parsed.geojson.type === 'Point') {
				return 'geometry-point';
			} else if (parsed.geojson.type === 'GeometryCollection') {
				return 'geometry-collection';
			} else {
				return 'geometry';
			}
		}

		// Check for raw GeoJSON (direct GeoJSON object)
		if (parsed && typeof parsed === 'object' && parsed.type && parsed.coordinates) {
			const validGeoJSONTypes = [
				'Point',
				'LineString',
				'Polygon',
				'MultiPoint',
				'MultiLineString',
				'MultiPolygon',
				'GeometryCollection',
			];
			if (validGeoJSONTypes.includes(parsed.type)) {
				if (parsed.type === 'Point') {
					return 'geometry-point';
				} else if (parsed.type === 'GeometryCollection') {
					return 'geometry-collection';
				} else {
					return 'geometry';
				}
			}
		}

		// Check for array data
		if (Array.isArray(parsed)) {
			return 'array';
		}

		// Check for interval data (objects with days/hours/minutes/seconds properties)
		if (
			parsed &&
			typeof parsed === 'object' &&
			(parsed.days !== undefined ||
				parsed.hours !== undefined ||
				parsed.minutes !== undefined ||
				parsed.seconds !== undefined)
		) {
			return 'interval';
		}

		// Check for image data (objects with url/src/href/path properties)
		if (parsed && typeof parsed === 'object' && (parsed.url || parsed.src || parsed.href || parsed.path)) {
			return 'image';
		}

		// Check for date strings (ISO format)
		if (typeof parsed === 'string' && /^\d{4}-\d{2}-\d{2}/.test(parsed)) {
			if (parsed.includes('T')) {
				return 'datetime';
			} else {
				return 'date';
			}
		}

		// Generic JSON object
		return 'json';
	} catch {
		// Not valid JSON, could be other data types

		// Check for date strings
		if (/^\d{4}-\d{2}-\d{2}/.test(data)) {
			if (data.includes('T')) {
				return 'datetime';
			} else {
				return 'date';
			}
		}

		// Check for time strings
		if (/^\d{2}:\d{2}/.test(data)) {
			return 'time';
		}

		return undefined;
	}
}

// Utility functions for array previews
export function formatArrayPreview(arr: any[]): string {
	const max = 3;
	const items = arr.slice(0, max).map((v) => (typeof v === 'object' ? compactJsonPreview(v, 20) : String(v)));
	const more = arr.length > max ? ` +${arr.length - max}` : '';
	return items.join(', ') + more;
}


// Row operations
export async function handleRowAppend(
	createFunction: (data: any) => Promise<any>,
): Promise<'top' | 'bottom' | number | undefined> {
	const { createdRow } = await createFunction({});
	if (createdRow) {
		return 'bottom';
	}
	return undefined;
}

// Type-safe header click handler for sorting
// Only allows sorting on columns in the sortableColumns set (excludes relation columns)
export function createHeaderClickHandler(
	columnKeys: string[],
	toggleSorting: (colId: string) => void,
	sortableColumns?: Set<string>,
) {
	return (colIndex: number) => {
		const colId = columnKeys[colIndex];
		if (!colId) return;

		// If sortableColumns is provided, only allow sorting on those columns
		if (sortableColumns && !sortableColumns.has(colId)) {
			return;
		}

		toggleSorting(colId);
	};
}

// Type-safe column resize handler
export function createColumnResizeHandler(resizeColumn: (id: string, width: number) => void) {
	return (column: { id?: string }, newSize: number) => {
		if (column.id) {
			resizeColumn(column.id, newSize);
		}
	};
}

/**
 * useSheets — headless grid assembly hook.
 *
 * Computes the data/state bindings the default {@link Sheets} component renders
 * with the native TanStack DOM grid: columns, the native cell-content resolver,
 * value-commit helpers, and the draft / selection / pagination APIs. The built-in
 * {@link Sheets} component is a thin consumer of this hook.
 *
 * The STABLE headless surface is {@link UseSheetsResult}. A handful of additional
 * fields under the `_shell` group are returned only so the built-in `<Sheets>`
 * chrome (toolbar, pagination, dock) can render; they are intentionally NOT part
 * of the supported headless contract and may change.
 */
import { useCallback, useEffect, useMemo, useRef } from 'react';

import type { SheetsSelection } from '../selection/selection-model';
import type { RelationInfo } from '../store/relation-info-slice';

import { useDataGridColumns, type RelationGridColumn } from '../hooks/use-relation-columns';
import { useSheetsContext } from '../context/sheets-context';
import { useSheetsStore } from '../store/sheets-store';
import { sheetsLogger } from '../utils/sheets-logger';
import { computeDraftMetaSignature } from '../store/draft-rows-slice';
import { toast } from '@/components/ui/toast';
import type { DataGridProps, SheetsEvent } from './sheets.types';
import { attachDraftMeta, getDraftMeta, type SheetsRow } from './row-model';

import { createCellTypeRegistry, type CellTypeRegistry } from '../cell-types/cell-type-registry';
import { createSheetsCell } from '../cell-model/create-sheets-cell';
import { compileSlots } from '../cell-model/cell-slots';
import { DRAFT_ACTION_COLUMN_KEY } from './sheets.constants';
import { countConditions } from './sheets.controls';
import { useFeedback } from './feedback';
import {
	buildWhereFromFilters,
	createHeaderClickHandler,
	mapFromFieldMetaMap,
	mapFromRelationInfoMap,
	normalizeServerRow,
} from './sheets.utils';
import { useSheetsMeta } from '../hooks/use-sheets-meta';
import type { DraftSubmitResult } from './draft-types';
import { useCellEditing } from './hooks/use-cell-editing';
import { useBatchCommit, type CellWrite, type CommitCellsOptions, type CommitCellsResult } from './hooks/use-batch-commit';
import { useUndoRedo } from './hooks/use-undo-redo';
import { useDraftRows } from './hooks/use-draft-rows';
import { useDraftSubmission } from './hooks/use-draft-submission';
import { useSheetsContent, type SheetsCellResolution } from '../grid-dom/use-sheets-content';
import { useGridOperations } from './hooks/use-grid-operations';
import { useGridSelectionState } from './hooks/use-grid-selection';
import { useGridState } from './hooks/use-grid-state';
import { useInfiniteGridData, type VisibleRowRange } from './hooks/use-infinite-grid-data';
import { useDataLoading } from './hooks/use-load-grid';
import {
	canRunSheetsMutation,
	getSheetsWriteCapability,
	resolveSheetsRowIdentity,
	sheetsRowKey,
	type SheetsRowIdentifier,
} from '../row-identity';

const EMPTY_RELATION_INFO_BY_FIELD = new Map<string, RelationInfo>();

/** Draft-row bindings for a headless shell. */
export interface SheetsDraftBindings {
	/** Whether any client-side draft rows exist. */
	hasDrafts: boolean;
	/** Append a new draft row. Returns the new row index. */
	appendRow: () => Promise<number | undefined>;
	/** Submit all pending draft rows. */
	submitDrafts: () => Promise<void>;
	/** Delete the currently selected rows (draft + server). */
	deleteSelected: () => Promise<void>;
}

/**
 * Selection bindings for a headless shell.
 *
 * The selection value is the native {@link SheetsSelection} (RangeSet-backed `rows`).
 */
export interface SheetsSelectionBindings {
	/** Current native grid selection. */
	gridSelection: SheetsSelection | undefined;
	/** Setter. */
	setGridSelection: (selection: SheetsSelection | undefined) => void;
	/** Park the active cell on `[col, row]` (preserves row/column selection). */
	setActiveCell: (col: number, row: number) => void;
	/** Move the active cell by `[dCol, dRow]`, clamped to grid bounds. */
	moveActive: (dCol: number, dRow: number, colCount: number, rowCount: number) => void;
}

/** Pagination bindings for a headless shell (paginated mode). */
export interface SheetsPaginationBindings {
	/** Current zero-based page index. */
	pageIndex: number;
	/** Total page count (>= 1). */
	pageCount: number;
	/** Set the page index (emits a `page:change` event). */
	setPageIndex: (updater: number | ((prev: number) => number)) => void;
}

/**
 * Stable headless surface returned by {@link useSheets}. (The hook also returns a
 * few `_shell`-grouped extras consumed only by the built-in {@link Sheets} chrome —
 * those are not part of this supported contract.)
 */
export interface UseSheetsResult {
	/** Native column descriptors (key/title/width). */
	columns: RelationGridColumn[];
	/** Number of rows to render. */
	rowCount: number;
	/** Draft-row bindings. */
	draft: SheetsDraftBindings;
	/** Selection bindings. */
	selection: SheetsSelectionBindings;
	/** Pagination bindings. */
	pagination: SheetsPaginationBindings;
	/** True only during the very first load (refetches keep previous data). */
	isInitialLoading: boolean;
	/** Data-load error, if any. */
	dataError: Error | null;
	/** Whether the initial load has completed (success). */
	hasCompletedInitialLoad: boolean;
	/** True when loaded, no server rows, no drafts, and no active filter. */
	isEmpty: boolean;
	/** Refetch the underlying data (mode-aware: infinite vs paginated). */
	refetch: () => void;
}

/**
 * Internal bindings consumed only by the built-in {@link Sheets} chrome
 * (toolbar, dock, pagination chrome). NOT a supported part of the headless contract.
 */
export interface SheetsShellBindings {
	combinedRows: SheetsRow[];
	columnKeys: string[];
	totalCount: number;
	serverRowCount: number;
	draftRowCount: number;
	infiniteScroll: boolean;
	filterTree: ReturnType<typeof useGridState>['state']['filterTree'];
	filtersOpen: boolean;
	setFilterTree: ReturnType<typeof useGridState>['actions']['setFilterTree'];
	setFiltersOpen: ReturnType<typeof useGridState>['actions']['setFiltersOpen'];
	clearAllFilters: ReturnType<typeof useGridState>['actions']['clearAllFilters'];
	applyFilters: () => void;
	fieldTypeMap: Record<string, { gqlType: string; isArray: boolean }>;
	setGridSelectionForControls: (selection: SheetsSelection | null) => void;
	/** Header sort toggle (colIndex → toggleSorting on the sortable column). */
	onHeaderClicked: (colIndex: number) => void;
	/** Prefetch the rows in an inclusive visible window (native range, infinite mode). */
	onVisibleRegionChanged: (range: VisibleRowRange) => void;
	/** @internal Sort state mirror ({ id, desc }) — the DOM header reads this for its caret. NOT a stable API. */
	sorting: ReturnType<typeof useGridState>['state']['sorting'];
	/** @internal Committed column widths (id → px) — the DOM grid maps these to v9 columnSizing. NOT a stable API. */
	columnWidths: ReturnType<typeof useGridState>['state']['columnWidths'];
	/** @internal Commit a column width (id, px) — the DOM resize handle drives this directly. NOT a stable API. */
	resizeColumn: ReturnType<typeof useGridState>['actions']['resizeColumn'];
	frozenCount: number;
	selectedRowCount: number;
	canCreate: boolean;
	canUpdate: boolean;
	canDelete: boolean;
	/** Human-readable reason shown when `_meta` proves the whole table is read-only. */
	readOnlyReason: string | null;
	/** Stable identity for selection, TanStack rows, and editor instances. */
	getRowId: (row: SheetsRow | null | undefined, index: number) => string;
	isSubmittingDrafts: boolean;
	submitDraftButtonDisabled: boolean;
	submitDraftLabel: string;
	/** @internal Native DOM content resolver for the TanStack DOM grid. NOT a stable API. */
	getSheetsCellContent: (rowIndex: number, colKey: string) => SheetsCellResolution;
	/** @internal Per-instance cell-type registry (consumer overrides over built-ins). NOT a stable API. */
	cellRegistry: CellTypeRegistry;
	/** @internal Native value-commit for the TanStack DOM portal editors. NOT a stable API. */
	commitCellValue: (rowIndex: number, colKey: string, nextValue: unknown) => void;
	/** @internal Batched server-row value commit (paste/fill/bulk + the single cell). NOT a stable API. */
	commitCells: (writes: CellWrite[], opts?: CommitCellsOptions) => Promise<CommitCellsResult>;
	/** @internal Native MULTI-field patch-commit for self-committing DOM portal editors (relation/image). NOT a stable API. */
	commitCellPatch: (rowIndex: number, patch: Record<string, unknown>) => void;
	/** @internal Submit a client-side draft row for a self-committing DOM portal editor. NOT a stable API. */
	submitDraftRow: (draftRowId: string) => Promise<DraftSubmitResult>;
	/** @internal Invalidate cached grid data after a self-committing DOM portal editor mutates out-of-band. NOT a stable API. */
	invalidateData: () => void;
	/** @internal Undo the last recorded server-row value write. NOT a stable API. */
	undo: () => Promise<void>;
	/** @internal Redo the last undone server-row value write. NOT a stable API. */
	redo: () => Promise<void>;
	/** @internal Whether an undo is available. NOT a stable API. */
	canUndo: boolean;
	/** @internal Whether a redo is available. NOT a stable API. */
	canRedo: boolean;
	/** @internal Observational event emitter (analytics/telemetry) — threaded into the command context. NOT a stable API. */
	emit: (type: SheetsEvent['type'], meta?: Record<string, unknown>) => void;
}

export type UseSheetsInternalResult<TRow extends SheetsRow = SheetsRow> = UseSheetsResult & {
	/** @internal Bindings for the built-in <Sheets> chrome — not a stable API. */
	_shell: SheetsShellBindings;
};

/**
 * Headless grid hook — returns the data/state bindings the built-in {@link Sheets}
 * component renders with the native DOM grid.
 *
 * Preconditions:
 * - You MUST render inside a `<FeedbackProvider>` (exported from this package) —
 *   the hook uses the bulk-operation feedback context and throws without it.
 *
 * NOTE: the generic `TRow` flows through {@link DataGridProps}'s row callbacks
 * (e.g. `onRowSelect`). It does not retype the cell bindings, which operate on
 * the dynamic schema-derived row shape.
 */
export function useSheets<TRow extends SheetsRow = SheetsRow>(
	props: DataGridProps<TRow>,
): UseSheetsInternalResult<TRow> {
	const {
		tableName,
		pageSize = 100,
		onRowSelect,
		onCellEdit,
		relationChipLimit,
		relationLabelMaxLength,
		infiniteScroll = false,
		cellTypes,
		cellSlots,
		onEvent,
	} = props;

	// Get feedback context for bulk operation status indicators
	const { startOperation, updateOperationProgress, completeOperation, clearOperationFeedback } = useFeedback();

	// Keep the latest onEvent in a ref so firing events never depends on (or churns)
	// the callbacks/effects below — purely observational, no behavioral coupling.
	const onEventRef = useRef(onEvent);
	onEventRef.current = onEvent;
	const emit = useCallback((type: SheetsEvent['type'], meta?: Record<string, unknown>) => {
		onEventRef.current?.({ type, tableName, at: Date.now(), meta });
	}, [tableName]);

	const { config } = useSheetsContext();

	// Per-instance cell-type registry: consumer overrides (provider plugins, then
	// per-instance cellTypes) layered over the built-in native engine. With no consumer
	// cell types this delegates 1:1 to createSheetsCell.
	const cellRegistry = useMemo(
		() =>
			createCellTypeRegistry(
				// Compiled cell-component slots go LAST so they win over plugins + cellTypes.
				[...(config.plugins ?? []).flatMap((p) => p.cellTypes), ...(cellTypes ?? []), ...compileSlots(cellSlots)],
				{
					// Native display builtin: the SheetsCell dispatcher.
					toSheetsCell: (value, ctx) => createSheetsCell(value, ctx.metadata),
				},
			),
		[config.plugins, cellTypes, cellSlots],
	);

	const tableKey = useMemo(() => {
		if (config.databaseId) return `${config.databaseId}::${tableName}`;
		return `default::${tableName}`;
	}, [config.databaseId, tableName]);

	// Clear stale operation feedback when switching tables
	useEffect(() => {
		clearOperationFeedback();
	}, [tableName, clearOperationFeedback]);

	// Centralized state management
	const { state: gridState, actions: gridActions } = useGridState();

	// Build orderBy from grid state
	const orderByClause = useMemo(
		() =>
			gridState.sorting.id
				? [{ field: gridState.sorting.id, direction: gridState.sorting.desc ? ('desc' as const) : ('asc' as const) }]
				: undefined,
		[gridState.sorting],
	);

	// ============== FILTER / SEARCH → WHERE CLAUSE ==============
	// Fetch meta independently so we can build the where clause before data hooks run
	const { data: filterMeta } = useSheetsMeta();
	const filterTableMeta = useMemo(
		() => filterMeta?._meta?.tables?.find((t) => t?.name === tableName) ?? null,
		[filterMeta, tableName],
	);

	const effectiveWhere = useMemo(
		() => buildWhereFromFilters(gridState.filterTree, filterTableMeta),
		[gridState.filterTree, filterTableMeta],
	);

	// Reset to page 0 when filters change (paginated mode)
	const prevWhereRef = useRef(effectiveWhere);
	useEffect(() => {
		if (prevWhereRef.current !== effectiveWhere) {
			prevWhereRef.current = effectiveWhere;
			if (!infiniteScroll) {
				gridActions.setPageIndex(0);
			}
		}
	}, [effectiveWhere, infiniteScroll, gridActions]);

	// ============== INFINITE SCROLL MODE ==============
	const infiniteGridData = useInfiniteGridData({
		tableName,
		pageSize,
		orderBy: orderByClause,
		where: effectiveWhere,
		enabled: infiniteScroll,
	});

	// ============== PAGINATED MODE ==============
	const initialQueryOptions = useMemo(
		() => ({
			limit: pageSize,
			offset: gridState.pageIndex * pageSize,
			orderBy: orderByClause,
			where: effectiveWhere,
		}),
		[pageSize, gridState.pageIndex, orderByClause, effectiveWhere],
	);

	// In infinite scroll mode we still use mutations from useDataLoading,
	// but disable row/count queries to avoid duplicate fetching.
	const dataLoadingResult = useDataLoading({
		tableName,
		queryOptions: initialQueryOptions,
		enabled: !infiniteScroll,
	});

	// ============== UNIFIED DATA ACCESS ==============
	// Choose data source based on mode
	const {
		serverData,
		totalCount,
		tableMeta,
		fieldMetaMap,
		allRelationFields,
		hasCompletedInitialLoad,
		dataError,
		isInitialLoading,
	} = useMemo(() => {
		if (infiniteScroll) {
			return {
				serverData: [] as any[], // Not used directly in infinite mode
				totalCount: infiniteGridData.totalCount,
				tableMeta: infiniteGridData.tableMeta,
				fieldMetaMap: infiniteGridData.fieldMetaMap,
				allRelationFields: infiniteGridData.allRelationFields,
				hasCompletedInitialLoad: infiniteGridData.hasInitialData,
				dataError: infiniteGridData.error,
				// Only the first load (no rows yet) should show the loading screen; refetches keep previous data.
				isInitialLoading: infiniteGridData.isLoading && !infiniteGridData.hasInitialData,
			};
		}
		const ctx = dataLoadingResult.contextValue;
		const rows = ctx.data || [];
		return {
			serverData: rows,
			totalCount: ctx.totalCount,
			tableMeta: ctx.tableMeta,
			fieldMetaMap: ctx.fieldMetaMap,
			allRelationFields: ctx.allRelationFields,
			hasCompletedInitialLoad: !ctx.isLoading,
			dataError: ctx.error,
			// isLoading is true only until the active scope receives its first result.
			isInitialLoading: ctx.isLoading && rows.length === 0,
		};
	}, [infiniteScroll, infiniteGridData, dataLoadingResult.contextValue]);

	const writeCapability = useMemo(() => getSheetsWriteCapability(tableMeta), [tableMeta]);
	const canCreate = canRunSheetsMutation(writeCapability, 'create');
	const canUpdate = canRunSheetsMutation(writeCapability, 'update');
	const canDelete = canRunSheetsMutation(writeCapability, 'delete');
	const primaryKeyFields = useMemo(
		() => new Set(writeCapability?.status === 'mutable' ? writeCapability.primaryKeyFields : []),
		[writeCapability],
	);
	const supportsScalarSelfCommit =
		writeCapability?.status === 'mutable' &&
		writeCapability.primaryKeyFields.length === 1 &&
		writeCapability.primaryKeyFields[0] === 'id';
	const readOnlyReason = writeCapability?.status === 'read-only'
		? 'This table is read-only because it has no primary key.'
		: null;
	const getRowIdentifier = useCallback(
		(row: Readonly<Record<string, unknown>>): SheetsRowIdentifier | null => {
			if (!tableMeta) return null;
			const resolution = resolveSheetsRowIdentity(tableMeta, row);
			return resolution.status === 'identified' ? resolution.identifier : null;
		},
		[tableMeta],
	);
	const getRowId = useCallback(
		(row: SheetsRow | null | undefined, index: number): string => {
			const draftMeta = getDraftMeta(row);
			if (draftMeta) return draftMeta.draftRowId;
			if (row && tableMeta) return sheetsRowKey(tableMeta, row, index);
			return `${tableMeta?.schemaName ?? ''}:${tableName}:row:${index}`;
		},
		[tableMeta, tableName],
	);

	// Emit load:success / load:error once per transition. Tracked via a ref so we
	// don't re-fire on unrelated re-renders.
	const lastLoadEmitRef = useRef<'success' | 'error' | null>(null);
	useEffect(() => {
		if (dataError) {
			if (lastLoadEmitRef.current !== 'error') {
				lastLoadEmitRef.current = 'error';
				emit('load:error', { error: dataError });
			}
			return;
		}
		if (hasCompletedInitialLoad && lastLoadEmitRef.current !== 'success') {
			lastLoadEmitRef.current = 'success';
			emit('load:success', { totalCount });
		}
	}, [dataError, hasCompletedInitialLoad, totalCount, emit]);

	// Get CRUD operations (only available in paginated mode for now)
	const { update, create, delete: deleteRow } = dataLoadingResult.contextValue;

	const relationFieldNames = useMemo(() => new Set(allRelationFields), [allRelationFields]);

	const normalizedServerData = useMemo(() => {
		if (infiniteScroll) return [] as any[]; // Not used in infinite mode
		if (!Array.isArray(serverData) || serverData.length === 0 || relationFieldNames.size === 0) {
			return serverData as any[];
		}
		return (serverData as any[]).map((row) => normalizeServerRow(row, relationFieldNames));
	}, [infiniteScroll, serverData, relationFieldNames]);

	const {
		draftRowsTable,
		draftRows,
		hasDraftRows,
		combinedRows: paginatedCombinedRows,
		draftRowIndices: paginatedDraftRowIndices,
		createDraftRow,
		updateDraftCell,
		removeDraftRow,
		syncDraftRowsWithMeta,
		setDraftRowStatus,
	} = useDraftRows({
		tableKey,
		serverRows: normalizedServerData as any[],
		hasCompletedInitialLoad,
	});

	const serverRowCount = infiniteScroll ? totalCount : normalizedServerData.length;

	const draftDataRows = useMemo(() => {
		if (!draftRows.length) return [] as SheetsRow[];
		return draftRows.map((draft) => {
			const row = { ...draft.values } as SheetsRow;
			return attachDraftMeta(row, {
				isDraft: true,
				draftRowId: draft.id,
				status: draft.status,
				errors: draft.errors,
			});
		});
	}, [draftRows]);

	// ============== INFINITE SCROLL: Virtual rows array ==============
	// Create a proxy array for infinite scroll mode that uses getRowAtIndex and appends draft rows.
	const infiniteRowsProxy = useMemo<SheetsRow[]>(() => {
		if (!infiniteScroll) return [];

		// Create an array-like object with a Proxy to intercept index access
		const handler: ProxyHandler<any[]> = {
			get(target, prop) {
				// Handle array methods and properties
				if (prop === 'length') {
					return serverRowCount + draftDataRows.length;
				}
				if (prop === Symbol.iterator) {
					return function* () {
						const len = serverRowCount + draftDataRows.length;
						for (let i = 0; i < len; i++) {
							if (i < serverRowCount) {
								yield infiniteGridData.getRowAtIndex(i);
							} else {
								yield draftDataRows[i - serverRowCount];
							}
						}
					};
				}
				// Handle numeric indices
				if (typeof prop === 'string' && !isNaN(Number(prop))) {
					const index = Number(prop);
					if (index < serverRowCount) {
						return infiniteGridData.getRowAtIndex(index);
					}
					return draftDataRows[index - serverRowCount];
				}
				// Delegate to target for other properties
				return Reflect.get(target, prop);
			},
		};

		// Single localized cast: the Proxy intercepts numeric index + length access to
		// surface server rows (via getRowAtIndex) and appended draft rows as SheetsRow,
		// so downstream `combinedRows[i]` reads are SheetsRow with no per-use cast.
		return new Proxy([], handler) as unknown as SheetsRow[];
	}, [infiniteScroll, infiniteGridData, serverRowCount, draftDataRows]);

	// Choose the appropriate rows array based on mode
	const combinedRows: SheetsRow[] = infiniteScroll ? infiniteRowsProxy : paginatedCombinedRows;

	const draftRowIndices = useMemo(() => {
		if (!draftDataRows.length) return [] as number[];
		if (infiniteScroll) {
			return draftDataRows.map((_, index) => serverRowCount + index);
		}
		return paginatedDraftRowIndices;
	}, [draftDataRows, infiniteScroll, paginatedDraftRowIndices, serverRowCount]);

	const fieldMetaByKey = useMemo(() => mapFromFieldMetaMap(fieldMetaMap), [fieldMetaMap]);

	// Build columns with actual data
	// In infinite scroll mode, check if we have initial data
	const hasServerRows = infiniteScroll ? infiniteGridData.hasInitialData : normalizedServerData.length > 0;

	const { columns: baseColumns, columnKeys } = useDataGridColumns(
		tableName,
		hasServerRows ? combinedRows : undefined,
	);

	const gridColumnKeys = useMemo(() => {
		if (!hasDraftRows) return columnKeys;
		return [...columnKeys, DRAFT_ACTION_COLUMN_KEY];
	}, [columnKeys, hasDraftRows]);

	// Pagination helpers
	const totalPages = Math.max(1, Math.ceil((totalCount || 0) / pageSize));
	useEffect(() => {
		gridActions.resetPageIfNeeded(totalPages);
	}, [totalPages, gridActions]);

	// Apply custom widths and sort indicators to columns
	const columns = useMemo<RelationGridColumn[]>(() => {
		const sortedColId = gridState.sorting.id;
		const isDesc = gridState.sorting.desc;

		const mapped = baseColumns.map((col) => {
			const isSorted = col.id === sortedColId;
			// Append sort indicator to title if this column is sorted
			const sortIndicator = isSorted ? (isDesc ? ' ↓' : ' ↑') : '';
			return {
				...col,
				title: col.title + sortIndicator,
				width: gridState.columnWidths.get(col.id || '') ?? col.width,
			};
		});

		if (hasDraftRows) {
			mapped.push({
				id: DRAFT_ACTION_COLUMN_KEY,
				title: '',
				width: gridState.columnWidths.get(DRAFT_ACTION_COLUMN_KEY) ?? 132,
			});
		}

		return mapped;
	}, [baseColumns, gridState.columnWidths, gridState.sorting, hasDraftRows]);

	// Handle row selection
	useEffect(() => {
		if (!onRowSelect || !gridState.gridSelection) return;
		const selectedIndices = gridState.gridSelection.rows.toArray();
		const selected = selectedIndices.map((i: number) => combinedRows[i]).filter(Boolean);
		// The grid's rows ARE the consumer's row type, so widen SheetsRow[] -> TRow[].
		onRowSelect(selected as TRow[]);
	}, [gridState.gridSelection, combinedRows, onRowSelect]);

	// ============== RELATION INFO (store-derived) ==============
	// The store owns relation metadata; ensure it for this table once and read the
	// per-field map. Used by the native content resolver + draft/relation routing.
	const ensureRelationInfo = useSheetsStore((st) => st.ensureRelationInfo);
	const relationInfoByFieldFromStore = useSheetsStore((st) =>
		tableName ? st.relationInfoMapCache[tableName] : undefined,
	);
	const relationInfoByField = relationInfoByFieldFromStore ?? EMPTY_RELATION_INFO_BY_FIELD;
	useEffect(() => {
		if (!tableName) return;
		ensureRelationInfo(tableName, filterMeta);
	}, [tableName, filterMeta, ensureRelationInfo]);

	const relationInfoObject = useMemo(() => mapFromRelationInfoMap(relationInfoByField), [relationInfoByField]);

	// Native DOM content resolver (mirrors the canvas getCellContent routing → SheetsCell).
	const { getSheetsCell: getSheetsCellContent } = useSheetsContent({
		data: combinedRows,
		columnKeys: gridColumnKeys,
		fieldMetaMap,
		registry: cellRegistry,
		tableName,
		options: { relationChipLimit, relationLabelMaxLength },
		relationInfoByField,
		meta: filterMeta,
		serverRowsReadOnly: !canUpdate,
		serverReadOnlyFields: primaryKeyFields,
		getRowIdentifier,
		supportsScalarSelfCommit,
	});

	const effectiveColumnOrder = useMemo(() => {
		if (columnKeys.length > 0) return columnKeys;
		return Object.keys(fieldMetaByKey);
	}, [columnKeys, fieldMetaByKey]);

	const metaSignature = useMemo(
		() => computeDraftMetaSignature(effectiveColumnOrder, fieldMetaByKey, relationInfoObject),
		[effectiveColumnOrder, fieldMetaByKey, relationInfoObject],
	);

	const allowedColumns = useMemo(() => {
		const tableFields = tableMeta?.fields as { name: string }[] | undefined;
		return tableFields ? new Set(tableFields.map((field) => field.name).filter(Boolean) as string[]) : undefined;
	}, [tableMeta?.fields]);

	useEffect(() => {
		if (!effectiveColumnOrder.length) return;
		syncDraftRowsWithMeta({
			tableKey,
			columnOrder: effectiveColumnOrder,
			fieldMetaByKey,
			relationInfoByKey: relationInfoObject,
			metaVersion: metaSignature,
		});
	}, [effectiveColumnOrder, fieldMetaByKey, relationInfoObject, metaSignature, syncDraftRowsWithMeta, tableKey]);

	/**
	 * Unified optimistic update handler for overlay editors. Editors that handle
	 * mutations internally (RelationEditor, ImageEditor, etc.) call this callback with
	 * a patch to update the grid cache without full refetch. The DOM grid re-renders
	 * reactively off `combinedRows`, so no surgical per-cell repaint is needed.
	 */
	const handleEditorSaveComplete = useCallback(
		(colKey: string, rowIndex: number, patch: Record<string, unknown>) => {
			void colKey;
			const rowData = combinedRows[rowIndex];

			// Draft row: update draft store directly
			const dm = getDraftMeta(rowData);
			if (dm) {
				for (const [key, value] of Object.entries(patch)) {
					updateDraftCell({ tableKey, draftRowId: dm.draftRowId, columnKey: key, value });
				}
				return;
			}

			// Server row: update infinite scroll cache (paginated handled by React Query)
			if (!infiniteScroll) return;

			// Apply optimistic update to infinite scroll cache; self-heal on a cache
			// miss (patch targeted a not-yet-cached page) by falling back to a refetch.
			const ok = infiniteGridData.updateRowAtIndex(rowIndex, patch);
			if (!ok) infiniteGridData.invalidate();
		},
		[combinedRows, infiniteScroll, infiniteGridData, updateDraftCell, tableKey],
	);

	// Ref to hold submitDraftRowForEditor - populated after useDraftSubmission
	// This breaks the circular dependency: editors need the function, but useDraftSubmission
	// needs hasDraftSelection which comes from useGridSelectionState which needs combinedRows
	const submitDraftRowForEditorRef = useRef<((draftRowId: string) => Promise<DraftSubmitResult>) | null>(null);

	const handleSubmitDraftRowForEditor = useCallback(
		async (draftRowId: string): Promise<DraftSubmitResult> => {
			if (!submitDraftRowForEditorRef.current) {
				return { createdRow: null };
			}
			return submitDraftRowForEditorRef.current(draftRowId);
		},
		[],
	);

	// Memoize feedback callbacks for grid operations
	const operationFeedback = useMemo(
		() => ({
			onStart: startOperation,
			onProgress: updateOperationProgress,
			onComplete: completeOperation,
		}),
		[startOperation, updateOperationProgress, completeOperation],
	);

	const gridOpsOptions = useMemo(
		() => ({
			onRemoveDraftRow: (draftRowId: string) => removeDraftRow(tableKey, draftRowId),
			getRowIdentifier,
			canDeleteServerRows: canDelete,
			feedback: operationFeedback,
		}),
		[removeDraftRow, tableKey, getRowIdentifier, canDelete, operationFeedback],
	);

	const { deleteSelected: baseDeleteSelected } = useGridOperations(
		combinedRows,
		deleteRow,
		gridState.gridSelection,
		() => gridActions.setGridSelection(undefined),
		{
			...gridOpsOptions,
			onAfterServerDeletes: infiniteScroll ? infiniteGridData.invalidate : undefined,
		},
	);

	// Wrap the delete handler to emit an observational row:delete event with the
	// selected-row count, then delegate to the real deletion logic.
	const deleteSelected = useCallback(async () => {
		const count = gridState.gridSelection?.rows.length ?? 0;
		emit('row:delete', { count });
		await baseDeleteSelected();
	}, [baseDeleteSelected, emit, gridState.gridSelection]);

	// Infinite-mode optimistic cache patch, handed to `useCellEditing` so a server-row
	// edit flips the cell BEFORE the `update` round-trip. Snapshots the prior values for
	// the patched keys and returns a revert thunk replayed only if the mutation rejects.
	// A cache miss (unloaded page) self-heals via `invalidate()`. Paginated mode returns
	// undefined here — its optimism lives in the update mutation's onMutate (use-table.ts).
	const applyOptimisticCellPatch = useCallback(
		(rowIndex: number, patch: Record<string, unknown>): (() => void) | void => {
			if (!infiniteScroll) return;
			const current = infiniteGridData.getRowAtIndex(rowIndex) as Record<string, unknown> | null;
			const ok = infiniteGridData.updateRowAtIndex(rowIndex, patch);
			if (!ok) {
				infiniteGridData.invalidate();
				return;
			}
			const snapshot: Record<string, unknown> = {};
			for (const key of Object.keys(patch)) snapshot[key] = current ? current[key] : undefined;
			return () => {
				const reverted = infiniteGridData.updateRowAtIndex(rowIndex, snapshot);
				if (!reverted) infiniteGridData.invalidate();
			};
		},
		[infiniteScroll, infiniteGridData],
	);

	const editCell = useCellEditing({
		combinedRows,
		fieldMetaMap,
		relationInfoByField,
		updateDraftCell,
		tableKey,
		update,
		getRowIdentifier,
		readOnlyFields: primaryKeyFields,
		canUpdate,
		onCellEdit,
		applyOptimisticPatch: applyOptimisticCellPatch,
	});

	// History (undo/redo) for server-row value writes. Draft edits are NOT recorded.
	const history = useUndoRedo();

	// Re-sync a canonical server row over the optimistic patch after the mutation
	// resolves (infinite mode only; paginated reconciles via React Query).
	const resyncRow = useCallback(
		(rowIndex: number, updatedRow: Record<string, unknown>) => {
			if (!infiniteScroll) return;
			const ok = infiniteGridData.updateRowAtIndex(rowIndex, updatedRow);
			if (!ok) infiniteGridData.invalidate();
		},
		[infiniteScroll, infiniteGridData],
	);

	// BATCHED commit primitive — the single server-row value-write path (paste / fill /
	// bulk AND, routed below, the single cell). Coalesces optimistic patches + server
	// mutations per row and records an undoable HistoryEntry (unless opts.record===false).
	const commitCells = useBatchCommit({
		combinedRows,
		fieldMetaMap,
		relationInfoByField,
		update,
		getRowIdentifier,
		readOnlyFields: primaryKeyFields,
		canUpdate,
		applyOptimisticPatch: applyOptimisticCellPatch,
		resyncRow,
		editCell,
		onCellEdit,
		record: history.record,
	});

	// @internal NATIVE value-commit for the TanStack DOM grid's portal editors.
	// Maps a (rowIndex, colKey, rawValue) commit straight onto the native `editCell`
	// (draft `updateDraftCell` / server mutation) — the raw value flows through with
	// NO glide cell round-trip (this is what keeps a boolean `false` as `false`). For
	// server edits `editCell` already applied the OPTIMISTIC infinite-cache patch before
	// awaiting the mutation (and reverted it on failure); here we only re-sync the
	// canonical server row when it comes back, then emit the observational `cell:edit`.
	// The DOM grid re-renders reactively from `combinedRows`.
	const commitCellValue = useCallback(
		(rowIndex: number, colKey: string, nextValue: unknown): void => {
			void (async () => {
				try {
					// Single-cell edits route through the SAME batched primitive so a normal cell
					// edit becomes undoable (server rows) — coercion / readonly / optimistic patch
					// / re-sync all live inside commitCells (draft rows take its per-cell branch).
					const isDraft = !!getDraftMeta(combinedRows[rowIndex]);
					const { applied } = await commitCells([{ rowIndex, colKey, value: nextValue }]);

					// Observational: a real cell edit landed — skip no-ops (applied 0 + non-draft).
					if (applied > 0 || isDraft) {
						emit('cell:edit', { field: colKey, rowIndex, target: isDraft ? 'draft' : 'server' });
					}
				} catch (e) {
					const description = e instanceof Error ? e.message : 'Failed to update cell';
					toast.error({ message: 'Update failed', description });
					sheetsLogger().error('Cell edit error:', e);
					config.onError?.(e, { source: 'mutation', tableName });
				}
			})();
		},
		[commitCells, combinedRows, config, tableName, emit],
	);

	// @internal NATIVE patch-commit for self-committing DOM portal editors (relation/
	// image). These editors mutate server-side themselves, then push a MULTI-field
	// patch — routes straight through the EXISTING `handleEditorSaveComplete` (draft
	// store update / infinite-cache patch), using the FIRST patch key as the primary colKey.
	const commitCellPatch = useCallback(
		(rowIndex: number, patch: Record<string, unknown>): void => {
			const primaryColKey = Object.keys(patch)[0];
			if (!primaryColKey) return;
			handleEditorSaveComplete(primaryColKey, rowIndex, patch);
		},
		[handleEditorSaveComplete],
	);

	// @internal NATIVE data-invalidate for self-committing DOM portal editors. Mirrors
	// the canvas wiring: infinite mode refetches via the React Query cache; paginated
	// invalidation is already handled by React Query in use-table, so this is a no-op there.
	const invalidateData = useCallback(() => {
		if (infiniteScroll) infiniteGridData.invalidate();
	}, [infiniteScroll, infiniteGridData]);

	const handleRowAppended = useCallback(async () => {
		if (!canCreate) return undefined;
		if (draftRows.length > 0) {
			return serverRowCount + draftRows.length - 1;
		}

		// Silently skip if metadata isn't ready - this is a transient state
		if (!effectiveColumnOrder.length) return undefined;

		createDraftRow({
			tableKey,
			columnOrder: effectiveColumnOrder,
			fieldMetaByKey: fieldMetaByKey as Record<string, any>,
			relationInfoByKey: relationInfoObject,
			metaVersion: metaSignature,
		});

		const rowIndex = serverRowCount + draftRows.length;
		emit('row:create', { rowIndex });
		return rowIndex;
	}, [
		createDraftRow,
		effectiveColumnOrder,
		fieldMetaByKey,
		relationInfoObject,
		metaSignature,
		tableKey,
		draftRows,
		serverRowCount,
		canCreate,
		emit,
	]);

	const { selectedRowCount, selectedDraftRowEntries, hasDraftSelection } = useGridSelectionState({
		gridSelection: gridState.gridSelection,
		combinedRows,
		draftRowsTable,
	});

	const {
		isSubmittingDrafts,
		submitDraftButtonDisabled,
		submitDraftLabel,
		handleSubmitDraftRows,
		submitDraftRowForEditor,
	} = useDraftSubmission({
		tableKey,
		draftRowsTable,
		selectedDraftRowEntries,
		hasDraftSelection,
		create,
		removeDraftRow,
		setDraftRowStatus,
		clearSelection: () => gridActions.setGridSelection(undefined),
		allowedColumns,
		relationInfoByKey: relationInfoObject,
		fieldMetaByKey: fieldMetaByKey as Record<string, any>,
		onSubmittedSuccessfully: infiniteScroll ? infiniteGridData.invalidate : undefined,
		feedback: operationFeedback,
	});

	// Populate the ref for editor access (breaks circular dependency)
	submitDraftRowForEditorRef.current = submitDraftRowForEditor;

	// Compute sortable columns (exclude relation fields - only simple data types are sortable)
	const sortableColumns = useMemo(() => {
		return new Set(gridColumnKeys.filter((key) => !relationFieldNames.has(key)));
	}, [gridColumnKeys, relationFieldNames]);

	// Header click handler for sorting (only allows sorting on non-relation columns; the
	// draft-action column is excluded because it is never in `sortableColumns`).
	const onHeaderClicked = useMemo(
		() => createHeaderClickHandler(gridColumnKeys, gridActions.toggleSorting, sortableColumns),
		[gridColumnKeys, gridActions.toggleSorting, sortableColumns],
	);

	// Emit sort:change whenever the resolved sort state transitions. Watching the
	// state (rather than the toggle call) reflects the real outcome and covers any
	// path that mutates sorting. Skip the initial mount so we don't fire on render.
	const didMountSortRef = useRef(false);
	useEffect(() => {
		if (!didMountSortRef.current) {
			didMountSortRef.current = true;
			return;
		}
		emit('sort:change', {
			field: gridState.sorting.id || null,
			direction: gridState.sorting.id ? (gridState.sorting.desc ? 'desc' : 'asc') : null,
		});
	}, [gridState.sorting, emit]);

	// ============== INFINITE SCROLL: onVisibleRegionChanged handler ==============
	// Translate the DOM viewport's inclusive {startIndex,endIndex} window into the
	// prefetch range the infinite source loads (clamped to the server row count).
	const handleVisibleRegionChanged = useCallback(
		(range: VisibleRowRange) => {
			if (!infiniteScroll) return;
			if (serverRowCount <= 0) return;

			const start = Math.max(0, Math.min(range.startIndex, serverRowCount - 1));
			const end = Math.max(start, Math.min(range.endIndex, serverRowCount - 1));
			infiniteGridData.onVisibleRegionChanged({ startIndex: start, endIndex: end });
		},
		[infiniteScroll, infiniteGridData, serverRowCount],
	);

	const setGridSelectionForControls = useCallback(
		(selection: SheetsSelection | null) => {
			gridActions.setGridSelection(selection ?? undefined);
		},
		[gridActions],
	);

	// Build fieldTypeMap for filter controls
	const fieldTypeMap = useMemo(() => {
		const map: Record<string, { gqlType: string; isArray: boolean }> = {};
		fieldMetaMap.forEach((meta, key) => {
			if (meta?.type?.gqlType) {
				map[key] = { gqlType: meta.type.gqlType, isArray: !!meta.type.isArray };
			}
		});
		return map;
	}, [fieldMetaMap]);

	const applyFilters = useCallback(() => {
		gridActions.setFiltersOpen(false);
		emit('filter:apply', { conditionCount: countConditions(gridState.filterTree) });
	}, [gridActions, emit, gridState.filterTree]);

	// Compute frozen columns: id column if present
	const frozenCount = useMemo(() => {
		const idFrozen = columnKeys[0] === 'id' ? 1 : 0;
		return idFrozen; // Row markers are separate
	}, [columnKeys]);

	// Unified, mode-aware refetch. Shared by the load-state retry path and the
	// imperative handle in the Sheets shell.
	const refetch = useCallback(() => {
		if (infiniteScroll) {
			infiniteGridData.invalidate();
		} else {
			void dataLoadingResult.contextValue.refetch?.();
		}
	}, [infiniteScroll, infiniteGridData, dataLoadingResult.contextValue]);

	// Pagination setter that mirrors the default chrome behavior (emit page:change).
	const setPageIndex = useCallback(
		(updater: number | ((prev: number) => number)) => {
			const next = typeof updater === 'function' ? updater(gridState.pageIndex) : updater;
			gridActions.setPageIndex(next);
			emit('page:change', { pageIndex: next });
		},
		[gridActions, gridState.pageIndex, emit],
	);

	// Loaded successfully but no server rows and nothing drafted yet, with no active filter.
	const isEmpty =
		hasCompletedInitialLoad &&
		serverRowCount === 0 &&
		draftRows.length === 0 &&
		countConditions(gridState.filterTree) === 0;

	return {
		// -- Stable headless surface (see UseSheetsResult) --
		columns,
		rowCount: combinedRows.length,
		draft: {
			hasDrafts: hasDraftRows,
			appendRow: handleRowAppended,
			submitDrafts: handleSubmitDraftRows,
			deleteSelected,
		},
		selection: {
			gridSelection: gridState.gridSelection,
			setGridSelection: gridActions.setGridSelection,
			setActiveCell: gridActions.setActiveCell,
			moveActive: gridActions.moveActiveCell,
		},
		pagination: {
			pageIndex: gridState.pageIndex,
			pageCount: totalPages,
			setPageIndex,
		},
		isInitialLoading,
		dataError,
		hasCompletedInitialLoad,
		isEmpty,
		refetch,

		// -- Internal chrome bindings (not a stable API) --
		_shell: {
			combinedRows,
			columnKeys,
			totalCount,
			serverRowCount,
			draftRowCount: draftRows.length,
			infiniteScroll,
			filterTree: gridState.filterTree,
			filtersOpen: gridState.filtersOpen,
			setFilterTree: gridActions.setFilterTree,
			setFiltersOpen: gridActions.setFiltersOpen,
			clearAllFilters: gridActions.clearAllFilters,
			applyFilters,
			fieldTypeMap,
			setGridSelectionForControls,
			onHeaderClicked,
			onVisibleRegionChanged: handleVisibleRegionChanged,
			sorting: gridState.sorting,
			columnWidths: gridState.columnWidths,
			resizeColumn: gridActions.resizeColumn,
			frozenCount,
			selectedRowCount,
			canCreate,
			canUpdate,
			canDelete,
			readOnlyReason,
			getRowId,
			isSubmittingDrafts,
			submitDraftButtonDisabled,
			submitDraftLabel,
			getSheetsCellContent,
			cellRegistry,
			commitCellValue,
			commitCells,
			commitCellPatch,
			submitDraftRow: handleSubmitDraftRowForEditor,
			invalidateData,
			undo: history.undo,
			redo: history.redo,
			canUndo: history.canUndo,
			canRedo: history.canRedo,
			emit,
		},
	};
}

import type { QueryClient } from '@tanstack/react-query';

import { TypedDocumentString } from '@constructive-io/data';
import type { CleanTable } from '@constructive-io/data';

import type { SheetsExecuteFn } from '../context/sheets-execute';
import type { SheetsScopeKey } from '../context/sheets-context';
import { sheetsQueryKeys } from './query-keys';

interface EnumValuesQuery {
	__type: {
		enumValues: Array<{ name: string } | null> | null;
	} | null;
}

interface EnumValuesQueryVariables {
	typeName: string;
}

const EnumValuesDoc = new TypedDocumentString<EnumValuesQuery, EnumValuesQueryVariables>(`
	query EnumValues($typeName: String!) {
		__type(name: $typeName) {
			enumValues {
				name
			}
		}
	}
`);

/**
 * Fetch and cache the valid orderBy enum values for a table.
 * Returns a Set of valid enum strings (e.g. "NOTES_ASC", "ID_DESC"),
 * or null if the type cannot be resolved.
 */
async function getOrderByEnumValues(
	orderByTypeName: string,
	scopeKey: SheetsScopeKey,
	queryClient: QueryClient,
	execute: SheetsExecuteFn,
): Promise<Set<string> | null> {
	const values = await queryClient.fetchQuery<Set<string>>({
		queryKey: sheetsQueryKeys.enumValues(scopeKey, orderByTypeName),
		queryFn: async () => {
			const response = await execute<EnumValuesQuery>(EnumValuesDoc, { typeName: orderByTypeName });

			const names = (response.__type?.enumValues ?? [])
				.map((v) => v?.name)
				.filter((name): name is string => typeof name === 'string' && name.length > 0);

			return new Set(names);
		},
		staleTime: 5 * 60 * 1000,
		gcTime: 30 * 60 * 1000,
	});

	return values.size > 0 ? values : null;
}

/**
 * Filter orderBy variables to only include values that exist in the schema.
 * Mutates the variables object in place — removes invalid values and deletes
 * the orderBy key entirely if no valid values remain.
 */
export async function validateOrderByVariables(
	variables: Record<string, unknown>,
	table: CleanTable,
	scopeKey: SheetsScopeKey,
	queryClient: QueryClient,
	execute: SheetsExecuteFn,
): Promise<void> {
	if (!variables.orderBy || !Array.isArray(variables.orderBy) || !table.inflection?.orderByType) {
		return;
	}

	const validValues = await getOrderByEnumValues(table.inflection.orderByType, scopeKey, queryClient, execute);
	if (!validValues) return;

	variables.orderBy = (variables.orderBy as string[]).filter((v) => validValues.has(v));
	if ((variables.orderBy as string[]).length === 0) {
		delete variables.orderBy;
	}
}

import type { SheetsScopeKey } from '../context/sheets-context';

export function isSheetsScopeKey(value: unknown): value is SheetsScopeKey {
	if (!value || typeof value !== 'object') return false;
	const candidate = value as Record<string, unknown>;
	return 'databaseId' in candidate && 'endpoint' in candidate && 'identityKey' in candidate;
}

export function reuseSheetsPlaceholderData<T>(
	previousData: T | undefined,
	previousQueryKey: readonly unknown[] | undefined,
	currentScope: SheetsScopeKey,
): T | undefined {
	const previousScope = previousQueryKey?.[1];
	if (!isSheetsScopeKey(previousScope)) return undefined;
	if (previousScope.databaseId !== currentScope.databaseId) return undefined;
	if (previousScope.endpoint !== currentScope.endpoint) return undefined;
	if (previousScope.identityKey !== currentScope.identityKey) return undefined;
	return previousData;
}

export const sheetsQueryKeys = {
	root: ['sheets'] as const,
	scope: (scope: SheetsScopeKey) => ['sheets', scope] as const,
	meta: (scope: SheetsScopeKey) => [...sheetsQueryKeys.scope(scope), 'meta'] as const,
	typeFields: (scope: SheetsScopeKey, typeName: string) =>
		[...sheetsQueryKeys.scope(scope), 'type-fields', typeName] as const,
	enumValues: (scope: SheetsScopeKey, typeName: string) =>
		[...sheetsQueryKeys.scope(scope), 'enum-values', typeName] as const,
	relations: (scope: SheetsScopeKey, tableName: string) =>
		[...sheetsQueryKeys.scope(scope), 'relations', tableName] as const,
	table: (scope: SheetsScopeKey, tableName: string) => [...sheetsQueryKeys.scope(scope), 'table', tableName] as const,
	tableRows: (scope: SheetsScopeKey, tableName: string, options?: unknown) =>
		[...sheetsQueryKeys.table(scope, tableName), 'rows', options] as const,
	tableRow: (scope: SheetsScopeKey, tableName: string, id: unknown) =>
		[...sheetsQueryKeys.table(scope, tableName), 'row', id] as const,
	tableCount: (scope: SheetsScopeKey, tableName: string, where?: Record<string, unknown> | null) =>
		[...sheetsQueryKeys.table(scope, tableName), 'count', where] as const,
	infiniteTable: (scope: SheetsScopeKey, tableName: string) =>
		[...sheetsQueryKeys.scope(scope), 'infinite-table', tableName] as const,
	infiniteTablePage: (scope: SheetsScopeKey, tableName: string, pageIndex: number, options: unknown) =>
		[...sheetsQueryKeys.infiniteTable(scope, tableName), 'page', pageIndex, options] as const,
	infiniteTableTotalCount: (scope: SheetsScopeKey, tableName: string, where?: Record<string, unknown>) =>
		[...sheetsQueryKeys.infiniteTable(scope, tableName), 'totalCount', where] as const,
	cursorTable: (scope: SheetsScopeKey, tableName: string, options?: unknown) =>
		[...sheetsQueryKeys.scope(scope), 'cursor-table', tableName, options] as const,
} as const;

import type { QueryClient } from '@tanstack/react-query';
import { toCamelCase, toPascalCase, pluralize, singularize } from 'inflekt';

import { TypedDocumentString } from '@constructive-io/data';

import type { CleanTable } from '@constructive-io/data';
import type { FieldSelection, SimpleFieldSelection } from '@constructive-io/data';
import type { SheetsExecuteFn } from '../context/sheets-execute';
import type { SheetsScopeKey } from '../context/sheets-context';
import { sheetsQueryKeys } from './query-keys';

interface TypeFieldsQuery {
	__type: {
		fields: Array<{ name: string } | null> | null;
	} | null;
}

interface TypeFieldsQueryVariables {
	typeName: string;
}

const TypeFieldsDoc = new TypedDocumentString<TypeFieldsQuery, TypeFieldsQueryVariables>(`
	query TypeFields($typeName: String!) {
		__type(name: $typeName) {
			fields {
				name
			}
		}
	}
`);

type RelationDescriptor = {
	fieldName: string;
	kind: 'belongsTo' | 'hasOne' | 'hasMany' | 'manyToMany';
	referencedTableName?: string;
	keyNames: string[];
};

type ResolveRelationFieldMapArgs = {
	table: CleanTable;
	fieldSelection?: FieldSelection;
	scopeKey: SheetsScopeKey;
	queryClient: QueryClient;
	execute: SheetsExecuteFn;
};

export async function resolveRelationFieldMap({
	table,
	fieldSelection,
	scopeKey,
	queryClient,
	execute,
}: ResolveRelationFieldMapArgs): Promise<Record<string, string | null>> {
	const requestedRelationFields = getRequestedRelationFields(fieldSelection);
	if (requestedRelationFields.length === 0) {
		return {};
	}

	const relations = collectRelationDescriptors(table);
	if (relations.length === 0) {
		return {};
	}

	const relationByFieldName = new Map(relations.map((relation) => [relation.fieldName, relation] as const));
	const relationFieldsSet = new Set(relations.map((relation) => relation.fieldName));
	const candidateFields = requestedRelationFields.filter((fieldName) => relationFieldsSet.has(fieldName));

	if (candidateFields.length === 0) {
		return {};
	}

	const availableFields = await getTypeFieldSet(table, scopeKey, queryClient, execute);

	const relationFieldMap: Record<string, string | null> = {};

	// Best effort fallback if introspection fields are unavailable.
	if (!availableFields || availableFields.size === 0) {
		candidateFields.forEach((fieldName) => {
			if (fieldName.includes('ByMy')) {
				relationFieldMap[fieldName] = fieldName.replace('ByMy', 'By');
			}
		});
		return relationFieldMap;
	}

	candidateFields.forEach((fieldName) => {
		if (availableFields.has(fieldName)) {
			return;
		}

		const relation = relationByFieldName.get(fieldName);
		const candidates = buildRelationFieldCandidates(fieldName, relation);
		const match = candidates.find((candidate) => availableFields.has(candidate));

		// Null means "omit this field from selection" to avoid query failure.
		relationFieldMap[fieldName] = match ?? null;
	});

	return relationFieldMap;
}

function getRequestedRelationFields(fieldSelection?: FieldSelection): string[] {
	if (!fieldSelection || typeof fieldSelection === 'string') {
		return [];
	}

	const requested = new Set<string>();
	const selection = fieldSelection as SimpleFieldSelection;

	(selection.includeRelations ?? []).forEach((fieldName) => requested.add(fieldName));

	if (selection.include) {
		Object.entries(selection.include).forEach(([fieldName, value]) => {
			if (value) {
				requested.add(fieldName);
			}
		});
	}

	return Array.from(requested);
}

function collectRelationDescriptors(table: CleanTable): RelationDescriptor[] {
	const descriptors: RelationDescriptor[] = [];

	table.relations.belongsTo.forEach((relation) => {
		if (!relation.fieldName) return;
		descriptors.push({
			fieldName: relation.fieldName,
			kind: 'belongsTo',
			referencedTableName: relation.referencesTable || undefined,
			keyNames: relation.keys.map((key) => key.name).filter(Boolean),
		});
	});

	table.relations.hasOne.forEach((relation) => {
		if (!relation.fieldName) return;
		descriptors.push({
			fieldName: relation.fieldName,
			kind: 'hasOne',
			referencedTableName: relation.referencedByTable || undefined,
			keyNames: relation.keys.map((key) => key.name).filter(Boolean),
		});
	});

	table.relations.hasMany.forEach((relation) => {
		if (!relation.fieldName) return;
		descriptors.push({
			fieldName: relation.fieldName,
			kind: 'hasMany',
			referencedTableName: relation.referencedByTable || undefined,
			keyNames: relation.keys.map((key) => key.name).filter(Boolean),
		});
	});

	table.relations.manyToMany.forEach((relation) => {
		if (!relation.fieldName) return;
		descriptors.push({
			fieldName: relation.fieldName,
			kind: 'manyToMany',
			referencedTableName: relation.rightTable || undefined,
			keyNames: [],
		});
	});

	return descriptors;
}

function buildRelationFieldCandidates(fieldName: string, relation?: RelationDescriptor): string[] {
	const candidates = new Set<string>();
	const add = (value: string | null | undefined) => {
		if (!value) return;
		candidates.add(value);
	};

	add(fieldName);
	add(fieldName.replace(/ByMy([A-Z])/g, 'By$1'));
	add(fieldName.replace(/My([A-Z])/g, '$1'));

	const byMatch = /^(.*)By(.+)$/.exec(fieldName);
	if (byMatch) {
		const [, prefixRaw, suffixRaw] = byMatch;
		const cleanedSuffix = suffixRaw.replace(/^My/, '');
		const prefixSingular = singularize(prefixRaw);
		const prefixPlural = pluralize(prefixSingular);

		add(`${prefixRaw}By${cleanedSuffix}`);
		add(`${prefixSingular}By${cleanedSuffix}`);
		add(`${prefixPlural}By${cleanedSuffix}`);
	}

	if (!relation) {
		return Array.from(candidates);
	}

	const firstKey = relation.keyNames[0];
	const keyPascalCase = firstKey ? toPascalCase(firstKey) : null;
	const relationTable = relation.referencedTableName;

	if (relationTable) {
		const singularRef = toCamelCase(relationTable);
		const pluralRef = pluralize(singularRef);

		add(singularRef);
		add(pluralRef);

		if (keyPascalCase) {
			add(`${singularRef}By${keyPascalCase}`);
			add(`${pluralRef}By${keyPascalCase}`);
		}
	}

	if (relation.kind === 'hasMany' || relation.kind === 'manyToMany') {
		const fieldPrefix = fieldName.split('By')[0];
		add(pluralize(singularize(fieldPrefix)));
	}

	return Array.from(candidates);
}

async function getTypeFieldSet(
	table: CleanTable,
	scopeKey: SheetsScopeKey,
	queryClient: QueryClient,
	execute: SheetsExecuteFn,
): Promise<Set<string> | null> {
	const typeNames = [table.inflection?.tableType, table.name]
		.filter((candidate): candidate is string => typeof candidate === 'string' && candidate.trim().length > 0)
		.filter((candidate, index, values) => values.indexOf(candidate) === index);

	for (const typeName of typeNames) {
		const fields = await queryClient.fetchQuery<string[]>({
			queryKey: sheetsQueryKeys.typeFields(scopeKey, typeName),
			queryFn: async () => {
				const response = await execute<TypeFieldsQuery>(TypeFieldsDoc, { typeName });

				return (response.__type?.fields ?? [])
					.map((field) => field?.name)
					.filter((name): name is string => typeof name === 'string' && name.length > 0);
			},
			staleTime: 5 * 60 * 1000,
			gcTime: 30 * 60 * 1000,
		});

		if (fields.length > 0) {
			return new Set(fields);
		}
	}

	return null;
}

/**
 * Build data grid columns that understand relation metadata
 */
import { useCallback, useMemo } from 'react';

import { isImageField, resolveCellType, type FieldMetadata } from '../cell-types/cell-type-resolver';
import { getColumnWidthByMeta } from '../grid/sheets.utils';

import { useRelationMetadataCache, type RelationMetadata } from './use-relation-metadata-cache';

type RelationKind = 'belongsTo' | 'hasOne' | 'hasMany' | 'manyToMany';

/** Native column descriptor — key/title/width, mappable 1:1 to {@link SheetsColumnDescriptor}. */
export interface RelationGridColumn {
	id: string;
	title: string;
	width: number;
}

/**
 * Relation-aware column info with simple error handling
 */
export interface RelationColumnInfo {
	columns: RelationGridColumn[];
	columnKeys: string[];
	relationMetadata: Record<string, RelationMetadata>;
	metaFields?: FieldMetadata[];
	hasRelationErrors: boolean;
	relationCount: number;
	// Helper functions (backward compatible)
	isImageField: (fieldMeta: FieldMetadata | undefined, fieldName?: string) => boolean;
	findImageColumnKey: (columnKeys: string[], fieldMetaMap: Map<string, unknown>, currentColKey?: string) => string;
	getRelationKind: (fieldName: string) => RelationKind | null;
	isRelationField: (fieldName: string) => boolean;
	invalidateRelationCache: () => Promise<void>;
	// For backward compatibility
	relationTypeByField: Map<string, RelationKind>;
}

/**
 * Create data grid columns with relation metadata baked in
 */
export function useRelationColumns(tableName?: string, rows?: unknown[]): RelationColumnInfo {
	const { relationMetadata, tableRelations, cacheState, getRelationKind, isRelationField, invalidateRelationCache } =
		useRelationMetadataCache(tableName);

	const metaFields = useMemo<FieldMetadata[] | undefined>(() => {
		return tableRelations?.fields.map((field) => ({
			name: field.name,
			type: field.type,
		}));
	}, [tableRelations]);

	const metaFieldByName = useMemo(() => {
		const map = new Map<string, FieldMetadata>();
		for (const field of metaFields ?? []) {
			if (field?.name) map.set(field.name, field);
		}
		return map;
	}, [metaFields]);

	const baseFieldNames = useMemo(() => {
		if (rows && rows.length > 0) {
			const sample = rows[0] ?? {};
			return Object.keys(sample);
		}

		if (metaFields?.length) {
			const scalarNames = metaFields.map((field) => field?.name).filter((name): name is string => Boolean(name));
			const relationNames: string[] = [];
			relationMetadata.forEach((rel) => {
				if (rel.sourceField === 'relation') relationNames.push(rel.fieldName);
			});
			return Array.from(new Set([...scalarNames, ...relationNames]));
		}

		return [] as string[];
	}, [rows, metaFields, relationMetadata]);

	// Extract column keys from data
	const columnKeys: string[] = useMemo(() => {
		if (baseFieldNames.length === 0) return [];
		const keys = [...baseFieldNames];

		const belongsToForeignKeysToHide = new Set<string>();
		const foreignKeysByRelationField = new Map<string, string[]>();

		relationMetadata.forEach((rel) => {
			if (rel.sourceField === 'foreignKey' && rel.relationFieldName) {
				const existing = foreignKeysByRelationField.get(rel.relationFieldName);
				if (existing) {
					existing.push(rel.fieldName);
				} else {
					foreignKeysByRelationField.set(rel.relationFieldName, [rel.fieldName]);
				}
			}
		});

		relationMetadata.forEach((rel) => {
			if (rel.sourceField !== 'relation' || rel.relationKind !== 'belongsTo' || !rel.relationFieldName) {
				return;
			}

			const foreignKeyEntries = foreignKeysByRelationField.get(rel.relationFieldName);
			if (foreignKeyEntries?.length) {
				foreignKeyEntries.forEach((fieldName) => {
					belongsToForeignKeysToHide.add(fieldName);
				});
			}
		});

		const filteredKeys = keys.filter((key) => !belongsToForeignKeysToHide.has(key));

		// Ensure id comes first if present
		const idIdx = filteredKeys.indexOf('id');
		if (idIdx > -1) {
			filteredKeys.splice(idIdx, 1);
			filteredKeys.unshift('id');
		}
		return filteredKeys;
	}, [baseFieldNames, relationMetadata]);

	// Create relation metadata map for quick lookup
	const relationMetadataMap = useMemo(() => {
		const map: Record<string, RelationMetadata> = {};

		relationMetadata.forEach((rel) => {
			map[rel.fieldName] = rel;
		});

		return map;
	}, [relationMetadata]);

	// Table fields metadata
	// Generate columns with improved error handling
	const columns: RelationGridColumn[] = useMemo(() => {
		return columnKeys.map((fieldName) => {
			const metaField = metaFieldByName.get(fieldName);
			const relationInfo = relationMetadataMap[fieldName];
			const relationDisplayField = relationInfo?.relationFieldName || undefined;
			const isForeignKeyRelationField = relationInfo?.sourceField === 'foreignKey';

			// Use centralized cell type resolution
			const resolution = resolveCellType(fieldName, metaField);
			const cellType = resolution.cellType;

			// For relation fields, use relation kind as type label
			const typeLabel = relationInfo?.relationKind
				? relationInfo.relationKind
				: metaField
					? metaField.type?.pgAlias || metaField.type?.pgType || metaField.type?.gqlType
					: cellType;

			let headerName = fieldName;
			if (relationInfo?.displayName) {
				headerName = relationInfo.displayName;
			} else if (relationDisplayField) {
				headerName = relationDisplayField;
			} else if (isForeignKeyRelationField) {
				const stripped = fieldName.replace(/Id$/i, '');
				headerName = stripped.length > 0 ? stripped : fieldName;
			}

			const titleRaw = typeLabel ? `${headerName} (${typeLabel})` : headerName;

			return {
				id: fieldName,
				title: titleRaw,
				width: metaField ? getColumnWidthByMeta(metaField) : 150,
			} satisfies RelationGridColumn;
		});
	}, [columnKeys, metaFieldByName, relationMetadataMap]);

	// Helper function using centralized image field detection
	const checkIsImageField = useCallback((fieldMeta: FieldMetadata | undefined, fieldName?: string): boolean => {
		return isImageField(fieldMeta, fieldName);
	}, []);

	// Helper function to find the correct column key for image cells
	const findImageColumnKey = useCallback(
		(columnKeys: string[], fieldMetaMap: Map<string, unknown>, currentColKey?: string): string => {
			// If we already have a reliable column key, use it
			if (currentColKey && currentColKey !== 'id' && fieldMetaMap.has(currentColKey)) {
				const fieldMeta = fieldMetaMap.get(currentColKey) as FieldMetadata | undefined;
				if (checkIsImageField(fieldMeta, currentColKey)) {
					return currentColKey;
				}
			}

			// Look through all columns to find image-type fields
			for (const key of columnKeys) {
				const fieldMeta = fieldMetaMap.get(key) as FieldMetadata | undefined;
				if (fieldMeta && checkIsImageField(fieldMeta, key)) {
					return key;
				}
			}

			// Fallback to the current column key or first non-id column
			return currentColKey || columnKeys.find((k) => k !== 'id') || columnKeys[0] || '';
		},
		[checkIsImageField],
	);

	// Create backward compatibility map
	const relationTypeByField = useMemo(() => {
		const map = new Map<string, RelationKind>();
		Object.entries(relationMetadataMap).forEach(([fieldName, info]) => {
			map.set(fieldName, info.relationKind);
		});
		return map;
	}, [relationMetadataMap]);

	return {
		columns,
		columnKeys,
		relationMetadata: relationMetadataMap,
		metaFields,
		hasRelationErrors: cacheState.isError,
		relationCount: cacheState.relationCount,
		isImageField: checkIsImageField,
		findImageColumnKey,
		getRelationKind,
		isRelationField,
		invalidateRelationCache,
		relationTypeByField, // For backward compatibility
	};
}

/**
 * Drop-in replacement for the original useDataGridColumns hook
 * Maintains complete backward compatibility while providing improvements
 */
export function useDataGridColumns(tableName?: string, rows: unknown[] = []) {
	const enhanced = useRelationColumns(tableName, rows);

	// Return exact same interface as original for backward compatibility
	return {
		columns: enhanced.columns,
		columnKeys: enhanced.columnKeys,
		metaFields: enhanced.metaFields,
		isImageField: enhanced.isImageField,
		findImageColumnKey: enhanced.findImageColumnKey,
		relationTypeByField: enhanced.relationTypeByField,
		// Add new enhanced features for those who want them
		relationMetadata: enhanced.relationMetadata,
		hasRelationErrors: enhanced.hasRelationErrors,
		relationCount: enhanced.relationCount,
		getRelationKind: enhanced.getRelationKind,
		isRelationField: enhanced.isRelationField,
		invalidateRelationCache: enhanced.invalidateRelationCache,
	};
}

/**
 * Light-weight relation metadata cache with straightforward error handling
 */
import { useCallback, useMemo } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';

import { pluralize } from 'inflekt';
import { cleanTable, pgFieldToCamelCase, type CleanTable } from '@constructive-io/data';
import { useSheetsMeta } from './use-sheets-meta';
import { useSheetsContext, type SheetsScopeKey } from '../context/sheets-context';
import { sheetsQueryKeys } from './query-keys';
import { getJunctionTableNames, isJunctionTablePure } from '../utils/relation-utils';
import { sheetsLogger } from '../utils/sheets-logger';

/**
 * Simple cache keys for relations
 */
export const RELATION_CACHE_KEYS = {
	tableRelations: (scope: SheetsScopeKey, tableName: string) => sheetsQueryKeys.relations(scope, tableName),
} as const;

/**
 * Cache timing tuned for relation metadata
 */
export const RELATION_CACHE_CONFIG = {
	staleTime: 5 * 60 * 1000, // 5 minutes - reasonable for relation metadata
	gcTime: 30 * 60 * 1000, // 30 minutes - keep in memory longer
	retry: 3, // Retry failed requests
	retryDelay: (attemptIndex: number) => Math.min(1000 * 2 ** attemptIndex, 5000),
} as const;

export type RelationMetadataSource = 'relation' | 'foreignKey';

export interface RelationMetadata {
	tableName: string;
	fieldName: string;
	relationKind: 'belongsTo' | 'hasOne' | 'hasMany' | 'manyToMany';
	targetTable: string;
	isOptional: boolean;
	foreignKeyFields: string[];
	/** Headline relation field name when this metadata originates from a foreign key */
	relationFieldName?: string | null;
	/** Primary foreign key field associated with the relation */
	foreignKeyField?: string;
	/** Indicates whether the metadata entry is for the relation field or the FK column */
	sourceField: RelationMetadataSource;
	junctionTable?: string;
	displayName?: string;
}

/**
 * Simple error state tracking
 */
export interface RelationCacheState {
	isLoading: boolean;
	isError: boolean;
	error: Error | null;
	hasData: boolean;
	relationCount: number;
}

export interface RelationMetadataSet {
	relationFields: RelationMetadata[];
	foreignKeyFields: RelationMetadata[];
}

/**
 * Cache and expose relation metadata for a table
 */
export function useRelationMetadataCache(tableName?: string) {
	const queryClient = useQueryClient();
	const { scopeKey } = useSheetsContext();
	const { data: metaData, isError: metaError, error: metaErrorDetails } = useSheetsMeta();

	// Get table relations with improved error handling
	const {
		data: tableRelations,
		isLoading,
		isError,
		error,
	} = useQuery({
		queryKey: RELATION_CACHE_KEYS.tableRelations(scopeKey, tableName || ''),
		queryFn: async (): Promise<CleanTable | null> => {
			if (!metaData?._meta?.tables || !tableName) {
				return null;
			}

			const metaTable = metaData._meta.tables.find((t) => t?.name === tableName);
			if (!metaTable) {
				// Don't throw error for missing table - just return null
				sheetsLogger().debug?.(`Table "${tableName}" not found in metadata`);
				return null;
			}

			return cleanTable(metaTable);
		},
		...RELATION_CACHE_CONFIG,
		refetchOnMount: true, // Respect staleTime and refresh stale relation metadata on mount
		enabled: Boolean(metaData && tableName),
	});

	// Extract relation metadata with error handling
	const { relationFields, foreignKeyFields } = useMemo((): RelationMetadataSet => {
		if (!tableRelations?.relations || isError) {
			return { relationFields: [], foreignKeyFields: [] };
		}

		const relationFieldEntries: RelationMetadata[] = [];
		const foreignKeyEntries: RelationMetadata[] = [];
		const relations = tableRelations.relations;

		try {
			// Process belongsTo relations
			relations.belongsTo.forEach((rel) => {
				if (!rel) return;
				const foreignKeys = rel.keys.map((k) => k.name);
				const primaryForeignKey = foreignKeys[0];
				if (rel.fieldName) {
					relationFieldEntries.push({
						tableName: tableName || '',
						fieldName: rel.fieldName,
						relationKind: 'belongsTo',
						targetTable: rel.referencesTable,
						isOptional: !rel.isUnique,
						foreignKeyFields: foreignKeys,
						relationFieldName: rel.fieldName,
						foreignKeyField: primaryForeignKey,
						sourceField: 'relation',
					});
				}

				foreignKeys.forEach((fk) => {
					if (!fk) return;
					foreignKeyEntries.push({
						tableName: tableName || '',
						fieldName: fk,
						relationKind: 'belongsTo',
						targetTable: rel.referencesTable,
						isOptional: !rel.isUnique,
						foreignKeyFields: foreignKeys,
						relationFieldName: rel.fieldName ?? null,
						foreignKeyField: fk,
						sourceField: 'foreignKey',
					});
				});
			});

			const rawMetaTables = (metaData?._meta?.tables ?? []).filter(
				(t): t is NonNullable<typeof t> => t != null,
			);

			// Resolve FK field in the related table using foreignKeyConstraints from _meta
			const findFk = (relatedTableName: string): string | undefined => {
				const rawRelated = rawMetaTables.find((t) => t?.name === relatedTableName);
				if (!rawRelated) return undefined;
				// v5 nested: constraints.foreignKey[]
				const v5Fks = Array.isArray(rawRelated.constraints) ? [] : rawRelated.constraints?.foreignKey;
				// v4 flat: foreignKeyConstraints[]
				const fks = v5Fks ?? rawRelated.foreignKeyConstraints ?? [];
				for (const fk of fks) {
					if (!fk) continue;
					const refName = fk.refTable?.name;
					if (refName && refName.toLowerCase() === (tableName || '').toLowerCase()) {
						const fieldName = fk.fields?.[0]?.name;
						if (fieldName) return pgFieldToCamelCase(fieldName);
					}
				}
				return undefined;
			};

			// Process hasOne relations
			relations.hasOne.forEach((rel) => {
				if (rel.fieldName) {
					relationFieldEntries.push({
						tableName: tableName || '',
						fieldName: rel.fieldName,
						relationKind: 'hasOne',
						targetTable: rel.referencedByTable,
						isOptional: true,
						foreignKeyFields: rel.keys.map((k) => k.name),
						relationFieldName: rel.fieldName,
						foreignKeyField: findFk(rel.referencedByTable),
						sourceField: 'relation',
					});
				}
			});

			const junctionTableNames = getJunctionTableNames(relations, rawMetaTables);

			// Process hasMany relations (skip those pointing to junction tables)
			relations.hasMany.forEach((rel) => {
				if (!rel.fieldName) return;
				// Skip hasMany relations pointing to junction tables (M:N covers these)
				if (junctionTableNames.has(rel.referencedByTable)) return;
				relationFieldEntries.push({
					tableName: tableName || '',
					fieldName: rel.fieldName,
					relationKind: 'hasMany',
					targetTable: rel.referencedByTable,
					isOptional: true,
					foreignKeyFields: rel.keys.map((k) => k.name),
					relationFieldName: rel.fieldName,
					foreignKeyField: findFk(rel.referencedByTable),
					sourceField: 'relation',
				});
			});

			// Process manyToMany relations (already deduped by rightTable in cleanTable())
			// Skip non-pure junction tables — they have required fields beyond the two FK columns
			relations.manyToMany.forEach((rel) => {
				if (rel.fieldName) {
					const leftFk = rel.junctionLeftKeyFields?.[0];
					const rightFk = rel.junctionRightKeyFields?.[0];
					if (rel.junctionTable && !isJunctionTablePure(rel.junctionTable, leftFk, rightFk, rawMetaTables)) {
						return;
					}
					relationFieldEntries.push({
						tableName: tableName || '',
						fieldName: rel.fieldName,
						relationKind: 'manyToMany',
						targetTable: rel.rightTable,
						isOptional: true,
						foreignKeyFields: [],
						relationFieldName: rel.fieldName,
						foreignKeyField: undefined,
						sourceField: 'relation',
						junctionTable: rel.junctionTable,
						displayName: pluralize(rel.rightTable),
					});
				}
			});
		} catch (processError) {
			sheetsLogger().warn('Error processing relation metadata:', processError);
		}

		return { relationFields: relationFieldEntries, foreignKeyFields: foreignKeyEntries };
	}, [tableRelations, tableName, isError, metaData]);

	const relationMetadata = useMemo(() => relationFields.concat(foreignKeyFields), [relationFields, foreignKeyFields]);

	const relationMap = useMemo(() => {
		const map = new Map<string, RelationMetadata>();
		relationFields.forEach((rel) => {
			map.set(rel.fieldName, rel);
		});
		foreignKeyFields.forEach((rel) => {
			map.set(rel.fieldName, rel);
		});
		return map;
	}, [relationFields, foreignKeyFields]);

	// Simple cache invalidation
	const invalidateRelationCache = useCallback(async () => {
		if (tableName) {
			await queryClient.invalidateQueries({
				queryKey: RELATION_CACHE_KEYS.tableRelations(scopeKey, tableName),
			});
		}
	}, [queryClient, scopeKey, tableName]);

	// Get relation info for a specific field
	const getRelationInfo = useCallback(
		(fieldName: string): RelationMetadata | null => {
			return relationMap.get(fieldName) || null;
		},
		[relationMap],
	);

	// Check if field is a relation
	const isRelationField = useCallback(
		(fieldName: string): boolean => {
			return relationMap.has(fieldName);
		},
		[relationMap],
	);

	// Get relation kind for backward compatibility
	const getRelationKind = useCallback(
		(fieldName: string): 'belongsTo' | 'hasOne' | 'hasMany' | 'manyToMany' | null => {
			const relation = relationMap.get(fieldName);
			return relation?.relationKind || null;
		},
		[relationMap],
	);

	// Simple cache state
	const cacheState: RelationCacheState = useMemo(
		() => ({
			isLoading: isLoading || (!metaData && !metaError),
			isError: isError || metaError,
			error: error || metaErrorDetails || null,
			hasData: Boolean(tableRelations && relationMetadata.length > 0),
			relationCount: relationMetadata.length,
		}),
		[isLoading, metaData, metaError, isError, error, metaErrorDetails, tableRelations, relationMetadata.length],
	);

	return {
		// Data
		relationMetadata,
		relationFields,
		foreignKeyFields,
		relationMap,
		tableRelations,

		// State
		cacheState,
		isLoading,
		isError,
		error,

		// Utilities
		getRelationInfo,
		isRelationField,
		getRelationKind,
		invalidateRelationCache,
	};
}

/**
 * Infinite scroll table hook with hybrid cursor-based pagination
 *
 * Uses a hybrid pagination strategy:
 * - Page 0: Offset-based (`first: N`) to get initial data + endCursor
 * - Page N+1: Cursor-based (`first: N, after: endCursor`) for efficient deep pagination
 *
 * This leverages PostGraphile's Relay Connection spec for optimal performance on large datasets.
 *
 * Data Persistence:
 * - Uses React Query cache as the source of truth for page data
 * - Data survives component unmount/remount and route changes
 * - Only clears when table name or query options actually change (deep comparison)
 *
 * Ported from apps/admin use-infinite-table.ts with context injection.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useQueries, useQueryClient } from '@tanstack/react-query';

import { useSheetsContext } from '../context/sheets-context';
import type { SheetsScopeKey } from '../context/sheets-context';

import {
	cleanTable,
	type CleanTable,
	type MetaTable,
	type MutationOptions,
	type PageInfo,
	type QueryOptions,
} from '@constructive-io/data';
import { createError } from '@constructive-io/data';
import type { FieldSelection } from '@constructive-io/data';
import { reuseSheetsPlaceholderData } from './query-keys';
import { toOrderByEnumValue } from '@constructive-io/data';
import { useSheetsAdapter } from '../adapter/use-sheets-adapter';
import { useSheetsMeta } from './use-sheets-meta';
import { sheetsQueryKeys } from './query-keys';
import { resolveRelationFieldMap } from './relation-field-resolution';
import { validateOrderByVariables } from './orderby-enum-resolution';
import { transformToPostGraphileVariables } from './use-sheets-table';

type RowRecord = Record<string, unknown>;

/** Data for a single loaded page */
export interface PageData<T = RowRecord> {
	rows: T[];
	pageInfo: PageInfo;
	pageIndex: number;
	totalCount?: number;
}

/** Options for the infinite table hook */
export interface UseInfiniteTableOptions {
	/** Page size for fetching */
	pageSize?: number;
	/** Order by clauses */
	orderBy?: Array<{ field: string; direction: 'asc' | 'desc' }>;
	/** Filter conditions */
	where?: Record<string, unknown>;
	/** Field selection preset or custom selection */
	select?: FieldSelection;
	/** Enable/disable the hook */
	enabled?: boolean;
	/** Mutation options for CRUD operations */
	mutationOptions?: MutationOptions;
}

/** Result from the infinite table hook */
export interface UseInfiniteTableResult<T = RowRecord> {
	/** Get row at a specific index, returns null if not loaded */
	getRowAtIndex: (index: number) => T | null;
	/** Total count of rows in the table */
	totalCount: number;
	/** Check if a specific row index is loaded */
	isRowLoaded: (rowIndex: number) => boolean;
	/** Check if a specific page is currently loading */
	isPageLoading: (pageIndex: number) => boolean;
	/** Ensure rows in a range are loaded (call from onVisibleRegionChanged) */
	ensureRowsLoaded: (startRow: number, endRow: number) => void;
	/** All loaded pages */
	loadedPages: Map<number, PageData<T>>;
	/** Page size */
	pageSize: number;
	/** Overall loading state (true if any page is loading) */
	isLoading: boolean;
	/** Whether initial data has been loaded */
	hasInitialData: boolean;
	/** Error from the most recent failed fetch */
	error: Error | null;
	/** Invalidate all pages and refetch */
	invalidate: () => void;
	/** Reset to initial state (clears all pages, refetches page 0) */
	reset: () => void;
	/**
	 * Optimistically update a single row in the page cache without refetching.
	 * @param rowIndex The absolute row index
	 * @param patch Partial row data to merge with existing row
	 * @returns true if the row was found and updated, false otherwise
	 */
	updateRowAtIndex: (rowIndex: number, patch: Partial<T>) => boolean;
}

/** Query key factory for infinite table pages */
const sheetsInfiniteTableKeys = {
	all: (scope: SheetsScopeKey, tableName: string) => sheetsQueryKeys.infiniteTable(scope, tableName),
	page: (scope: SheetsScopeKey, tableName: string, pageIndex: number, optionsKey: string) =>
		[...sheetsQueryKeys.infiniteTable(scope, tableName), 'page', pageIndex, optionsKey] as const,
	totalCount: (scope: SheetsScopeKey, tableName: string, where?: Record<string, unknown>) =>
		sheetsQueryKeys.infiniteTableTotalCount(scope, tableName, where),
};

/**
 * Create a stable JSON key from options for deep comparison.
 * This ensures the key only changes when the actual values change, not object references.
 */
function createStableOptionsKey(options: {
	pageSize: number;
	orderBy?: Array<{ field: string; direction: 'asc' | 'desc' }>;
	where?: Record<string, unknown>;
	fieldSelection?: FieldSelection;
}): string {
	return JSON.stringify({
		pageSize: options.pageSize,
		orderBy: options.orderBy ?? null,
		where: options.where ?? null,
		fieldSelection: options.fieldSelection ?? null,
	});
}

/**
 * Hook for infinite scroll table with hybrid cursor-based pagination.
 * Uses React Query cache as the source of truth for data persistence.
 */
export function useSheetsInfiniteTable<T extends RowRecord = RowRecord>(
	tableName: string,
	options: UseInfiniteTableOptions = {},
): UseInfiniteTableResult<T> {
	const { pageSize = 100, orderBy, where, select: fieldSelection, enabled = true } = options;

	const queryClient = useQueryClient();
	const { execute, scopeKey } = useSheetsContext();
	const { data: meta } = useSheetsMeta({ enabled });
	const adapter = useSheetsAdapter();

	// Create stable options key using JSON serialization for deep comparison
	const stableOptionsKey = useMemo(
		() => createStableOptionsKey({ pageSize, orderBy, where, fieldSelection }),
		[pageSize, orderBy, where, fieldSelection],
	);

	// Track which pages we want to load
	const [requestedPages, setRequestedPages] = useState<Set<number>>(() => new Set([0]));

	// Cursor chain for cursor-based pagination (stored in ref for performance)
	const cursorChainRef = useRef<Map<number, string>>(new Map());
	const [cursorChainVersion, setCursorChainVersion] = useState(0);

	// Track latest total count from any page response
	const totalCountRef = useRef<number>(0);

	// Flag to defer cache invalidation to useEffect after synchronous reset
	const needsInvalidationRef = useRef(false);

	// Generation counter: incremented on every table/options reset. queryFn closures capture
	// the current generation and skip cursor writes if stale. This prevents in-flight queries
	// from a previous table/options context from poisoning cursorChainRef after a reset.
	// (PostGraphile v5 cursors include a digest hash scoped to table + ORDER BY, so a cursor
	// from one query context will be rejected by a different query context.)
	const generationRef = useRef(0);

	// Track previous stable key to detect actual changes
	const prevStableKeyRef = useRef<string>(stableOptionsKey);
	const prevTableNameRef = useRef<string>(tableName);

	// Get table metadata
	const tables = useMemo<CleanTable[]>(() => {
		if (!meta?._meta?.tables) return [];
		return meta._meta.tables
			.filter((candidate): candidate is MetaTable => candidate != null)
			.map((metaTable) => cleanTable(metaTable));
	}, [meta]);

	const table = useMemo<CleanTable | null>(
		() => tables.find((candidate) => candidate.name === tableName) ?? null,
		[tables, tableName],
	);

	// Synchronous render-time reset: clear cursors and state BEFORE pageQueries useMemo reads them.
	// This follows the React 18+ "storing information from previous renders" pattern where setState
	// during render causes React to discard the current render and retry with updated state.
	// On retry, the condition is false (refs already updated) so no infinite loop occurs.
	const tableChanged = prevTableNameRef.current !== tableName;
	const optionsChanged = prevStableKeyRef.current !== stableOptionsKey;

	if (tableChanged || optionsChanged) {
		// Clear cursors synchronously — must happen before pageQueries useMemo
		cursorChainRef.current.clear();
		totalCountRef.current = 0;

		// Bump generation so in-flight queryFn closures from the old context
		// will skip writing their stale cursors into cursorChainRef
		generationRef.current += 1;

		// Update tracking refs so condition is false on retry render
		prevTableNameRef.current = tableName;
		prevStableKeyRef.current = stableOptionsKey;

		// Flag cache invalidation for the subsequent useEffect
		needsInvalidationRef.current = true;

		// Trigger state update — React discards current render and retries
		setCursorChainVersion(0);
		setRequestedPages(new Set([0]));
	}

	// Cache invalidation is a side effect and must stay in useEffect
	useEffect(() => {
		if (needsInvalidationRef.current) {
			needsInvalidationRef.current = false;
			queryClient.invalidateQueries({
				queryKey: sheetsInfiniteTableKeys.all(scopeKey, tableName),
			});
		}
	}, [tableName, stableOptionsKey, queryClient, scopeKey]);

	// Helper to get page data from React Query cache
	const getPageDataFromCache = useCallback(
		(pageIndex: number): PageData<T> | undefined => {
			return queryClient.getQueryData<PageData<T>>(
				sheetsInfiniteTableKeys.page(scopeKey, tableName, pageIndex, stableOptionsKey),
			);
		},
		[queryClient, scopeKey, tableName, stableOptionsKey],
	);

	// Create query options for each requested page
	const pageQueries = useMemo(() => {
		if (!table || !enabled) return [];
		// Force recompute when cursor chain advances
		void cursorChainVersion;

		// Capture generation at useMemo time — queryFn closures use this to detect
		// if the query context has changed (table/options reset) before they write cursors
		const queryGeneration = generationRef.current;

		return Array.from(requestedPages).map((pageIndex) => {
			// Determine pagination strategy
			const isFirstPage = pageIndex === 0;
			const previousCursor = pageIndex > 0 ? cursorChainRef.current.get(pageIndex - 1) : undefined;
			// Pages:
			// - 0: always fetch
			// - 1: wait for cursor from page 0 (prefer cursor-based)
			// - 2+: allow offset fallback (supports scrollbar jumps without loading all intermediate pages)
			const canUseOffsetFallback = pageIndex >= 2;
			const canFetch = isFirstPage || previousCursor !== undefined || canUseOffsetFallback;

			return {
				queryKey: sheetsInfiniteTableKeys.page(scopeKey, tableName, pageIndex, stableOptionsKey),
				queryFn: async (): Promise<PageData<T>> => {
					if (!table) {
						throw createError.notFound(`Table '${tableName}' not found`);
					}

					// Build query options. `includePageInfo` is always set so the cursor
					// chain works on every page (page 0 has no `after` to imply pageInfo).
					const queryOptions: QueryOptions = {
						first: pageSize,
						orderBy,
						where: where as QueryOptions['where'],
						fieldSelection,
						includePageInfo: true, // Always include for cursor chain
					};

					// Prefer cursor-based pagination when possible; allow offset fallback for deep jumps.
					if (!isFirstPage) {
						if (previousCursor) {
							queryOptions.after = previousCursor;
						} else if (canUseOffsetFallback) {
							queryOptions.offset = pageIndex * pageSize;
						}
					}

					// Cache-bound resolution stays in the hook. The orderBy validation mutates
					// `variables.orderBy` (PostGraphile enum strings) in place; we fold that
					// result back into the `{ field, direction }[]` orderBy we hand the adapter,
					// so the adapter rebuilds an identical (validated) variables payload.
					const variables = transformToPostGraphileVariables(table, queryOptions);

					const [relationFieldMap] = await Promise.all([
						resolveRelationFieldMap({
							table,
							fieldSelection: queryOptions.fieldSelection,
							scopeKey,
							queryClient,
							execute,
						}),
						validateOrderByVariables(variables, table, scopeKey, queryClient, execute),
					]);

					const validatedOrderByEnum = new Set((variables.orderBy as string[] | undefined) ?? []);
					const availableOrderByFields = new Set(table.fields.map((field) => field.name));
					const validatedOrderBy = orderBy?.filter(
						({ field, direction }) =>
							availableOrderByFields.has(field) && validatedOrderByEnum.has(toOrderByEnumValue(field, direction)),
					);

					const res = await adapter.listRows<T>(
						{ table, allTables: tables, tableName },
						{
							...queryOptions,
							orderBy: validatedOrderBy,
							// resolveRelationFieldMap yields `string | null` (null = omit field). The
							// contract narrows to `string`, but the null values are passed through to
							// buildSelect unchanged at runtime — behavior is identical to before.
							relationFieldMap: relationFieldMap as Record<string, string>,
						},
						execute,
					);

					const rows = res.rows;
					// The adapter's AdapterPageInfo marks booleans optional; the underlying
					// PostGraphile connection always populates them (the doc selects all four),
					// so this narrows to PageInfo exactly as the inline connection cast did.
					const pageInfo: PageInfo = (res.pageInfo as PageInfo | undefined) || {
						hasNextPage: false,
						hasPreviousPage: false,
						endCursor: null,
						startCursor: null,
					};

					// Guard: only write refs if this queryFn's generation matches the current one.
					// In-flight queries from a previous table/options context will have a stale
					// generation and their writes are silently discarded.
					const isCurrentGeneration = queryGeneration === generationRef.current;

					// Update total count ref
					if (res.totalCount !== undefined && isCurrentGeneration) {
						totalCountRef.current = res.totalCount;
					}

					// Store cursor for next page (and bump version so dependent pages can enable)
					if (pageInfo.endCursor && isCurrentGeneration) {
						const prev = cursorChainRef.current.get(pageIndex);
						if (prev !== pageInfo.endCursor) {
							cursorChainRef.current.set(pageIndex, pageInfo.endCursor);
							setCursorChainVersion((v) => v + 1);
						}
					}

					const pageData: PageData<T> = {
						rows,
						pageInfo,
						pageIndex,
						totalCount: res.totalCount,
					};

					return pageData;
				},
				enabled: enabled && !!table && canFetch,
				// Reuse a page across sort/filter/page-size key changes only while the
				// endpoint, database, and authenticated identity remain unchanged.
				placeholderData: (
					previousData: PageData<T> | undefined,
					previousQuery: { queryKey: readonly unknown[] } | undefined,
				) =>
					reuseSheetsPlaceholderData(previousData, previousQuery?.queryKey, scopeKey),
				staleTime: 5 * 60 * 1000, // 5 minutes
				gcTime: 10 * 60 * 1000, // 10 minutes
			};
		});
		}, [
			table,
			tables,
			tableName,
			enabled,
			scopeKey,
			queryClient,
			execute,
			adapter,
			requestedPages,
			stableOptionsKey,
			pageSize,
		orderBy,
		where,
		fieldSelection,
		cursorChainVersion,
	]);

	// Execute all page queries
	const queryResults = useQueries({ queries: pageQueries });

	// Sync cursor chain from React Query cache on mount/rehydration
	// This restores cursors for pages that were cached but cursor chain was lost.
	// Guarded by generation to avoid restoring stale cursors during a reset transition.
	useEffect(() => {
		if (!enabled || !table) return;

		const gen = generationRef.current;

		// Check React Query cache for existing page data and restore cursors
		for (let i = 0; i < 100; i++) {
			// Bail if generation changed (a reset happened while this effect was running)
			if (gen !== generationRef.current) break;

			// Check up to 100 pages
			const cachedData = getPageDataFromCache(i);
			if (cachedData?.pageInfo?.endCursor && !cursorChainRef.current.has(i)) {
				cursorChainRef.current.set(i, cachedData.pageInfo.endCursor);
			}
			if (cachedData?.totalCount !== undefined) {
				totalCountRef.current = cachedData.totalCount;
			}
			if (!cachedData) break; // Stop at first missing page
		}
	}, [enabled, table, getPageDataFromCache]);

	// Compute loading states
	const isLoading = queryResults.some((result) => result.isLoading);

	// Check if we have initial data - either from current query or from cache
	const hasInitialData = useMemo(() => {
		// Check query results first
		const page0Query = queryResults.find((_, idx) => Array.from(requestedPages)[idx] === 0);
		if (page0Query?.data) return true;

		// Fall back to cache check
		const cachedPage0 = getPageDataFromCache(0);
		return cachedPage0 !== undefined;
	}, [queryResults, requestedPages, getPageDataFromCache]);

	const error = queryResults.find((result) => result.error)?.error ?? null;

	// Get row at index - reads from React Query cache
	// IMPORTANT: Always read from cache first since optimistic updates use setQueryData
	// which updates cache but doesn't immediately update queryResults references
	const getRowAtIndex = useCallback(
		(rowIndex: number): T | null => {
			const pageIndex = Math.floor(rowIndex / pageSize);
			const rowIndexInPage = rowIndex % pageSize;

			// Always read from React Query cache first - this ensures we get optimistically
			// updated data from setQueryData calls (used in updateRowAtIndex)
			const cachedData = getPageDataFromCache(pageIndex);
			if (cachedData) {
				return cachedData.rows[rowIndexInPage] ?? null;
			}

			// Fall back to query results if cache miss (shouldn't happen normally)
			const queryIndex = Array.from(requestedPages).indexOf(pageIndex);
			if (queryIndex !== -1 && queryResults[queryIndex]?.data) {
				const pageData = queryResults[queryIndex].data;
				return pageData.rows[rowIndexInPage] ?? null;
			}

			return null;
		},
		[pageSize, getPageDataFromCache, requestedPages, queryResults],
	);

	// Check if row is loaded - reads from cache first for consistency with getRowAtIndex
	const isRowLoaded = useCallback(
		(rowIndex: number): boolean => {
			const pageIndex = Math.floor(rowIndex / pageSize);
			const rowIndexInPage = rowIndex % pageSize;

			// Check cache first (consistent with getRowAtIndex)
			const cachedData = getPageDataFromCache(pageIndex);
			if (cachedData) {
				return rowIndexInPage < cachedData.rows.length;
			}

			// Fallback to query results
			const queryIndex = Array.from(requestedPages).indexOf(pageIndex);
			if (queryIndex !== -1 && queryResults[queryIndex]?.data) {
				return rowIndexInPage < queryResults[queryIndex].data.rows.length;
			}

			return false;
		},
		[pageSize, getPageDataFromCache, requestedPages, queryResults],
	);

	// Check if page is loading
	const isPageLoading = useCallback(
		(pageIndex: number): boolean => {
			const queryIndex = Array.from(requestedPages).indexOf(pageIndex);
			if (queryIndex === -1) return false;
			return queryResults[queryIndex]?.isLoading ?? false;
		},
		[requestedPages, queryResults],
	);

	// Ensure rows in range are loaded
	const ensureRowsLoaded = useCallback(
		(startRow: number, endRow: number) => {
			const startPage = Math.floor(Math.max(0, startRow) / pageSize);
			const endPage = Math.floor(Math.max(0, endRow - 1) / pageSize);

			const minPage = Math.max(0, startPage);
			const maxPage = endPage;

			setRequestedPages((prev) => {
				const next = new Set(prev);
				let changed = false;

				const maxPossiblePage =
					totalCountRef.current > 0 ? Math.max(0, Math.ceil(totalCountRef.current / pageSize) - 1) : null;
				const cappedMaxPage = maxPossiblePage === null ? maxPage : Math.min(maxPage, maxPossiblePage);

				for (let page = minPage; page <= cappedMaxPage; page++) {
					if (!next.has(page)) {
						next.add(page);
						changed = true;
					}
				}

				return changed ? next : prev;
			});
		},
		[pageSize],
	);

	// Build loadedPages map from React Query cache for backward compatibility
	const loadedPages = useMemo(() => {
		const map = new Map<number, PageData<T>>();

		// Add data from current query results
		Array.from(requestedPages).forEach((pageIndex, idx) => {
			const result = queryResults[idx];
			if (result?.data) {
				map.set(pageIndex, result.data);
			}
		});

		return map;
	}, [requestedPages, queryResults]);

	// Compute total count from query results or ref
	const totalCount = useMemo(() => {
		// Try to get from latest query result
		for (const result of queryResults) {
			if (result.data?.totalCount !== undefined) {
				return result.data.totalCount;
			}
		}
		return totalCountRef.current;
	}, [queryResults]);

	// Invalidate all pages
	const invalidate = useCallback(() => {
		// Clear cursor chain and bump generation to discard in-flight stale cursors
		cursorChainRef.current.clear();
		totalCountRef.current = 0;
		generationRef.current += 1;
		setCursorChainVersion(0);

		// Reset to page 0
		setRequestedPages(new Set([0]));

		// Invalidate React Query cache
		queryClient.invalidateQueries({ queryKey: sheetsInfiniteTableKeys.all(scopeKey, tableName) });
	}, [queryClient, scopeKey, tableName]);

	// Reset to initial state
	const reset = useCallback(() => {
		invalidate();
	}, [invalidate]);

	// Optimistically update a single row in the React Query cache
	const updateRowAtIndex = useCallback(
		(rowIndex: number, patch: Partial<T>): boolean => {
			const pageIndex = Math.floor(rowIndex / pageSize);
			const rowIndexInPage = rowIndex % pageSize;

			const queryKey = sheetsInfiniteTableKeys.page(scopeKey, tableName, pageIndex, stableOptionsKey);
			const cachedData = queryClient.getQueryData<PageData<T>>(queryKey);

			if (!cachedData || !cachedData.rows[rowIndexInPage]) {
				return false;
			}

			// Update the cache optimistically
			queryClient.setQueryData<PageData<T>>(queryKey, (old) => {
				if (!old) return old;

				const newRows = [...old.rows];
				newRows[rowIndexInPage] = { ...newRows[rowIndexInPage], ...patch } as T;

				return {
					...old,
					rows: newRows,
				};
			});

			return true;
		},
		[pageSize, queryClient, scopeKey, tableName, stableOptionsKey],
	);

	return {
		getRowAtIndex,
		totalCount,
		isRowLoaded,
		isPageLoading,
		ensureRowsLoaded,
		loadedPages,
		pageSize,
		isLoading,
		hasInitialData,
		error: error as Error | null,
		invalidate,
		reset,
		updateRowAtIndex,
	};
}

/**
 * Export query keys for external cache management
 */
export { sheetsInfiniteTableKeys };

// src/hooks/use-sheets-meta.ts
import { useQuery, type UseQueryResult } from '@tanstack/react-query';

import type { MetaQuery } from '@constructive-io/data';

import { useSheetsAdapter } from '../adapter/use-sheets-adapter';
import { useSheetsContext, type SheetsScopeKey } from '../context/sheets-context';
import { sheetsQueryKeys } from './query-keys';

export const metaKey = (scope: SheetsScopeKey) => sheetsQueryKeys.meta(scope);

export interface UseMetaOptions {
	enabled?: boolean;
}

export function useSheetsMeta(options: UseMetaOptions = {}): UseQueryResult<MetaQuery, Error> {
	const { enabled = true } = options;
	const { execute, scopeKey } = useSheetsContext();
	const adapter = useSheetsAdapter();
	return useQuery<MetaQuery, Error>({
		queryKey: metaKey(scopeKey),
		queryFn: () => adapter.fetchMeta(execute),
		staleTime: 5 * 60 * 1000, // 5 min - finite so invalidation + remount triggers refetch
		gcTime: 30 * 60 * 1000, // 30 min - survive long schema-editing sessions
		refetchOnMount: true, // Respect staleTime and refetch stale metadata on mount
		enabled,
	});
}

/**
 * Cursor-based paginated table hook for "load more" patterns.
 *
 * Uses TanStack Query v5 `useInfiniteQuery` with PostGraphile Relay Connection
 * cursor pagination (first/after + pageInfo).
 *
 * Designed for sequential "load more" use cases (e.g., relation picker overlays).
 * For non-sequential virtual grid scrolling, see `useSheetsInfiniteTable`.
 */
import { useMemo } from 'react';
import { useInfiniteQuery, useQueryClient } from '@tanstack/react-query';

import { useSheetsMeta } from './use-sheets-meta';
import { useSheetsContext } from '../context/sheets-context';

import {
	cleanTable,
	type CleanTable,
	type Filter,
	type MetaTable,
	type PageInfo,
	type QueryOptions,
} from '@constructive-io/data';
import { createError } from '@constructive-io/data';
import type { FieldSelection } from '@constructive-io/data';
import { toOrderByEnumValue } from '@constructive-io/data';
import { useSheetsAdapter } from '../adapter/use-sheets-adapter';
import { sheetsQueryKeys } from './query-keys';
import { resolveRelationFieldMap } from './relation-field-resolution';
import { validateOrderByVariables } from './orderby-enum-resolution';
import { transformToPostGraphileVariables } from './use-sheets-table';

type RowRecord = Record<string, unknown>;

export interface UseSheetsTableCursorOptions {
	enabled?: boolean;
	select?: FieldSelection;
	pageSize?: number;
	where?: Filter;
	orderBy?: Array<{ field: string; direction: 'asc' | 'desc' }>;
}

export interface UseSheetsTableCursorResult<TData extends RowRecord = RowRecord> {
	data: TData[];
	totalCount: number;
	isLoading: boolean;
	isFetchingNextPage: boolean;
	hasNextPage: boolean;
	fetchNextPage: () => void;
	error: Error | null;
}

interface CursorPage<TData = RowRecord> {
	rows: TData[];
	totalCount: number;
	pageInfo: PageInfo;
}

export function useSheetsTableCursor<TData extends RowRecord = RowRecord>(
	tableName: string,
	options: UseSheetsTableCursorOptions = {},
): UseSheetsTableCursorResult<TData> {
	const queryClient = useQueryClient();
	const { execute, scopeKey } = useSheetsContext();
	const { data: meta } = useSheetsMeta();
	const adapter = useSheetsAdapter();

	const tables = useMemo<CleanTable[]>(() => {
		if (!meta?._meta?.tables) return [];
		return meta._meta.tables
			.filter((candidate): candidate is MetaTable => candidate != null)
			.map((metaTable) => cleanTable(metaTable));
	}, [meta]);

	const table = useMemo<CleanTable | null>(
		() => tables.find((candidate) => candidate.name === tableName) ?? null,
		[tables, tableName],
	);

	const { enabled = true, select: fieldSelection, pageSize = 20, where, orderBy } = options;

	// Stable options key for query cache (excludes enabled/pageSize which don't affect data identity)
	const stableOptions = useMemo(
		() => ({ fieldSelection, where, orderBy }),
		[fieldSelection, where, orderBy],
	);

	const queryOptions: QueryOptions = useMemo(
		() => ({
			fieldSelection,
			where,
			orderBy,
			limit: pageSize,
			includePageInfo: true,
		}),
		[fieldSelection, where, orderBy, pageSize],
	);

	const {
		data,
		isLoading,
		isFetchingNextPage,
		hasNextPage,
		fetchNextPage,
		error,
	} = useInfiniteQuery<CursorPage<TData>, Error>({
		queryKey: sheetsQueryKeys.cursorTable(scopeKey, tableName, stableOptions),
		queryFn: async ({ pageParam }) => {
			if (!table) {
				throw createError.notFound(`Table '${tableName}' not found`);
			}

			const cursor = pageParam as string | undefined;

			const variableOptions: QueryOptions = {
				limit: pageSize,
				where,
				orderBy,
				...(cursor ? { after: cursor } : {}),
			};
			// Cache-bound resolution stays in the hook. The orderBy validation mutates
			// `variables.orderBy` (PostGraphile enum strings) in place; we fold that
			// result back into the `{ field, direction }[]` orderBy we hand the adapter,
			// so the adapter rebuilds an identical (validated) variables payload.
			const variables = transformToPostGraphileVariables(table, variableOptions);

			const [relationFieldMap] = await Promise.all([
				resolveRelationFieldMap({
					table,
					fieldSelection,
					scopeKey,
					queryClient,
					execute,
				}),
				validateOrderByVariables(variables, table, scopeKey, queryClient, execute),
			]);

			const validatedOrderByEnum = new Set((variables.orderBy as string[] | undefined) ?? []);
			const availableOrderByFields = new Set(table.fields.map((field) => field.name));
			const validatedOrderBy = orderBy?.filter(
				({ field, direction }) =>
					availableOrderByFields.has(field) && validatedOrderByEnum.has(toOrderByEnumValue(field, direction)),
			);

			const res = await adapter.listRows<TData>(
				{ table, allTables: tables, tableName },
				{
					...queryOptions,
					orderBy: validatedOrderBy,
					// resolveRelationFieldMap yields `string | null` (null = omit field). The
					// contract narrows to `string`, but the null values are passed through to
					// buildSelect unchanged at runtime — behavior is identical to before.
					relationFieldMap: relationFieldMap as Record<string, string>,
					...(cursor ? { after: cursor } : {}),
				},
				execute,
			);

			// The adapter's AdapterPageInfo marks booleans optional; the underlying
			// PostGraphile connection always populates them, so this narrows to PageInfo
			// exactly as the inline connection cast did. The fallback default mirrors the
			// prior direct-array branch byte-for-byte.
			const pageInfo: PageInfo = (res.pageInfo as PageInfo | undefined) ?? {
				hasNextPage: false,
				hasPreviousPage: false,
			};

			return {
				rows: res.rows,
				totalCount: res.totalCount,
				pageInfo,
			};
		},
		initialPageParam: undefined as string | undefined,
		getNextPageParam: (lastPage) =>
			lastPage.pageInfo.hasNextPage && lastPage.pageInfo.endCursor
				? lastPage.pageInfo.endCursor
				: undefined,
		enabled: enabled && !!table,
		staleTime: 5 * 60 * 1000,
	});

	const flatData = useMemo<TData[]>(
		() => data?.pages.flatMap((page) => page.rows) ?? [],
		[data],
	);

	const totalCount = useMemo(
		() => data?.pages[data.pages.length - 1]?.totalCount ?? 0,
		[data],
	);

	return {
		data: flatData,
		totalCount,
		isLoading,
		isFetchingNextPage,
		hasNextPage: hasNextPage ?? false,
		fetchNextPage,
		error,
	};
}

/**
 * Unified hooks system for table operations
 * Consolidates all table operations into a single, powerful hook
 *
 * Ported from apps/admin use-table.ts with context injection.
 */
import { useMemo } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';

import { useSheetsMeta } from './use-sheets-meta';
import { useSheetsAdapter } from '../adapter/use-sheets-adapter';
import { useSheetsContext } from '../context/sheets-context';
import type { SheetsScopeKey } from '../context/sheets-context';

import { cleanTable, type CleanTable, type MetaTable, type MutationOptions, type QueryOptions } from '@constructive-io/data';
import { createError } from '@constructive-io/data';
import type { FieldSelection } from '@constructive-io/data';
import {
	buildSelect,
	toCamelCasePlural,
	toCamelCaseSingular,
	toOrderByEnumValue,
} from '@constructive-io/data';
import { reuseSheetsPlaceholderData, sheetsQueryKeys } from './query-keys';
import { resolveRelationFieldMap } from './relation-field-resolution';
import { validateOrderByVariables } from './orderby-enum-resolution';
import {
	assertSheetsMutationAllowed,
	resolveSheetsIdentifier,
	resolveSheetsRowIdentity,
	sheetsIdentifierCacheKey,
	sheetsIdentifierToWhere,
	type SheetsRowIdentifier,
} from '../row-identity';

type RowRecord = Record<string, unknown>;
type DeleteIdentifier = SheetsRowIdentifier;

/**
 * Transform relation data by extracting nodes from hasMany/manyToMany connections
 */
export function transformRelationData<TData extends RowRecord>(data: unknown, table: CleanTable): TData[] {
	if (!data) return [] as TData[];
	if (!Array.isArray(data)) return data as TData[];

	const transformed = data.map((row) => {
		if (!row || typeof row !== 'object') return row as TData;

		const transformedRow: RowRecord = { ...(row as RowRecord) };

		const hasManyRelations = table.relations.hasMany || [];
		const manyToManyRelations = table.relations.manyToMany || [];
		const connectionRelations = [...hasManyRelations, ...manyToManyRelations];

		connectionRelations.forEach((relation) => {
			const fieldName = relation.fieldName;
			if (!fieldName || !(fieldName in transformedRow)) return;

			const relationValue = transformedRow[fieldName];
			if (relationValue && typeof relationValue === 'object' && 'nodes' in (relationValue as RowRecord)) {
				const connectionData = relationValue as { nodes?: unknown[] };
				transformedRow[fieldName] = connectionData.nodes || [];
			}
		});

		return transformedRow as TData;
	});

	return transformed as TData[];
}

/**
 * Unified table hook options
 */
export interface UseTableOptions extends QueryOptions {
	/** Enable/disable automatic data fetching */
	enabled?: boolean;
	/** Field selection for queries */
	select?: FieldSelection;
	/** Mutation options */
	mutationOptions?: MutationOptions;
}

/**
 * Unified table hook result
 */
export interface UseTableResult<TData extends RowRecord = RowRecord> {
	// Data
	data: TData[];
	totalCount: number;
	isLoading: boolean;
	error: Error | null;

	// Single row operations
	findOne: (id: SheetsRowIdentifier) => Promise<TData | null>;

	// Mutations
	create: (data: RowRecord) => Promise<{ createdRow: TData | null }>;
	update: (id: SheetsRowIdentifier, patch: RowRecord) => Promise<{ updatedRow: TData | null }>;
	delete: (id: DeleteIdentifier) => Promise<{ deletedId: DeleteIdentifier }>;

	// Mutation states
	isCreating: boolean;
	isUpdating: boolean;
	isDeleting: boolean;

	// Mutation errors
	createError: Error | null;
	updateError: Error | null;
	deleteError: Error | null;

	// Utilities
	refetch: () => Promise<unknown>;
	invalidate: () => void;
}

/**
 * Generate query keys for consistent cache management
 */
export const sheetsTableQueryKeys = {
	scope: (scope: SheetsScopeKey) => sheetsQueryKeys.scope(scope),
	table: (scope: SheetsScopeKey, tableName: string) => sheetsQueryKeys.table(scope, tableName),
	tableRows: (scope: SheetsScopeKey, tableName: string, options?: QueryOptions) =>
		sheetsQueryKeys.tableRows(scope, tableName, options),
	tableRow: (scope: SheetsScopeKey, tableName: string, id: unknown) =>
		sheetsQueryKeys.tableRow(scope, tableName, id),
	tableCount: (scope: SheetsScopeKey, tableName: string, where?: Record<string, unknown>) =>
		sheetsQueryKeys.tableCount(scope, tableName, where),
};

const sheetsTableMutationKeys = {
	create: (scope: SheetsScopeKey, tableName: string) =>
		[...sheetsTableQueryKeys.table(scope, tableName), 'mutation', 'create'] as const,
	update: (scope: SheetsScopeKey, tableName: string) =>
		[...sheetsTableQueryKeys.table(scope, tableName), 'mutation', 'update'] as const,
	delete: (scope: SheetsScopeKey, tableName: string) =>
		[...sheetsTableQueryKeys.table(scope, tableName), 'mutation', 'delete'] as const,
};

/**
 * Transform QueryOptions to PostGraphile pagination variables
 */
export function transformToPostGraphileVariables(table: CleanTable, options: QueryOptions = {}): Record<string, unknown> {
	const variables: Record<string, unknown> = {};

	// Transform limit to first (PostGraphile uses first for forward pagination)
	const limitValue = options.limit ?? options.first;
	if (limitValue !== undefined) {
		variables.first = limitValue;
	}

	// Keep offset as is (PostGraphile supports offset-based pagination)
	if (options.offset !== undefined) {
		variables.offset = options.offset;
	}

	// Add cursor-based pagination variables (for infinite scroll)
	if (options.after !== undefined) {
		variables.after = options.after;
	}
	if (options.before !== undefined) {
		variables.before = options.before;
	}

	// Transform orderBy to PostGraphile format
	// PostGraphile expects format like: ["ID_ASC", "NAME_DESC"]
	if (options.orderBy && options.orderBy.length > 0) {
		const availableFields = new Set(table.fields.map((field) => field.name));
		variables.orderBy = options.orderBy
			.filter(({ field }) => availableFields.has(field))
			.map(({ field, direction }) => toOrderByEnumValue(field, direction));
	}

	// Add where/filter conditions if present
	if (options.where) {
		// constructive APIs expose the connection filter as `where` (buildSelect emits `$where`).
		// Naming this variable `filter` left `$where` unbound → server-side filtering was
		// silently dropped (every `where` returned all rows). Must match buildSelect's `$where`.
		variables.where = options.where;
	}

	return variables;
}

/**
 * Main unified table hook
 * Returns all table operations in a single hook
 */
export function useSheetsTable<TData extends RowRecord = RowRecord>(
	tableName: string,
	options: UseTableOptions = {},
): UseTableResult<TData> {
	const queryClient = useQueryClient();
	const { execute, scopeKey } = useSheetsContext();
	const { data: meta } = useSheetsMeta();
	const adapter = useSheetsAdapter();

	const metaTables = useMemo<MetaTable[]>(() => {
		if (!meta?._meta?.tables) return [];

		return meta._meta.tables.filter((candidate): candidate is MetaTable => candidate != null);
	}, [meta]);

	const tables = useMemo<CleanTable[]>(() => metaTables.map(cleanTable), [metaTables]);

	const table = useMemo<CleanTable | null>(
		() => tables.find((candidate) => candidate.name === tableName) ?? null,
		[tables, tableName],
	);
	const tableMeta = useMemo<MetaTable | null>(
		() => metaTables.find((candidate) => candidate.name === tableName) ?? null,
		[metaTables, tableName],
	);

	const resolveIdentifier = (identifier: SheetsRowIdentifier): SheetsRowIdentifier => {
		if (!tableMeta) throw createError.notFound(`Table '${tableName}' not found`);
		const resolution = resolveSheetsIdentifier(tableMeta, identifier);
		if (resolution.status !== 'identified') {
			throw createError.badRequest(`Cannot resolve a primary-key identity for table '${tableName}'.`);
		}
		return resolution.identifier;
	};

	const rowCacheKey = (row: RowRecord | null | undefined): string | number | null => {
		if (!tableMeta || !row) return null;
		const resolution = resolveSheetsRowIdentity(tableMeta, row);
		if (resolution.status !== 'identified') return null;
		return typeof resolution.identifier === 'object' ? resolution.key : resolution.identifier;
	};

	// Extract options
	const { enabled = true, select: fieldSelection, mutationOptions = {}, ...queryOptions } = options;

	// Update query options with field selection
	const finalQueryOptions: QueryOptions = {
		...queryOptions,
		fieldSelection,
	};

	// Data fetching with error handling
	const {
		data,
		isLoading,
		error,
		refetch,
		} = useQuery<{ rows: TData[]; totalCount: number }>({
			queryKey: sheetsTableQueryKeys.tableRows(scopeKey, tableName, finalQueryOptions),
			queryFn: async () => {
				if (!table) {
					throw createError.notFound(`Table '${tableName}' not found`);
				}

				// Cache-bound resolution stays in the hook. The orderBy validation mutates
				// `variables.orderBy` (PostGraphile enum strings) in place; we fold that
				// result back into the `{ field, direction }[]` orderBy we hand the adapter,
				// so the adapter rebuilds an identical (validated) variables payload.
				const variables = transformToPostGraphileVariables(table, finalQueryOptions);

				const [relationFieldMap] = await Promise.all([
					resolveRelationFieldMap({
						table,
						fieldSelection: finalQueryOptions.fieldSelection,
						scopeKey,
						queryClient,
						execute,
					}),
					validateOrderByVariables(variables, table, scopeKey, queryClient, execute),
				]);

				const validatedOrderByEnum = new Set((variables.orderBy as string[] | undefined) ?? []);
				const availableOrderByFields = new Set(table.fields.map((field) => field.name));
				const validatedOrderBy = finalQueryOptions.orderBy?.filter(
					({ field, direction }) =>
						availableOrderByFields.has(field) && validatedOrderByEnum.has(toOrderByEnumValue(field, direction)),
				);

				const { rows, totalCount } = await adapter.listRows<TData>(
					{ table, allTables: tables, tableName },
					{
						...finalQueryOptions,
						orderBy: validatedOrderBy,
						// resolveRelationFieldMap yields `string | null` (null = omit field). The
						// contract narrows to `string`, but the null values are passed through to
						// buildSelect unchanged at runtime — behavior is identical to before.
						relationFieldMap: relationFieldMap as Record<string, string>,
					},
					execute,
				);
				return { rows, totalCount };
		},
		enabled: enabled && !!table,
		placeholderData: (previousData, previousQuery) =>
			reuseSheetsPlaceholderData(previousData, previousQuery?.queryKey, scopeKey),
		staleTime: 5 * 60 * 1000, // 5 minutes
	});

	const rowsData = data?.rows ?? [];
	const totalCount = data?.totalCount ?? 0;

	// Create mutation with error handling
	const createMutation = useMutation<
		{ createdRow: TData | null; __rawResult: Record<string, unknown> },
		Error,
		RowRecord
	>({
		mutationKey: sheetsTableMutationKeys.create(scopeKey, tableName),
		mutationFn: async (data: RowRecord) => {
			if (!table || !tableMeta) {
				throw createError.notFound(`Table '${tableName}' not found`);
			}
			assertSheetsMutationAllowed(tableMeta, 'create');

			// Get all tables for AST generation
			const allTables = meta?._meta?.tables
				? meta._meta.tables.filter((t): t is NonNullable<typeof t> => t != null).map(cleanTable)
				: [];

			const createdRow = await adapter.createRow<TData>({ table, allTables, tableName }, data, execute, {
				...mutationOptions,
				fieldSelection: mutationOptions.fieldSelection || fieldSelection || 'display',
			});

			return { createdRow, __rawResult: {} };
		},
		onSuccess: ({ createdRow }: { createdRow: TData | null; __rawResult: Record<string, unknown> }) => {
			// Invalidate all related queries for paginated mode
			queryClient.invalidateQueries({ queryKey: sheetsTableQueryKeys.table(scopeKey, tableName) });

			// Cross-invalidate infinite scroll queries to ensure both modes stay in sync
			queryClient.invalidateQueries({ queryKey: sheetsQueryKeys.infiniteTable(scopeKey, tableName) });

			// Update individual row cache
			const createdRowKey = rowCacheKey(createdRow as RowRecord | null);
			if (createdRowKey !== null) {
				queryClient.setQueryData(sheetsTableQueryKeys.tableRow(scopeKey, tableName, createdRowKey), createdRow);
			}
		},
	});

	// Update mutation with error handling
	const updateMutation = useMutation<
		{ updatedRow: TData | null; __rawResult: Record<string, unknown> },
		Error,
		{ id: SheetsRowIdentifier; patch: RowRecord },
		{ previousRows: Array<[readonly unknown[], { rows: TData[]; totalCount: number } | undefined]> }
	>({
		mutationKey: sheetsTableMutationKeys.update(scopeKey, tableName),
		mutationFn: async ({ id, patch }) => {
			if (!table || !tableMeta) {
				throw createError.notFound(`Table '${tableName}' not found`);
			}
			assertSheetsMutationAllowed(tableMeta, 'update');
			const mutationIdentifier = resolveIdentifier(id);

			// Get all tables for AST generation
			const allTables = meta?._meta?.tables
				? meta._meta.tables.filter((t): t is NonNullable<typeof t> => t != null).map(cleanTable)
				: [];

			const updatedRow = await adapter.updateRow<TData>({ table, allTables, tableName }, mutationIdentifier, patch, execute, {
				...mutationOptions,
				fieldSelection: mutationOptions.fieldSelection || fieldSelection || 'display',
			});

			return { updatedRow, __rawResult: {} };
		},
		// Optimistic patch: an inline cell edit must show the new value instantly,
		// not after the server round-trip + the onSuccess refetch round-trip. The
		// active rows cache is `{ rows, totalCount }` keyed by `tableRows(...options)`;
		// patch every cached `tableRows` variant that holds the row (the active query
		// key embeds `finalQueryOptions`, but other option permutations may be cached
		// too), matching the row by its scalar `id`.
		onMutate: async ({ id, patch }) => {
			const tablePrefix = sheetsTableQueryKeys.table(scopeKey, tableName);
			await queryClient.cancelQueries({ queryKey: tablePrefix });
			const targetKey = tableMeta ? sheetsIdentifierCacheKey(tableMeta, id) : null;

			const isRowsKey = (key: readonly unknown[]) => key[key.length - 2] === 'rows';
			const previousRows = queryClient
				.getQueriesData<{ rows: TData[]; totalCount: number }>({ queryKey: tablePrefix })
				.filter(([key]) => isRowsKey(key)) as Array<
				[readonly unknown[], { rows: TData[]; totalCount: number } | undefined]
			>;

			for (const [key] of previousRows) {
				queryClient.setQueryData<{ rows: TData[]; totalCount: number }>(key, (old) => {
					if (!old) return old;
					let changed = false;
					const rows = old.rows.map((row) => {
						if (targetKey !== null && rowCacheKey(row as RowRecord) === targetKey) {
							changed = true;
							return { ...(row as RowRecord), ...patch } as TData;
						}
						return row;
					});
					return changed ? { ...old, rows } : old;
				});
			}

			return { previousRows };
		},
		onError: (_err, _vars, ctx) => {
			// Roll the optimistic patch back to the snapshot on failure.
			ctx?.previousRows.forEach(([key, data]) => queryClient.setQueryData(key, data));
		},
		onSuccess: ({ updatedRow }: { updatedRow: TData | null; __rawResult: Record<string, unknown> }) => {
			// Invalidate all related queries for paginated mode
			queryClient.invalidateQueries({ queryKey: sheetsTableQueryKeys.table(scopeKey, tableName) });

			// NOTE: deliberately NOT invalidating the infinite-scroll cache here.
			// An inline field update never changes row membership/ordering/count, so:
			//   - infinite mode reconciles via the caller's optimistic `updateRowAtIndex`
			//     (+ self-heal refetch on a cache miss) in use-sheets.ts;
			//   - paginated mode is covered by the `table` invalidation above.
			// A blanket `infiniteTable` invalidation would refetch EVERY loaded page
			// (the live-observed 2x refetch on each edit) and clobber the optimistic
			// patch on the active page. The create/delete mutations still
			// cross-invalidate the infinite cache since no per-cell optimistic patch
			// covers a membership change.

			// Update individual row cache
			const updatedRowKey = rowCacheKey(updatedRow as RowRecord | null);
			if (updatedRowKey !== null) {
				queryClient.setQueryData(sheetsTableQueryKeys.tableRow(scopeKey, tableName, updatedRowKey), updatedRow);
			}
		},
	});

	// Delete mutation with error handling
	const deleteMutation = useMutation<
		{ deletedId: DeleteIdentifier; __rawResult: Record<string, unknown> },
		Error,
		DeleteIdentifier
	>({
		mutationKey: sheetsTableMutationKeys.delete(scopeKey, tableName),
		mutationFn: async (idOrPk) => {
			if (!table || !tableMeta) {
				throw createError.notFound(`Table '${tableName}' not found`);
			}
			assertSheetsMutationAllowed(tableMeta, 'delete');
			const mutationIdentifier = resolveIdentifier(idOrPk);

			// Get all tables for AST generation
			const allTables = meta?._meta?.tables
				? meta._meta.tables.filter((t): t is NonNullable<typeof t> => t != null).map(cleanTable)
				: [];

			await adapter.deleteRow({ table, allTables, tableName }, mutationIdentifier, execute, mutationOptions);

			return { deletedId: idOrPk, __rawResult: {} };
		},
		onSuccess: ({ deletedId }: { deletedId: DeleteIdentifier; __rawResult: Record<string, unknown> }) => {
			// Invalidate all related queries for paginated mode
			queryClient.invalidateQueries({ queryKey: sheetsTableQueryKeys.table(scopeKey, tableName) });

			// Cross-invalidate infinite scroll queries to ensure both modes stay in sync
			queryClient.invalidateQueries({ queryKey: sheetsQueryKeys.infiniteTable(scopeKey, tableName) });

			const deletedRowKey = tableMeta ? sheetsIdentifierCacheKey(tableMeta, deletedId) : null;
			if (deletedRowKey !== null) {
				queryClient.removeQueries({
					queryKey: sheetsTableQueryKeys.tableRow(scopeKey, tableName, deletedRowKey),
				});
			}
		},
	});

	// Find one function with error handling
	const findOne = async (id: SheetsRowIdentifier) => {
		if (!table || !tableMeta) {
			throw createError.notFound(`Table '${tableName}' not found`);
		}
		const where = sheetsIdentifierToWhere(tableMeta, id);
		if (!where) {
			throw createError.badRequest(`Cannot resolve a primary-key identity for table '${tableName}'.`);
		}

		const doc = buildSelect(table, tables, {
			where,
			limit: 1,
		});
		const variables = transformToPostGraphileVariables(table, {
			where,
			limit: 1,
		});
		const result = (await execute(doc, variables)) as Record<string, unknown>;

		// Some schemas expose a singular root field; keep this as a compatibility fallback.
		const singularName = toCamelCaseSingular(tableName, table);
		const singularData = result[singularName];
		if (singularData && typeof singularData === 'object') {
			return singularData as TData;
		}

		// Handle Relay-style response structure (connection fallback)
		const queryTableName = toCamelCasePlural(tableName, table);
		const data = result[queryTableName];

		if (data && typeof data === 'object' && 'nodes' in data) {
			const nodes = (data as { nodes: unknown[] }).nodes || [];
			const transformedNodes = transformRelationData<TData>(nodes, table);
			return transformedNodes[0] || null;
		}

		// Fallback for direct array response
		const rows = (result[tableName] as unknown[]) || [];
		const transformedRows = transformRelationData<TData>(rows, table);
		return transformedRows[0] || null;
	};

	// Invalidate function
	const invalidate = () => {
		queryClient.invalidateQueries({ queryKey: sheetsTableQueryKeys.table(scopeKey, tableName) });
	};

	return {
		// Data
		data: rowsData,
		totalCount,
		isLoading,
		error,

		// Single row operations
		findOne,

		// Mutations
		create: (data: RowRecord) => createMutation.mutateAsync(data),
		update: (id: SheetsRowIdentifier, patch: RowRecord) => updateMutation.mutateAsync({ id, patch }),
		delete: (id: DeleteIdentifier) => deleteMutation.mutateAsync(id),

		// Mutation states
		isCreating: createMutation.isPending,
		isUpdating: updateMutation.isPending,
		isDeleting: deleteMutation.isPending,

		// Mutation errors
		createError: createMutation.error,
		updateError: updateMutation.error,
		deleteError: deleteMutation.error,

		// Utilities
		refetch,
		invalidate,
	};
}

/**
 * Field-Specific Upload Hook
 * Provides upload functionality that integrates with the existing dynamic mutation system
 * Works with backend's field-specific upload pattern: <fieldName>Upload fields
 *
 * Ported from apps/admin use-image-upload.ts with context injection.
 */

import { useEffect, useMemo, useRef } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';

import { cleanTable, type CleanTable, type MetaTable } from '@constructive-io/data';
import { useSheetsMeta } from './use-sheets-meta';
import {
	toCamelCaseSingular,
	toPatchFieldName,
	toUpdateInputTypeName,
	toUpdateMutationName,
} from '@constructive-io/data';

import { useSheetsContext } from '../context/sheets-context';
import type { SheetsScopeKey, SheetsConfig } from '../context/sheets-context';
import {
	createSheetsExecute,
	createSheetsUpload,
	type SheetsExecuteFn,
	type SheetsUploadFn,
} from '../context/sheets-execute';
import { sheetsTableQueryKeys } from './use-sheets-table';
import { useSheetsStoreApi } from '../store/sheets-store';

/**
 * Upload progress callback type
 */
export interface UploadProgress {
	loaded: number;
	total: number;
	percentage: number;
}

/**
 * Upload response from backend
 */
export interface UploadResponse {
	url: string;
	filename: string;
	mime: string;
	size: number;
}

/**
 * Field upload options
 */
export interface UseFieldUploadOptions {
	onProgress?: (progress: UploadProgress) => void;
	onSuccess?: (data: UploadResponse) => void;
	onError?: (error: Error) => void;
	showToast?: boolean; // default true
	successMessage?: string; // custom success message
	successToastDelayMs?: number; // optional delay for success toast
}

interface UploadNaming {
	mutationName: string;
	singularName: string;
	patchFieldName: string;
	updateInputTypeName: string;
}

interface ExecuteFieldUploadOptions {
	onAuthError?: () => void;
	/**
	 * Transport seam. When the hooks call this, they thread the context
	 * `execute`/`executeUpload` here so injected/mock implementations intercept
	 * both steps. When omitted (e.g. image-editor's direct retry path), the
	 * functions are built from `endpoint`/`getToken`/`onAuthError` via the same
	 * factories — never a raw fetch.
	 */
	execute?: SheetsExecuteFn;
	executeUpload?: SheetsUploadFn;
	onProgress?: (progress: UploadProgress) => void;
}

function resolveUploadNaming(tableName: string, table?: CleanTable | null): UploadNaming {
	return {
		mutationName: toUpdateMutationName(tableName, table),
		singularName: toCamelCaseSingular(tableName, table),
		patchFieldName: toPatchFieldName(tableName, table),
		updateInputTypeName: toUpdateInputTypeName(tableName),
	};
}

interface PatchMutationResult {
	[mutationName: string]: { [singular: string]: Record<string, unknown> } | undefined;
}

/**
 * Build the transport seam for an upload. When the caller injects
 * `execute`/`executeUpload` (the hooks pass the context functions), those are
 * used verbatim so consumer/mock implementations intercept both steps.
 * Otherwise the same factories that back the provider are used, sourced from
 * `endpoint`/`getToken`/`onAuthError` — guaranteeing canonical error normalization
 * and onAuthError without any raw fetch in this module.
 */
function resolveTransport(
	endpoint: string,
	getToken: () => string | null,
	options?: ExecuteFieldUploadOptions,
): { execute: SheetsExecuteFn; executeUpload: SheetsUploadFn } {
	if (options?.execute && options?.executeUpload) {
		return { execute: options.execute, executeUpload: options.executeUpload };
	}
	const config: SheetsConfig = {
		endpoint,
		auth: { mode: 'standalone' },
		onAuthError: options?.onAuthError,
	};
	return {
		execute: createSheetsExecute(config, getToken),
		executeUpload: createSheetsUpload(config, getToken),
	};
}

/**
 * Execute field upload using two sequential requests, both routed through the
 * injectable transport seam:
 * 1. File upload via `executeUpload` → returns file metadata
 * 2. GraphQL mutation via `execute` to patch the row with the upload result
 *
 * Exported for direct use when record ID is known at call time (e.g., after draft submission)
 *
 * @param tableName - Table name
 * @param fieldName - Field name for the upload (the actual DB column, e.g. "photo")
 * @param recordId - Record ID to update
 * @param file - File to upload
 * @param endpoint - GraphQL endpoint URL (used to build the seam when none injected)
 * @param getToken - Function that returns the current auth token (or null)
 * @param naming - Optional pre-resolved naming overrides
 * @param options - Auth callback + optional injected execute/executeUpload + progress
 */
export async function executeFieldUpload(
	tableName: string,
	fieldName: string,
	recordId: string | number,
	file: File,
	endpoint: string,
	getToken: () => string | null,
	naming?: UploadNaming,
	options?: ExecuteFieldUploadOptions,
): Promise<UploadResponse> {
	// Validate endpoint (only meaningful for the factory-built seam path)
	if (!endpoint && !(options?.execute && options?.executeUpload)) {
		throw new Error('No endpoint configured. Select a database API or use Direct Connect.');
	}

	const { execute, executeUpload } = resolveTransport(endpoint, getToken, options);

	// ── Step 1: Upload file through the executeUpload seam ──
	// Field/row metadata + progress flow as the third arg so injected
	// implementations can use them; the default REST transport ignores them.
	const uploadResult = await executeUpload(file, undefined, {
		tableName,
		fieldName,
		recordId,
		onProgress: options?.onProgress,
	});

	// ── Step 2: Patch the row with the upload result via the execute seam ──
	const resolvedNaming = naming ?? resolveUploadNaming(tableName);

	// Sanitize upload result — only pass fields the DB schema expects.
	// For jsonb columns (image/upload domains): { url, filename, mime, size }
	// For text columns (attachment domain): just the URL string.
	const patchValue = {
		...(uploadResult.url != null && { url: uploadResult.url }),
		...(uploadResult.filename != null && { filename: uploadResult.filename }),
		...(uploadResult.mime != null && { mime: uploadResult.mime }),
		...(uploadResult.size != null && { size: uploadResult.size }),
	};

	const mutationString = `
		mutation ${resolvedNaming.mutationName}Mutation($input: ${resolvedNaming.updateInputTypeName}!) {
			${resolvedNaming.mutationName}(input: $input) {
				${resolvedNaming.singularName} {
					id
					${fieldName}
				}
			}
		}
	`.trim();

	// execute() normalizes auth/forbidden/GraphQL errors to ConstructiveError and fires
	// onAuthError on 401/UNAUTHENTICATED — no manual equivalent needed here.
	const result = await execute<PatchMutationResult>(mutationString, {
		input: {
			id: recordId,
			[resolvedNaming.patchFieldName]: {
				[fieldName]: patchValue,
			},
		},
	});

	// Extract the updated record from PostGraphile response
	const updatedRecord = result?.[resolvedNaming.mutationName]?.[resolvedNaming.singularName] as
		| Record<string, unknown>
		| undefined;

	if (!updatedRecord) {
		throw new Error('Upload succeeded but no data returned from patch');
	}

	// Extract the uploaded file data from the updated record. jsonb columns
	// (image/upload domains) return an object; text columns (attachment domain)
	// return a plain URL string.
	const uploadedFileData = updatedRecord[fieldName];
	if (!uploadedFileData) {
		throw new Error(`Upload succeeded but ${fieldName} field not found in response`);
	}

	const fileObject =
		typeof uploadedFileData === 'object' ? (uploadedFileData as Record<string, unknown>) : null;

	// Return standardized upload response
	return {
		url: (fileObject?.url as string) || (uploadedFileData as string),
		filename: (fileObject?.filename as string) || file.name,
		mime: (fileObject?.mime as string) || file.type,
		size: (fileObject?.size as number) || file.size,
	};
}

/**
 * Hook for uploading files to specific table fields
 * Integrates with the existing dynamic mutation system
 */
export function useSheetsFieldUpload(
	tableName: string,
	fieldName: string,
	recordId: string | number,
	options: UseFieldUploadOptions = {},
) {
	const queryClient = useQueryClient();
	const { scopeKey, config, execute, executeUpload } = useSheetsContext();
	const storeApi = useSheetsStoreApi();
	const { data: meta } = useSheetsMeta();
	const table = useMemo<CleanTable | null>(() => {
		if (!meta?._meta?.tables) return null;
		const candidate = meta._meta.tables.find((item) => item?.name === tableName) as MetaTable | undefined;
		return candidate ? cleanTable(candidate) : null;
	}, [meta, tableName]);
	const resolvedNaming = useMemo(() => resolveUploadNaming(tableName, table), [tableName, table]);

	// Build a stable getToken from context
	const getToken = useMemo(() => {
		if (config.auth.mode === 'embedded') {
			return config.auth.getToken;
		}
		return () => storeApi.getState().accessToken;
	}, [config.auth, storeApi]);

	// Keep latest params in refs to avoid stale closures
	const tableRef = useRef(tableName);
	const fieldRef = useRef(fieldName);
	const idRef = useRef(recordId);

	useEffect(() => {
		tableRef.current = tableName;
		fieldRef.current = fieldName;
		idRef.current = recordId;
	}, [tableName, fieldName, recordId]);

	return useMutation<UploadResponse, Error, File>({
		mutationKey: ['sheets', scopeKey, 'field-upload', tableName, fieldName, recordId],
		mutationFn: async (file: File) => {
			// Route both steps through the context seam so injected/mock
			// execute/executeUpload intercept the upload.
			return executeFieldUpload(
				tableRef.current,
				fieldRef.current,
				idRef.current,
				file,
				config.endpoint,
				getToken,
				resolvedNaming,
				{ onAuthError: config.onAuthError, execute, executeUpload, onProgress: options.onProgress },
			);
		},
		onSuccess: (data) => {
			// First allow callers to react (e.g., close overlay)
			options.onSuccess?.(data);
			// Invalidate related queries to refresh data
			queryClient.invalidateQueries({ queryKey: sheetsTableQueryKeys.table(scopeKey, tableRef.current) });
			queryClient.invalidateQueries({ queryKey: sheetsTableQueryKeys.tableRow(scopeKey, tableRef.current, idRef.current) });
		},
		onError: (error) => {
			options.onError?.(error);
		},
	});
}

/**
 * Hook for uploading images with validation
 * Convenience wrapper around useSheetsFieldUpload with image-specific validation
 */
export function useSheetsImageUpload(
	tableName: string,
	fieldName: string,
	recordId: string | number,
	options: UseFieldUploadOptions = {},
) {
	const queryClient = useQueryClient();
	const { scopeKey, config, execute, executeUpload } = useSheetsContext();
	const storeApi = useSheetsStoreApi();
	const { data: meta } = useSheetsMeta();
	const table = useMemo<CleanTable | null>(() => {
		if (!meta?._meta?.tables) return null;
		const candidate = meta._meta.tables.find((item) => item?.name === tableName) as MetaTable | undefined;
		return candidate ? cleanTable(candidate) : null;
	}, [meta, tableName]);
	const resolvedNaming = useMemo(() => resolveUploadNaming(tableName, table), [tableName, table]);

	// Build a stable getToken from context
	const getToken = useMemo(() => {
		if (config.auth.mode === 'embedded') {
			return config.auth.getToken;
		}
		return () => storeApi.getState().accessToken;
	}, [config.auth, storeApi]);

	// Keep latest params in refs to avoid stale closures
	const tableRef = useRef(tableName);
	const fieldRef = useRef(fieldName);
	const idRef = useRef(recordId);

	useEffect(() => {
		tableRef.current = tableName;
		fieldRef.current = fieldName;
		idRef.current = recordId;
	}, [tableName, fieldName, recordId]);

	return useMutation<UploadResponse, Error, File>({
		mutationKey: ['sheets', scopeKey, 'image-upload', tableName, fieldName, recordId],
		mutationFn: async (file: File) => {
			// Validate file type
			if (!file.type.startsWith('image/')) {
				throw new Error('Please select an image file');
			}

			// Validate file size (10MB limit)
			const maxSize = 10 * 1024 * 1024; // 10MB
			if (file.size > maxSize) {
				throw new Error('File size must be less than 10MB');
			}

			// Route both steps through the context seam so injected/mock
			// execute/executeUpload intercept the upload.
			return executeFieldUpload(
				tableRef.current,
				fieldRef.current,
				idRef.current,
				file,
				config.endpoint,
				getToken,
				resolvedNaming,
				{ onAuthError: config.onAuthError, execute, executeUpload, onProgress: options.onProgress },
			);
		},
		onSuccess: (data) => {
			// First allow callers to react (e.g., close overlay)
			options.onSuccess?.(data);

			// Invalidate related queries to refresh data
			queryClient.invalidateQueries({ queryKey: sheetsTableQueryKeys.table(scopeKey, tableRef.current) });
			queryClient.invalidateQueries({ queryKey: sheetsTableQueryKeys.tableRow(scopeKey, tableRef.current, idRef.current) });
		},
		onError: (error) => {
			options.onError?.(error);
		},
	});
}

