import {
	assessTableWriteCapability,
	resolveRowIdentity,
	rowIdentityToPrimaryKey,
	serializeRowIdentity,
	type MetaTable,
	type RowIdentityValue,
	type TableWriteCapability,
} from '@constructive-io/data';

/** A row locator accepted by Sheets CRUD operations. */
export type SheetsRowIdentifier =
	| string
	| number
	| Readonly<Record<string, RowIdentityValue>>;

export type SheetsMutationOperation = 'create' | 'update' | 'delete';

export type SheetsRowIdentityResolution =
	| Readonly<{
			status: 'identified';
			/** Backwards-compatible scalar for an ordinary `id` PK; otherwise the PK object. */
			identifier: SheetsRowIdentifier;
			/** GraphQL primary-key input, including renamed and composite keys. */
			primaryKey: Readonly<Record<string, RowIdentityValue>>;
			/** Stable, schema-qualified key used by caches, selection, and editors. */
			key: string;
	  }>
	| Readonly<{
			status: 'unavailable';
			reason: 'no-primary-key' | 'invalid-row';
	  }>;

function isLegacyScalarId(
	primaryKey: Readonly<Record<string, RowIdentityValue>>,
): primaryKey is Readonly<{ id: string | number }> {
	const entries = Object.entries(primaryKey);
	return (
		entries.length === 1 &&
		entries[0][0] === 'id' &&
		(typeof entries[0][1] === 'string' || typeof entries[0][1] === 'number')
	);
}

/**
 * Resolve one server row from `_meta`. The familiar scalar `id` contract is kept
 * for existing adapters, while renamed and composite keys use the full PK input.
 */
export function resolveSheetsRowIdentity(
	table: MetaTable,
	row: Readonly<Record<string, unknown>>,
): SheetsRowIdentityResolution {
	const resolution = resolveRowIdentity(table, row);
	if (resolution.status === 'read-only') {
		return { status: 'unavailable', reason: 'no-primary-key' };
	}
	if (resolution.status === 'invalid-row') {
		return { status: 'unavailable', reason: 'invalid-row' };
	}

	const primaryKey = rowIdentityToPrimaryKey(resolution.identity);
	return {
		status: 'identified',
		identifier: isLegacyScalarId(primaryKey) ? primaryKey.id : primaryKey,
		primaryKey,
		key: serializeRowIdentity(resolution.identity),
	};
}

/** Resolve a public CRUD identifier through the same `_meta` identity contract. */
export function resolveSheetsIdentifier(
	table: MetaTable,
	identifier: SheetsRowIdentifier,
): SheetsRowIdentityResolution {
	const row =
		typeof identifier === 'object' && identifier !== null
			? identifier
			: { id: identifier };
	return resolveSheetsRowIdentity(table, row);
}

/** Build the PostGraphile connection filter used by `findOne`. */
export function sheetsIdentifierToWhere(
	table: MetaTable,
	identifier: SheetsRowIdentifier,
): Record<string, { equalTo: RowIdentityValue }> | null {
	const resolution = resolveSheetsIdentifier(table, identifier);
	if (resolution.status !== 'identified') return null;
	return Object.fromEntries(
		Object.entries(resolution.primaryKey).map(([field, value]) => [field, { equalTo: value }]),
	);
}

/** Use scalar IDs as cache keys for compatibility; use serialized identities otherwise. */
export function sheetsIdentifierCacheKey(
	table: MetaTable,
	identifier: SheetsRowIdentifier,
): string | number | null {
	const resolution = resolveSheetsIdentifier(table, identifier);
	if (resolution.status !== 'identified') return null;
	return typeof resolution.identifier === 'object'
		? resolution.key
		: resolution.identifier;
}

/** Stable TanStack/selection/editor key with an index fallback only for non-writable rows. */
export function sheetsRowKey(
	table: MetaTable,
	row: Readonly<Record<string, unknown>>,
	index: number,
): string {
	const resolution = resolveSheetsRowIdentity(table, row);
	if (resolution.status === 'identified') {
		return typeof resolution.identifier === 'object'
			? resolution.key
			: String(resolution.identifier);
	}
	return `${table.schemaName ?? ''}:${table.name}:row:${index}`;
}

export function getSheetsWriteCapability(table: MetaTable | null): TableWriteCapability | null {
	return table ? assessTableWriteCapability(table) : null;
}

export function canRunSheetsMutation(
	capability: TableWriteCapability | null,
	operation: SheetsMutationOperation,
): boolean {
	if (!capability || capability.status !== 'mutable') return false;
	return capability.operations[operation];
}

export function assertSheetsMutationAllowed(
	table: MetaTable,
	operation: SheetsMutationOperation,
): void {
	const capability = assessTableWriteCapability(table);
	if (capability.status === 'read-only') {
		throw new Error(`Table '${table.name}' is read-only because it has no primary key.`);
	}
	if (!capability.operations[operation]) {
		const article = operation === 'update' ? 'an' : 'a';
		throw new Error(`Table '${table.name}' does not expose ${article} ${operation} mutation.`);
	}
}

/**
 * Range-value extractor — pulls the matrix of cell values covered by a
 * {@link SelectionRect} out of the (possibly virtualized) row array.
 *
 * PURE + SSR-safe — no React, no DOM. The BOUNDED contract is load-bearing: it
 * reads only the cells inside the rect (w×h), never enumerates `rows.length`, so
 * a paste/fill/copy targeting a few cells of a million-row grid stays O(w·h). An
 * unfetched proxy row (infinite-mode) reads as `null` -> its cells come back as
 * `null`; an out-of-range column reads as `null` too.
 *
 * Reused by P3 (paste/fill writes the same coordinate matrix back) and P4 (copy
 * serializes {@link toTSV}).
 */

import type { SelectionRect } from './selection-model';

/** The extracted block: a `values[row][col]` matrix plus the row indices + col keys it covers. */
export interface ExtractedRange {
	/** `values[r][c]` — outer index aligns with `rows[r]`, inner with `cols[c]`. */
	values: unknown[][];
	/** Absolute row indices covered (y .. y+height-1). */
	rows: number[];
	/** Column keys covered (columnKeys[x .. x+width-1]). */
	cols: string[];
}

/**
 * Read every cell inside `range` (half-open: x/width = cols, y/height = rows) from
 * `rows` keyed by `columnKeys`. `getDisplay`, when supplied, maps the raw value to
 * the value to emit (e.g. a display string for copy) — defaults to the raw value.
 * Null-safe for unfetched proxy rows and out-of-range columns.
 */
export function getCellsInRange(
	range: SelectionRect,
	rows: readonly unknown[],
	columnKeys: readonly string[],
	getDisplay?: (value: unknown, rowIndex: number, colKey: string) => unknown,
): ExtractedRange {
	const cols: string[] = [];
	for (let c = 0; c < range.width; c++) {
		cols.push(columnKeys[range.x + c]);
	}

	const rowIndices: number[] = [];
	const values: unknown[][] = [];
	for (let r = 0; r < range.height; r++) {
		const rowIndex = range.y + r;
		rowIndices.push(rowIndex);
		const rowData = rows[rowIndex] as Record<string, unknown> | null | undefined;
		const line: unknown[] = [];
		for (let c = 0; c < range.width; c++) {
			const colKey = cols[c];
			const raw = rowData && colKey != null ? rowData[colKey] : null;
			const cellValue = raw === undefined ? null : raw;
			line.push(getDisplay ? getDisplay(cellValue, rowIndex, colKey) : cellValue);
		}
		values.push(line);
	}

	return { values, rows: rowIndices, cols };
}

/**
 * Serialize a value matrix to TSV (tab-joined cols, newline-joined rows). Each value
 * is stringified; `null`/`undefined` become an empty cell. Spreadsheet-paste shape —
 * reused by P4 copy.
 */
export function toTSV(values: readonly (readonly unknown[])[]): string {
	return values
		.map((row) => row.map((cell) => (cell == null ? '' : String(cell))).join('\t'))
		.join('\n');
}

/**
 * Fill-math — REPLICATE a source row/column across a target range (P4 Phase 3).
 *
 * PURE + SSR-safe (no React, no DOM) — the analog of {@link getCellsInRange} on the
 * WRITE side: it reads the seed cells out of the raw `rows` array (null-safe for
 * unfetched proxy rows / out-of-range columns, exactly like the extractor) and emits
 * the {@link CellWrite}[] the command hands to `commitCells` (readonly/UUID skips +
 * undo live inside that batch, never here).
 *
 * SCOPE — value REPLICATION only. Numeric/date SERIES detection (1,2 -> 3,4 ; Jan,Feb
 * -> Mar) is DEFERRED: every filled cell is a verbatim copy of the seed.
 */

import type { SelectionRect } from './selection-model';
import type { CellWrite } from '../grid/hooks/use-batch-commit';

/** Read one raw cell value, null-safe (mirrors getCellsInRange: undefined -> null). */
function readCell(rows: readonly unknown[], rowIndex: number, colKey: string): unknown {
	const rowData = rows[rowIndex] as Record<string, unknown> | null | undefined;
	const raw = rowData && colKey != null ? rowData[colKey] : null;
	return raw === undefined ? null : raw;
}

/**
 * Fill DOWN: SOURCE = the TOP row of `range` (y). For each col `x..x+width-1`, replicate
 * the seed cell value into every row `y+1..y+height-1`. Returns the writes column-major
 * is not required — emitted row-major (top-to-bottom within each... actually outer loop is
 * target rows, inner is cols) so commitCells coalesces per row. A single-row range yields
 * no writes (nothing below the seed).
 */
export function fillDownWrites(
	range: SelectionRect,
	rows: readonly unknown[],
	columnKeys: readonly string[],
): CellWrite[] {
	const writes: CellWrite[] = [];
	const sourceRow = range.y;
	for (let targetRow = range.y + 1; targetRow < range.y + range.height; targetRow++) {
		for (let c = 0; c < range.width; c++) {
			const colKey = columnKeys[range.x + c];
			if (colKey == null) continue;
			writes.push({ rowIndex: targetRow, colKey, value: readCell(rows, sourceRow, colKey) });
		}
	}
	return writes;
}

/**
 * Fill RIGHT: SOURCE = the LEFT column of `range` (x). For each col `x+1..x+width-1`,
 * replicate that column's seed (the value in the LEFT column of the SAME row) rightward
 * across every row `y..y+height-1`. A single-column range yields no writes.
 */
export function fillRightWrites(
	range: SelectionRect,
	rows: readonly unknown[],
	columnKeys: readonly string[],
): CellWrite[] {
	const writes: CellWrite[] = [];
	const sourceColKey = columnKeys[range.x];
	for (let r = 0; r < range.height; r++) {
		const rowIndex = range.y + r;
		const seed = sourceColKey == null ? null : readCell(rows, rowIndex, sourceColKey);
		for (let c = 1; c < range.width; c++) {
			const colKey = columnKeys[range.x + c];
			if (colKey == null) continue;
			writes.push({ rowIndex, colKey, value: seed });
		}
	}
	return writes;
}

/**
 * Bulk-edit: FAN a single committed `value` across every cell of `range` (the classic
 * "select range, type, commit, fill" edit). Unlike fill-down/right this reads NO seed
 * out of the data — every cell in the range gets the SAME `value` (per-column coercion
 * happens downstream in commitCells/resolveServerPatch). The write set is the COMPLETE
 * range INCLUDING the active cell, so the caller does ONE commitCells (never a single
 * commit + a separate range commit) — no double-write, one optimistic patch, one undo.
 * Out-of-bounds column slots are skipped (mirrors the other fill writers).
 */
export function bulkEditWrites(
	range: SelectionRect,
	value: unknown,
	columnKeys: readonly string[],
): CellWrite[] {
	const writes: CellWrite[] = [];
	for (let r = 0; r < range.height; r++) {
		const rowIndex = range.y + r;
		for (let c = 0; c < range.width; c++) {
			const colKey = columnKeys[range.x + c];
			if (colKey == null) continue;
			writes.push({ rowIndex, colKey, value });
		}
	}
	return writes;
}

/**
 * Fill-handle DRAG geometry — extend `from` toward target cell `[col,row]` along the
 * DOMINANT axis (v1 supports one axis at a time). PURE.
 *
 * The axis is chosen by which direction the target overshoots `from` the most: if the
 * vertical overshoot (below the bottom / above the top) exceeds the horizontal one we
 * fill VERTICALLY (the rect's height grows); otherwise HORIZONTALLY (width grows). Ties
 * and a target already inside `from` collapse to `from` (no extension). The off-axis span
 * is left exactly as `from`'s.
 */
export function extendedFillRect(from: SelectionRect, target: readonly [number, number]): SelectionRect {
	const [col, row] = target;
	const bottom = from.y + from.height - 1;
	const right = from.x + from.width - 1;
	// Overshoot past the source band on each axis (0 when target is within the band).
	const vOver = row > bottom ? row - bottom : from.y - row > 0 ? from.y - row : 0;
	const hOver = col > right ? col - right : from.x - col > 0 ? from.x - col : 0;
	if (vOver === 0 && hOver === 0) return from;
	if (vOver >= hOver) {
		// Vertical fill: grow the height toward `row`, keep x/width.
		const y = Math.min(from.y, row);
		const yEnd = Math.max(bottom, row);
		return { x: from.x, y, width: from.width, height: yEnd - y + 1 };
	}
	// Horizontal fill: grow the width toward `col`, keep y/height.
	const x = Math.min(from.x, col);
	const xEnd = Math.max(right, col);
	return { x, y: from.y, width: xEnd - x + 1, height: from.height };
}

/**
 * Replicate the SOURCE band `from` across the NEW cells of `extended` (the cells in
 * `extended` that are NOT in `from`). For a vertical extension each new row copies the
 * matching column's value from the NEAREST source row (the band repeats); for a horizontal
 * extension each new column copies the matching row's nearest source column. Value
 * REPLICATION only — SERIES detection DEFERRED. Skips the `from` band (already populated).
 */
export function fillDragWrites(
	from: SelectionRect,
	extended: SelectionRect,
	rows: readonly unknown[],
	columnKeys: readonly string[],
): CellWrite[] {
	const writes: CellWrite[] = [];
	for (let ty = extended.y; ty < extended.y + extended.height; ty++) {
		for (let tx = extended.x; tx < extended.x + extended.width; tx++) {
			// Inside the source band — already has its value, never overwrite.
			if (tx >= from.x && tx < from.x + from.width && ty >= from.y && ty < from.y + from.height) continue;
			const colKey = columnKeys[tx];
			if (colKey == null) continue;
			// Tile the source band: map the target back into the band on each axis.
			const srcCol = from.x + ((tx - from.x) % from.width + from.width) % from.width;
			const srcRow = from.y + ((ty - from.y) % from.height + from.height) % from.height;
			const srcKey = columnKeys[srcCol];
			writes.push({ rowIndex: ty, colKey, value: srcKey == null ? null : readCell(rows, srcRow, srcKey) });
		}
	}
	return writes;
}

/**
 * RangeSet — the immutable selection primitive for the native (TanStack DOM)
 * grid. It replaces glide's `CompactSelection` for row selection state.
 *
 * Internal representation: a sorted, non-overlapping, NON-ADJACENT array of
 * `[start, end)` half-open ranges. Adjacency MERGES on touch (so `add([0,3))`
 * then `add([3,5))` collapses to a single `[0,5)`), keeping a 10k-row selection
 * O(#ranges) instead of O(#rows). Every mutator returns a NEW RangeSet; the
 * receiver is never mutated.
 *
 * Focused tests protect merging, splitting, offsets, and immutability without
 * freezing the obsolete grid implementation this class replaced.
 */

type Range = readonly [start: number, end: number];

/** Normalize the `number | [number, number]` arg to a half-open `[start, end)`. */
function toRange(i: number | [number, number]): Range {
	return typeof i === 'number' ? [i, i + 1] : [i[0], i[1]];
}

/** True when the range is empty/inverted (start >= end) and contributes nothing. */
function isEmptyRange([start, end]: Range): boolean {
	return start >= end;
}

/**
 * Insert `[s, e)` into a sorted, disjoint, non-adjacent range list, merging any
 * ranges it overlaps OR merely TOUCHES (touch = adjacency merge). Returns a new
 * sorted, disjoint, non-adjacent list.
 */
function insertRange(ranges: readonly Range[], [s, e]: Range): Range[] {
	const out: Range[] = [];
	let start = s;
	let end = e;
	let inserted = false;
	for (const [rs, re] of ranges) {
		if (re < start) {
			// Entirely before the new range (and not touching) — keep as-is.
			out.push([rs, re]);
		} else if (rs > end) {
			// Entirely after the new range (and not touching) — emit the merged
			// range once, then keep the rest.
			if (!inserted) {
				out.push([start, end]);
				inserted = true;
			}
			out.push([rs, re]);
		} else {
			// Overlaps or touches — widen the in-flight merged range.
			start = Math.min(start, rs);
			end = Math.max(end, re);
		}
	}
	if (!inserted) out.push([start, end]);
	return out;
}

/**
 * Subtract `[selMin, selMax)` from a sorted, disjoint range list, SPLITTING any
 * covering range (removing the middle of one yields two).
 *
 * This is a faithful port of glide `CompactSelection.remove`, including its two
 * documented quirks rather than a clean set difference:
 *
 *   1. Overlap test is `start <= selMax && selMin <= end` — both bounds `<=`, so
 *      a range touching the cut is "intersected" (usually a harmless in-place
 *      replace with an identical range).
 *   2. It SPLICES `items` in place while iterating with `items.entries()`, whose
 *      cursor just counts iterations (0,1,2,…) regardless of mutation. So when a
 *      range is fully consumed (`toAdd` empty), `splice(i, 1)` shrinks the array
 *      and the element that slides into slot `i` is SKIPPED — the next read is
 *      slot `i + 1`. A plain index loop over the MUTATED array reproduces this
 *      exactly: never re-align `i`. ("remove-spanning-three-ranges" depends on
 *      it — the range after a fully dropped middle range survives untouched.)
 */
function subtractRange(ranges: readonly Range[], [selMin, selMax]: Range): Range[] {
	const items: Range[] = ranges.map(([start, end]) => [start, end]);
	for (let i = 0; i < items.length; i++) {
		const [start, end] = items[i];
		if (start <= selMax && selMin <= end) {
			const toAdd: Range[] = [];
			if (start < selMin) toAdd.push([start, selMin]);
			if (selMax < end) toAdd.push([selMax, end]);
			items.splice(i, 1, ...toAdd);
		}
	}
	return items;
}

export class RangeSet {
	private readonly ranges: readonly Range[];

	private constructor(ranges: readonly Range[]) {
		this.ranges = ranges;
	}

	static empty(): RangeSet {
		return new RangeSet([]);
	}

	/** RESET to a single index `[i, i+1)` or a single `[start, end)` range. */
	static fromSingleSelection(i: number | [number, number]): RangeSet {
		const range = toRange(i);
		return isEmptyRange(range) ? new RangeSet([]) : new RangeSet([range]);
	}

	/** Add an index/range; merges adjacent + overlapping ranges; contained = no-op. */
	add(i: number | [number, number]): RangeSet {
		const range = toRange(i);
		if (isEmptyRange(range)) return this;
		return new RangeSet(insertRange(this.ranges, range));
	}

	/** Remove an index/range; SPLITS a covering range. */
	remove(i: number | [number, number]): RangeSet {
		const range = toRange(i);
		if (isEmptyRange(range)) return this;
		return new RangeSet(subtractRange(this.ranges, range));
	}

	/** Shift every range by `amount`. */
	offset(amount: number): RangeSet {
		if (amount === 0) return this;
		return new RangeSet(this.ranges.map(([start, end]) => [start + amount, end + amount]));
	}

	hasIndex(i: number): boolean {
		for (const [start, end] of this.ranges) {
			if (i >= start && i < end) return true;
		}
		return false;
	}

	/** Ascending expansion of every selected index. */
	toArray(): number[] {
		const out: number[] = [];
		for (const [start, end] of this.ranges) {
			for (let i = start; i < end; i++) out.push(i);
		}
		return out;
	}

	/** Total selected count — sum of `(end - start)` across ranges. */
	get length(): number {
		let total = 0;
		for (const [start, end] of this.ranges) total += end - start;
		return total;
	}

	/** Lowest selected index, or `undefined` when empty. */
	first(): number | undefined {
		return this.ranges.length === 0 ? undefined : this.ranges[0][0];
	}

	/** Highest selected index, or `undefined` when empty. */
	last(): number | undefined {
		if (this.ranges.length === 0) return undefined;
		return this.ranges[this.ranges.length - 1][1] - 1;
	}
}

/**
 * SheetsSelection — the native (TanStack DOM) selection value that replaces
 * glide's `GridSelection`. It is the canonical selection state for the new grid;
 * glide's `GridSelection` is only a derived projection (see `glide-projection.ts`)
 * kept alive for the still-drawing canvas during the phased port.
 *
 * Shape mirrors the slice of glide the grid actually reads/round-trips:
 *   - `rows`    — selected ROW indices (a {@link RangeSet}; the only thing
 *                 production consumes via `.toArray()` / `.length`).
 *   - `columns` — selected COLUMN indices. Nothing consumes it today; it exists
 *                 solely so the glide projection has a faithful slot. Stays empty.
 *   - `current` — the active cell + optional active range (glide's `current.cell`
 *                 + `current.range`). The canvas keyboard-nav cursor depends on it,
 *                 so the projection must preserve it round-trip.
 *
 * The interaction helpers below are PURE and own the click logic glide used to
 * own internally (plain/ctrl/shift row clicks). They operate on ROW indices.
 *
 * NOTE — anchor tracking for shift-click is NOT stored here: `selectRange` takes
 * the anchor as an argument, so the caller (the reducer / interaction layer) owns
 * "where the last plain click landed". This keeps the model a pure value with no
 * hidden interaction state.
 */

import { RangeSet } from './range-set';

/** A half-open active range in cell coordinates (mirrors glide's `Rectangle`). */
export interface SelectionRect {
	x: number;
	y: number;
	width: number;
	height: number;
}

/** The active cell (and optional active range) — glide's `current`, trimmed. */
export interface SelectionCurrent {
	/** `[col, row]` — mirrors glide's `Item` ordering. */
	cell: [number, number];
	/** Active range; absent for a bare single-cell cursor. */
	range?: SelectionRect;
}

export interface SheetsSelection {
	current?: SelectionCurrent;
	rows: RangeSet;
	columns: RangeSet;
}

/** The zero value — no rows, no columns, no active cell. */
export const emptySheetsSelection: SheetsSelection = {
	rows: RangeSet.empty(),
	columns: RangeSet.empty()
};

/**
 * Plain row click: REPLACE the row selection with just `index` and park the
 * active cell on that row (column 0). Columns are left empty.
 */
export function selectRow(sel: SheetsSelection, index: number): SheetsSelection {
	return {
		current: { cell: [0, index] },
		rows: RangeSet.fromSingleSelection(index),
		columns: sel.columns
	};
}

/**
 * Ctrl/cmd row click: TOGGLE `index` in the existing row selection (add when
 * absent, remove when present). The active cell follows the touched row.
 */
export function toggleRow(sel: SheetsSelection, index: number): SheetsSelection {
	const rows = sel.rows.hasIndex(index) ? sel.rows.remove(index) : sel.rows.add(index);
	return {
		current: { cell: [0, index] },
		rows,
		columns: sel.columns
	};
}

/**
 * Shift row click: REPLACE the row selection with the contiguous block spanning
 * `anchor`..`index` (inclusive, either order). The active cell follows `index`.
 */
export function selectRange(sel: SheetsSelection, anchor: number, index: number): SheetsSelection {
	const min = Math.min(anchor, index);
	const max = Math.max(anchor, index);
	return {
		current: { cell: [0, index] },
		rows: RangeSet.fromSingleSelection([min, max + 1]),
		columns: sel.columns
	};
}

/** Clear everything back to the empty selection. */
export function clear(_sel: SheetsSelection): SheetsSelection {
	return emptySheetsSelection;
}

/** Clamp `n` into the inclusive `[min, max]` range. */
function clamp(n: number, min: number, max: number): number {
	return Math.max(min, Math.min(max, n));
}

/**
 * Park the active cell on `[col, row]`, dropping any prior active range. PRESERVES
 * `rows` and `columns` — cell navigation must NOT touch the row-checkbox selection
 * that drives delete/export.
 */
export function selectCell(sel: SheetsSelection, col: number, row: number): SheetsSelection {
	return { ...sel, current: { cell: [col, row] } };
}

/**
 * Extend the active range from an anchor cell to `[col, row]`. The active cell
 * becomes `[col, row]`; `current.range` is a normalized HALF-OPEN {@link SelectionRect}
 * spanning anchor..target in either order. PRESERVES `rows` and `columns`.
 */
export function extendRangeToCell(
	sel: SheetsSelection,
	col: number,
	row: number,
	anchorCol: number,
	anchorRow: number,
): SheetsSelection {
	return {
		...sel,
		current: {
			cell: [col, row],
			range: {
				x: Math.min(col, anchorCol),
				y: Math.min(row, anchorRow),
				width: Math.abs(col - anchorCol) + 1,
				height: Math.abs(row - anchorRow) + 1,
			},
		},
	};
}

/**
 * Select the WHOLE grid as a single cell range (Ctrl/Cmd+A). `current.range` is ONE
 * rect spanning every column/row and `current.cell` parks at `[0, 0]`; `rows`/`columns`
 * are untouched. Coordinate-only — NEVER enumerates rows (the infinite row-model is
 * O(totalCount)), so a million-row grid stays a single interval.
 */
export function selectAllCells(sel: SheetsSelection, colCount: number, rowCount: number): SheetsSelection {
	return {
		...sel,
		current: { cell: [0, 0], range: { x: 0, y: 0, width: colCount, height: rowCount } },
	};
}

/**
 * Move the active cell by `[dCol, dRow]`, clamped to the grid bounds. Starts from
 * `[0, 0]` when no active cell exists. Drops any prior range; PRESERVES rows/columns.
 */
export function moveActive(
	sel: SheetsSelection,
	dCol: number,
	dRow: number,
	colCount: number,
	rowCount: number,
): SheetsSelection {
	const base = sel.current?.cell ?? [0, 0];
	const col = clamp(base[0] + dCol, 0, colCount - 1);
	const row = clamp(base[1] + dRow, 0, rowCount - 1);
	return selectCell(sel, col, row);
}

/**
 * Pure nav-key resolver for the extended spreadsheet keys (Tab/Home/End + their
 * Ctrl/Cmd variants + PageUp/PageDown). Returns the NEW `[col, row]` target clamped
 * to grid bounds, or `null` when the key is not one of these moves (Arrow keys and
 * Enter/F2 are handled separately). `base` is the current active cell, `pageRows` is
 * the row span of one visible page (PageUp/Dn). Coordinate-only — never enumerates rows.
 */
export function computeKeyNavTarget(
	key: string,
	mods: { ctrlOrMeta: boolean; shift: boolean },
	base: [number, number],
	colCount: number,
	rowCount: number,
	pageRows: number,
): [number, number] | null {
	const [col, row] = base;
	const lastCol = colCount - 1;
	const lastRow = rowCount - 1;

	switch (key) {
		case 'Tab': {
			if (mods.shift) {
				// col-1; before col 0 wrap to the last col of the previous row. Clamp at grid start.
				if (col > 0) return [col - 1, row];
				if (row > 0) return [lastCol, row - 1];
				return [0, 0];
			}
			// col+1; past the last col wrap to col 0 of the next row. Clamp at grid end.
			if (col < lastCol) return [col + 1, row];
			if (row < lastRow) return [0, row + 1];
			return [lastCol, lastRow];
		}
		case 'Home':
			return mods.ctrlOrMeta ? [0, 0] : [0, row];
		case 'End':
			return mods.ctrlOrMeta ? [lastCol, lastRow] : [lastCol, row];
		case 'PageUp':
			return [col, clamp(row - pageRows, 0, lastRow)];
		case 'PageDown':
			return [col, clamp(row + pageRows, 0, lastRow)];
		default:
			return null;
	}
}

/**
 * TSV parse + tile — the INVERSE of {@link toTSV} (cell-extract.ts), used by the
 * clipboard.paste command. PURE + SSR-safe (no React, no DOM, no clipboard).
 *
 * `parseTSV` round-trips a `toTSV` string back into a `string[][]` matrix (split rows
 * on `\n`, cols on `\t`), tolerating ONE trailing newline (a spreadsheet copy ends the
 * last row with `\n`) so it does not yield a spurious empty trailing row. `tileMatrix`
 * implements spreadsheet fill semantics: a 1×N / N×1 source REPEATS to fill a larger
 * target, otherwise the source is written from the anchor as-is.
 */

/**
 * Parse a TSV string into a `string[][]` matrix (rows × cols). Splits rows on `\n`
 * (a lone trailing `\n` is dropped so it does not add an empty row) and cols on `\t`.
 * `\r` is stripped so a CRLF clipboard payload parses the same as LF. An empty string
 * yields a single empty cell `[['']]` (mirrors a 1×1 blank paste).
 */
export function parseTSV(text: string): string[][] {
	const normalized = text.replace(/\r\n?/g, '\n');
	// Drop a single trailing newline so a spreadsheet copy's terminal `\n` is not an extra row.
	const body = normalized.endsWith('\n') ? normalized.slice(0, -1) : normalized;
	return body.split('\n').map((line) => line.split('\t'));
}

/**
 * Tile `source` to fill a `targetW × targetH` region (spreadsheet fill semantics):
 *   • a 1×N source (single row) repeats DOWN to fill targetH rows.
 *   • an N×1 source (single col) repeats ACROSS to fill targetW cols.
 *   • a 1×1 source repeats in both axes.
 *   • any other (genuinely 2-D) source is returned unchanged — the caller writes it
 *     from the anchor as-is (no tiling), matching spreadsheet "paste block" behavior.
 *
 * Only repeats when the source is strictly smaller than the target on the repeating
 * axis; a source already >= the target is left intact (clamping is the caller's job).
 */
export function tileMatrix(source: string[][], targetW: number, targetH: number): string[][] {
	const srcH = source.length;
	const srcW = srcH > 0 ? source[0].length : 0;
	if (srcH === 0 || srcW === 0) return source;

	const isSingleRow = srcH === 1;
	const isSingleCol = srcW === 1;
	// Only 1×N / N×1 (and 1×1) sources tile; a real 2-D block pastes as-is.
	if (!isSingleRow && !isSingleCol) return source;

	const outH = isSingleRow && targetH > srcH ? targetH : srcH;
	const outW = isSingleCol && targetW > srcW ? targetW : srcW;

	const out: string[][] = [];
	for (let r = 0; r < outH; r++) {
		const srcRow = source[r % srcH];
		const line: string[] = [];
		for (let c = 0; c < outW; c++) {
			line.push(srcRow[c % srcW]);
		}
		out.push(line);
	}
	return out;
}

import type { RelationInfo } from './relation-info-slice';

type DraftRowStatus = 'idle' | 'saving' | 'error';

export interface DraftRow {
  id: string;
  values: Record<string, unknown>;
  status: DraftRowStatus;
  errors: Record<string, string> | null;
  createdAt: number;
  metaVersion: string;
}

interface DraftRowsTableState {
  order: string[];
  map: Record<string, DraftRow>;
  template: Record<string, unknown>;
  metaVersion: string;
  columnOrder: string[];
}

export function parseDraftTableKey(tableKey: string): { databaseId: string | null; tableName: string } | null {
  const parts = tableKey.split('::');
  if (parts.length === 2) {
    const [databaseId, tableName] = parts;
    if (!databaseId || !tableName) return null;
    return { databaseId, tableName };
  }
  return null;
}

export interface DraftRowCreationArgs {
  tableKey: string;
  columnOrder: readonly string[];
  fieldMetaByKey: Record<string, DraftFieldMetadata | undefined>;
  relationInfoByKey?: Record<string, RelationInfo | undefined>;
  metaVersion: string;
}

export type DraftRowsSyncArgs = DraftRowCreationArgs;

export interface DraftRowUpdateArgs {
  tableKey: string;
  draftRowId: string;
  columnKey: string;
  value: unknown;
  extraValues?: Record<string, unknown>;
}

export interface DraftRowsSlice {
  draftRowsByTable: Record<string, DraftRowsTableState | undefined>;
  createDraftRow: (args: DraftRowCreationArgs) => string;
  updateDraftCell: (args: DraftRowUpdateArgs) => void;
  removeDraftRow: (tableKey: string, draftRowId: string) => void;
  clearDraftRowsForTable: (tableKey: string) => void;
  clearDraftRowsForDatabase: (databaseId: string) => void;
  clearAllDraftRows: () => void;
  syncDraftRowsWithMeta: (args: DraftRowsSyncArgs) => void;
  setDraftRowStatus: (args: {
    tableKey: string;
    draftRowId: string;
    status: DraftRowStatus;
    errors?: Record<string, string> | null;
  }) => void;
}

type DraftFieldMetadata = {
  name?: string | null;
  isNotNull?: boolean | null;
  hasDefault?: boolean | null;
  type?: {
    gqlType?: string | null;
    isArray?: boolean | null;
    pgAlias?: string | null;
    pgType?: string | null;
    subtype?: string | null;
  } | null;
};

type DraftRowsSetState = (
	partial: Partial<DraftRowsSlice> | ((state: DraftRowsSlice) => Partial<DraftRowsSlice> | DraftRowsSlice),
) => void;

export function createDraftRowsSlice(set: DraftRowsSetState): DraftRowsSlice {
	return {
    draftRowsByTable: {},

    createDraftRow: (args) => {
      const { tableKey, columnOrder, fieldMetaByKey, relationInfoByKey, metaVersion } = args;

      const effectiveColumnOrder = ensureColumnOrder(columnOrder, fieldMetaByKey, relationInfoByKey);
      const template = buildTemplate(effectiveColumnOrder, relationInfoByKey);
      const draftRowId = `draft:${generateDraftSuffix()}`;
      const values = initializeValuesFromTemplate(template, draftRowId);

      set((state: DraftRowsSlice) => {
        const existing = state.draftRowsByTable[tableKey];

        const nextOrder = existing ? [...existing.order, draftRowId] : [draftRowId];
	        const nextMap: Record<string, DraftRow> = {
	          ...(existing?.map ?? {}),
          [draftRowId]: {
            id: draftRowId,
            values,
            status: 'idle' as const,
            errors: null,
            createdAt: Date.now(),
            metaVersion,
          },
        };

        return {
          draftRowsByTable: {
            ...state.draftRowsByTable,
            [tableKey]: {
              order: nextOrder,
              map: nextMap,
              template,
              metaVersion,
              columnOrder: [...effectiveColumnOrder],
            },
          },
        };
      });

      return draftRowId;
    },

	    updateDraftCell: ({ tableKey, draftRowId, columnKey, value, extraValues }) => {
	      set((state: DraftRowsSlice) => {
	        const tableState = state.draftRowsByTable[tableKey];
	        if (!tableState) return state;

	        const existingRow = tableState.map[draftRowId];
	        if (!existingRow) return state;

	        let hasValueChanges = !deepEqual(existingRow.values[columnKey], value);
	        if (!hasValueChanges && extraValues) {
	          for (const [key, extraValue] of Object.entries(extraValues)) {
	            if (!deepEqual(existingRow.values[key], extraValue)) {
	              hasValueChanges = true;
	              break;
	            }
	          }
	        }

	        const shouldResetErrors = existingRow.status === 'error' || existingRow.errors !== null;
	        if (!hasValueChanges && !shouldResetErrors) return state;

	        const updatedValues = hasValueChanges ? { ...existingRow.values, [columnKey]: deepClone(value) } : existingRow.values;
	        if (hasValueChanges && extraValues) {
	          for (const [key, extraValue] of Object.entries(extraValues)) {
	            updatedValues[key] = deepClone(extraValue);
	          }
	        }

	        const nextMap: Record<string, DraftRow> = {
	          ...tableState.map,
          [draftRowId]: {
            ...existingRow,
            values: updatedValues,
            status: existingRow.status === 'error' ? ('idle' as const) : existingRow.status,
            errors: null,
          },
        };

        return {
          draftRowsByTable: {
            ...state.draftRowsByTable,
            [tableKey]: {
              ...tableState,
              map: nextMap,
            },
          },
        };
      });
    },

    removeDraftRow: (tableKey, draftRowId) => {
      set((state: DraftRowsSlice) => {
        const tableState = state.draftRowsByTable[tableKey];
        if (!tableState) return state;
        if (!tableState.map[draftRowId]) return state;

        const nextOrder = tableState.order.filter((id) => id !== draftRowId);
        const nextMap = { ...tableState.map };
        delete nextMap[draftRowId];

        const nextTableState: DraftRowsTableState | undefined = nextOrder.length
          ? { ...tableState, order: nextOrder, map: nextMap }
          : undefined;

        const nextByTable = { ...state.draftRowsByTable };
        if (nextTableState) {
          nextByTable[tableKey] = nextTableState;
        } else {
          delete nextByTable[tableKey];
        }

        return { draftRowsByTable: nextByTable };
      });
    },

    clearDraftRowsForTable: (tableKey) => {
      set((state: DraftRowsSlice) => {
        if (!state.draftRowsByTable[tableKey]) return state;
        const nextByTable = { ...state.draftRowsByTable };
        delete nextByTable[tableKey];
        return { draftRowsByTable: nextByTable };
      });
    },

    clearDraftRowsForDatabase: (databaseId) => {
      set((state: DraftRowsSlice) => {
        if (!databaseId || !Object.keys(state.draftRowsByTable).length) return state;
        let changed = false;
        const nextByTable: Record<string, DraftRowsTableState | undefined> = { ...state.draftRowsByTable };

        for (const tableKey of Object.keys(nextByTable)) {
          const parsed = parseDraftTableKey(tableKey);
          const matchesDatabase = parsed ? parsed.databaseId === databaseId : tableKey.includes(`${databaseId}::`);

          if (matchesDatabase) {
            delete nextByTable[tableKey];
            changed = true;
          }
        }

        return changed ? { draftRowsByTable: nextByTable } : state;
      });
    },

    clearAllDraftRows: () => {
      set((state: DraftRowsSlice) => {
        if (!Object.keys(state.draftRowsByTable).length) return state;
        return { draftRowsByTable: {} };
      });
    },

	    syncDraftRowsWithMeta: (args) => {
	      const { tableKey, columnOrder, fieldMetaByKey, relationInfoByKey, metaVersion } = args;

	      set((state: DraftRowsSlice) => {
	        const tableState = state.draftRowsByTable[tableKey];
	        const effectiveColumnOrder = ensureColumnOrder(columnOrder, fieldMetaByKey, relationInfoByKey);
	        const template = buildTemplate(effectiveColumnOrder, relationInfoByKey);

	        if (!tableState) {
	          return state;
	        }

	        if (tableState.order.length === 0) {
	          const nextByTable = { ...state.draftRowsByTable };
	          delete nextByTable[tableKey];
	          return { draftRowsByTable: nextByTable };
	        }

	        const isSameMeta =
	          tableState.metaVersion === metaVersion && shallowEqualArrays(tableState.columnOrder, effectiveColumnOrder);

        if (isSameMeta) return state;

        const nextMap: Record<string, DraftRow> = {};
        for (const draftId of tableState.order) {
          const row = tableState.map[draftId];
          if (!row) continue;

          const mergedValues: Record<string, unknown> = initializeValuesFromTemplate(template, draftId);
          for (const key of Object.keys(row.values)) {
            if (Object.prototype.hasOwnProperty.call(template, key)) {
              mergedValues[key] = deepClone(row.values[key]);
            }
          }

          nextMap[draftId] = {
            ...row,
            values: mergedValues,
            metaVersion,
            status: row.status === 'error' ? 'idle' as const : row.status,
            errors: row.status === 'error' ? null : row.errors,
          };
        }

        return {
          draftRowsByTable: {
            ...state.draftRowsByTable,
            [tableKey]: {
              order: [...tableState.order],
              map: nextMap,
              template,
              metaVersion,
              columnOrder: [...effectiveColumnOrder],
            },
          },
        };
      });
    },

	    setDraftRowStatus: ({ tableKey, draftRowId, status, errors }) => {
	      set((state: DraftRowsSlice) => {
	        const tableState = state.draftRowsByTable[tableKey];
	        if (!tableState) return state;
	        const row = tableState.map[draftRowId];
	        if (!row) return state;
	        const nextErrors = errors ?? null;
	        if (row.status === status && shallowEqualRecords(row.errors, nextErrors)) return state;

	        const nextMap: Record<string, DraftRow> = {
	          ...tableState.map,
	          [draftRowId]: { ...row, status, errors: nextErrors },
	        };

        return {
          draftRowsByTable: {
            ...state.draftRowsByTable,
            [tableKey]: { ...tableState, map: nextMap },
          },
        };
      });
    },
  };
}

function ensureColumnOrder(
  columnOrder: readonly string[],
  fieldMetaByKey: Record<string, DraftFieldMetadata | undefined>,
  relationInfoByKey?: Record<string, RelationInfo | undefined>,
): string[] {
  if (columnOrder.length > 0) return [...columnOrder];

  const keys = new Set<string>();
  Object.keys(fieldMetaByKey).forEach((key) => {
    if (key) keys.add(key);
  });
  if (relationInfoByKey) {
    Object.keys(relationInfoByKey).forEach((key) => {
      if (key) keys.add(key);
    });
  }
  return Array.from(keys).sort((a, b) => a.localeCompare(b));
}

function buildTemplate(
  columnOrder: readonly string[],
  relationInfoByKey?: Record<string, RelationInfo | undefined>,
): Record<string, unknown> {
  const template: Record<string, unknown> = {};

  for (const column of columnOrder) {
    if (!column) continue;
    const relationInfo = relationInfoByKey?.[column];

    if (relationInfo && (relationInfo.kind === 'hasMany' || relationInfo.kind === 'manyToMany')) {
      template[column] = [];
    } else {
      template[column] = null;
    }
  }

  return template;
}

function generateDraftSuffix(): string {
  const cryptoObj = typeof globalThis !== 'undefined' ? (globalThis as any).crypto : undefined;
  if (cryptoObj && typeof cryptoObj.getRandomValues === 'function') {
    const buffer = new Uint32Array(1);
    cryptoObj.getRandomValues(buffer);
    return buffer[0].toString(36).slice(0, 8);
  }
  return Math.random().toString(36).slice(2, 10);
}

function initializeValuesFromTemplate(template: Record<string, unknown>, draftRowId: string): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(template)) {
    result[key] = deepClone(value);
  }
  if (!result.id) result.id = draftRowId;
  return result;
}

function deepClone<T>(value: T): T {
  if (Array.isArray(value)) return value.map((item) => deepClone(item)) as unknown as T;
  if (value instanceof Date) return new Date(value.getTime()) as unknown as T;
  if (value && typeof value === 'object') {
    const result: Record<string, unknown> = {};
    for (const [key, val] of Object.entries(value as Record<string, unknown>)) {
      result[key] = deepClone(val);
    }
    return result as unknown as T;
  }
	return value;
}

function deepEqual(a: unknown, b: unknown): boolean {
	if (Object.is(a, b)) return true;
	if (a instanceof Date && b instanceof Date) return a.getTime() === b.getTime();
	if (Array.isArray(a) && Array.isArray(b)) {
		if (a.length !== b.length) return false;
		for (let i = 0; i < a.length; i += 1) {
			if (!deepEqual(a[i], b[i])) return false;
		}
		return true;
	}
	if (a && b && typeof a === 'object' && typeof b === 'object') {
		const keysA = Object.keys(a as Record<string, unknown>);
		const keysB = Object.keys(b as Record<string, unknown>);
		if (keysA.length !== keysB.length) return false;
		for (const key of keysA) {
			if (!(key in (b as Record<string, unknown>))) return false;
			if (!deepEqual((a as Record<string, unknown>)[key], (b as Record<string, unknown>)[key])) return false;
		}
		return true;
	}
	return false;
}

function shallowEqualRecords(
	a: Record<string, string> | null,
	b: Record<string, string> | null,
): boolean {
	if (a === b) return true;
	if (!a || !b) return false;
	const keysA = Object.keys(a);
	const keysB = Object.keys(b);
	if (keysA.length !== keysB.length) return false;
	for (const key of keysA) {
		if (a[key] !== b[key]) return false;
	}
	return true;
}

function shallowEqualArrays(a: readonly string[], b: readonly string[]): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i += 1) {
    if (a[i] !== b[i]) return false;
  }
  return true;
}

export function computeDraftMetaSignature(
  columnOrder: readonly string[],
  fieldMetaByKey: Record<string, DraftFieldMetadata | undefined>,
  relationInfoByKey?: Record<string, RelationInfo | undefined>,
): string {
  const signatureParts = columnOrder.map((column) => {
    const typeMeta = fieldMetaByKey[column]?.type;
    const relationMeta = relationInfoByKey?.[column];

    const typePart = typeMeta
      ? [
          typeMeta.gqlType ?? '',
          typeMeta.isArray ? '1' : '0',
          typeMeta.pgAlias ?? '',
          typeMeta.pgType ?? '',
          typeMeta.subtype ?? '',
        ].join(':')
      : '';

    const relationPart = relationMeta
      ? [relationMeta.kind ?? '', relationMeta.foreignKeyField ?? '', relationMeta.relationField ?? ''].join(':')
      : '';

    return `${column}|${typePart}|${relationPart}`;
  });

  return hashString(signatureParts.join('||'));
}

function hashString(input: string): string {
  let hash = 0;
  for (let i = 0; i < input.length; i += 1) {
    hash = (hash << 5) - hash + input.charCodeAt(i);
    hash |= 0;
  }
  return hash.toString(16);
}

import { pluralize } from 'inflekt';
import { cleanTable, pgFieldToCamelCase, type CleanTable, type MetaQuery } from '@constructive-io/data';
import { getJunctionTableNames, isJunctionTablePure } from '../utils/relation-utils';

export type RelationKind = 'belongsTo' | 'hasOne' | 'hasMany' | 'manyToMany';

export interface RelationInfo {
  kind: RelationKind;
  relatedTable?: string;
  displayCandidates: string[];
  relationField?: string;
  foreignKeyField?: string;
  junctionTable?: string;
  junctionLeftKeyField?: string;
  junctionRightKeyField?: string;
  displayName?: string;
}

export interface RelationInfoSlice {
  relationInfoCache: Record<string, Record<string, RelationInfo>>;
  relationInfoMapCache: Record<string, Map<string, RelationInfo>>;
  setRelationInfoForTable: (tableName: string, info: Record<string, RelationInfo>) => void;
  getRelationInfoForTable: (tableName: string) => Record<string, RelationInfo> | undefined;
  getRelationInfoMapForTable: (tableName: string) => Map<string, RelationInfo> | undefined;
  rebuildRelationInfo: (tableName: string, meta: MetaQuery | undefined) => void;
  ensureRelationInfo: (tableName: string, meta: MetaQuery | undefined) => Record<string, RelationInfo>;
  clearRelationInfoCache: () => void;
}

interface RelationInfoState {
  relationInfoCache: Record<string, Record<string, RelationInfo>>;
  relationInfoMapCache: Record<string, Map<string, RelationInfo>>;
}

type RelationInfoSetState = (
  partial: Partial<RelationInfoState> | ((state: RelationInfoState) => Partial<RelationInfoState>),
) => void;

type RelationInfoGetState = () => RelationInfoState;

function toRelationInfoMap(info: Record<string, RelationInfo>): Map<string, RelationInfo> {
  return new Map(Object.entries(info));
}

function setTableRelationInfo(set: RelationInfoSetState, tableName: string, info: Record<string, RelationInfo>): void {
  set((state) => ({
    relationInfoCache: { ...state.relationInfoCache, [tableName]: info },
    relationInfoMapCache: { ...state.relationInfoMapCache, [tableName]: toRelationInfoMap(info) },
  }));
}

export function createRelationInfoSlice(set: RelationInfoSetState, get: RelationInfoGetState): RelationInfoSlice {
  return {
    relationInfoCache: {},
    relationInfoMapCache: {},
    setRelationInfoForTable: (tableName, info) => setTableRelationInfo(set, tableName, info),
    getRelationInfoForTable: (tableName) => get().relationInfoCache[tableName],
    getRelationInfoMapForTable: (tableName) => get().relationInfoMapCache[tableName],
    clearRelationInfoCache: () => set({ relationInfoCache: {}, relationInfoMapCache: {} }),
    rebuildRelationInfo: (tableName: string, meta: MetaQuery | undefined) => {
      try {
        const info = buildRelationInfoFromMeta(tableName, meta);
        if (!info) return;
        setTableRelationInfo(set, tableName, info);
      } catch {
        // ignore
      }
    },
    ensureRelationInfo: (tableName: string, meta: MetaQuery | undefined) => {
      const existing = get().relationInfoCache[tableName];
      if (existing) return existing;
      const info = buildRelationInfoFromMeta(tableName, meta) || {};
      if (Object.keys(info).length) {
        setTableRelationInfo(set, tableName, info);
      }
      return info;
    },
  };
}

type MetaTableNode = NonNullable<NonNullable<NonNullable<MetaQuery['_meta']>['tables']>[number]>;

function toCleanTables(meta: MetaQuery | undefined): CleanTable[] {
  const tables = meta?._meta?.tables ?? [];
  return tables.filter((table): table is MetaTableNode => table != null).map((table) => cleanTable(table));
}

function firstFieldName(fields: Array<{ name: string }>): string | undefined {
  return fields[0]?.name;
}

/**
 * For hasOne/hasMany relations, find the FK field in the RELATED table that
 * references the current table. relation.keys contains the PK of the current
 * table (e.g. "id"), but the relation editor needs the FK in the child table
 * (e.g. "questionnaireId") to link/unlink records.
 *
 * Resolution chain:
 * 1. Related table's belongsTo relations (from cleanTable)
 * 2. Related table's foreignKeyConstraints (from raw _meta)
 */
function findForeignKeyInRelatedTable(
  currentTableName: string,
  relatedTableName: string,
  allTables: CleanTable[],
  rawMetaTables: readonly MetaTableNode[],
): string | undefined {
  // 1. Try belongsTo on the related cleaned table
  const relatedTable = allTables.find((t) => t.name === relatedTableName);
  if (relatedTable) {
    const belongsTo = relatedTable.relations.belongsTo.find(
      (rel) => rel.referencesTable === currentTableName,
    );
    if (belongsTo?.keys?.[0]?.name) return belongsTo.keys[0].name;
  }

  // 2. Fall back to foreignKeyConstraints on the raw _meta related table
  const rawRelated = rawMetaTables.find((t) => t.name === relatedTableName);
  if (rawRelated) {
    // v5 nested: constraints.foreignKey[]
    const v5Fks = Array.isArray(rawRelated.constraints) ? [] : rawRelated.constraints?.foreignKey;
    // v4 flat: foreignKeyConstraints[]
    const fks = v5Fks ?? rawRelated.foreignKeyConstraints ?? [];
    for (const fk of fks) {
      if (!fk) continue;
      const refName = fk.refTable?.name;
      // refTable.name is a codec name (camelCase) — match case-insensitively
      if (refName && refName.toLowerCase() === currentTableName.toLowerCase()) {
        const fieldName = fk.fields?.[0]?.name;
        if (fieldName) return pgFieldToCamelCase(fieldName);
      }
    }
  }

  return undefined;
}

export function buildRelationInfoFromMeta(
  tableName: string,
  meta: MetaQuery | undefined,
): Record<string, RelationInfo> | null {
  const tables = toCleanTables(meta);
  const table = tables.find((candidate) => candidate.name === tableName);
  if (!table) return null;

  const rawMetaTables = (meta?._meta?.tables ?? []).filter(
    (t): t is MetaTableNode => t != null,
  );

  const PRIORITY_FIELDS = [
    'displayName',
    'fullName',
    'preferredName',
    'nickname',
    'firstName',
    'lastName',
    'givenName',
    'familyName',
    'username',
    'handle',
    'email',
    'phone',
    'title',
    'label',
    'slug',
    'code',
    'name',
  ];
  const NAME_PATTERN = /name/i;

  const computeCandidates = (relatedTableName?: string): string[] => {
    if (!relatedTableName) return [];
    const related = tables.find((candidate) => candidate.name === relatedTableName);
    if (!related) return [];

    const fieldNamesSet = new Set<string>(related.fields.map((field) => field.name));
    const explicit = PRIORITY_FIELDS.filter((k) => fieldNamesSet.has(k));
    const explicitSet = new Set(explicit);

    const nameLike: string[] = [];
    for (const name of fieldNamesSet) {
      if (NAME_PATTERN.test(name) && !explicitSet.has(name)) {
        nameLike.push(name);
      }
    }
    nameLike.sort((a, b) => a.length - b.length);

    return Array.from(new Set([...explicit, ...nameLike]));
  };

  const info: Record<string, RelationInfo> = {};
  table.relations.belongsTo.forEach((relation) => {
    const displayCandidates = computeCandidates(relation.referencesTable);
    const foreignKeys = relation.keys.map((key) => key.name).filter(Boolean);
    const primaryForeignKey = foreignKeys[0];

    if (relation.fieldName) {
      info[relation.fieldName] = {
        kind: 'belongsTo',
        relatedTable: relation.referencesTable,
        displayCandidates,
        relationField: relation.fieldName,
        foreignKeyField: primaryForeignKey,
      };
    }

    foreignKeys.forEach((fk) => {
      if (!fk) return;
      info[fk] = {
        kind: 'belongsTo',
        relatedTable: relation.referencesTable,
        displayCandidates,
        relationField: relation.fieldName ?? undefined,
        foreignKeyField: fk,
      };
    });
  });
  table.relations.hasOne.forEach((relation) => {
    if (relation.fieldName) {
      // relation.keys contains the PK of the CURRENT table, not the FK in the
      // related table. Resolve the actual FK field via:
      // 1. Related table's belongsTo (cleanTable)
      // 2. Related table's foreignKeyConstraints (raw _meta)
      const fkInRelated = findForeignKeyInRelatedTable(tableName, relation.referencedByTable, tables, rawMetaTables);
      info[relation.fieldName] = {
        kind: 'hasOne',
        relatedTable: relation.referencedByTable,
        displayCandidates: computeCandidates(relation.referencedByTable),
        relationField: relation.fieldName,
        foreignKeyField: fkInRelated,
      };
    }
  });
  const junctionTableNames = getJunctionTableNames(table.relations, rawMetaTables);

  table.relations.hasMany.forEach((relation) => {
    if (!relation.fieldName) return;
    // Skip hasMany relations pointing to junction tables (M:N covers these)
    if (junctionTableNames.has(relation.referencedByTable)) return;
    const fkInRelated = findForeignKeyInRelatedTable(tableName, relation.referencedByTable, tables, rawMetaTables);
    info[relation.fieldName] = {
      kind: 'hasMany',
      relatedTable: relation.referencedByTable,
      displayCandidates: computeCandidates(relation.referencedByTable),
      relationField: relation.fieldName,
      foreignKeyField: fkInRelated,
    };
  });
  table.relations.manyToMany.forEach((relation) => {
    if (relation.fieldName) {
      // Prefer direct key fields from enriched cleanTable()
      let junctionLeftKeyField = relation.junctionLeftKeyFields?.[0];
      let junctionRightKeyField = relation.junctionRightKeyFields?.[0];

      // Fallback: derive from junction table's belongsTo relations
      if (!junctionLeftKeyField || !junctionRightKeyField) {
        const junctionTableName = relation.junctionTable;
        const junctionTable = junctionTableName
          ? tables.find((candidate) => candidate.name === junctionTableName)
          : undefined;
        const junctionBelongsTo = junctionTable?.relations.belongsTo ?? [];
        if (!junctionLeftKeyField) {
          const leftRelation = junctionBelongsTo.find((entry) => entry.referencesTable === tableName);
          junctionLeftKeyField = firstFieldName(leftRelation?.keys ?? []);
        }
        if (!junctionRightKeyField) {
          const rightRelation = junctionBelongsTo.find((entry) => entry.referencesTable === relation.rightTable);
          junctionRightKeyField = firstFieldName(rightRelation?.keys ?? []);
        }
      }

      // Skip non-pure junction tables — they have required fields beyond the
      // two FK columns, so the manyToMany editor cannot produce valid mutations.
      if (!isJunctionTablePure(relation.junctionTable, junctionLeftKeyField, junctionRightKeyField, rawMetaTables)) {
        return;
      }

      info[relation.fieldName] = {
        kind: 'manyToMany',
        relatedTable: relation.rightTable,
        displayCandidates: computeCandidates(relation.rightTable),
        relationField: relation.fieldName,
        junctionTable: relation.junctionTable,
        junctionLeftKeyField,
        junctionRightKeyField,
        displayName: pluralize(relation.rightTable),
      };
    }
  });

  return info;
}

import { createContext, useContext } from 'react';
import { createStore, useStore as useZustandStore, type StoreApi } from 'zustand';

import { createDraftRowsSlice, type DraftRowsSlice } from './draft-rows-slice';
import { createRelationInfoSlice, type RelationInfoSlice } from './relation-info-slice';

export interface SheetsAuthState {
  isAuthenticated: boolean;
  accessToken: string | null;
  expiresAt: string | null;
  identityKey: string | null;
  setAuthenticated: (token: string, expiresAt: string, identityKey?: string | null) => void;
  setUnauthenticated: () => void;
}

export type SheetsStoreState = DraftRowsSlice & RelationInfoSlice & SheetsAuthState;

export function createSheetsStore(): StoreApi<SheetsStoreState> {
  return createStore<SheetsStoreState>((set, get) => ({
    // Draft rows
    ...createDraftRowsSlice(set),

    // Relation info cache
    ...createRelationInfoSlice(set, get),

    // Auth state (standalone mode)
    isAuthenticated: false,
    accessToken: null,
    expiresAt: null,
    identityKey: null,
    setAuthenticated: (token: string, expiresAt: string, identityKey = null) =>
      set({ isAuthenticated: true, accessToken: token, expiresAt, identityKey }),
    setUnauthenticated: () => set({ isAuthenticated: false, accessToken: null, expiresAt: null, identityKey: null }),
  }));
}

export const SheetsStoreContext = createContext<StoreApi<SheetsStoreState> | null>(null);

export function useSheetsStore<T>(selector: (state: SheetsStoreState) => T): T {
  const store = useContext(SheetsStoreContext);
  if (!store) {
    throw new Error('useSheetsStore must be used within a <SheetsProvider>');
  }
  return useZustandStore(store, selector);
}

export function useSheetsStoreApi(): StoreApi<SheetsStoreState> {
  const store = useContext(SheetsStoreContext);
  if (!store) {
    throw new Error('useSheetsStoreApi must be used within a <SheetsProvider>');
  }
  return store;
}

// The TanStack Table v9 feature set for the DOM port — EXACTLY the four
// client-state features (S1). No sort/filter/pagination features and no
// row-model factories: rows arrive already server-sorted/filtered/paginated
// from useSheets, so this instance is a pure column + selection state-mirror.
//
// Built at module scope so the feature object has a stable identity across
// renders (a fresh tableFeatures({...}) per render would churn the table).
import {
	columnSizingFeature, // committed column widths   -> state.columnSizing
	columnResizingFeature, // transient drag-resize    -> state.columnResizing
	columnPinningFeature, // logical start/end pin      -> state.columnPinning
	rowSelectionFeature, // row selection               -> state.rowSelection
	tableFeatures
} from '@tanstack/react-table';

export const sheetsTableFeatures = tableFeatures({
	columnSizingFeature,
	columnResizingFeature,
	columnPinningFeature,
	rowSelectionFeature
});

export type SheetsTableFeatures = typeof sheetsTableFeatures;

// The DOM viewport for the TanStack port — where LAYOUT happens (the v9 table
// instance from S3 is a pure state-mirror; this is the dual-axis TanStack
// Virtual shell that paints it).
//
// VERTICAL virtualizer over rows (dynamic height via measureElement), HORIZONTAL
// virtualizer over columns. The STICKY column (start-pinned via columnPinning, or
// the first column when nothing is pinned) is painted OUTSIDE the horizontal
// virtual window — a separate `left: 0` element per row — so it stays put under
// horizontal scroll. The horizontal virtualizer still counts it (so column start
// offsets stay correct), but the item loop SKIPS the sticky index; it is never
// double-painted.
//
// A sticky HEADER band (S1) sits at the top of the scroll content, reusing the
// SAME column layout as the body (sticky-col header + the virtualized non-sticky
// headers at the identical translateX offsets). Each header carries a sort caret
// (clickable -> onHeaderClick) and a drag-resize handle on its right edge.
//
// `renderCell` is injected so S4 stays host-decoupled and testable: S5 supplies
// the real cell host. The root carries `data-impl="dom"` so tests / Chrome can
// assert the DOM path is live.
import { useImperativeHandle, useMemo, useRef } from 'react';
import type { Ref } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';
import type { Cell, Column, Row, Table } from '@tanstack/react-table';

import { Checkbox } from '@/components/ui/checkbox';

import { cn } from '../utils/cn';
import type { SheetsRow } from '../grid/row-model';
import type { SelectionRect } from '../selection/selection-model';
import type { SheetsTableFeatures } from './features';

/** Comfortable density default (DESIGN_SPEC §5). Drives the v-virtualizer estimate,
 *  range-band / fill-nub geometry, and hit-testing — change here propagates everywhere. */
const ESTIMATED_ROW_HEIGHT = 44;
/** Extra rows rendered above/below the visible window — fewer blank rows on fast vertical scroll. */
const ROW_OVERSCAN = 12;
/** Extra columns rendered left/right of the visible window — fewer blank cells on fast horizontal scroll. */
const COLUMN_OVERSCAN = 6;
/** Header band height (DESIGN_SPEC §5 comfortable) — slightly shorter than the body row. */
const HEADER_HEIGHT = 40;
/** Width of the optional leading row-marker (checkbox) column — glide's rowMarker analogue. */
const MARKER_WIDTH = 40;

// Row-hover tint for the PINNED (sticky) cells. The pinned column/marker sit OVER the
// horizontally-scrolled body, so their hover background must be fully OPAQUE — a translucent
// `bg-muted/50` (as used on the row itself) would let the scrolled-away cells bleed through the
// pinned column on hover. `color-mix` precomputes the SAME tint as opaque: 50% muted over the
// surface, so the pinned column matches the row exactly while staying solid. Theme-safe (the raw
// `--muted`/`--background` vars flip in dark mode). Uses raw vars, not `--color-*`, because the UI
// theme is `@theme inline` (the `--color-*` aliases aren't emitted at runtime).
const PINNED_HOVER_BG = 'group-hover:bg-[color-mix(in_oklab,var(--muted)_50%,var(--background))]';

type SheetsTable = Table<SheetsTableFeatures, SheetsRow>;
type SheetsTableCell = Cell<SheetsTableFeatures, SheetsRow, unknown>;
type SheetsTableColumn = Column<SheetsTableFeatures, SheetsRow, unknown>;

/** Sorting state mirror (the shell owns it via useGridState — `id:null` = unsorted). */
export interface GridViewportSorting {
	id: string | null;
	desc: boolean;
}

/** Per-cell layout context handed to the host alongside the v9 cell. */
export interface RenderCellContext {
	rowIndex: number;
	columnIndex: number;
	/** True for the sticky column, painted outside the h-virtual window. */
	isStickyColumn: boolean;
	/** True when this cell is the active (keyboard cursor) cell. Drives the focus ring. */
	isActive: boolean;
}

export type RenderCell = (cell: SheetsTableCell, ctx: RenderCellContext) => React.ReactNode;

/** Imperative handle for the later SheetsHandle scrollToRow path. */
export interface GridViewportHandle {
	scrollToIndex: (rowIndex: number) => void;
	/** Scroll the given cell into view (row + column virtualizers). Used by keyboard nav. */
	scrollToCell: (columnIndex: number, rowIndex: number) => void;
}

/** Visible row window (overscan-inclusive) reported to the shell for infinite-scroll prefetch. */
export interface VisibleRange {
	startIndex: number;
	endIndex: number;
}

export interface GridViewportProps {
	table: SheetsTable;
	renderCell: RenderCell;
	handleRef?: Ref<GridViewportHandle>;
	/**
	 * Fired on the scroll root's `scroll`. The DOM grid uses this to close (commit-or-
	 * dismiss) any open overlay editor: a virtualized cell anchor can unmount under
	 * scroll, so Phase-4 closes rather than re-positions against a stale rect.
	 */
	onScroll?: (e: React.UIEvent<HTMLDivElement>) => void;
	/** Sort caret state for the header. Defaults to unsorted (`{ id: null, desc: false }`). */
	sorting?: GridViewportSorting;
	/** Toggle sort for a column. The shell wires this to onHeaderClicked / toggleSorting. */
	onHeaderClick?: (colKey: string) => void;
	/**
	 * Commit a column width from the header drag-resize handle. When provided, the handle
	 * drives a manual pointer-drag against this (shell sizing lives in useGridState). When
	 * omitted, the handle falls back to the v9 `header.getResizeHandler()` (columnResizeMode
	 * 'onChange' feeds the table's own columnSizing state).
	 */
	onResize?: (colKey: string, width: number) => void;
	/**
	 * Total row count for the VERTICAL virtualizer. Defaults to the table's row-model length.
	 * Infinite scroll passes the server total here so the scrollbar spans every (lazily loaded)
	 * row — the table's `data` is the same-length proxy, so this matches `rows.length` in practice
	 * but is threaded explicitly so the shell stays the single source of truth for row count.
	 */
	count?: number;
	/**
	 * Fired (effect-free, via the row virtualizer's `onChange`) with the current overscan-inclusive
	 * visible window. The shell maps this to the canvas `onVisibleRegionChanged({ y, height })` so
	 * infinite-scroll prefetch runs identically. Omitted in paginated mode.
	 */
	onVisibleRangeChange?: (range: VisibleRange) => void;
	/**
	 * Optional leading checkbox / select-all column (glide's `rowMarkers` analogue). When supplied,
	 * a sticky MARKER column (fixed {@link MARKER_WIDTH}px) is painted to the LEFT of the sticky col0,
	 * driving the canonical {@link SheetsSelection} RangeSet. When OMITTED, the grid renders exactly as
	 * before (no marker column) so existing tests/stories that pass no rowMarker are unaffected.
	 */
	rowMarker?: RowMarker;
	/** Active (keyboard cursor) cell `[col, row]`. Drives the per-cell focus ring + aria-activedescendant. */
	activeCell?: [number, number];
	/** Active range (cell coords) — rendered as an inert pointer-events-none band overlay. P2 populates it. */
	activeRange?: SelectionRect;
	/** Keydown handler for the grid root — the shell owns spreadsheet nav (arrows / Enter / F2). */
	onGridKeyDown?: (e: React.KeyboardEvent) => void;
	/**
	 * Native clipboard handlers for the grid root. They fire only when the root (tabIndex=0) holds
	 * focus and an overlay editor is NOT open (the editor owns its own clipboard while editing). The
	 * shell routes each to the `clipboard.copy`/`cut`/`paste` command through the ONE dispatch pipeline.
	 */
	onCopy?: (e: React.ClipboardEvent) => void;
	onCut?: (e: React.ClipboardEvent) => void;
	onPaste?: (e: React.ClipboardEvent) => void;
	/** DOM id of the active cell node, mirrored to `aria-activedescendant` on the grid root. */
	activeDescendantId?: string;
	/**
	 * Fired on a fill-handle (nub) drag RELEASE when the dropped cell extends the source range.
	 * `sourceRange` is the active range (or a 1×1 rect at the active cell) the drag started from;
	 * `target` is the `[col,row]` under the pointer at release (clamped to grid bounds). The shell
	 * routes this to the `fill.drag` command. Omitted = no nub rendered.
	 */
	onFillDrag?: (sourceRange: SelectionRect, target: [number, number]) => void;
	className?: string;
}

/** Selection wiring for the leading checkbox column. The shell derives this from SheetsSelection. */
export interface RowMarker {
	/** True when row `rowIndex` is in the canonical selection. */
	isSelected: (rowIndex: number) => boolean;
	/** Toggle row `rowIndex`; `shiftKey` requests a contiguous range-select from the last anchor. */
	onToggleRow: (rowIndex: number, shiftKey: boolean) => void;
	/** Every row selected — the header checkbox shows checked. */
	allSelected: boolean;
	/** Some (but not all) rows selected — the header checkbox shows indeterminate. */
	someSelected: boolean;
	/** Select-all / clear-all from the header checkbox. */
	onToggleAll: () => void;
}

function cellForColumnIndex(row: Row<SheetsTableFeatures, SheetsRow>, columnIndex: number): SheetsTableCell {
	return row.getAllCells()[columnIndex];
}

/**
 * Project a half-open active {@link SelectionRect} (cell coords) into px box geometry for
 * the inert range-band overlay. X/width sum `columns[i].getSize()` across the spanned cols
 * (honoring the leading `markerWidth` offset); Y/height use the uniform ESTIMATED_ROW_HEIGHT.
 * INERT in P1 (nothing sets `activeRange`); wired so P2 just populates `current.range`.
 */
function rangeBandStyle(range: SelectionRect, columns: SheetsTableColumn[], markerWidth: number): React.CSSProperties {
	let left = markerWidth;
	for (let i = 0; i < range.x && i < columns.length; i++) left += columns[i].getSize();
	let width = 0;
	for (let i = range.x; i < range.x + range.width && i < columns.length; i++) width += columns[i].getSize();
	return {
		transform: `translate(${left}px, ${range.y * ESTIMATED_ROW_HEIGHT}px)`,
		width,
		height: range.height * ESTIMATED_ROW_HEIGHT
	};
}

/** Side of the square fill-handle nub (px). Centered on the source rect's bottom-right corner. */
const FILL_NUB_SIZE = 8;

/**
 * Position the fill-handle nub centered on the BOTTOM-RIGHT corner of the source {@link SelectionRect}.
 * Reuses {@link rangeBandStyle}'s left/width math (column-width sum + markerWidth) so the nub tracks
 * scroll in the SAME body coordinate space as the range band; the corner is `(left+width, top+height)`.
 */
function fillNubStyle(source: SelectionRect, columns: SheetsTableColumn[], markerWidth: number): React.CSSProperties {
	let left = markerWidth;
	for (let i = 0; i < source.x && i < columns.length; i++) left += columns[i].getSize();
	let width = 0;
	for (let i = source.x; i < source.x + source.width && i < columns.length; i++) width += columns[i].getSize();
	const right = left + width;
	const bottom = (source.y + source.height) * ESTIMATED_ROW_HEIGHT;
	return {
		transform: `translate(${right - FILL_NUB_SIZE / 2}px, ${bottom - FILL_NUB_SIZE / 2}px)`,
		width: FILL_NUB_SIZE,
		height: FILL_NUB_SIZE
	};
}

/**
 * Hit-test a client pointer position to a `[col, row]` cell index over the virtualized body.
 *
 * Converts to CONTENT space (add the scroll element's scroll offset, subtract its bounding-rect
 * origin), then: X walks the per-column widths from the leading `markerWidth` to find the column
 * whose band the pointer is over; Y subtracts the sticky `headerHeight` and floors by the uniform
 * `rowHeight`. Both axes CLAMP to `[0, count-1]` so a drag past the grid edge lands on the last
 * cell. PURE (takes the geometry, returns indices) — testable without a DOM.
 */
export function hitTestCell(
	clientX: number,
	clientY: number,
	geom: {
		rect: { left: number; top: number };
		scrollLeft: number;
		scrollTop: number;
		markerWidth: number;
		headerHeight: number;
		rowHeight: number;
		colWidths: readonly number[];
		rowCount: number;
	},
): [number, number] {
	const { rect, scrollLeft, scrollTop, markerWidth, headerHeight, rowHeight, colWidths, rowCount } = geom;
	// Column: walk widths in content space from the marker offset.
	const localX = clientX - rect.left + scrollLeft - markerWidth;
	let col = 0;
	let acc = 0;
	for (let i = 0; i < colWidths.length; i++) {
		acc += colWidths[i];
		if (localX < acc) {
			col = i;
			break;
		}
		col = i;
	}
	col = Math.max(0, Math.min(col, colWidths.length - 1));
	// Row: subtract the sticky header, floor by the uniform row height.
	const localY = clientY - rect.top + scrollTop - headerHeight;
	let row = Math.floor(localY / rowHeight);
	row = Math.max(0, Math.min(row, rowCount - 1));
	return [col, row];
}

/** Index of the start-pinned column, else the first column (sticky-by-default). */
function findStickyColumnIndex(columns: SheetsTableColumn[]): number {
	const pinned = columns.findIndex((col) => col.getIsPinned() === 'start');
	return pinned >= 0 ? pinned : columns.length > 0 ? 0 : -1;
}

/** Header label: shell meta title -> string header -> column id. `meta` is the empty v9 type, so read it loosely. */
function columnTitle(column: SheetsTableColumn): string {
	const meta = column.columnDef.meta as { title?: string } | undefined;
	if (meta?.title) return meta.title;
	const header = column.columnDef.header;
	if (typeof header === 'string') return header;
	return column.id;
}

interface HeaderCellProps {
	column: SheetsTableColumn;
	header: import('@tanstack/react-table').Header<SheetsTableFeatures, SheetsRow, unknown>;
	sorting: GridViewportSorting;
	onHeaderClick?: (colKey: string) => void;
	onResize?: (colKey: string, width: number) => void;
}

/** A single header cell: title + sort caret (click toggles) + right-edge resize handle. */
function HeaderCell({ column, header, sorting, onHeaderClick, onResize }: HeaderCellProps) {
	const isSorted = sorting.id === column.id;
	const direction: 'asc' | 'desc' | 'none' = isSorted ? (sorting.desc ? 'desc' : 'asc') : 'none';

	function onResizePointerDown(e: React.PointerEvent<HTMLDivElement>) {
		// Don't toggle sort while grabbing the handle, and don't select header text.
		e.preventDefault();
		e.stopPropagation();
		if (onResize) {
			const startX = e.clientX;
			const startWidth = column.getSize();
			const onMove = (move: PointerEvent) => onResize(column.id, Math.max(40, startWidth + (move.clientX - startX)));
			const onUp = () => {
				window.removeEventListener('pointermove', onMove);
				window.removeEventListener('pointerup', onUp);
			};
			window.addEventListener('pointermove', onMove);
			window.addEventListener('pointerup', onUp);
			return;
		}
		// Fall back to the v9 feature handler (columnResizeMode 'onChange').
		header.getResizeHandler()(e.nativeEvent);
	}

	return (
		<div
			role='columnheader'
			data-part-id='sheets-header-cell'
			data-col-key={column.id}
			aria-sort={direction === 'asc' ? 'ascending' : direction === 'desc' ? 'descending' : 'none'}
			onClick={() => onHeaderClick?.(column.id)}
			className={cn(
				'group relative flex h-full w-full select-none items-center gap-1 border-b border-border bg-background px-3 text-xs font-medium text-muted-foreground',
				onHeaderClick && 'cursor-pointer hover:bg-muted/50 hover:text-foreground'
			)}
		>
			<span className='truncate'>{columnTitle(column)}</span>
			<SortCaret direction={direction} />
			<div
				role='separator'
				aria-orientation='vertical'
				data-part-id='sheets-resize-handle'
				onClick={(e) => e.stopPropagation()}
				onPointerDown={onResizePointerDown}
				className='absolute right-0 top-0 h-full w-1 cursor-col-resize touch-none select-none bg-transparent hover:bg-primary/50'
			/>
		</div>
	);
}

/** Up/down/neutral sort caret (inline SVG, no icon-lib dep — matches the package's glyph style). */
function SortCaret({ direction }: { direction: 'asc' | 'desc' | 'none' }) {
	return (
		<svg
			data-part-id='sheets-sort-caret'
			data-direction={direction}
			width='8'
			height='8'
			viewBox='0 0 8 8'
			aria-hidden='true'
			className={cn('ml-auto shrink-0', direction === 'none' && 'opacity-30')}
		>
			{direction === 'desc' ? <path d='M0 2 L4 6 L8 2 Z' fill='currentColor' /> : <path d='M0 6 L4 2 L8 6 Z' fill='currentColor' />}
		</svg>
	);
}

/** Header marker cell: the select-all checkbox (checked = all, indeterminate = some). */
function RowMarkerHeaderCell({ rowMarker }: { rowMarker: RowMarker }) {
	return (
		<div
			role='columnheader'
			data-part-id='sheets-row-marker-header'
			data-slot='row-marker-header'
			className='flex h-full w-full select-none items-center justify-center border-b border-border bg-background'
		>
			<Checkbox
				checked={rowMarker.allSelected}
				indeterminate={rowMarker.someSelected}
				onClick={() => rowMarker.onToggleAll()}
				aria-label={rowMarker.allSelected ? 'Deselect all rows' : 'Select all rows'}
			/>
		</div>
	);
}

/** Body marker cell per row: a checkbox reflecting selection; click (with shiftKey) drives the toggle. */
function RowMarkerCell({ rowIndex, rowMarker }: { rowIndex: number; rowMarker: RowMarker }) {
	const selected = rowMarker.isSelected(rowIndex);
	// Reveal-on-hover (DESIGN_SPEC §9): checkbox is hidden until the row is hovered, but stays
	// visible once this row is checked OR any selection is active (so multi-select stays legible).
	const reveal = selected || rowMarker.someSelected || rowMarker.allSelected;
	return (
		<div
			data-part-id='sheets-row-marker-cell'
			data-slot='row-marker-cell'
			// Stop the click from bubbling into the row (which would also start a cell edit).
			onClick={(e) => e.stopPropagation()}
			onDoubleClick={(e) => e.stopPropagation()}
			className={`flex h-full w-full select-none items-center justify-center bg-background ${PINNED_HOVER_BG}`}
		>
			<Checkbox
				checked={selected}
				// base-ui Checkbox renders a <button>; onClick carries the native shiftKey for range-select.
				onClick={(e) => rowMarker.onToggleRow(rowIndex, e.shiftKey)}
				aria-label={`Select row ${rowIndex}`}
				className={cn(!reveal && 'opacity-0 transition-opacity group-hover:opacity-100 motion-reduce:transition-none')}
			/>
		</div>
	);
}

export function GridViewport({
	table,
	renderCell,
	handleRef,
	onScroll,
	sorting = { id: null, desc: false },
	onHeaderClick,
	onResize,
	count,
	onVisibleRangeChange,
	rowMarker,
	activeCell,
	activeRange,
	onGridKeyDown,
	onCopy,
	onCut,
	onPaste,
	activeDescendantId,
	onFillDrag,
	className
}: GridViewportProps) {
	const scrollRef = useRef<HTMLDivElement>(null);

	const rows = table.getRowModel().rows;
	const columns = table.getAllLeafColumns();

	// Report the visible window WITHOUT an effect: the virtualizer's `onChange` fires on every
	// recompute (scroll/resize/measure) with the live instance, whose `.range` is the overscan-
	// inclusive {startIndex,endIndex}. Keep the ref current each render so the latch never goes stale.
	const onVisibleRangeChangeRef = useRef(onVisibleRangeChange);
	onVisibleRangeChangeRef.current = onVisibleRangeChange;

	const rowVirtualizer = useVirtualizer({
		count: count ?? rows.length,
		getScrollElement: () => scrollRef.current,
		estimateSize: () => ESTIMATED_ROW_HEIGHT,
		overscan: ROW_OVERSCAN,
		onChange: (instance) => {
			const range = instance.range;
			if (range) onVisibleRangeChangeRef.current?.({ startIndex: range.startIndex, endIndex: range.endIndex });
		}
	});

	const columnVirtualizer = useVirtualizer({
		horizontal: true,
		count: columns.length,
		getScrollElement: () => scrollRef.current,
		estimateSize: (index) => columns[index].getSize(),
		getItemKey: (index) => columns[index]?.id ?? index,
		overscan: COLUMN_OVERSCAN
	});

	useImperativeHandle(
		handleRef,
		() => ({
			scrollToIndex: (rowIndex: number) => rowVirtualizer.scrollToIndex(rowIndex),
			scrollToCell: (columnIndex: number, rowIndex: number) => {
				rowVirtualizer.scrollToIndex(rowIndex);
				columnVirtualizer.scrollToIndex(columnIndex);
			}
		}),
		[rowVirtualizer, columnVirtualizer]
	);

	const stickyIndex = findStickyColumnIndex(columns);
	const hasStickyColumn = stickyIndex >= 0;
	const stickyColumn = hasStickyColumn ? columns[stickyIndex] : undefined;
	const stickyWidth = stickyColumn ? stickyColumn.getSize() : 0;
	const stickyHeader = stickyColumn ? table.getLeafHeaders().find((h) => h.column.id === stickyColumn.id) : undefined;
	const headersByColumnId = useMemo(() => new Map(table.getLeafHeaders().map((h) => [h.column.id, h])), [table, columns]);

	const totalWidth = columnVirtualizer.getTotalSize();
	const virtualColumns = columnVirtualizer.getVirtualItems();

	// The optional leading marker column shifts EVERYTHING right by MARKER_WIDTH: the sticky col0
	// pins at `left: markerWidth` (the marker owns `left: 0`), virtualized columns translate by an
	// extra markerWidth, and the header/body content width grows by markerWidth. When no rowMarker
	// is supplied, markerWidth is 0 and the layout is byte-identical to before.
	const markerWidth = rowMarker ? MARKER_WIDTH : 0;
	const contentWidth = totalWidth + markerWidth;

	// Fill-handle SOURCE rect: the active range, else a 1×1 rect at the active cell. Drives the nub
	// position (its bottom-right corner) and is the `from` handed to onFillDrag. Absent when neither.
	const fillSource: SelectionRect | undefined = onFillDrag
		? activeRange ?? (activeCell ? { x: activeCell[0], y: activeCell[1], width: 1, height: 1 } : undefined)
		: undefined;

	function onFillNubPointerDown(e: React.PointerEvent<HTMLDivElement>) {
		// Don't start a cell selection / text-select while grabbing the nub.
		e.preventDefault();
		e.stopPropagation();
		if (!onFillDrag || !fillSource) return;
		const source = fillSource;
		const scrollEl = scrollRef.current;
		if (!scrollEl) return;
		const colWidths = columns.map((c) => c.getSize());
		let target: [number, number] = [source.x + source.width - 1, source.y + source.height - 1];
		const onMove = (move: PointerEvent) => {
			const rect = scrollEl.getBoundingClientRect();
			target = hitTestCell(move.clientX, move.clientY, {
				rect: { left: rect.left, top: rect.top },
				scrollLeft: scrollEl.scrollLeft,
				scrollTop: scrollEl.scrollTop,
				markerWidth,
				headerHeight: HEADER_HEIGHT,
				rowHeight: ESTIMATED_ROW_HEIGHT,
				colWidths,
				rowCount: count ?? rows.length
			});
		};
		const onUp = () => {
			window.removeEventListener('pointermove', onMove);
			window.removeEventListener('pointerup', onUp);
			onFillDrag(source, target);
		};
		window.addEventListener('pointermove', onMove);
		window.addEventListener('pointerup', onUp);
	}

	return (
		<div
			ref={scrollRef}
			data-impl='dom'
			data-part-id='sheets-viewport'
			role='grid'
			tabIndex={0}
			onScroll={onScroll}
			onKeyDown={(e) => onGridKeyDown?.(e)}
			onCopy={onCopy}
			onCut={onCut}
			onPaste={onPaste}
			aria-activedescendant={activeDescendantId}
			aria-rowcount={count ?? rows.length}
			aria-colcount={columns.length}
			className={cn('relative h-full w-full overflow-auto outline-none', className)}
		>
			{/* Sticky HEADER band — same column layout as the body. */}
			<div
				role='row'
				data-part-id='sheets-header-row'
				className='sticky top-0 z-30 flex bg-background'
				style={{ height: HEADER_HEIGHT, width: contentWidth }}
			>
				{rowMarker && (
					<div className='sticky left-0 z-40 flex shrink-0' style={{ width: markerWidth, height: '100%' }}>
						<RowMarkerHeaderCell rowMarker={rowMarker} />
					</div>
				)}
				{stickyColumn && stickyHeader && (
					<div className='sticky z-40 flex shrink-0 border-r border-border' style={{ left: markerWidth, width: stickyWidth, height: '100%' }}>
						<HeaderCell
							column={stickyColumn}
							header={stickyHeader}
							sorting={sorting}
							onHeaderClick={onHeaderClick}
							onResize={onResize}
						/>
					</div>
				)}
				{virtualColumns.map((virtualCol) => {
					if (virtualCol.index === stickyIndex) return null; // sticky header painted above
					const column = columns[virtualCol.index];
					const header = headersByColumnId.get(column.id);
					if (!header) return null;
					return (
						<div
							key={virtualCol.key}
							className='absolute top-0 flex'
							style={{ transform: `translateX(${virtualCol.start + markerWidth}px)`, width: virtualCol.size, height: '100%' }}
						>
							<HeaderCell
								column={column}
								header={header}
								sorting={sorting}
								onHeaderClick={onHeaderClick}
								onResize={onResize}
							/>
						</div>
					);
				})}
			</div>

			{/* BODY — virtualized rows × columns. */}
			<div style={{ height: rowVirtualizer.getTotalSize(), width: contentWidth, position: 'relative' }}>
				{rowVirtualizer.getVirtualItems().map((virtualRow) => {
					const row = rows[virtualRow.index];
					// Defensive: when `count` (server total) leads the loaded `rows` window, the proxy
					// should still back every index — but guard the off-by-one race rather than crash.
					if (!row) return null;
					const rowSelected = rowMarker?.isSelected(virtualRow.index) ?? false;
					return (
						<div
							key={virtualRow.key}
							role='row'
							data-index={virtualRow.index}
							data-row={virtualRow.index}
							data-selected={rowSelected || undefined}
							aria-rowindex={virtualRow.index + 1}
							className={cn(
							'group absolute left-0 top-0 flex border-b border-border',
							rowSelected ? 'bg-primary/5' : 'hover:bg-muted/50'
						)}
							style={{ transform: `translateY(${virtualRow.start}px)`, height: ESTIMATED_ROW_HEIGHT, width: '100%' }}
						>
							{rowMarker && (
								<div className='sticky left-0 z-20 flex shrink-0' style={{ width: markerWidth }}>
									<RowMarkerCell rowIndex={virtualRow.index} rowMarker={rowMarker} />
								</div>
							)}
							{hasStickyColumn && (
								<div
									className={`sticky z-10 flex shrink-0 border-r border-border bg-background ${PINNED_HOVER_BG}`}
									data-col={stickyIndex}
									aria-colindex={stickyIndex + 1}
									style={{ left: markerWidth, width: stickyWidth }}
								>
									{renderCell(cellForColumnIndex(row, stickyIndex), {
										rowIndex: virtualRow.index,
										columnIndex: stickyIndex,
										isStickyColumn: true,
										isActive: activeCell?.[0] === stickyIndex && activeCell?.[1] === virtualRow.index
									})}
								</div>
							)}
							{virtualColumns.map((virtualCol) => {
								if (virtualCol.index === stickyIndex) return null; // sticky col painted by the element above
								return (
									<div
										key={virtualCol.key}
										className='absolute top-0 flex'
										data-col={virtualCol.index}
										aria-colindex={virtualCol.index + 1}
										style={{ transform: `translateX(${virtualCol.start + markerWidth}px)`, width: virtualCol.size, height: '100%' }}
									>
										{renderCell(cellForColumnIndex(row, virtualCol.index), {
											rowIndex: virtualRow.index,
											columnIndex: virtualCol.index,
											isStickyColumn: false,
											isActive: activeCell?.[0] === virtualCol.index && activeCell?.[1] === virtualRow.index
										})}
									</div>
								);
							})}
						</div>
					);
				})}
				{activeRange && (
					<div
						data-part-id='sheets-range-band'
						aria-hidden='true'
						className='pointer-events-none absolute z-[5] border border-primary/50 bg-primary/10'
						style={rangeBandStyle(activeRange, columns, markerWidth)}
					/>
				)}
				{fillSource && (
					<div
						data-part-id='sheets-fill-handle'
						role='button'
						aria-label='Fill handle'
						onPointerDown={onFillNubPointerDown}
						className='absolute z-10 cursor-crosshair touch-none select-none rounded-[1px] border border-background bg-primary'
						style={fillNubStyle(fillSource, columns, markerWidth)}
					/>
				)}
			</div>
		</div>
	);
}

// The TanStack Table v9 instance for the DOM port.
//
// This is a STATE-MIRROR over already-server-processed rows — NOT a layout
// layer (TanStack Virtual does layout in S4) and NOT a data layer (useSheets
// does data). The hook takes EXPLICIT params (it never calls useSheets) so it
// is unit-testable with hand-fed data.
//
// Controlled state (S1): v8-style `state` partial + per-feature `on*Change`
// callbacks. The CALLER owns the slices (useGridState / the store) — the table
// is never a second writer, so there is no echo loop.
//
// manualSorting / manualFiltering / manualPagination / rowCount are OMITTED:
// they live only on the sorting/filtering/pagination feature option types,
// which we do not register, so those keys are not in our TableOptions and
// passing them is a TS error (S1 verdict).
import { useMemo } from 'react';
import { createColumnHelper, useTable } from '@tanstack/react-table';
import type {
	ColumnDef,
	ColumnPinningState,
	ColumnResizeMode,
	ColumnSizingState,
	OnChangeFn,
	RowSelectionState
} from '@tanstack/react-table';

import type { SheetsRow } from '../grid/row-model';
import { sheetsTableFeatures, type SheetsTableFeatures } from './features';

/** Smallest column descriptor the instance needs — key + header label (+ optional width). */
export interface SheetsColumnDescriptor {
	key: string;
	name: string;
	size?: number;
}

export type SheetsColumnDef = ColumnDef<SheetsTableFeatures, SheetsRow>;

export interface UseSheetsTableInstanceParams {
	/** Render-column descriptors (header label + key), in display order. */
	columns: SheetsColumnDescriptor[];
	/** Rows fed AS-IS — already server sorted/filtered/paginated by useSheets. */
	data: SheetsRow[];
	/** Committed column widths (caller-owned). */
	columnSizing: ColumnSizingState;
	/** Logical start/end column pins (caller-owned). */
	columnPinning: ColumnPinningState;
	/** Row selection map (caller-owned). */
	rowSelection: RowSelectionState;
	onColumnSizingChange: OnChangeFn<ColumnSizingState>;
	onColumnPinningChange: OnChangeFn<ColumnPinningState>;
	onRowSelectionChange: OnChangeFn<RowSelectionState>;
	/** Stable row id from the server primary key / draft meta. Defaults to `row.id`. */
	getRowId?: (row: SheetsRow, index: number) => string;
}

function defaultGetRowId(row: SheetsRow, index: number): string {
	// In infinite-scroll mode `data` is the null-backed proxy from useSheets: indices not yet
	// fetched read back as `null`. TanStack Table v9 builds its row model over EVERY index
	// (getRowId is called per row, eagerly), so guard the null placeholder and key it on the
	// index — the stable id an unloaded slot should carry until its page resolves.
	return row?.id != null ? String(row.id) : String(index);
}

/**
 * Build a v9 table instance wired with {@link sheetsTableFeatures} and the
 * caller-owned controlled state. The column defs carry only a minimal value
 * accessor (`row[key]`); the actual cell RENDER is the S5 host's job, so no
 * `cell` renderer is duplicated here.
 */
export function useSheetsTableInstance(params: UseSheetsTableInstanceParams) {
	const {
		columns,
		data,
		columnSizing,
		columnPinning,
		rowSelection,
		onColumnSizingChange,
		onColumnPinningChange,
		onRowSelectionChange,
		getRowId = defaultGetRowId
	} = params;

	const columnDefs = useMemo<SheetsColumnDef[]>(() => {
		const helper = createColumnHelper<SheetsTableFeatures, SheetsRow>();
		// accessor-FUNCTION branch (value by key) → requires an explicit `id`. Null-guard the row:
		// v9 evaluates accessors eagerly while building the row model, and in infinite-scroll mode
		// `data` is the null-backed proxy (unloaded indices read as `null`). The DOM cell host paints
		// those slots from `getSheetsCellContent` (→ loading skeleton), so this accessor value is only
		// a placeholder; returning `undefined` for a null row keeps the eager build from throwing.
		return columns.map((col) => helper.accessor((row) => row?.[col.key], { id: col.key, header: col.name, size: col.size }));
	}, [columns]);

	// The v9 pinning feature reads `state.columnPinning.{start,end}` directly (no defaulting
	// when a partial object is supplied), so `column.getIsPinned()` throws on a bare `{}`.
	// Normalize to a complete shape so callers may pass `{}` for "nothing pinned".
	const normalizedPinning = useMemo<ColumnPinningState>(
		() => ({ start: columnPinning.start ?? [], end: columnPinning.end ?? [] }),
		[columnPinning]
	);

	return useTable({
		features: sheetsTableFeatures,
		columns: columnDefs,
		data,
		getRowId,
		enableColumnPinning: true,
		enableColumnResizing: true,
		enableRowSelection: true,
		columnResizeMode: 'onChange' as ColumnResizeMode,
		// Controlled: our reducer/store is the source of truth for these slices.
		state: { columnSizing, columnPinning: normalizedPinning, rowSelection },
		onColumnSizingChange,
		onColumnPinningChange,
		onRowSelectionChange
		// Subscribe to NOTHING (`() => null`). v9 `useTable` runs `table.setOptions(...)` DURING render
		// to sync the controlled `state` above into its @tanstack/store atoms; a broad selector would make
		// THIS component a store subscriber, so that render-phase write notifies it synchronously →
		// `forceStoreRerender` → React's "Cannot update a component while rendering" warning. The slices
		// are caller-owned (the shell is the single source of truth) and the DOM grid reads layout via direct
		// table methods (getRowModel/getSize/getIsPinned), not `table.state`, so no subscription is needed —
		// the grid already re-renders from the shell's own state. (TanStack production-readiness: prefer
		// `() => null` + `table.Subscribe` over a broad `() => state` selector.)
	}, (): null => null);
}

import { type ClassValue, clsx } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

// Parse image data - handles both URL strings and image objects
export const getImageUrl = (imageValue: unknown): string | null => {
	if (!imageValue) return null;

	// If it's a string, assume it's a URL
	if (typeof imageValue === 'string') {
		return imageValue;
	}

	// If it's an object, look for common URL properties
	if (typeof imageValue === 'object' && imageValue !== null) {
		// Try different possible URL properties
		const urlCandidates = ['url', 'src', 'href', 'link', 'path'];
		for (const candidate of urlCandidates) {
			const obj = imageValue as Record<string, unknown>;
			if (obj[candidate] && typeof obj[candidate] === 'string') {
				return obj[candidate] as string;
			}
		}
	}

	return null;
};

// Get image metadata from image object
export const getImageMetadata = (imageValue: unknown) => {
	if (!imageValue || typeof imageValue !== 'object') return null;

	const obj = imageValue as Record<string, unknown>;
	return {
		filename: (obj.filename as string) || (obj.name as string) || 'Unknown',
		size: (obj.size as number) || (obj.fileSize as number) || 0,
		mime: (obj.mime as string) || (obj.type as string) || (obj.contentType as string) || 'unknown',
		url: getImageUrl(imageValue) || '',
	};
};

// Format file size for display
export const formatFileSize = (bytes: number): string => {
	if (bytes === 0) return '0 B';
	const k = 1024;
	const sizes = ['B', 'KB', 'MB', 'GB'];
	const i = Math.floor(Math.log(bytes) / Math.log(k));
	return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
};

'use client';

import React, { ImgHTMLAttributes, useMemo, useState } from 'react';

import { useImageStatus } from './use-image-status';
import { cn } from './cn';

type Fallback = string | React.ReactNode; // a URL or JSX (icon, initials, skeleton...)

/**
 * Props mirror <img> + a few extras. Extend or omit freely.
 */
export interface ImageWithFallbackProps extends Omit<ImgHTMLAttributes<HTMLImageElement>, 'src'> {
	/** Primary image source. */
	src?: string | null;
	/** Ordered list of fallbacks. */
	fallback?: Fallback | Fallback[];
	/** Optional class for wrappers (useful for width / height utilities). */
	wrapperClassName?: string;
	/** Legacy props for backward compatibility */
	fallbackElement?: React.ReactNode;
	loadingElement?: React.ReactNode;
}

export function ImageWithFallback({
	src,
	alt = '',
	fallback,
	fallbackElement,
	loadingElement,
	wrapperClassName,
	className,
	...imgProps
}: ImageWithFallbackProps) {
	/* ----- flatten fallbacks into an array ---------------------------- */
	const fallbacks = useMemo<Fallback[]>(() => {
		const legacyFallbacks = [];
		if (loadingElement) legacyFallbacks.push(loadingElement);
		if (fallbackElement) legacyFallbacks.push(fallbackElement);

		const primaryFallbacks = fallback === undefined ? [] : Array.isArray(fallback) ? fallback : [fallback];

		return [...primaryFallbacks, ...legacyFallbacks];
	}, [fallback, fallbackElement, loadingElement]);

	/* ----- track which source we're currently trying ------------------ */
	const [currentSrcIndex, setCurrentSrcIndex] = useState(0);
	const currentSrc = currentSrcIndex === 0 ? src : (fallbacks[currentSrcIndex - 1] as string | undefined);

	/* ----- get status of the CURRENT url ------------------------------ */
	const status = useImageStatus(typeof currentSrc === 'string' ? currentSrc : undefined);

	/* ----- if it errors, bump index and try the next ------------------ */
	if (status === 'error' && currentSrcIndex < fallbacks.length) {
		// only URLs auto-advance
		if (typeof fallbacks[currentSrcIndex] === 'string') {
			setCurrentSrcIndex((i) => i + 1);
		}
	}

	/* ------------------------------------------------------------------ */
	const renderContent = () => {
		switch (status) {
			case 'idle':
			case 'loading': {
				// if the NEXT fallback is JSX (e.g. skeleton), render it early
				const maybeJSX = fallbacks.find((f) => typeof f !== 'string');
				return maybeJSX ?? <div className='bg-muted h-full w-full animate-pulse rounded-md' />;
			}

			case 'loaded': {
				return (
					<img
						src={currentSrc!}
						alt={alt}
						className={cn(
							'object-cover outline-1 -outline-offset-1 outline-black/10 dark:outline-white/10',
							className,
						)}
						{...imgProps}
					/>
				);
			}

			case 'error': {
				// final fallback: the first JSX fallback, or a default icon
				const jsxFallback = fallbacks.find((f) => typeof f !== 'string');
				return (
					jsxFallback ?? (
						<div className='bg-muted flex h-full w-full items-center justify-center rounded-md text-sm'>
							{alt?.[0] ?? '?'}
						</div>
					)
				);
			}
		}
	};

	return <div className={cn('relative overflow-hidden', wrapperClassName)}>{renderContent()}</div>;
}

'use client';

import React, { lazy, Suspense, useCallback, useEffect, useRef, useState } from 'react';
import type { LeafletMouseEvent } from 'leaflet';
import { MapPinIcon, SearchIcon, XIcon, Loader2 } from 'lucide-react';

import { cn } from './cn';
import { sheetsLogger } from './sheets-logger';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { InputGroup, InputGroupAddon, InputGroupInput } from '@/components/ui/input-group';

// TypeScript interfaces
interface GeoJSONPoint {
	type: 'Point';
	coordinates: [number, number]; // [longitude, latitude]
}

interface MapPickerValue {
	geojson: GeoJSONPoint;
	srid: number;
	x: number;
	y: number;
}

interface MapPickerProps {
	value?: MapPickerValue | GeoJSONPoint | any;
	onChange?: (value: MapPickerValue | undefined) => void;
	className?: string;
	placeholder?: string;
	disabled?: boolean;
	height?: number;
	markerColor?: string;
}

interface SearchResult {
	display_name: string;
	lat: string;
	lon: string;
	place_id: string;
}

// Utility functions
const createMapValue = (lat: number, lng: number): MapPickerValue => ({
	geojson: {
		type: 'Point',
		coordinates: [lng, lat],
	},
	srid: 4326,
	x: lng,
	y: lat,
});

const extractPosition = (value: any): [number, number] | null => {
	if (!value) return null;

	let coordinates: [number, number] | undefined;

	if (value.type === 'Point' && Array.isArray(value.coordinates)) {
		coordinates = value.coordinates;
	} else if (value.geojson?.type === 'Point' && Array.isArray(value.geojson.coordinates)) {
		coordinates = value.geojson.coordinates;
	}

	if (!coordinates || coordinates.length < 2) return null;

	const [lng, lat] = coordinates;

	if (typeof lng !== 'number' || typeof lat !== 'number') return null;
	if (!isFinite(lng) || !isFinite(lat)) return null;

	return [lat, lng];
};

const searchLocation = async (query: string): Promise<SearchResult[]> => {
	if (!query.trim()) return [];

	try {
		const response = await fetch(
			`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(query)}&limit=5&addressdetails=1`,
		);
		const results = await response.json();
		return results || [];
	} catch (error) {
		sheetsLogger().error('Search error:', error);
		return [];
	}
};

/**
 * Inner map component that uses react-leaflet.
 * Lazy-loaded to avoid bundling ~270KB Leaflet in main chunk.
 */
const LeafletMapInner = lazy(() =>
	Promise.all([import('react-leaflet'), import('leaflet')]).then(([reactLeaflet, L]) => {
		const { MapContainer, TileLayer, Marker, useMapEvents, useMap } = reactLeaflet;

		const createCustomIcon = (color: string = '#3b82f6') => {
			return L.divIcon({
				html: `
					<div style="
						width: 32px;
						height: 32px;
						display: flex;
						align-items: center;
						justify-content: center;
						background: ${color};
						border: 3px solid white;
						border-radius: 50% 50% 50% 0;
						transform: rotate(-45deg);
						box-shadow: 0 2px 8px rgba(0,0,0,0.3);
					">
						<svg width="16" height="16" viewBox="0 0 24 24" fill="white" style="transform: rotate(45deg);">
							<path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z"/>
						</svg>
					</div>
				`,
				className: 'custom-marker',
				iconSize: [32, 32],
				iconAnchor: [16, 32],
				popupAnchor: [0, -32],
			});
		};

		function MapEventHandler({
			onMapClick,
			position,
		}: {
			onMapClick: (lat: number, lng: number) => void;
			position: [number, number] | null;
		}): React.ReactElement | null {
			const map = useMap();

			useMapEvents({
				click(e: LeafletMouseEvent) {
					onMapClick(e.latlng.lat, e.latlng.lng);
				},
			});

			React.useEffect(() => {
				if (position && map) {
					map.setView(position, 15);
				}
			}, [position, map]);

			return null;
		}

		function LeafletMap({
			position,
			onMapClick,
			disabled,
			height,
			markerColor,
		}: {
			position: [number, number] | null;
			onMapClick: (lat: number, lng: number) => void;
			disabled: boolean;
			height: number;
			markerColor: string;
		}) {
			const defaultCenter: [number, number] = [40.7128, -74.006];

			return (
				<div style={{ height: `${height}px` }} className='relative'>
					<MapContainer
						center={position || defaultCenter}
						zoom={position ? 15 : 10}
						style={{ height: '100%', width: '100%' }}
						className={cn('z-0', disabled && 'pointer-events-none opacity-64')}
					>
						<TileLayer
							attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
							url='https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png'
						/>

						{position && <Marker position={position} icon={createCustomIcon(markerColor)} />}

						<MapEventHandler onMapClick={onMapClick} position={position} />
					</MapContainer>

					{disabled && <div className='bg-background/50 absolute inset-0 z-10' />}
				</div>
			);
		}

		return { default: LeafletMap };
	})
);

function MapLoading({ height }: { height: number }) {
	return (
		<div style={{ height: `${height}px` }} className='bg-muted flex items-center justify-center rounded-lg border'>
			<Loader2 className='h-6 w-6 animate-spin text-muted-foreground' />
		</div>
	);
}

export function MapPicker({
	value,
	onChange,
	className,
	placeholder = 'Search for a location...',
	disabled = false,
	height = 300,
	markerColor = '#3b82f6',
}: MapPickerProps) {
	const [searchQuery, setSearchQuery] = useState('');
	const [searchResults, setSearchResults] = useState<SearchResult[]>([]);
	const [isSearching, setIsSearching] = useState(false);
	const [showResults, setShowResults] = useState(false);
	const searchTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

	const position = extractPosition(value);

	const handleMapClick = useCallback(
		(lat: number, lng: number) => {
			if (disabled) return;
			const newValue = createMapValue(lat, lng);
			onChange?.(newValue);
			setSearchQuery('');
			setShowResults(false);
		},
		[disabled, onChange],
	);

	const handleSearchChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
		const query = e.target.value;
		setSearchQuery(query);

		if (searchTimeoutRef.current) {
			clearTimeout(searchTimeoutRef.current);
		}

		searchTimeoutRef.current = setTimeout(async () => {
			if (query.trim()) {
				setIsSearching(true);
				setShowResults(true);
				const results = await searchLocation(query);
				setSearchResults(results);
				setIsSearching(false);
			} else {
				setShowResults(false);
				setSearchResults([]);
			}
		}, 300);
	}, []);

	const handleResultSelect = useCallback(
		(result: SearchResult) => {
			if (disabled) return;
			const lat = parseFloat(result.lat);
			const lng = parseFloat(result.lon);
			const newValue = createMapValue(lat, lng);
			onChange?.(newValue);
			setSearchQuery(result.display_name);
			setShowResults(false);
		},
		[disabled, onChange],
	);

	const clearSearch = useCallback(() => {
		setSearchQuery('');
		setShowResults(false);
		setSearchResults([]);
	}, []);

	const clearLocation = useCallback(() => {
		if (disabled) return;
		onChange?.(undefined);
		setSearchQuery('');
	}, [disabled, onChange]);

	useEffect(() => {
		return () => {
			if (searchTimeoutRef.current) {
				clearTimeout(searchTimeoutRef.current);
			}
		};
	}, []);

	return (
		<div className={cn('relative w-full', className)}>
			{/* Search Input */}
			<div className='relative mb-2'>
				<InputGroup>
					<InputGroupAddon>
						<SearchIcon />
					</InputGroupAddon>
					<InputGroupInput
						type='text'
						placeholder={placeholder}
						value={searchQuery}
						onChange={handleSearchChange}
						disabled={disabled}
					/>
					<InputGroupAddon align='inline-end'>
						{searchQuery && (
							<Button
								type='button'
								variant='ghost'
								size='sm'
								onClick={clearSearch}
								disabled={disabled}
								className='h-7 w-7 p-0'
							>
								<XIcon className='h-3 w-3' />
							</Button>
						)}
						{position && (
							<Button
								type='button'
								variant='ghost'
								size='sm'
								onClick={clearLocation}
								disabled={disabled}
								className='h-7 w-7 p-0'
							>
								<MapPinIcon className='h-3 w-3' />
							</Button>
						)}
					</InputGroupAddon>
				</InputGroup>

				{/* Search Results */}
				{showResults && (
					<Card className='absolute top-full right-0 left-0 z-50 mt-1 max-h-60 overflow-y-auto'>
						<CardContent className='p-0'>
							{isSearching && <div className='text-muted-foreground px-3 py-2 text-sm'>Searching...</div>}
							{!isSearching && searchResults.length === 0 && searchQuery && (
								<div className='text-muted-foreground px-3 py-2 text-sm'>No results found</div>
							)}
							{!isSearching &&
								searchResults.map((result) => (
									<button
										key={result.place_id}
										onClick={() => handleResultSelect(result)}
										disabled={disabled}
										className='hover:bg-accent hover:text-accent-foreground w-full px-3 py-2 text-left text-sm
											disabled:cursor-not-allowed disabled:opacity-64'
									>
										{result.display_name}
									</button>
								))}
						</CardContent>
					</Card>
				)}
			</div>

			{/* Map Container */}
			<Card className='overflow-hidden'>
				<CardContent className='p-0'>
					<Suspense fallback={<MapLoading height={height} />}>
						<LeafletMapInner
							position={position}
							onMapClick={handleMapClick}
							disabled={disabled}
							height={height}
							markerColor={markerColor}
						/>
					</Suspense>
				</CardContent>
			</Card>

			{/* Current Location Info */}
			{position && (
				<div className='text-muted-foreground mt-2 text-xs'>
					<div className='flex items-center gap-1'>
						<MapPinIcon className='h-3 w-3' />
						<span>
							Latitude: {position[0].toFixed(6)}, Longitude: {position[1].toFixed(6)}
						</span>
					</div>
				</div>
			)}
		</div>
	);
}

import type { Transition } from 'motion/react';

/**
 * Shared motion configuration for consistent animations across the app.
 * Based on practical animation tips from https://emilkowal.ski/ui/7-practical-animation-tips
 *
 * Key principles:
 * 1. Keep UI animations under 300ms
 * 2. Never animate from scale(0) - use 0.9+ for natural feel
 * 3. Use custom easing curves for more impactful animations
 * 4. Make animations origin-aware when possible
 * 5. Use blur to smooth transitions when needed
 */

// =============================================================================
// Easing Curves
// =============================================================================

/**
 * Standard easing curves for UI animations.
 * Reference: https://easings.co/
 */
export const easings = {
	/** Smooth deceleration - good for elements entering the screen */
	easeOut: [0.25, 0.1, 0.25, 1] as const,

	/** Smooth acceleration - good for elements leaving the screen */
	easeIn: [0.42, 0, 1, 1] as const,

	/** Smooth both ways - good for hover states and toggles */
	easeInOut: [0.42, 0, 0.58, 1] as const,

	/** Snappy entrance with soft landing - great for modals/dialogs */
	snappy: [0.2, 0, 0, 1] as const,

	/** Bouncy feel - use sparingly for playful interactions */
	bounce: [0.34, 1.56, 0.64, 1] as const,

	/** Quick start, gradual stop - good for quick feedback */
	emphasized: [0.4, 0, 0.2, 1] as const,

	/** Physical feel for exit animations */
	physicalExit: [0.4, 0, 0.6, 1] as const,
} as const;

// =============================================================================
// Duration Presets
// =============================================================================

/**
 * Duration presets in seconds.
 * Rule: UI animations should be under 300ms (0.3s)
 */
export const durations = {
	/** Instant feedback (button press, toggle) */
	instant: 0.1,

	/** Quick transitions (tooltips, small elements) */
	fast: 0.15,

	/** Standard UI transitions (modals, panels) */
	normal: 0.2,

	/** Deliberate animations (page transitions, complex reveals) */
	slow: 0.3,

	/** Maximum for UI - use rarely */
	deliberate: 0.4,
} as const;

// =============================================================================
// Spring Presets
// =============================================================================

/**
 * Spring configurations for physics-based animations.
 * These create more natural, organic motion.
 */
export const springs = {
	/** Snappy spring - good for quick interactions */
	snappy: {
		type: 'spring' as const,
		stiffness: 400,
		damping: 30,
		mass: 0.8,
	},

	/** Bouncy spring - good for playful elements */
	bouncy: {
		type: 'spring' as const,
		stiffness: 300,
		damping: 20,
		mass: 0.6,
	},

	/** Gentle spring - good for large elements */
	gentle: {
		type: 'spring' as const,
		stiffness: 150,
		damping: 25,
		mass: 1,
	},

	/** Stiff spring - good for precise movements */
	stiff: {
		type: 'spring' as const,
		stiffness: 500,
		damping: 35,
		mass: 0.5,
	},

	/** Panel/sheet animations */
	panel: {
		type: 'spring' as const,
		stiffness: 150,
		damping: 25,
	},
} as const;

// =============================================================================
// Transition Presets
// =============================================================================

/**
 * Pre-configured transitions for common animation patterns.
 */
export const transitions = {
	/** Fast fade for overlays and simple elements */
	fade: {
		duration: durations.fast,
		ease: easings.easeOut,
	} satisfies Transition,

	/** Standard enter/exit for UI elements */
	enterExit: {
		duration: durations.normal,
		ease: easings.easeOut,
	} satisfies Transition,

	/** Snappy transition for interactive elements */
	snappy: {
		duration: durations.fast,
		ease: easings.snappy,
	} satisfies Transition,

	/** Panel slide transition */
	panel: {
		type: 'spring',
		stiffness: 150,
		damping: 25,
	} satisfies Transition,

	/** Exit transition with physical feel */
	exit: {
		type: 'tween',
		duration: durations.normal,
		ease: easings.physicalExit,
	} satisfies Transition,

	/** Layout animations */
	layout: {
		type: 'spring',
		stiffness: 300,
		damping: 30,
	} satisfies Transition,
} as const;

// =============================================================================
// Animation Variants
// =============================================================================

/**
 * Common animation variants for AnimatePresence patterns.
 * Follows the rule: never animate from scale(0), use 0.9+ instead.
 */
export const variants = {
	/** Fade with subtle scale - good for modals, cards */
	fadeScale: {
		initial: { opacity: 0, scale: 0.95 },
		animate: { opacity: 1, scale: 1 },
		exit: { opacity: 0, scale: 0.95 },
	},

	/** Fade with subtle slide up - good for content reveals */
	fadeSlideUp: {
		initial: { opacity: 0, y: 8 },
		animate: { opacity: 1, y: 0 },
		exit: { opacity: 0, y: -8 },
	},

	/** Fade with subtle slide down - good for dropdowns */
	fadeSlideDown: {
		initial: { opacity: 0, y: -8 },
		animate: { opacity: 1, y: 0 },
		exit: { opacity: 0, y: 8 },
	},

	/** Simple fade - for overlays */
	fade: {
		initial: { opacity: 0 },
		animate: { opacity: 1 },
		exit: { opacity: 0 },
	},

	/** Dock/floating element - scales from bottom */
	floatUp: {
		initial: { opacity: 0, y: 8, scale: 0.98 },
		animate: { opacity: 1, y: 0, scale: 1 },
		exit: { opacity: 0, y: 8, scale: 0.98 },
	},
} as const;

// =============================================================================
// Convenience Aliases (from original template)
// =============================================================================

export const MOTION_SPRING = springs.stiff;
export const MOTION_DURATION = { duration: durations.normal };

import { singularize } from "inflekt";
import { pgFieldToCamelCase, type CleanTable, type CleanRelations, type MetaQuery } from "@constructive-io/data";

type PrimitiveId = string | number | null;

type MetaTable = NonNullable<NonNullable<NonNullable<MetaQuery["_meta"]>["tables"]>[number]>;


/**
 * Convert a camelCase plural codec name (as used in raw _meta relation references)
 * to PascalCase singular (matching `_meta.tables[].name` format).
 * e.g. "formResponses" → "FormResponse"
 */
function codecNameToTableName(name: string): string {
  if (!name) return name;
  const singular = singularize(name);
  return singular.charAt(0).toUpperCase() + singular.slice(1);
}

/**
 * Derive all relation field names from raw table metadata relations.
 * Filters out hasMany entries that point to junction tables (those are surfaced via manyToMany),
 * and deduplicates manyToMany entries targeting the same table.
 */
export function getAllRelationFields(
  relations: MetaTable["relations"] | null | undefined,
  metaTables?: readonly MetaTable[],
): string[] {
  if (!relations) return [];

  const out: string[] = [];
  const push = (fieldName?: string | null) => {
    if (fieldName) out.push(fieldName);
  };

  relations.belongsTo?.forEach((rel) => push(rel?.fieldName));
  relations.hasOne?.forEach((rel) => push(rel?.fieldName));

  const junctionNames = new Set<string>();
  relations.manyToMany?.forEach((rel) => {
    const jtName = rel?.junctionTable?.name;
    if (!jtName) return;
    // When meta tables are available, skip non-pure junction tables
    if (metaTables) {
      const leftFk = rel?.junctionLeftKeyAttributes?.[0]?.name;
      const rightFk = rel?.junctionRightKeyAttributes?.[0]?.name;
      const leftFkCamel = leftFk ? pgFieldToCamelCase(leftFk) : undefined;
      const rightFkCamel = rightFk ? pgFieldToCamelCase(rightFk) : undefined;
      // Raw _meta codec names need conversion to match MetaTable.name format
      const jtTableName = codecNameToTableName(jtName);
      if (!isJunctionTablePure(jtTableName, leftFkCamel, rightFkCamel, metaTables)) return;
    }
    junctionNames.add(jtName);
  });
  relations.hasMany?.forEach((rel) => {
    const refName = rel?.referencedBy?.name;
    if (refName && junctionNames.has(refName)) return;
    push(rel?.fieldName);
  });

  const seenM2N = new Map<string, { fieldName?: string | null }>();
  relations.manyToMany?.forEach((rel) => {
    const target = rel?.rightTable?.name;
    if (!target) return;
    // Skip non-pure junction table M:N relations
    if (metaTables) {
      const jtName = rel?.junctionTable?.name;
      if (jtName) {
        const leftFk = rel?.junctionLeftKeyAttributes?.[0]?.name;
        const rightFk = rel?.junctionRightKeyAttributes?.[0]?.name;
        const leftFkCamel = leftFk ? pgFieldToCamelCase(leftFk) : undefined;
        const rightFkCamel = rightFk ? pgFieldToCamelCase(rightFk) : undefined;
        const jtTableName = codecNameToTableName(jtName);
        if (!isJunctionTablePure(jtTableName, leftFkCamel, rightFkCamel, metaTables)) return;
      }
    }
    seenM2N.set(target, rel);
  });
  seenM2N.forEach((rel) => push(rel?.fieldName));

  return Array.from(new Set(out));
}

/**
 * Check whether a junction table is "pure" — i.e. it has no required fields
 * beyond the two FK columns that form the M:N link.
 *
 * Rich entity tables that PostGraphile incidentally detects as junction tables
 * (e.g. `form_response` which has FKs to both `form_question` and `form_section`
 * but also requires `entity_id`, `session_id`, etc.) should NOT be treated as
 * simple junction tables because the manyToMany editor can only set the two FK
 * fields and would produce invalid mutations.
 */
export function isJunctionTablePure(
  junctionTableName: string,
  leftFkField: string | undefined,
  rightFkField: string | undefined,
  metaTables: readonly MetaTable[],
): boolean {
  if (!leftFkField || !rightFkField) return true; // Can't verify, assume pure
  const junctionMeta = metaTables.find((t) => t?.name === junctionTableName);
  if (!junctionMeta?.fields) return true; // No field info available, assume pure

  const exemptFields = new Set(['id', leftFkField, rightFkField]);

  for (const field of junctionMeta.fields) {
    if (!field?.name) continue;
    const camelName = pgFieldToCamelCase(field.name);
    if (exemptFields.has(camelName)) continue;
    if (field.isNotNull && !field.hasDefault) return false;
  }
  return true;
}

/**
 * Collect junction table names from M:N relations.
 * Used to suppress hasMany-to-junction columns and hide junction tables from UIs.
 *
 * When `metaTables` is provided, non-pure junction tables (those with extra required
 * fields beyond the two FK columns) are excluded — their hasMany entries should remain
 * visible since the manyToMany editor cannot handle them.
 */
export function getJunctionTableNames(
  relations: CleanRelations,
  metaTables?: readonly MetaTable[],
): Set<string> {
  const names = new Set<string>();
  for (const rel of relations.manyToMany) {
    if (!rel.junctionTable) continue;
    if (metaTables) {
      const leftFk = rel.junctionLeftKeyFields?.[0];
      const rightFk = rel.junctionRightKeyFields?.[0];
      if (!isJunctionTablePure(rel.junctionTable, leftFk, rightFk, metaTables)) continue;
    }
    names.add(rel.junctionTable);
  }
  return names;
}

function extractPrimitiveId(candidate: unknown): PrimitiveId {
  if (candidate === null || candidate === undefined) return null;
  if (typeof candidate === "string" || typeof candidate === "number") {
    return candidate;
  }
  if (typeof candidate === "object") {
    const record = candidate as Record<string, unknown>;
    const id = record.id;
    if (typeof id === "string" || typeof id === "number") {
      return id;
    }
  }
  return null;
}

export function normalizeForeignKeyValue(input: unknown): unknown {
  if (input === undefined) return undefined;
  if (input === null) return null;

  if (Array.isArray(input)) {
    return input
      .map((entry) => extractPrimitiveId(entry))
      .filter((entry): entry is PrimitiveId => entry !== undefined);
  }

  return extractPrimitiveId(input);
}

/**
 * Find the foreign key field in a related table that references the current table
 */
function findForeignKeyField(
  currentTableName: string,
  relatedTableName: string,
  allTables?: CleanTable[],
): string | undefined {
  if (!allTables) return undefined;

  // Find the related table
  const relatedTable = allTables.find((table) => table.name === relatedTableName);
  if (!relatedTable) return undefined;

  // Look for a belongsTo relation in the related table that references our current table
  const belongsToRelation = relatedTable.relations.belongsTo.find(
    (relation) => relation.referencesTable === currentTableName,
  );

  if (belongsToRelation && belongsToRelation.keys?.[0]?.name) {
    return belongsToRelation.keys[0].name;
  }

  return undefined;
}

export interface RelationshipInfo {
  relationType: "belongsTo" | "hasOne" | "hasMany" | "manyToMany";
  relationField: string;
  relatedTableName: string;
  foreignKeyField?: string;
  junctionTableName?: string;
  junctionLeftKey?: string;
  junctionRightKey?: string;
}

/**
 * Extract relationship information from table metadata for a specific field
 * For hasMany/hasOne relations, we need to find the actual foreign key field in the related table
 */
export function getRelationshipInfo(
  currentTable: CleanTable,
  relationFieldName: string,
  allTables?: CleanTable[],
): RelationshipInfo | null {
  const { relations } = currentTable;

  // Check belongsTo relations
  const belongsToRelation = relations.belongsTo.find((rel) => rel.fieldName === relationFieldName);
  if (belongsToRelation) {
    // For belongsTo: get the foreign key field name from the keys array
    const foreignKeyField = belongsToRelation.keys?.[0]?.name;
    return {
      relationType: "belongsTo",
      relationField: relationFieldName,
      relatedTableName: belongsToRelation.referencesTable,
      foreignKeyField: foreignKeyField,
    };
  }

  // Check hasOne relations
  const hasOneRelation = relations.hasOne.find((rel) => rel.fieldName === relationFieldName);
  if (hasOneRelation) {
    // For hasOne: find the foreign key field in the related table that references our current table
    const foreignKeyField = findForeignKeyField(
      currentTable.name,
      hasOneRelation.referencedByTable,
      allTables,
    );
    return {
      relationType: "hasOne",
      relationField: relationFieldName,
      relatedTableName: hasOneRelation.referencedByTable,
      foreignKeyField: foreignKeyField,
    };
  }

  // Check hasMany relations
  const hasManyRelation = relations.hasMany.find((rel) => rel.fieldName === relationFieldName);
  if (hasManyRelation) {
    // For hasMany: find the foreign key field in the related table that references our current table
    const foreignKeyField = findForeignKeyField(
      currentTable.name,
      hasManyRelation.referencedByTable,
      allTables,
    );
    return {
      relationType: "hasMany",
      relationField: relationFieldName,
      relatedTableName: hasManyRelation.referencedByTable,
      foreignKeyField: foreignKeyField,
    };
  }

  // Check manyToMany relations
  const manyToManyRelation = relations.manyToMany.find(
    (rel) => rel.fieldName === relationFieldName,
  );
  if (manyToManyRelation) {
    return {
      relationType: "manyToMany",
      relationField: relationFieldName,
      relatedTableName: manyToManyRelation.rightTable,
      junctionTableName: manyToManyRelation.junctionTable,
      junctionLeftKey: manyToManyRelation.junctionLeftKeyFields?.[0],
      junctionRightKey: manyToManyRelation.junctionRightKeyFields?.[0],
    };
  }

  return null;
}

/**
 * Get a display-friendly label from a record using common field patterns
 */
const DISPLAY_LABEL_FIELDS = [
  "name", "title", "label", "displayName", "fullName",
  "email", "username", "description", "code",
];

export function getRecordDisplayLabel(record: any): string {
  if (!record || typeof record !== "object") {
    return String(record || "");
  }

  // Try common display field patterns
  for (const field of DISPLAY_LABEL_FIELDS) {
    if (record[field] != null && String(record[field]).trim()) {
      return String(record[field]);
    }
  }

  // Fallback to ID
  if (record.id != null) {
    return `Record ${record.id}`;
  }

  return "Unknown Record";
}

/**
 * Get record ID, handling different ID field patterns
 */
export function getRecordId(record: any): string {
  if (!record || typeof record !== "object") {
    return String(record || "");
  }

  // Try common ID field patterns
  const idFields = ["id", "uuid", "_id", "pk"];

  for (const field of idFields) {
    if (record[field] != null) {
      return String(record[field]);
    }
  }

  // Fallback to first field value
  const keys = Object.keys(record);
  if (keys.length > 0) {
    return String(record[keys[0]] || "");
  }

  return "";
}

/**
 * Locale seam for @constructive-io/sheets.
 *
 * The host app may set a BCP-47 locale via SheetsConfig.locale. The provider
 * installs it into this module singleton (see sheets-provider.tsx), so any cell
 * renderer / editor can format dates and numbers locale-aware without threading
 * the locale through props/context. Defaults to 'en-US' (the prior hardcoded
 * behavior), so omitting `locale` changes nothing.
 */
const DEFAULT_LOCALE = 'en-US';

let active: string = DEFAULT_LOCALE;

/** Install (or reset) the active locale. Pass null/undefined to restore the default. */
export function setSheetsLocale(locale?: string | null): void {
	active = locale || DEFAULT_LOCALE;
}

/** Get the active locale (BCP-47). Safe to call anywhere; returns 'en-US' until set. */
export function sheetsLocale(): string {
	return active;
}

/**
 * Injectable logger seam for @constructive-io/sheets.
 *
 * The host app may provide a custom logger via SheetsConfig.logger. The provider
 * installs it into this module singleton (see sheets-provider.tsx), so any module
 * or hook can log without threading the logger through props/context.
 *
 * Default behaviour matches the prior console.* calls. `debug` is omitted from the
 * default logger (no-op) so verbose diagnostics stay silent unless a host opts in.
 */
export interface SheetsLogger {
	debug?(msg: string, ctx?: unknown): void;
	warn(msg: string, ctx?: unknown): void;
	error(msg: string, ctx?: unknown): void;
}

const defaultLogger: SheetsLogger = {
	warn: (...a) => console.warn(...a),
	error: (...a) => console.error(...a),
	// debug omitted = no-op
};

let active: SheetsLogger = defaultLogger;

/**
 * Install (or reset) the active logger. Pass a host logger to override; pass
 * null/undefined to restore the default. Host overrides are merged over the
 * default so a partial logger still gets working warn/error.
 */
export function setSheetsLogger(l?: SheetsLogger | null): void {
	active = l ? { ...defaultLogger, ...l } : defaultLogger;
}

/** Get the active logger. Safe to call anywhere (returns the default until set). */
export function sheetsLogger(): SheetsLogger {
	return active;
}

import { useEffect, useState } from 'react';

export function useColorScheme(): 'light' | 'dark' {
	const [scheme, setScheme] = useState<'light' | 'dark'>('light');

	useEffect(() => {
		const update = () => {
			setScheme(document.documentElement.classList.contains('dark') ? 'dark' : 'light');
		};
		update();
		const observer = new MutationObserver(() => update());
		observer.observe(document.documentElement, { attributes: true, attributeFilter: ['class'] });
		return () => observer.disconnect();
	}, []);

	return scheme;
}

import { useEffect, useState } from 'react';

export type ImageStatus = 'idle' | 'loading' | 'loaded' | 'error';

export function useImageStatus(src?: string): ImageStatus {
	const [status, setStatus] = useState<ImageStatus>('idle');

	useEffect(() => {
		if (!src) return setStatus('idle');

		setStatus('loading');
		const img = new Image();
		img.src = src;

		const onLoad = () => setStatus('loaded');
		const onError = () => setStatus('error');

		img.addEventListener('load', onLoad);
		img.addEventListener('error', onError);

		return () => {
			img.removeEventListener('load', onLoad);
			img.removeEventListener('error', onError);
		};
	}, [src]);

	return status;
}

import { useCallback, useRef, useState } from 'react';

interface Size { width: number; height: number; }

export function useResizeObserver<T extends HTMLElement>(): [React.RefCallback<T>, Size] {
	const [size, setSize] = useState<Size>({ width: 0, height: 0 });
	const observerRef = useRef<ResizeObserver | null>(null);

	const ref = useCallback((node: T | null) => {
		if (observerRef.current) {
			observerRef.current.disconnect();
			observerRef.current = null;
		}
		if (node) {
			const observer = new ResizeObserver(([entry]) => {
				if (entry) {
					setSize({ width: entry.contentRect.width, height: entry.contentRect.height });
				}
			});
			observer.observe(node);
			observerRef.current = observer;
		}
	}, []);

	return [ref, size];
}

